/* ── Global settings (defined here since test_main.c replaces main.c) */
settings_t g_settings = { ANGLE_RADIANS, true, 6, COMPLEX_OFF, false, STEP_ALL,
                          SOLVE_FULL_AUTO, METHOD_AUTO };

/* ── Previous answer (defined here since test_main.c replaces main.c) */
ce_float_t g_last_answer = 0;

/* ── Test infrastructure ─────────────────────────────────── */

static int tests_run    = 0;
static int tests_passed = 0;
static int tests_failed = 0;

#define ASSERT_TRUE(cond, msg) do { \
    tests_run++; \
    if (cond) { tests_passed++; } \
    else { tests_failed++; \
           printf("  FAIL [%s:%d] %s\n", __FILE__, __LINE__, msg); } \
} while(0)

#define ASSERT_EQ_INT(a, b, msg) ASSERT_TRUE((a) == (b), msg)
#define ASSERT_EQ_FLOAT(a, b, tol, msg) ASSERT_TRUE(fabsf((a)-(b)) < (tol), msg)
#define ASSERT_STR_EQ(a, b, msg) ASSERT_TRUE(strcmp((a), (b)) == 0, msg)
#define ASSERT_STR_CONTAINS(haystack, needle, msg) \
    ASSERT_TRUE(strstr(haystack, needle) != NULL, msg)

/* Default settings for test isolation */
static const settings_t DEFAULT_SETTINGS = { ANGLE_RADIANS, true, 6, COMPLEX_OFF, false, STEP_ALL,
                                             SOLVE_FULL_AUTO, METHOD_AUTO };

/* Run a test function with settings isolation: restores defaults after each test */
#define RUN_TEST(fn) do { fn(); g_settings = DEFAULT_SETTINGS; mem_free_all(); steps_clear(); macros_init(); } while(0)

/* Helper: parse an expression string into an AST */
static ast_node_t *parse_str(const char *input)
{
    static tokenizer_t tok;
    static parser_t    par;
    char expanded[MAX_INPUT_LEN];
    char macro_err[80];

    if (!macros_expand(input, expanded, sizeof(expanded), macro_err, sizeof(macro_err)))
        return NULL;

    tok_init(&tok, expanded);
    if (tok_tokenize(&tok) != CE_OK) return NULL;
    parser_init(&par, &tok);
    return parser_parse(&par);
}

static bool expr_has_top_level_equals(const char *input)
{
    int depth = 0;

    if (!input) return false;
    while (*input) {
        if (*input == '(') {
            depth++;
        } else if (*input == ')' && depth > 0) {
            depth--;
        } else if (*input == '=' && depth == 0) {
            return true;
        }
        input++;
    }

    return false;
}

static bool response_step_contains(const ce_response_t *resp, const char *needle)
{
    int i;

    if (!resp || !needle || !needle[0]) return false;
    for (i = 0; i < resp->step_count; i++) {
        if (strstr(resp->steps[i], needle) != NULL) {
            return true;
        }
    }

    return false;
}

static int step_index_containing_from(const char *needle, int start)
{
    int i;

    if (!needle || !needle[0]) return -1;
    if (start < 0) start = 0;

    for (i = start; i < steps_count(); i++) {
        const char *step = steps_get(i);
        if (step && strstr(step, needle) != NULL) {
            return i;
        }
    }

    return -1;
}

static bool steps_contain_in_order(const char *const *needles, int count)
{
    int i;
    int cursor = 0;

    if (!needles || count <= 0) return false;

    for (i = 0; i < count; i++) {
        int index = step_index_containing_from(needles[i], cursor);
        if (index < 0) return false;
        cursor = index + 1;
    }

    return true;
}

static bool processor_run_expr(const char *input,
                               ce_response_t *resp,
                               ce_domain_t *out_domain,
                               const char **out_program)
{
    ast_node_t *root;
    bool had_equals;
    ce_domain_t domain;

    if (!input || !resp) return false;

    mem_free_all();
    steps_clear();
    memset(resp, 0, sizeof(*resp));

    root = parse_str(input);
    if (!root) return false;

    had_equals = expr_has_top_level_equals(input);
    domain = ce_classify_expression(root, had_equals);
    if (out_domain) *out_domain = domain;
    if (out_program) *out_program = ce_domain_program(domain);

    return ce_processor_run_preparsed(input, root, had_equals, resp);
}

/* Helper: parse and evaluate an expression numerically */
static ce_float_t eval_str(const char *input, ce_error_t *err)
{
    ast_node_t *root;
    eval_ctx_t ctx;
    ce_float_t val;

    *err = CE_OK;
    root = parse_str(input);
    if (!root) { *err = CE_ERR_SYNTAX; return 0; }

    eval_init(&ctx);
    val = eval_expr(&ctx, root);
    *err = eval_error(&ctx);
    ast_free(root);
    return val;
}

/* Helper: parse, evaluate with x bound */
static ce_float_t eval_str_at(const char *input, char var,
                               ce_float_t x, ce_error_t *err)
{
    ast_node_t *root;
    eval_ctx_t ctx;
    ce_float_t val;

    *err = CE_OK;
    root = parse_str(input);
    if (!root) { *err = CE_ERR_SYNTAX; return 0; }

    eval_init(&ctx);
    eval_set_var(&ctx, var, x);
    val = eval_expr(&ctx, root);
    *err = eval_error(&ctx);
    ast_free(root);
    return val;
}

/* Helper: parse with parser error details for strict malformed-input tests */
static ast_node_t *parse_str_detailed(const char *input,
                                      ce_error_t *err,
                                      char *msg, size_t msg_size)
{
    static tokenizer_t tok;
    static parser_t par;
    char expanded[MAX_INPUT_LEN];
    char macro_err[80];
    ast_node_t *root;

    if (err) *err = CE_OK;
    if (msg && msg_size > 0) msg[0] = '\0';

    if (!macros_expand(input, expanded, sizeof(expanded), macro_err, sizeof(macro_err))) {
        if (err) *err = CE_ERR_SYNTAX;
        if (msg && msg_size > 0) {
            strncpy(msg, macro_err, msg_size - 1);
            msg[msg_size - 1] = '\0';
        }
        return NULL;
    }

    tok_init(&tok, expanded);
    if (tok_tokenize(&tok) != CE_OK) {
        if (err) *err = CE_ERR_SYNTAX;
        if (msg && msg_size > 0) {
            strncpy(msg, "Tokenizer error", msg_size - 1);
            msg[msg_size - 1] = '\0';
        }
        return NULL;
    }

    parser_init(&par, &tok);
    root = parser_parse(&par);
    if (!root) {
        if (err) *err = parser_error(&par);
        if (msg && msg_size > 0) {
            strncpy(msg, parser_error_msg(&par), msg_size - 1);
            msg[msg_size - 1] = '\0';
        }
    }
    return root;
}

static void assert_astwire_roundtrip(const char *expr, const char *tag)
{
    uint8_t buf[CE_AST_WIRE_MAX];
    uint16_t size = 0;
    ast_node_t *root = parse_str(expr);
    ast_node_t *roundtrip;
    char msg[128];

    snprintf(msg, sizeof(msg), "%s: parse", tag);
    ASSERT_TRUE(root != NULL, msg);
    if (!root) return;

    snprintf(msg, sizeof(msg), "%s: serialize ok", tag);
    ASSERT_TRUE(ce_ast_serialize(root, buf, (uint16_t)sizeof(buf), &size), msg);
    if (size == 0) {
        ast_free(root);
        return;
    }
    snprintf(msg, sizeof(msg), "%s: payload non-empty", tag);
    ASSERT_TRUE(size > 0, msg);

    roundtrip = ce_ast_deserialize(buf, size);
    snprintf(msg, sizeof(msg), "%s: deserialize ok", tag);
    ASSERT_TRUE(roundtrip != NULL, msg);
    if (roundtrip) {
        snprintf(msg, sizeof(msg), "%s: AST preserved", tag);
        ASSERT_TRUE(ast_equal(root, roundtrip), msg);
        ast_free(roundtrip);
    }

    ast_free(root);
}

static ast_node_t *alloc_test_node(node_type_t type)
{
    ast_node_t *node = mem_alloc_node();
    if (!node) return NULL;
    memset(node, 0, sizeof(*node));
    node->type = type;
    return node;
}

/* ═══════════════════════════════════════════════════════════ */
/*                    MEMORY POOL TESTS                        */
/* ═══════════════════════════════════════════════════════════ */

static void test_memory(void)
{
    ast_node_t *nodes[10];
    int i;

    printf("=== Memory Pool ===\n");

    mem_init();
    ASSERT_EQ_INT(mem_nodes_used(), 0, "init: 0 used");
    ASSERT_EQ_INT(mem_nodes_free(), NODE_POOL_SIZE, "init: all free");

    /* Allocate a few */
    for (i = 0; i < 10; i++)
        nodes[i] = mem_alloc_node();
    ASSERT_EQ_INT(mem_nodes_used(), 10, "alloc 10");
    ASSERT_TRUE(nodes[0] != NULL, "alloc non-null");

    /* Free them */
    for (i = 0; i < 10; i++)
        mem_free_node(nodes[i]);
    ASSERT_EQ_INT(mem_nodes_used(), 0, "free all: 0 used");

    /* Double-free protection */
    {
        ast_node_t *n = mem_alloc_node();
        uint16_t before = mem_nodes_used();
        mem_free_node(n);
        mem_free_node(n);  /* should be a no-op */
        ASSERT_EQ_INT(mem_nodes_used(), before - 1, "double-free: no corruption");
    }

    /* Free-all resets */
    mem_alloc_node();
    mem_alloc_node();
    mem_free_all();
    ASSERT_EQ_INT(mem_nodes_used(), 0, "free_all resets");
    ASSERT_EQ_INT(mem_nodes_free(), NODE_POOL_SIZE, "free_all: all free");

    /* Pool exhaustion */
    mem_init();
    for (i = 0; i < NODE_POOL_SIZE; i++)
        mem_alloc_node();
    ASSERT_TRUE(mem_alloc_node() == NULL, "pool exhaustion returns NULL");
    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    TOKENIZER TESTS                          */
/* ═══════════════════════════════════════════════════════════ */

static void test_tokenizer(void)
{
    tokenizer_t tok;
    const token_t *t;

    printf("=== Tokenizer ===\n");

    /* Basic number */
    tok_init(&tok, "42");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: '42' ok");
    t = tok_get(&tok, 0);
    ASSERT_TRUE(t != NULL && t->type == TOK_NUMBER, "tok: 42 is NUM");
    ASSERT_EQ_FLOAT(t->num_val, 42.0f, 0.01f, "tok: 42 value");

    /* Decimal */
    tok_init(&tok, "3.14");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: '3.14' ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_FLOAT(t->num_val, 3.14f, 0.01f, "tok: 3.14 value");

    /* Leading dot */
    tok_init(&tok, ".5");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: '.5' ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_FLOAT(t->num_val, 0.5f, 0.01f, "tok: .5 value");

    /* Operators */
    tok_init(&tok, "1+2*3");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: ops ok");
    ASSERT_EQ_INT(tok.count, 6, "tok: 1+2*3 -> 6 tokens (incl EOF)");

    /* Functions */
    tok_init(&tok, "sin(x)");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: sin(x) ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_SIN, "tok: sin token");

    /* Constants */
    tok_init(&tok, "pi");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: pi ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_PI, "tok: pi token");

    /* d/dx notation */
    tok_init(&tok, "d/dx(x^2)");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: d/dx ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_DERIV, "tok: d/dx is DERIV");
    ASSERT_EQ_INT(t->var_name, 'x', "tok: d/dx var=x");

    /* Integral differential notation: int(...)dx */
    tok_init(&tok, "int(x^2)dx");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: int(...)dx ok");
    t = tok_get(&tok, tok.count - 2); /* token before EOF */
    ASSERT_TRUE(t != NULL, "tok: differential token exists");
    ASSERT_EQ_INT(t->type, TOK_DIFFVAR, "tok: dx is differential");
    ASSERT_EQ_INT(t->var_name, 'x', "tok: dx var=x");

    tok_init(&tok, "D/DX x^2");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: uppercase D/DX ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_DERIV, "tok: uppercase D/DX is DERIV");
    ASSERT_EQ_INT(t->var_name, 'X', "tok: uppercase D/DX preserves case to X");

    /* Variable 'e' is constant */
    tok_init(&tok, "e");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: 'e' ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_E, "tok: e is constant");

    /* Calculus keywords */
    tok_init(&tok, "int(");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: int ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_INTEGRAL, "tok: int is INTEGRAL");

    tok_init(&tok, "lim(");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: lim ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_LIMIT, "tok: lim is LIMIT");

    /* Algebra keywords */
    tok_init(&tok, "solve(");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: solve ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_SOLVE, "tok: solve token");

    /* Error: unknown char */
    tok_init(&tok, "@");
    ASSERT_TRUE(tok_tokenize(&tok) != CE_OK, "tok: '@' error");

    /* arcsin/arccos/arctan aliases */
    tok_init(&tok, "arcsin(");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: arcsin ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_ASIN, "tok: arcsin = ASIN");

    /* TI OS_TOK_DIVIDE (0x83): standalone division */
    tok_init(&tok, "x\x83y");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: x/y with TI 0x83 ok");
    ASSERT_EQ_INT(tok.count, 4, "tok: x/y has 4 tokens (x,/,y,EOF)");
    t = tok_get(&tok, 1);
    ASSERT_EQ_INT(t->type, TOK_DIVIDE, "tok: 0x83 is TOK_DIVIDE");

    /* TI OS_TOK_DIVIDE in d/dx shorthand */
    tok_init(&tok, "d\x83" "dx(x^2)");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: d/dx with TI 0x83 ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_DERIV, "tok: d[0x83]dx is DERIV");
    ASSERT_EQ_INT(t->var_name, 'x', "tok: d[0x83]dx var=x");

    /* TI OS_TOK_SIN (0xC2): sin function with auto-open-paren */
    tok_init(&tok, "\xC2" "x)");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: 0xC2 sin ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_SIN, "tok: 0xC2 first token is SIN");
    t = tok_get(&tok, 1);
    ASSERT_EQ_INT(t->type, TOK_LPAREN, "tok: 0xC2 second token is LPAREN");
    t = tok_get(&tok, 2);
    ASSERT_EQ_INT(t->type, TOK_VARIABLE, "tok: 0xC2 third token is VARIABLE");

    /* TI OS_TOK_SIN in lim(sin(x)/x, x, 0) context */
    tok_init(&tok, "lim(\xC2" "x)\x83" "x,x,0)");
    ASSERT_EQ_INT(tok_tokenize(&tok), CE_OK, "tok: lim with 0xC2 and 0x83 ok");
    t = tok_get(&tok, 0);
    ASSERT_EQ_INT(t->type, TOK_LIMIT, "tok: lim..0xC2..0x83 first=LIMIT");
    t = tok_get(&tok, 2);
    ASSERT_EQ_INT(t->type, TOK_SIN, "tok: lim..0xC2 sin token found");
}

/* ═══════════════════════════════════════════════════════════ */
/*                    PARSER TESTS                             */
/* ═══════════════════════════════════════════════════════════ */

static void test_parser(void)
{
    ast_node_t *root;
    char buf[128];

    printf("=== Parser ===\n");

    mem_free_all();

    /* Simple number */
    root = parse_str("42");
    ASSERT_TRUE(root != NULL, "parse: '42' non-null");
    ASSERT_EQ_INT(root->type, NODE_NUMBER, "parse: 42 is NUMBER");
    ASSERT_EQ_FLOAT(root->d.number, 42.0f, 0.01f, "parse: 42 value");
    ast_free(root);

    /* Binary operation */
    mem_free_all();
    root = parse_str("2+3");
    ASSERT_TRUE(root != NULL, "parse: '2+3' non-null");
    ASSERT_EQ_INT(root->type, NODE_BINOP, "parse: 2+3 is BINOP");
    ASSERT_EQ_INT(root->d.binop.op, OP_ADD, "parse: 2+3 is ADD");
    ast_free(root);

    /* Precedence: 2+3*4 = 2+(3*4) */
    mem_free_all();
    root = parse_str("2+3*4");
    ASSERT_TRUE(root != NULL, "parse: '2+3*4' non-null");
    ASSERT_EQ_INT(root->d.binop.op, OP_ADD, "parse: top is ADD");
    ASSERT_EQ_INT(root->d.binop.right->type, NODE_BINOP, "parse: rhs is BINOP");
    ASSERT_EQ_INT(root->d.binop.right->d.binop.op, OP_MUL, "parse: rhs is MUL");
    ast_free(root);

    /* Power right-assoc: 2^3^4 = 2^(3^4) */
    mem_free_all();
    root = parse_str("2^3^4");
    ASSERT_TRUE(root != NULL, "parse: '2^3^4' non-null");
    ASSERT_EQ_INT(root->d.binop.right->type, NODE_BINOP, "parse: rhs is BINOP");
    ASSERT_EQ_INT(root->d.binop.right->d.binop.op, OP_POW, "parse: rhs is POW");
    ast_free(root);

    /* Implicit multiplication: 2x = 2*x */
    mem_free_all();
    root = parse_str("2x");
    ASSERT_TRUE(root != NULL, "parse: '2x' non-null");
    ASSERT_EQ_INT(root->type, NODE_BINOP, "parse: 2x is BINOP");
    ASSERT_EQ_INT(root->d.binop.op, OP_MUL, "parse: 2x is MUL");
    ast_free(root);

    /* Function call */
    mem_free_all();
    root = parse_str("sin(x)");
    ASSERT_TRUE(root != NULL, "parse: sin(x) non-null");
    ASSERT_EQ_INT(root->type, NODE_FUNC, "parse: sin(x) is FUNC");
    ASSERT_EQ_INT(root->d.func.id, FN_SIN, "parse: sin(x) is SIN");
    ast_free(root);

    /* Unary minus */
    mem_free_all();
    root = parse_str("-5");
    ASSERT_TRUE(root != NULL, "parse: -5 non-null");
    ASSERT_EQ_INT(root->type, NODE_UNOP, "parse: -5 is UNOP");
    ASSERT_EQ_INT(root->d.unop.op, UOP_NEG, "parse: -5 is NEG");
    ast_free(root);

    /* Derivative */
    mem_free_all();
    root = parse_str("d/dx(x^2)");
    ASSERT_TRUE(root != NULL, "parse: d/dx(x^2) non-null");
    ASSERT_EQ_INT(root->type, NODE_DERIV, "parse: d/dx is DERIV");
    ASSERT_EQ_INT(root->d.deriv.var, 'x', "parse: d/dx var=x");
    ast_free(root);

    /* Natural derivative shorthand: d/dx expr */
    mem_free_all();
    root = parse_str("d/dx x^2");
    ASSERT_TRUE(root != NULL, "parse: d/dx x^2 non-null");
    ASSERT_EQ_INT(root->type, NODE_DERIV, "parse: d/dx shorthand is DERIV");
    ASSERT_EQ_INT(root->d.deriv.var, 'x', "parse: d/dx shorthand var=x");
    ast_free(root);

    /* Integral */
    mem_free_all();
    root = parse_str("int(x^2,x)");
    ASSERT_TRUE(root != NULL, "parse: int(x^2,x) non-null");
    ASSERT_EQ_INT(root->type, NODE_INTEGRAL, "parse: is INTEGRAL");
    ASSERT_EQ_INT(root->d.integral.var, 'x', "parse: int var=x");
    ASSERT_TRUE(root->d.integral.lo == NULL, "parse: int no lo bound");
    ast_free(root);

    /* Integral with bounds */
    mem_free_all();
    root = parse_str("int(x,x,0,1)");
    ASSERT_TRUE(root != NULL, "parse: int(x,x,0,1) non-null");
    ASSERT_TRUE(root->d.integral.lo != NULL, "parse: int has lo");
    ASSERT_TRUE(root->d.integral.hi != NULL, "parse: int has hi");
    ast_free(root);

    /* Natural integral differential notation: int(...)dx */
    mem_free_all();
    root = parse_str("int(x^2+1)dx");
    ASSERT_TRUE(root != NULL, "parse: int(x^2+1)dx non-null");
    ASSERT_EQ_INT(root->type, NODE_INTEGRAL, "parse: int(...)dx is INTEGRAL");
    ASSERT_EQ_INT(root->d.integral.var, 'x', "parse: int(...)dx var=x");
    ASSERT_TRUE(root->d.integral.lo == NULL, "parse: int(...)dx no lo bound");
    ASSERT_TRUE(root->d.integral.hi == NULL, "parse: int(...)dx no hi bound");
    ast_free(root);

    mem_free_all();
    root = parse_str("int(x) d y");
    ASSERT_TRUE(root != NULL, "parse: int(x) d y non-null");
    ASSERT_EQ_INT(root->type, NODE_INTEGRAL, "parse: int(x) d y is INTEGRAL");
    ASSERT_EQ_INT(root->d.integral.var, 'y', "parse: int(x) d y var=y");
    ast_free(root);

    /* Differential mismatch should fail */
    mem_free_all();
    root = parse_str("int(x,t)dx");
    ASSERT_TRUE(root == NULL, "parse: int(x,t)dx mismatch rejected");

    mem_free_all();
    root = parse_str("int(x)d");
    ASSERT_TRUE(root == NULL, "parse: int(x)d missing differential variable rejected");

    /* Limit */
    mem_free_all();
    root = parse_str("lim(x,x,0)");
    ASSERT_TRUE(root != NULL, "parse: lim(x,x,0) non-null");
    ASSERT_EQ_INT(root->type, NODE_LIMIT, "parse: is LIMIT");
    ast_free(root);

    /* Summation */
    mem_free_all();
    root = parse_str("sum(n,n,1,10)");
    ASSERT_TRUE(root != NULL, "parse: sum non-null");
    ASSERT_EQ_INT(root->type, NODE_SUM, "parse: is SUM");
    ast_free(root);

    /* Solve with equation */
    mem_free_all();
    root = parse_str("solve(x^2=4,x)");
    ASSERT_TRUE(root != NULL, "parse: solve(x^2=4) non-null");
    ASSERT_EQ_INT(root->type, NODE_SOLVE, "parse: is SOLVE");
    ast_free(root);

    /* AST printer round-trip */
    mem_free_all();
    root = parse_str("sin(x)+cos(x)");
    ASSERT_TRUE(root != NULL, "parse: sin+cos non-null");
    ast_to_str(root, buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "sin", "ast_to_str contains 'sin'");
    ASSERT_STR_CONTAINS(buf, "cos", "ast_to_str contains 'cos'");
    ast_free(root);

    mem_free_all();
}

static void test_macros(void)
{
    char out[256];
    char err[128];
    ce_error_t ce_err;

    printf("=== Macros ===\n");

    macros_init();
    ASSERT_EQ_INT(macros_count(), 0, "macros: init empty");

    ASSERT_EQ_INT(macros_try_command("macro(g,9.8)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_OK, "macros: define scalar shortcut");
    ASSERT_EQ_INT(macros_count(), 1, "macros: count after first define");

    ASSERT_TRUE(macros_expand("2*g", out, sizeof(out), err, sizeof(err)),
                "macros: expand scalar shortcut");
    ASSERT_STR_CONTAINS(out, "9.8", "macros: expansion contains body");

    ce_err = CE_OK;
    ASSERT_EQ_FLOAT(eval_str("2*g", &ce_err), 19.6f, 0.01f,
                    "macros: eval with scalar shortcut");
    ASSERT_EQ_INT(ce_err, CE_OK, "macros: eval scalar shortcut status ok");

    ASSERT_EQ_INT(macros_try_command("macro(sq(x),x*x)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_OK, "macros: define function shortcut");
    ce_err = CE_OK;
    ASSERT_EQ_FLOAT(eval_str("sq(3+1)", &ce_err), 16.0f, 0.01f,
                    "macros: function substitution preserves precedence");
    ASSERT_EQ_INT(ce_err, CE_OK, "macros: eval function shortcut status ok");

    ASSERT_TRUE(!macros_expand("sq(2,3)", out, sizeof(out), err, sizeof(err)),
                "macros: arg-count mismatch rejected");
    ASSERT_STR_CONTAINS(err, "expects 1 args",
                        "macros: arg-count mismatch has clear error");

    ASSERT_EQ_INT(macros_try_command("macro(loop,loop)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_OK, "macros: define recursive shortcut");
    ASSERT_TRUE(!macros_expand("loop+1", out, sizeof(out), err, sizeof(err)),
                "macros: recursive expansion blocked");
    ASSERT_STR_CONTAINS(err, "too deep", "macros: recursion error message");

    ASSERT_EQ_INT(macros_try_command("unmacro(loop)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_OK, "macros: remove existing macro");
    ASSERT_EQ_INT(macros_try_command("macros()",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_OK, "macros: list command");
    ASSERT_STR_CONTAINS(out, "sq(x)", "macros: list includes function macro");

    ASSERT_EQ_INT(macros_try_command("unmacro(does_not_exist)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_ERROR, "macros: removing missing macro fails");
    ASSERT_STR_CONTAINS(err, "not found",
                        "macros: missing macro error is descriptive");

    ASSERT_EQ_INT(macros_try_command("macro(bad(,),x)",
                                     out, sizeof(out), err, sizeof(err)),
                  MACRO_CMD_ERROR, "macros: invalid signature rejected");
    ASSERT_STR_CONTAINS(err, "Empty parameter name",
                        "macros: invalid signature has clear error");
}

/* ═══════════════════════════════════════════════════════════ */
/*                    EVALUATOR TESTS                          */
/* ═══════════════════════════════════════════════════════════ */

static void test_evaluator(void)
{
    ce_error_t err;
    ce_float_t val;

    printf("=== Evaluator ===\n");

    mem_free_all();

    /* Arithmetic */
    val = eval_str("2+3", &err);
    ASSERT_EQ_INT(err, CE_OK, "eval: 2+3 ok");
    ASSERT_EQ_FLOAT(val, 5.0f, 0.01f, "eval: 2+3 = 5");

    val = eval_str("10-4", &err);
    ASSERT_EQ_FLOAT(val, 6.0f, 0.01f, "eval: 10-4 = 6");

    val = eval_str("3*7", &err);
    ASSERT_EQ_FLOAT(val, 21.0f, 0.01f, "eval: 3*7 = 21");

    val = eval_str("15/3", &err);
    ASSERT_EQ_FLOAT(val, 5.0f, 0.01f, "eval: 15/3 = 5");

    val = eval_str("2^10", &err);
    ASSERT_EQ_FLOAT(val, 1024.0f, 0.01f, "eval: 2^10 = 1024");

    /* Precedence */
    val = eval_str("2+3*4", &err);
    ASSERT_EQ_FLOAT(val, 14.0f, 0.01f, "eval: 2+3*4 = 14");

    val = eval_str("(2+3)*4", &err);
    ASSERT_EQ_FLOAT(val, 20.0f, 0.01f, "eval: (2+3)*4 = 20");

    /* Unary minus */
    val = eval_str("-5+3", &err);
    ASSERT_EQ_FLOAT(val, -2.0f, 0.01f, "eval: -5+3 = -2");

    /* Constants */
    val = eval_str("pi", &err);
    ASSERT_EQ_FLOAT(val, CE_PI, 0.001f, "eval: pi");

    val = eval_str("e", &err);
    ASSERT_EQ_FLOAT(val, CE_E, 0.001f, "eval: e");

    /* Functions */
    val = eval_str("sin(0)", &err);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.001f, "eval: sin(0) = 0");

    val = eval_str("cos(0)", &err);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "eval: cos(0) = 1");

    val = eval_str("ln(1)", &err);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.001f, "eval: ln(1) = 0");

    val = eval_str("exp(0)", &err);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "eval: exp(0) = 1");

    val = eval_str("sqrt(9)", &err);
    ASSERT_EQ_FLOAT(val, 3.0f, 0.001f, "eval: sqrt(9) = 3");

    val = eval_str("abs(-7)", &err);
    ASSERT_EQ_FLOAT(val, 7.0f, 0.001f, "eval: abs(-7) = 7");

    val = eval_str("log(100)", &err);
    ASSERT_EQ_FLOAT(val, 2.0f, 0.01f, "eval: log(100) = 2");

    /* Factorial */
    val = eval_str("5!", &err);
    ASSERT_EQ_FLOAT(val, 120.0f, 0.01f, "eval: 5! = 120");

    /* Implicit multiplication */
    val = eval_str_at("2x", 'x', 5.0f, &err);
    ASSERT_EQ_FLOAT(val, 10.0f, 0.01f, "eval: 2x at x=5 = 10");

    val = eval_str_at("3sin(0)", 'x', 0, &err);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.01f, "eval: 3sin(0) = 0");

    /* Division by zero */
    val = eval_str("1/0", &err);
    ASSERT_EQ_INT(err, CE_ERR_DIV_ZERO, "eval: 1/0 error");

    /* Domain errors */
    val = eval_str("sqrt(-1)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "eval: sqrt(-1) domain");

    val = eval_str("ln(-1)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "eval: ln(-1) domain");

    val = eval_str("asin(2)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "eval: asin(2) domain");

    /* Numerical summation */
    val = eval_str("sum(n,n,1,10)", &err);
    ASSERT_EQ_INT(err, CE_OK, "eval: sum(n,n,1,10) ok");
    ASSERT_EQ_FLOAT(val, 55.0f, 0.1f, "eval: sum(n,1,10) = 55");

    /* Numerical integral: int(x,x,0,1) ≈ 0.5 */
    val = eval_str("int(x,x,0,1)", &err);
    ASSERT_EQ_INT(err, CE_OK, "eval: int(x,x,0,1) ok");
    ASSERT_EQ_FLOAT(val, 0.5f, 0.01f, "eval: int(x,0,1) = 0.5");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    SIMPLIFIER TESTS                         */
/* ═══════════════════════════════════════════════════════════ */

static void test_simplifier(void)
{
    ast_node_t *node, *result;

    printf("=== Simplifier ===\n");

    mem_free_all();

    /* 0 + x → x */
    node = ast_binop(OP_ADD, ast_number(0), ast_variable('x'));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: 0+x → x");
    ast_free(result);

    /* x + 0 → x */
    mem_free_all();
    node = ast_binop(OP_ADD, ast_variable('x'), ast_number(0));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: x+0 → x");
    ast_free(result);

    /* 0 * x → 0 */
    mem_free_all();
    node = ast_binop(OP_MUL, ast_number(0), ast_variable('x'));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "simp: 0*x → 0");
    ASSERT_EQ_FLOAT(result->d.number, 0.0f, 0.01f, "simp: 0*x = 0");
    ast_free(result);

    /* 1 * x → x */
    mem_free_all();
    node = ast_binop(OP_MUL, ast_number(1), ast_variable('x'));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: 1*x → x");
    ast_free(result);

    /* x^0 → 1 */
    mem_free_all();
    node = ast_binop(OP_POW, ast_variable('x'), ast_number(0));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "simp: x^0 → 1");
    ASSERT_EQ_FLOAT(result->d.number, 1.0f, 0.01f, "simp: x^0 = 1");
    ast_free(result);

    /* x^1 → x */
    mem_free_all();
    node = ast_binop(OP_POW, ast_variable('x'), ast_number(1));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: x^1 → x");
    ast_free(result);

    /* Constant folding: 2+3 → 5 */
    mem_free_all();
    node = ast_binop(OP_ADD, ast_number(2), ast_number(3));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "simp: 2+3 → NUM");
    ASSERT_EQ_FLOAT(result->d.number, 5.0f, 0.01f, "simp: 2+3 = 5");
    ast_free(result);

    /* -(-x) → x */
    mem_free_all();
    node = ast_unop(UOP_NEG, ast_unop(UOP_NEG, ast_variable('x')));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: -(-x) → x");
    ast_free(result);

    /* -0 → 0 */
    mem_free_all();
    node = ast_unop(UOP_NEG, ast_number(0));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "simp: -0 → 0");
    ASSERT_EQ_FLOAT(result->d.number, 0.0f, 0.01f, "simp: -0 = 0");
    ast_free(result);

    /* (-1)*x → -x */
    mem_free_all();
    node = ast_binop(OP_MUL, ast_number(-1), ast_variable('x'));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_UNOP, "simp: (-1)*x → -x");
    ASSERT_EQ_INT(result->d.unop.op, UOP_NEG, "simp: (-1)*x is NEG");
    ast_free(result);

    /* x - 0 → x */
    mem_free_all();
    node = ast_binop(OP_SUB, ast_variable('x'), ast_number(0));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_VARIABLE, "simp: x-0 → x");
    ast_free(result);

    /* 0/1 → 0 */
    mem_free_all();
    node = ast_binop(OP_DIV, ast_number(0), ast_number(1));
    result = ast_simplify(node);
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "simp: 0/1 → 0");
    ast_free(result);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    DIFFERENTIATION TESTS                     */
/* ═══════════════════════════════════════════════════════════ */

static void test_differentiation(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;
    printf("=== Differentiation ===\n");

    /* d/dx(x) = 1 */
    mem_free_all();
    expr = ast_variable('x');
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(x) non-null");
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "deriv: d/dx(x) is NUM");
    ASSERT_EQ_FLOAT(result->d.number, 1.0f, 0.01f, "deriv: d/dx(x) = 1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(5) = 0 */
    mem_free_all();
    expr = ast_number(5);
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(5) non-null");
    ASSERT_EQ_FLOAT(result->d.number, 0.0f, 0.01f, "deriv: d/dx(5) = 0");
    ast_free(result);
    ast_free(expr);

    /* d/dx(x^2) = 2x — evaluate at x=3 should give 6 */
    mem_free_all();
    expr = parse_str("x^2");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(x^2) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 3.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 6.0f, 0.1f, "deriv: d/dx(x^2)|x=3 = 6");
    ast_free(result);
    ast_free(expr);

    /* d/dx(x^3) at x=2 = 12 */
    mem_free_all();
    expr = parse_str("x^3");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(x^3) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 2.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 12.0f, 0.2f, "deriv: d/dx(x^3)|x=2 = 12");
    ast_free(result);
    ast_free(expr);

    /* d/dx(sin(x)) = cos(x) — check at x=0 */
    mem_free_all();
    expr = parse_str("sin(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(sin(x)) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "deriv: d/dx(sin(x))|0 = cos(0) = 1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(cos(x)) = -sin(x) — check at x=pi/2 */
    mem_free_all();
    expr = parse_str("cos(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(cos(x)) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', CE_PI / 2);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, -1.0f, 0.05f, "deriv: d/dx(cos)|pi/2 = -1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(e^x) = e^x — check at x=1 */
    mem_free_all();
    expr = parse_str("e^x");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(e^x) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 1.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, CE_E, 0.1f, "deriv: d/dx(e^x)|1 = e");
    ast_free(result);
    ast_free(expr);

    /* d/dx(ln(x)) = 1/x — check at x=2 */
    mem_free_all();
    expr = parse_str("ln(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: d/dx(ln(x)) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 2.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.5f, 0.01f, "deriv: d/dx(ln(x))|2 = 0.5");
    ast_free(result);
    ast_free(expr);

    /* Product rule: d/dx(x*sin(x)) at x=0 = sin(0)+0*cos(0) = 0 */
    mem_free_all();
    expr = parse_str("x*sin(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: product rule non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.05f, "deriv: d/dx(x*sin(x))|0 = 0");
    ast_free(result);
    ast_free(expr);

    /* Chain rule: d/dx(sin(2x)) at x=0 = 2*cos(0) = 2 */
    mem_free_all();
    expr = parse_str("sin(2*x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "deriv: chain rule non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 2.0f, 0.1f, "deriv: d/dx(sin(2x))|0 = 2");
    ast_free(result);
    ast_free(expr);

    /* Steps are recorded */
    ASSERT_TRUE(steps_count() > 0, "deriv: steps recorded");

    /* deriv_diff_quiet does not clobber steps */
    mem_free_all();
    steps_clear();
    steps_addf("test step");
    {
        uint8_t sc = (uint8_t)steps_count();
        expr = parse_str("x^2");
        result = deriv_diff_quiet(expr, 'x');
        ASSERT_TRUE(result != NULL, "deriv_quiet: non-null");
        ASSERT_EQ_INT(steps_count(), sc, "deriv_quiet: steps not clobbered");
        ast_free(result);
        ast_free(expr);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    INTEGRATION TESTS                        */
/* ═══════════════════════════════════════════════════════════ */

static void test_integration(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;
    ce_error_t err;

    printf("=== Integration ===\n");

    /* A numerator k*u' scales the primitive by k, not 1/k. Check
     * symbolic derivatives independently of definite integration's fallback. */
    {
        static const char *inputs[] = {
            "x/(x^2+1)", "x/(x^2+1)^2", "2*x/(x^2+1)",
            "x^3/(x^4+1)", "3*x/(x^2+1)", "-x/(x^2+1)",
            "x/(x^2-1)", "x*exp(x^2)", "x*cos(x^2)"
        };
        static const ce_float_t points[] = {-2.0f, -0.5f, 0.0f, 0.5f, 2.0f};
        unsigned i, j;
        for (i = 0; i < sizeof(inputs)/sizeof(inputs[0]); ++i) {
            ast_node_t *df;
            mem_free_all();
            expr = parse_str(inputs[i]);
            result = integrate(expr, 'x');
            ASSERT_TRUE(result != NULL, "usub coefficient: primitive exists");
            if (!result) continue;
            df = deriv_diff_quiet(result, 'x');
            ASSERT_TRUE(df != NULL, "usub coefficient: derivative exists");
            if (!df) continue;
            for (j = 0; j < sizeof(points)/sizeof(points[0]); ++j) {
                ce_float_t expected, actual;
                eval_init(&ctx);
                eval_set_var(&ctx, 'x', points[j]);
                expected = eval_expr(&ctx, expr);
                ASSERT_EQ_INT(ctx.error, CE_OK, "usub coefficient: input evaluates");
                actual = eval_expr(&ctx, df);
                ASSERT_EQ_INT(ctx.error, CE_OK, "usub coefficient: derivative evaluates");
                ASSERT_EQ_FLOAT(actual, expected, 0.0001f * (1.0f + fabsf(expected)),
                                "usub coefficient: dF/dx equals f");
            }
        }
        mem_free_all();
        expr = parse_str("x/(x^2+1)");
        val = integrate_definite(expr, 'x', 0, 1, NULL, 0, &err);
        ASSERT_EQ_INT(err, CE_OK, "usub coefficient: finite status");
        ASSERT_EQ_FLOAT(val, 0.5f*logf(2.0f), 0.00001f, "usub coefficient: ln(2)/2");
        mem_free_all();
        expr = parse_str("x^3/(x^4+1)");
        val = integrate_definite(expr, 'x', -1, 2, NULL, 0, &err);
        ASSERT_EQ_INT(err, CE_OK, "usub coefficient: quartic status");
        ASSERT_EQ_FLOAT(val, 0.25f*logf(8.5f), 0.00001f, "usub coefficient: ln(17/2)/4");
        mem_free_all();
        expr = parse_str("x/(x^2+1)^2");
        ASSERT_EQ_INT(integrate_improper(expr, 'x', 0, false, 0, true, &val),
                      IMPROP_OK, "usub coefficient: reciprocal square converges");
        ASSERT_EQ_FLOAT(val, 0.5f, 0.0001f, "usub coefficient: reciprocal square tail");
        mem_free_all();
        expr = parse_str("x/(x^2+1)-1/(x+1)");
        ASSERT_EQ_INT(integrate_improper(expr, 'x', 0, false, 0, true, &val),
                      IMPROP_OK, "usub coefficient: log tails cancel");
        ASSERT_TRUE(val == 0.0f, "usub coefficient: cancelled tail is exactly zero");
        mem_free_all();
        expr = parse_str("ln(abs(x^2+1))");
        ASSERT_TRUE(integrate_err_scale(expr, 'x', 0) == 0,
                    "usub coefficient: exact ln(abs(1)) has no rounding");
        mem_free_all();
        expr = parse_str("ln(1+x/100000000)");
        ASSERT_TRUE(integrate_err_scale(expr, 'x', 1) > 0,
                    "usub coefficient: rounded-to-one argument retains uncertainty");
        mem_free_all();
        expr = parse_str("abs(1+x/100000000)");
        ASSERT_TRUE(integrate_err_scale(expr, 'x', 1) > 0,
                    "usub coefficient: abs preserves child uncertainty");
        mem_free_all();
        expr = parse_str("x/(x^2+1)");
        val = integrate_definite(expr, 'x', 1000000, 1000001, NULL, 0, &err);
        ASSERT_TRUE(err != CE_OK, "usub coefficient: near-cancelling logabs still refuses");
        mem_free_all();
        expr = parse_str("x/(x^2+1)-1/(x+1)");
        ASSERT_EQ_INT(integrate_improper(expr, 'x', 0.1f, false, 0, true, &val),
                      IMPROP_OK, "usub coefficient: inexact finite bound converges");
        ASSERT_EQ_FLOAT(val, logf(1.1f)-0.5f*logf(1.01f), 0.00001f,
                        "usub coefficient: inexact finite bound is nonzero");
#ifndef CE_DISABLE_STEP_RECORDING
        mem_free_all();
        steps_clear();
        expr = parse_str("x*exp(x^2)");
        result = integrate(expr, 'x');
        ASSERT_TRUE(result != NULL, "usub coefficient: exponential primitive exists");
        {
            bool usub = false, scale = false;
            int step;
            for (step = 0; step < steps_count(); ++step) {
                if (strstr(steps_get(step), "Nonlinear u-sub")) usub = true;
                if (strstr(steps_get(step), "Derivative factor scale: 0.5")) scale = true;
            }
            ASSERT_TRUE(usub && scale, "usub coefficient: nonlinear path and half scale recorded");
        }
#endif
        mem_free_all();
    }

    /* int(1, x) = x — evaluate at x=5 */
    mem_free_all();
    expr = ast_number(1);
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(1) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 5.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 5.0f, 0.1f, "integ: int(1)|5 = 5");
    ast_free(result);
    ast_free(expr);

    /* int(x, x) = x^2/2 — evaluate at x=4 → 8 */
    mem_free_all();
    expr = ast_variable('x');
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(x) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 4.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 8.0f, 0.1f, "integ: int(x)|4 = 8");
    ast_free(result);
    ast_free(expr);

    /* int(x^2, x) = x^3/3 — evaluate at x=3 → 9 */
    mem_free_all();
    expr = parse_str("x^2");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(x^2) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 3.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 9.0f, 0.1f, "integ: int(x^2)|3 = 9");
    ast_free(result);
    ast_free(expr);

    /* int(sin(x)) = -cos(x) — check F(pi)-F(0) = -(-1)-(-1) = 2 */
    mem_free_all();
    expr = parse_str("sin(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(sin(x)) non-null");
    {
        ce_float_t fpi, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI);
        fpi = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fpi - f0, 2.0f, 0.05f, "integ: int(sin,0,pi) = 2");
    }
    ast_free(result);
    ast_free(expr);

    /* int(cos(x)) = sin(x) */
    mem_free_all();
    expr = parse_str("cos(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(cos(x)) non-null");
    ast_free(result);
    ast_free(expr);

    /* int(e^x) = e^x — check F(1)-F(0) = e-1 */
    mem_free_all();
    expr = parse_str("e^x");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(e^x) non-null");
    {
        ce_float_t f1, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(f1 - f0, CE_E - 1.0f, 0.1f,
                         "integ: int(e^x,0,1) = e-1");
    }
    ast_free(result);
    ast_free(expr);

    /* Definite integral: int(x^2, x, 0, 3) = 9 */
    mem_free_all();
    expr = parse_str("x^2");
    val = integrate_definite(expr, 'x', 0, 3,
                             NULL, 0, &err);
    ASSERT_EQ_INT(err, CE_OK, "integ_def: int(x^2,0,3) ok");
    ASSERT_EQ_FLOAT(val, 9.0f, 0.1f, "integ_def: int(x^2,0,3) = 9");
    ast_free(expr);

    /* Constant-multiple: int(3x^2) = x^3 — eval at x=2 → 8 */
    mem_free_all();
    expr = parse_str("3*x^2");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(3x^2) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 2.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 8.0f, 0.2f, "integ: int(3x^2)|2 = 8");
    ast_free(result);
    ast_free(expr);

    /* 1/x → ln|x| — check F(e)-F(1) = 1 */
    mem_free_all();
    expr = parse_str("1/x");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "integ: int(1/x) non-null");
    {
        ce_float_t fe, f1;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_E);
        fe = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fe - f1, 1.0f, 0.1f, "integ: int(1/x,1,e) = 1");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    LIMITS TESTS                             */
/* ═══════════════════════════════════════════════════════════ */

static void test_limits(void)
{
    ast_node_t *expr, *point;
    ce_float_t result;
    lim_status_t status;

    printf("=== Limits ===\n");

    /* lim x→2 of x^2 = 4 (direct sub) */
    mem_free_all();
    expr  = parse_str("x^2");
    point = ast_number(2);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: x^2 at 2 ok");
    ASSERT_EQ_FLOAT(result, 4.0f, 0.1f, "lim: x^2 at 2 = 4");
    ast_free(expr);
    ast_free(point);

    /* lim x→0 of sin(x)/x = 1 (special limit) */
    mem_free_all();
    expr  = parse_str("sin(x)/x");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: sin(x)/x at 0 ok");
    ASSERT_EQ_FLOAT(result, 1.0f, 0.01f, "lim: sin(x)/x at 0 = 1");
    ast_free(expr);
    ast_free(point);

    /* lim x→0 of (e^x-1)/x = 1 (special limit) */
    mem_free_all();
    expr  = parse_str("(e^x-1)/x");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: (e^x-1)/x at 0 ok");
    ASSERT_EQ_FLOAT(result, 1.0f, 0.01f, "lim: (e^x-1)/x = 1");
    ast_free(expr);
    ast_free(point);

    /* lim x→0 of (1-cos(x))/x^2 = 0.5 (special limit) */
    mem_free_all();
    expr  = parse_str("(1-cos(x))/x^2");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: (1-cos(x))/x^2 ok");
    ASSERT_EQ_FLOAT(result, 0.5f, 0.01f, "lim: (1-cos(x))/x^2 = 0.5");
    ast_free(expr);
    ast_free(point);

    /* lim x→inf of 1/x = 0 */
    mem_free_all();
    expr  = parse_str("1/x");
    point = ast_constant(CONST_INF);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: 1/x at inf ok");
    ASSERT_EQ_FLOAT(result, 0.0f, 0.01f, "lim: 1/x at inf = 0");
    ast_free(expr);
    ast_free(point);

    /* L'Hopital: lim x→0 of x^2/x = 0 (L'Hop 0/0) */
    mem_free_all();
    expr  = parse_str("x^2/x");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: x^2/x at 0 ok");
    ASSERT_EQ_FLOAT(result, 0.0f, 0.1f, "lim: x^2/x at 0 = 0");
    ast_free(expr);
    ast_free(point);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    SERIES TESTS                             */
/* ═══════════════════════════════════════════════════════════ */

static void test_series(void)
{
    ast_node_t *expr, *result;
    conv_info_t ci;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("=== Series ===\n");

    /* Geometric series: 1/2^n converges, sum = 1/(1-0.5) = 2 (from n=0)
     * But we test from n=1: a(1)=0.5, r=0.5, S = 0.5/(1-0.5) = 1 */
    mem_free_all();
    expr = parse_str("1/2^n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series: 1/2^n converges");
    ast_free(expr);

    /* Divergent: 1/n (harmonic) → p=1 */
    mem_free_all();
    expr = parse_str("1/n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series: 1/n diverges");
    ast_free(expr);

    /* Convergent: 1/n^2 */
    mem_free_all();
    expr = parse_str("1/n^2");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series: 1/n^2 converges");
    ast_free(expr);

    /* nth-term test: n diverges (lim a_n != 0) */
    mem_free_all();
    expr = parse_str("n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series: sum(n) diverges");
    ast_free(expr);

    /* Taylor: sin(x) at 0, degree 5 — check sin(0.5)≈0.479 */
    mem_free_all();
    expr = parse_str("sin(x)");
    result = taylor_series(expr, 'x', 0, 5);
    ASSERT_TRUE(result != NULL, "taylor: sin(x) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.5f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, sinf(0.5f), 0.01f, "taylor: sin(x) at 0.5");
    ast_free(result);
    ast_free(expr);

    /* Taylor: e^x at 0, degree 5 — check e^0.5≈1.649 */
    mem_free_all();
    expr = parse_str("e^x");
    result = taylor_series(expr, 'x', 0, 5);
    ASSERT_TRUE(result != NULL, "taylor: e^x non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.5f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, expf(0.5f), 0.05f, "taylor: e^x at 0.5");
    ast_free(result);
    ast_free(expr);

    /* Fourier: constant 1 → a0/2 = 1 */
    mem_free_all();
    expr = ast_number(1);
    result = fourier_series(expr, 'x', 3);
    ASSERT_TRUE(result != NULL, "fourier: const non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.5f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.1f, "fourier: const ≈ 1");
    ast_free(result);
    ast_free(expr);

    /* Power series radius: 1/n! → R = inf (ratio test) */
    mem_free_all();
    {
        ce_float_t R;
        expr = parse_str("1/n!");
        R = power_series_radius(expr, 'n');
        /* For 1/n!, a_n/a_{n+1} = (n+1)! / n! = n+1 → ∞, so R should be large */
        ASSERT_TRUE(R > 10.0f, "radius: 1/n! large R");
        ast_free(expr);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    ALGEBRA TESTS                            */
/* ═══════════════════════════════════════════════════════════ */

static void test_algebra(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;
    char buf[256];

    printf("=== Algebra ===\n");

    /* Expand: (x+1)^2 = x^2+2x+1 — eval at x=3 = 16 */
    mem_free_all();
    expr = parse_str("(x+1)^2");
    result = algebra_expand(expr, 'x');
    ASSERT_TRUE(result != NULL, "expand: (x+1)^2 non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 3.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 16.0f, 0.1f, "expand: (x+1)^2 at 3 = 16");
    ast_free(result);
    ast_free(expr);

    /* Expand: (x+1)(x-1) = x^2-1 */
    mem_free_all();
    expr = parse_str("(x+1)*(x-1)");
    result = algebra_expand(expr, 'x');
    ASSERT_TRUE(result != NULL, "expand: (x+1)(x-1) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 5.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 24.0f, 0.1f, "expand: (x+1)(x-1) at 5 = 24");
    ast_free(result);
    ast_free(expr);

    /* Factor: x^2-4 = (x-2)(x+2) */
    mem_free_all();
    expr = parse_str("x^2-4");
    result = algebra_factor(expr, 'x');
    ASSERT_TRUE(result != NULL, "factor: x^2-4 non-null");
    /* Verify by evaluating at x=2 (should be 0) */
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 2.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.1f, "factor: x^2-4 at x=2 = 0");
    ast_free(result);
    ast_free(expr);

    /* Factor: x^3-6x^2+11x-6 = (x-1)(x-2)(x-3) */
    mem_free_all();
    expr = parse_str("x^3-6*x^2+11*x-6");
    result = algebra_factor(expr, 'x');
    ASSERT_TRUE(result != NULL, "factor: cubic non-null");
    /* Should have root at x=1 */
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 1.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.1f, "factor: cubic(1) = 0");
    ast_free(result);
    ast_free(expr);

    /* Solve: linear 2x+6=0 → x=-3 */
    mem_free_all();
    expr = parse_str("2*x+6");
    algebra_solve(expr, 'x', buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "-3", "solve: 2x+6 → x=-3");
    ast_free(expr);

    /* Solve: quadratic x^2-9=0 → x=3 or x=-3 */
    mem_free_all();
    expr = parse_str("x^2-9");
    algebra_solve(expr, 'x', buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "3", "solve: x^2-9 has root 3");
    ast_free(expr);

    /* Solve: complex x^2+1=0 → complex roots */
    mem_free_all();
    expr = parse_str("x^2+1");
    algebra_solve(expr, 'x', buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "i", "solve: x^2+1 has complex roots");
    ast_free(expr);

    /* Polynomial division: (x^2-1)/(x-1) = x+1, R=0 */
    mem_free_all();
    {
        ast_node_t *dividend = parse_str("x^2-1");
        ast_node_t *divisor  = parse_str("x-1");
        char rem_buf[64];

        result = algebra_poly_div(dividend, divisor, 'x',
                                   rem_buf, sizeof(rem_buf));
        ASSERT_TRUE(result != NULL, "polydiv: (x^2-1)/(x-1) non-null");
        ASSERT_TRUE(strcmp(rem_buf, "0") == 0, "polydiv: remainder = 0");

        /* Quotient should be x+1, eval at x=5 → 6 */
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 5.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 6.0f, 0.1f, "polydiv: (x^2-1)/(x-1) at 5 = 6");

        ast_free(result);
        ast_free(dividend);
        ast_free(divisor);
    }

    /* Trig simplification: sin^2(x)+cos^2(x) = 1 */
    mem_free_all();
    expr = parse_str("sin(x)^2+cos(x)^2");
    result = algebra_trig_simplify(expr);
    ASSERT_TRUE(result != NULL, "trig_simp: sin^2+cos^2 non-null");
    ASSERT_EQ_INT(result->type, NODE_NUMBER, "trig_simp: result is NUM");
    ASSERT_EQ_FLOAT(result->d.number, 1.0f, 0.01f, "trig_simp: = 1");
    ast_free(result);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    AST UTILITY TESTS                        */
/* ═══════════════════════════════════════════════════════════ */

static void test_ast_utils(void)
{
    ast_node_t *orig, *clone;
    char buf1[128], buf2[128];

    printf("=== AST Utilities ===\n");

    mem_free_all();

    /* Clone fidelity */
    orig = parse_str("sin(x^2)+3*cos(x)");
    ASSERT_TRUE(orig != NULL, "ast: complex expr non-null");
    clone = ast_clone(orig);
    ASSERT_TRUE(clone != NULL, "ast: clone non-null");

    ast_to_str(orig, buf1, sizeof(buf1));
    ast_to_str(clone, buf2, sizeof(buf2));
    ASSERT_TRUE(strcmp(buf1, buf2) == 0, "ast: clone matches original");

    /* ast_contains_var */
    ASSERT_TRUE(ast_contains_var(orig, 'x'), "ast: contains x");
    ASSERT_TRUE(!ast_contains_var(orig, 'y'), "ast: doesn't contain y");

    ast_free(orig);
    ast_free(clone);

    /* Clone of NULL is safe */
    ASSERT_TRUE(ast_clone(NULL) == NULL, "ast: clone(NULL) = NULL");

    /* Free NULL is safe */
    ast_free(NULL);  /* should not crash */
    ASSERT_TRUE(1, "ast: free(NULL) safe");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    STEPS MODULE TESTS                        */
/* ═══════════════════════════════════════════════════════════ */

static void test_steps(void)
{
    printf("=== Steps ===\n");

    steps_clear();
    ASSERT_EQ_INT(steps_count(), 0, "steps: clear → 0");

    steps_add("Line 1");
    steps_add("Line 2");
    ASSERT_EQ_INT(steps_count(), 2, "steps: add 2");
    ASSERT_TRUE(strcmp(steps_get(0), "Line 1") == 0, "steps: get(0)");
    ASSERT_TRUE(strcmp(steps_get(1), "Line 2") == 0, "steps: get(1)");

    steps_addf("Value = %d", 42);
    ASSERT_TRUE(strstr(steps_get(2), "42") != NULL, "steps: addf");

    /* Out of bounds returns "" */
    ASSERT_TRUE(strcmp(steps_get(100), "") == 0, "steps: oob = ''");
    ASSERT_TRUE(strcmp(steps_get(-1), "") == 0, "steps: negative index = ''");

    /* Guard clauses */
    ASSERT_TRUE(!steps_add(NULL), "steps: add(NULL) rejected");
    ASSERT_TRUE(!steps_addf(NULL), "steps: addf(NULL) rejected");

    /* Restore */
    {
        uint8_t saved = (uint8_t)steps_count();
        steps_add("extra");
        steps_restore(saved);
        ASSERT_EQ_INT(steps_count(), saved, "steps: restore works");
    }

    /* Overflow protection */
    steps_clear();
    {
        int i;
        for (i = 0; i < MAX_STEPS + 5; i++)
            steps_add("line");
        ASSERT_EQ_INT(steps_count(), MAX_STEPS, "steps: overflow capped");
    }
}

/* ═══════════════════════════════════════════════════════════ */
/*                    EDGE CASE TESTS                          */
/* ═══════════════════════════════════════════════════════════ */

static void test_edge_cases(void)
{
    ce_error_t err;
    ce_float_t val;
    ast_node_t *root;

    printf("=== Edge Cases ===\n");

    mem_free_all();

    /* Empty input */
    root = parse_str("");
    ASSERT_TRUE(root == NULL, "edge: empty input → NULL");

    /* Nested parens */
    val = eval_str("((((5))))", &err);
    ASSERT_EQ_INT(err, CE_OK, "edge: nested parens ok");
    ASSERT_EQ_FLOAT(val, 5.0f, 0.01f, "edge: ((5)) = 5");

    /* Chained multiplication */
    val = eval_str("2*3*4", &err);
    ASSERT_EQ_FLOAT(val, 24.0f, 0.01f, "edge: 2*3*4 = 24");

    /* Unary minus chain */
    val = eval_str("--5", &err);
    /* --5 parses as -(-5) = 5 */
    ASSERT_EQ_INT(err, CE_OK, "edge: --5 ok");
    ASSERT_EQ_FLOAT(val, 5.0f, 0.01f, "edge: --5 = 5");

    /* Large factorial */
    val = eval_str("12!", &err);
    ASSERT_EQ_INT(err, CE_OK, "edge: 12! ok");
    ASSERT_EQ_FLOAT(val, 479001600.0f, 1.0f, "edge: 12! = 479001600");

    /* Factorial overflow guard: 13! → 0 */
    val = eval_str("13!", &err);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.01f, "edge: 13! = 0 (overflow guard)");

    /* pi * e */
    val = eval_str("pi*e", &err);
    ASSERT_EQ_FLOAT(val, CE_PI * CE_E, 0.01f, "edge: pi*e");

    /* Implicit mul: 3(2+1) = 9 */
    val = eval_str("3(2+1)", &err);
    ASSERT_EQ_FLOAT(val, 9.0f, 0.01f, "edge: 3(2+1) = 9");

    /* Trig identity: sin(pi/6) ≈ 0.5 */
    val = eval_str("sin(pi/6)", &err);
    ASSERT_EQ_FLOAT(val, 0.5f, 0.01f, "edge: sin(pi/6) = 0.5");

    /* sec/csc/cot */
    val = eval_str("sec(0)", &err);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "edge: sec(0) = 1");

    /* Syntax error */
    root = parse_str("2++");
    ASSERT_TRUE(root == NULL, "edge: '2++' parse error");

    /* Mismatched parens */
    root = parse_str("(2+3");
    ASSERT_TRUE(root == NULL, "edge: '(2+3' parse error");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*               CALC 2 INTEGRATION TESTS                      */
/* ═══════════════════════════════════════════════════════════ */

static void test_calc2_integration(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;
    ce_error_t err;

    printf("=== Calc 2: Integration ===\n");

    /* ── Integration by parts: x*e^x ───────────────────── */
    /* int(x*e^x) = x*e^x - e^x;  F(1)-F(0) = 1*e-e - (0-1) = 1 */
    mem_free_all();
    expr = parse_str("x*e^x");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "ibp: int(x*e^x) non-null");
    if (result) {
        ce_float_t f1, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(f1 - f0, 1.0f, 0.2f, "ibp: int(x*e^x,0,1) = 1");
    }
    ast_free(result);
    ast_free(expr);

    /* ── Integration by parts: x*sin(x) ────────────────── */
    /* int(x*sin(x)) = sin(x)-x*cos(x); F(pi)-F(0)=0-(-pi)-(0-0)=pi */
    mem_free_all();
    expr = parse_str("x*sin(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "ibp: int(x*sin(x)) non-null");
    if (result) {
        ce_float_t fpi, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI);
        fpi = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fpi - f0, CE_PI, 0.3f, "ibp: int(x*sin(x),0,pi) ~ pi");
    }
    ast_free(result);
    ast_free(expr);

    /* ── u-sub: sin(2x) ───────────────────────────────── */
    /* int(sin(2x)) = -cos(2x)/2; F(pi/2)-F(0) = -cos(pi)/2-(-cos(0)/2) = 1 */
    mem_free_all();
    expr = parse_str("sin(2*x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "usub: int(sin(2x)) non-null");
    if (result) {
        ce_float_t fh, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI / 2);
        fh = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fh - f0, 1.0f, 0.1f, "usub: int(sin(2x),0,pi/2) = 1");
    }
    ast_free(result);
    ast_free(expr);

    /* ── u-sub: e^(3x) ────────────────────────────────── */
    /* int(e^(3x)) = e^(3x)/3; F(1)-F(0) = (e^3-1)/3 */
    mem_free_all();
    expr = parse_str("e^(3*x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "usub: int(e^(3x)) non-null");
    if (result) {
        ce_float_t f1, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(f1 - f0, (expf(3.0f) - 1.0f) / 3.0f, 0.3f,
                         "usub: int(e^(3x),0,1) = (e^3-1)/3");
    }
    ast_free(result);
    ast_free(expr);

    /* ── sec(x)*tan(x) → sec(x) ───────────────────────── */
    mem_free_all();
    expr = parse_str("sec(x)*tan(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trig: int(sec*tan) non-null");
    if (result) {
        /* sec(x) evaluated at x=0 = 1 */
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "trig: int(sec*tan)|0 = sec(0) = 1");
    }
    ast_free(result);
    ast_free(expr);

    /* ── 1/(1+x^2) → atan(x) ──────────────────────────── */
    /* int(1/(1+x^2),0,1) = atan(1) - atan(0) = pi/4 */
    mem_free_all();
    expr = parse_str("1/(1+x^2)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "invtrig: int(1/(1+x^2)) non-null");
    if (result) {
        ce_float_t f1, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(f1 - f0, CE_PI / 4, 0.01f,
                         "invtrig: int(1/(1+x^2),0,1) = pi/4");
    }
    ast_free(result);
    ast_free(expr);

    /* ── 1/sqrt(1-x^2) → asin(x) ─────────────────────── */
    /* int(1/sqrt(1-x^2), 0, 0.5) = asin(0.5) - asin(0) = pi/6 */
    mem_free_all();
    expr = parse_str("1/sqrt(1-x^2)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "invtrig: int(1/sqrt(1-x^2)) non-null");
    if (result) {
        ce_float_t fh, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        fh = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fh - f0, CE_PI / 6, 0.01f,
                         "invtrig: int(1/sqrt(1-x^2),0,0.5) = pi/6");
    }
    ast_free(result);
    ast_free(expr);

    /* ── sin^2(x): int(sin^2,0,pi) = pi/2 ─────────────── */
    mem_free_all();
    expr = parse_str("sin(x)^2");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trig2: int(sin^2) non-null");
    if (result) {
        ce_float_t fpi, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI);
        fpi = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fpi - f0, CE_PI / 2, 0.05f,
                         "trig2: int(sin^2,0,pi) = pi/2");
    }
    ast_free(result);
    ast_free(expr);

    /* ── cos^2(x): int(cos^2,0,pi) = pi/2 ─────────────── */
    mem_free_all();
    expr = parse_str("cos(x)^2");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trig2: int(cos^2) non-null");
    if (result) {
        ce_float_t fpi, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI);
        fpi = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fpi - f0, CE_PI / 2, 0.05f,
                         "trig2: int(cos^2,0,pi) = pi/2");
    }
    ast_free(result);
    ast_free(expr);

    /* ── tan^2(x): int(tan^2,0,pi/4) = 1-pi/4 ────────── */
    mem_free_all();
    expr = parse_str("tan(x)^2");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trig2: int(tan^2) non-null");
    if (result) {
        ce_float_t fq, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI / 4);
        fq = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fq - f0, 1.0f - CE_PI / 4, 0.05f,
                         "trig2: int(tan^2,0,pi/4) = 1-pi/4");
    }
    ast_free(result);
    ast_free(expr);

    /* ── int(atan(x)) by parts: x*atan(x)-ln(1+x^2)/2 ── */
    mem_free_all();
    expr = parse_str("atan(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "ibp: int(atan(x)) non-null");
    if (result) {
        ce_float_t f1, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        f1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        /* Expected: 1*atan(1) - ln(2)/2 = pi/4 - ln(2)/2 ≈ 0.4388 */
        ASSERT_EQ_FLOAT(f1 - f0, CE_PI / 4 - logf(2) / 2, 0.05f,
                         "ibp: int(atan(x),0,1)");
    }
    ast_free(result);
    ast_free(expr);

    /* ── Definite: int(1/(1+x^2), -1, 1) = pi/2 ──────── */
    mem_free_all();
    expr = parse_str("1/(1+x^2)");
    val = integrate_definite(expr, 'x', -1, 1, NULL, 0, &err);
    ASSERT_EQ_INT(err, CE_OK, "def: int(1/(1+x^2),-1,1) ok");
    ASSERT_EQ_FLOAT(val, CE_PI / 2, 0.05f,
                     "def: int(1/(1+x^2),-1,1) = pi/2");
    ast_free(expr);

    /* ── Sum/diff rule: int(sin+cos) ──────────────────── */
    mem_free_all();
    expr = parse_str("sin(x)+cos(x)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "sum: int(sin+cos) non-null");
    if (result) {
        /* F(pi/2)-F(0) = [-cos(pi/2)+sin(pi/2)] - [-cos(0)+sin(0)]
         *              = [0+1] - [-1+0] = 1+1 = 2 */
        ce_float_t fh, f0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', CE_PI / 2);
        fh = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        f0 = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(fh - f0, 2.0f, 0.1f,
                         "sum: int(sin+cos,0,pi/2) = 2");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*               CALC 2 DERIVATIVE TESTS                       */
/* ═══════════════════════════════════════════════════════════ */

static void test_calc2_derivatives(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("=== Calc 2: Derivatives ===\n");

    /* d/dx(tan(x)) = sec^2(x), at x=0 → 1 */
    mem_free_all();
    expr = parse_str("tan(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(tan) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "d: d/dx(tan)|0 = sec^2(0) = 1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(sec(x)) = sec(x)*tan(x), at x=0 → 0 */
    mem_free_all();
    expr = parse_str("sec(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(sec) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.01f, "d: d/dx(sec)|0 = 0");
    ast_free(result);
    ast_free(expr);

    /* d/dx(e^(2x)) = 2*e^(2x), at x=0 → 2 */
    mem_free_all();
    expr = parse_str("e^(2*x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(e^(2x)) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 2.0f, 0.1f, "d: d/dx(e^(2x))|0 = 2");
    ast_free(result);
    ast_free(expr);

    /* d/dx(asin(x)) = 1/sqrt(1-x^2), at x=0 → 1 */
    mem_free_all();
    expr = parse_str("asin(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(asin) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "d: d/dx(asin)|0 = 1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(atan(x)) = 1/(1+x^2), at x=0 → 1 */
    mem_free_all();
    expr = parse_str("atan(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(atan) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "d: d/dx(atan)|0 = 1");
    ast_free(result);
    ast_free(expr);

    /* d/dx(x/(x+1)) at x=0 = 1/(1+0)^2 = 1 (quotient rule) */
    mem_free_all();
    expr = parse_str("x/(x+1)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: quotient non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 0.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 1.0f, 0.05f, "d: d/dx(x/(x+1))|0 = 1");
    ast_free(result);
    ast_free(expr);

    /* Chain: d/dx(sin(x^2)) at x=1 = 2*cos(1) ≈ 1.0806 */
    mem_free_all();
    expr = parse_str("sin(x^2)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: chain sin(x^2) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 1.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 2.0f * cosf(1.0f), 0.1f,
                     "d: d/dx(sin(x^2))|1 = 2cos(1)");
    ast_free(result);
    ast_free(expr);

    /* d/dx(sqrt(x)) = 1/(2*sqrt(x)), at x=4 → 1/4 */
    mem_free_all();
    expr = parse_str("sqrt(x)");
    result = deriv_diff(expr, 'x');
    ASSERT_TRUE(result != NULL, "d: d/dx(sqrt) non-null");
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', 4.0f);
    val = eval_expr(&ctx, result);
    ASSERT_EQ_FLOAT(val, 0.25f, 0.01f, "d: d/dx(sqrt(x))|4 = 0.25");
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*               CALC 2 LIMIT TESTS                            */
/* ═══════════════════════════════════════════════════════════ */

static void test_calc2_limits(void)
{
    ast_node_t *expr, *point;
    ce_float_t result;
    lim_status_t status;

    printf("=== Calc 2: Limits ===\n");

    /* L'Hôpital 0/0: lim x→1 of (x^2-1)/(x-1) = 2 */
    mem_free_all();
    expr  = parse_str("(x^2-1)/(x-1)");
    point = ast_number(1);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: (x^2-1)/(x-1) at 1 ok");
    ASSERT_EQ_FLOAT(result, 2.0f, 0.1f, "lim: (x^2-1)/(x-1) = 2");
    ast_free(expr);
    ast_free(point);

    /* lim x→0 of tan(x)/x = 1 (special) */
    mem_free_all();
    expr  = parse_str("tan(x)/x");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: tan(x)/x at 0 ok");
    ASSERT_EQ_FLOAT(result, 1.0f, 0.01f, "lim: tan(x)/x = 1");
    ast_free(expr);
    ast_free(point);

    /* lim x→inf of (3x^2+1)/(x^2+2) = 3 */
    mem_free_all();
    expr  = parse_str("(3*x^2+1)/(x^2+2)");
    point = ast_constant(CONST_INF);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: rational at inf ok");
    ASSERT_EQ_FLOAT(result, 3.0f, 0.1f, "lim: (3x^2+1)/(x^2+2) = 3");
    ast_free(expr);
    ast_free(point);

    /* One-sided: lim x→0+ of 1/x = +inf */
    mem_free_all();
    expr  = parse_str("1/x");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 1, &result);
    ASSERT_EQ_INT(status, LIM_POS_INF, "lim: 1/x at 0+ = +inf");
    ast_free(expr);
    ast_free(point);

    /* lim x→0 of x*sin(1/x) = 0 (squeeze) */
    /* This requires numerical approach */
    mem_free_all();
    expr  = parse_str("x*sin(1/x)");
    point = ast_number(0);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_TRUE(status == LIM_OK || status == LIM_FAILED,
                "lim: x*sin(1/x) at 0 returns valid status");
    if (status == LIM_OK) {
        ASSERT_EQ_FLOAT(result, 0.0f, 0.1f, "lim: x*sin(1/x) at 0 ~ 0");
    }
    ast_free(expr);
    ast_free(point);

    /* lim x→inf of sin(x)/x = 0 */
    mem_free_all();
    expr  = parse_str("sin(x)/x");
    point = ast_constant(CONST_INF);
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_EQ_INT(status, LIM_OK, "lim: sin(x)/x at inf ok");
    ASSERT_EQ_FLOAT(result, 0.0f, 0.01f, "lim: sin(x)/x at inf = 0");
    ast_free(expr);
    ast_free(point);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*               CALC 2 SERIES TESTS                           */
/* ═══════════════════════════════════════════════════════════ */

static void test_calc2_series(void)
{
    ast_node_t *expr, *result;
    conv_info_t ci;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("=== Calc 2: Series ===\n");

    /* p-series: 1/n^3 converges */
    mem_free_all();
    expr = parse_str("1/n^3");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series: 1/n^3 converges");
    ast_free(expr);

    /* Alternating: (-1)^n/n converges */
    mem_free_all();
    expr = parse_str("(-1)^n/n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series: alt 1/n converges");
    ast_free(expr);

    /* nth-term: 2^n diverges */
    mem_free_all();
    expr = parse_str("2^n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series: 2^n diverges");
    ast_free(expr);

    /* p-series: 1/sqrt(n) = 1/n^0.5 diverges (p=0.5 < 1) */
    mem_free_all();
    expr = parse_str("1/sqrt(n)");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series: 1/sqrt(n) diverges");
    ast_free(expr);

    /* Geometric: (2/3)^n converges */
    mem_free_all();
    expr = parse_str("(2/3)^n");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series: (2/3)^n converges");
    ast_free(expr);

    /* Taylor: cos(x) at 0, degree 6 — check cos(0.5) */
    mem_free_all();
    expr = parse_str("cos(x)");
    result = taylor_series(expr, 'x', 0, 6);
    ASSERT_TRUE(result != NULL, "taylor: cos(x) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, cosf(0.5f), 0.01f, "taylor: cos(0.5) accurate");
    }
    ast_free(result);
    ast_free(expr);

    /* Taylor: 1/(1-x) at 0, degree 5 → 1+x+x^2+...+x^5 */
    mem_free_all();
    expr = parse_str("1/(1-x)");
    result = taylor_series(expr, 'x', 0, 5);
    ASSERT_TRUE(result != NULL, "taylor: 1/(1-x) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.3f);
        val = eval_expr(&ctx, result);
        /* 1/(1-0.3) = 1.4286, Taylor approx should be close */
        ASSERT_EQ_FLOAT(val, 1.0f / 0.7f, 0.01f, "taylor: 1/(1-0.3) ≈ 1.4286");
    }
    ast_free(result);
    ast_free(expr);

    /* Power series: x^n/n → R=1 (ratio: a(n)/a(n+1) = (n+1)/n → 1) */
    mem_free_all();
    {
        ce_float_t R;
        expr = parse_str("1/n");
        R = power_series_radius(expr, 'n');
        ASSERT_EQ_FLOAT(R, 1.0f, 0.2f, "radius: 1/n → R=1");
        ast_free(expr);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: HIGHER-ORDER DERIVATIVES                   */
/* ═══════════════════════════════════════════════════════════ */

static void test_higher_order_deriv(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("=== Higher-Order Derivatives ===\n");

    /* d^2/dx^2(x^3) = 6x */
    mem_free_all();
    expr = parse_str("x^3");
    result = deriv_nth(expr, 'x', 2);
    ASSERT_TRUE(result != NULL, "d2: x^3 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 12.0f, 0.1f, "d2: x^3 at x=2 = 12");
    }
    ast_free(result);
    ast_free(expr);

    /* d^3/dx^3(x^4) = 24x */
    mem_free_all();
    expr = parse_str("x^4");
    result = deriv_nth(expr, 'x', 3);
    ASSERT_TRUE(result != NULL, "d3: x^4 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 24.0f, 0.1f, "d3: x^4 at x=1 = 24");
    }
    ast_free(result);
    ast_free(expr);

    /* d^2/dx^2(sin(x)) = -sin(x) */
    mem_free_all();
    expr = parse_str("sin(x)");
    result = deriv_nth(expr, 'x', 2);
    ASSERT_TRUE(result != NULL, "d2: sin(x) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, -sinf(1.0f), 0.05f, "d2: sin(x) at x=1 = -sin(1)");
    }
    ast_free(result);
    ast_free(expr);

    /* d^4/dx^4(sin(x)) = sin(x) (full cycle) */
    mem_free_all();
    expr = parse_str("sin(x)");
    result = deriv_nth(expr, 'x', 4);
    ASSERT_TRUE(result != NULL, "d4: sin(x) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, sinf(0.5f), 0.05f, "d4: sin(x) at x=0.5 = sin(0.5)");
    }
    ast_free(result);
    ast_free(expr);

    /* d^2/dx^2(e^x) = e^x */
    mem_free_all();
    expr = parse_str("e^x");
    result = deriv_nth(expr, 'x', 2);
    ASSERT_TRUE(result != NULL, "d2: e^x non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, expf(1.0f), 0.1f, "d2: e^x at x=1 = e");
    }
    ast_free(result);
    ast_free(expr);

    /* d^0/dx^0(x^2) = x^2 (identity) */
    mem_free_all();
    expr = parse_str("x^2");
    result = deriv_nth(expr, 'x', 0);
    ASSERT_TRUE(result != NULL, "d0: x^2 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 9.0f, 0.1f, "d0: x^2 at x=3 = 9");
    }
    ast_free(result);
    ast_free(expr);

    /* d^5/dx^5(x^4) = 0 (derivative of constant) */
    mem_free_all();
    expr = parse_str("x^4");
    result = deriv_nth(expr, 'x', 5);
    ASSERT_TRUE(result != NULL, "d5: x^4 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 5.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 0.0f, 0.1f, "d5: x^4 at x=5 = 0");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: IMPLICIT DIFFERENTIATION                   */
/* ═══════════════════════════════════════════════════════════ */

static void test_implicit_diff(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("=== Implicit Differentiation ===\n");

    /* x^2 + y^2 - 25 = 0 (circle)
     * f_x = 2x, f_y = 2y
     * dy/dx = -2x / 2y = -x/y
     * At (3,4): dy/dx = -3/4 = -0.75 */
    mem_free_all();
    expr = parse_str("x^2+y^2-25");
    result = deriv_implicit(expr, 'x', 'y');
    ASSERT_TRUE(result != NULL, "implicit: circle non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        eval_set_var(&ctx, 'y', 4.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, -0.75f, 0.05f, "implicit: circle dy/dx(3,4) = -0.75");
    }
    ast_free(result);
    ast_free(expr);

    /* x*y - 6 = 0  → dy/dx = -y/x
     * At (2,3): dy/dx = -3/2 = -1.5 */
    mem_free_all();
    expr = parse_str("x*y-6");
    result = deriv_implicit(expr, 'x', 'y');
    ASSERT_TRUE(result != NULL, "implicit: xy=6 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        eval_set_var(&ctx, 'y', 3.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, -1.5f, 0.05f, "implicit: xy=6 dy/dx(2,3) = -1.5");
    }
    ast_free(result);
    ast_free(expr);

    /* x^3 + y^3 - 9 = 0
     * f_x = 3x^2, f_y = 3y^2
     * dy/dx = -x^2/y^2
     * At (1,2): dy/dx = -1/4 = -0.25 */
    mem_free_all();
    expr = parse_str("x^3+y^3-9");
    result = deriv_implicit(expr, 'x', 'y');
    ASSERT_TRUE(result != NULL, "implicit: x^3+y^3 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        eval_set_var(&ctx, 'y', 2.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, -0.25f, 0.05f, "implicit: x^3+y^3 dy/dx(1,2) = -0.25");
    }
    ast_free(result);
    ast_free(expr);

    /* y^2 - x = 0 (parabola)
     * f_x = -1, f_y = 2y
     * dy/dx = 1/(2y)
     * At (4,2): dy/dx = 1/4 = 0.25 */
    mem_free_all();
    expr = parse_str("y^2-x");
    result = deriv_implicit(expr, 'x', 'y');
    ASSERT_TRUE(result != NULL, "implicit: y^2=x non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 4.0f);
        eval_set_var(&ctx, 'y', 2.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, 0.25f, 0.05f, "implicit: y^2=x dy/dx(4,2) = 0.25");
    }
    ast_free(result);
    ast_free(expr);

    /* e^(x*y) - 1 = 0 is harder; test simpler: x+y-5=0 → dy/dx = -1 */
    mem_free_all();
    expr = parse_str("x+y-5");
    result = deriv_implicit(expr, 'x', 'y');
    ASSERT_TRUE(result != NULL, "implicit: x+y=5 non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        eval_set_var(&ctx, 'y', 3.0f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, -1.0f, 0.05f, "implicit: x+y=5 dy/dx = -1");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: TRIGONOMETRIC SUBSTITUTION                  */
/* ═══════════════════════════════════════════════════════════ */

static void test_trig_substitution(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val, expected;

    printf("=== Trig Substitution ===\n");

    /* int(1/sqrt(1-x^2)) = asin(x) — should already work via inverse trig,
     * but verify through the trig sub path too */
    mem_free_all();
    expr = parse_str("1/sqrt(1-x^2)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/sqrt(1-x^2) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        val = eval_expr(&ctx, result);
        ASSERT_EQ_FLOAT(val, asinf(0.5f), 0.05f, "trigsub: 1/sqrt(1-x^2) = asin(0.5)");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/sqrt(4-x^2)) = asin(x/2) */
    mem_free_all();
    expr = parse_str("1/sqrt(4-x^2)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/sqrt(4-x^2) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        val = eval_expr(&ctx, result);
        expected = asinf(0.5f); /* asin(1/2) */
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "trigsub: 1/sqrt(4-x^2) at x=1");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/sqrt(x^2+1)) = ln|x+sqrt(x^2+1)| */
    mem_free_all();
    expr = parse_str("1/sqrt(x^2+1)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/sqrt(x^2+1) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        val = eval_expr(&ctx, result);
        expected = logf(1.0f + sqrtf(2.0f)); /* ln(1+sqrt(2)) ≈ 0.8814 */
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "trigsub: 1/sqrt(x^2+1) at x=1");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/sqrt(x^2+4)) = ln|x+sqrt(x^2+4)| */
    mem_free_all();
    expr = parse_str("1/sqrt(x^2+4)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/sqrt(x^2+4) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        val = eval_expr(&ctx, result);
        expected = logf(2.0f + sqrtf(8.0f)); /* ln(2+2sqrt(2)) */
        ASSERT_EQ_FLOAT(val, expected, 0.1f, "trigsub: 1/sqrt(x^2+4) at x=2");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/sqrt(x^2-1)) = ln|x+sqrt(x^2-1)| for x>1 */
    mem_free_all();
    expr = parse_str("1/sqrt(x^2-1)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/sqrt(x^2-1) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        val = eval_expr(&ctx, result);
        expected = logf(2.0f + sqrtf(3.0f)); /* ln(2+sqrt(3)) */
        ASSERT_EQ_FLOAT(val, expected, 0.1f, "trigsub: 1/sqrt(x^2-1) at x=2");
    }
    ast_free(result);
    ast_free(expr);

    /* int(sqrt(1-x^2)) = (x/2)*sqrt(1-x^2) + (1/2)*asin(x) */
    mem_free_all();
    expr = parse_str("sqrt(1-x^2)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: sqrt(1-x^2) non-null");
    if (result) {
        /* Definite: int_0^1 sqrt(1-x^2) dx = pi/4 (quarter circle area) */
        /* Evaluate F(0.5) - F(0) = (0.25)*sqrt(0.75) + 0.5*asin(0.5) - 0 */
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        val = eval_expr(&ctx, result);
        expected = (0.25f) * sqrtf(0.75f) + 0.5f * asinf(0.5f);
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "trigsub: sqrt(1-x^2) at x=0.5");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/(x^2+4)) = (1/2)*atan(x/2) */
    mem_free_all();
    expr = parse_str("1/(x^2+4)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "trigsub: 1/(x^2+4) non-null");
    if (result) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        val = eval_expr(&ctx, result);
        expected = 0.5f * atanf(1.0f); /* (1/2)*atan(2/2) = (1/2)*pi/4 */
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "trigsub: 1/(x^2+4) at x=2");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: PARTIAL FRACTIONS                           */
/* ═══════════════════════════════════════════════════════════ */

static void test_partial_fractions(void)
{
    ast_node_t *expr, *result;
    eval_ctx_t ctx;
    ce_float_t val, expected;

    printf("=== Partial Fractions ===\n");

    /* int(1/(x*(x+1))) = ln|x| - ln|x+1|
     * Verify: F(2) - F(1) should be numerically correct */
    mem_free_all();
    expr = parse_str("1/(x*(x+1))");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "pf: 1/(x(x+1)) non-null");
    if (result) {
        ce_float_t F2, F1;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        F2 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        F1 = eval_expr(&ctx, result);
        val = F2 - F1;
        /* Exact: ln(2)-ln(3)-ln(1)+ln(2) = 2*ln(2)-ln(3) ≈ 0.2877 */
        expected = 2.0f * logf(2.0f) - logf(3.0f);
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "pf: int 1/(x(x+1)) from 1 to 2");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/(x*(x+2))) = (1/2)*ln|x| - (1/2)*ln|x+2| */
    mem_free_all();
    expr = parse_str("1/(x*(x+2))");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "pf: 1/(x(x+2)) non-null");
    if (result) {
        ce_float_t F3, F1;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        F3 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        F1 = eval_expr(&ctx, result);
        val = F3 - F1;
        /* Exact: (1/2)[ln(3)-ln(5)-ln(1)+ln(3)] = (1/2)[2ln3-ln5] */
        expected = 0.5f * (2.0f * logf(3.0f) - logf(5.0f));
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "pf: int 1/(x(x+2)) from 1 to 3");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/((x+1)*(x+3))) = (1/2)[ln|x+1|-ln|x+3|] */
    mem_free_all();
    expr = parse_str("1/((x+1)*(x+3))");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "pf: 1/((x+1)(x+3)) non-null");
    if (result) {
        ce_float_t F1, F0;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        F1 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        F0 = eval_expr(&ctx, result);
        val = F1 - F0;
        /* At x=1: (1/2)[ln(2)-ln(4)] = (1/2)[-ln(2)]
         * At x=0: (1/2)[ln(1)-ln(3)] = (1/2)[-ln(3)]
         * F(1)-F(0) = (1/2)[-ln(2)+ln(3)] = (1/2)*ln(3/2) ≈ 0.2027 */
        expected = 0.5f * logf(1.5f);
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "pf: int 1/((x+1)(x+3)) from 0 to 1");
    }
    ast_free(result);
    ast_free(expr);

    /* int(1/(x^2-4)) = partial fractions of 1/((x-2)(x+2))
     * = (1/4)*ln|x-2| - (1/4)*ln|x+2| */
    mem_free_all();
    expr = parse_str("1/(x^2-4)");
    result = integrate(expr, 'x');
    ASSERT_TRUE(result != NULL, "pf: 1/(x^2-4) non-null");
    if (result) {
        ce_float_t F5, F3;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 5.0f);
        F5 = eval_expr(&ctx, result);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        F3 = eval_expr(&ctx, result);
        val = F5 - F3;
        /* (1/4)[ln3-ln7-ln1+ln5] = (1/4)[ln15-ln7] = (1/4)*ln(15/7) */
        expected = 0.25f * logf(15.0f / 7.0f);
        ASSERT_EQ_FLOAT(val, expected, 0.05f, "pf: int 1/(x^2-4) from 3 to 5");
    }
    ast_free(result);
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: IMPROPER INTEGRALS                         */
/* ═══════════════════════════════════════════════════════════ */

static void test_improper_integrals(void)
{
    ast_node_t *expr;
    ce_float_t result;
    improp_status_t status;

    printf("=== Improper Integrals ===\n");

    /* int(1/x^2, 1, inf) = 1 (convergent) */
    mem_free_all();
    expr = parse_str("1/x^2");
    status = integrate_improper(expr, 'x', 1.0f, false, 0, true, &result);
    ASSERT_EQ_INT(status, IMPROP_OK, "improper: 1/x^2 [1,inf) converges");
    if (status == IMPROP_OK)
        ASSERT_EQ_FLOAT(result, 1.0f, 0.1f, "improper: int 1/x^2 = 1");
    ast_free(expr);

    /* int(e^(-x), 0, inf) = 1 (convergent) */
    mem_free_all();
    expr = parse_str("e^(-x)");
    status = integrate_improper(expr, 'x', 0.0f, false, 0, true, &result);
    ASSERT_EQ_INT(status, IMPROP_OK, "improper: e^(-x) [0,inf) converges");
    if (status == IMPROP_OK)
        ASSERT_EQ_FLOAT(result, 1.0f, 0.1f, "improper: int e^(-x) = 1");
    ast_free(expr);

    /* int(1/x, 1, inf) = divergent */
    mem_free_all();
    expr = parse_str("1/x");
    status = integrate_improper(expr, 'x', 1.0f, false, 0, true, &result);
    ASSERT_EQ_INT(status, IMPROP_DIVERGES, "improper: 1/x [1,inf) diverges");
    ast_free(expr);

    /* int(1/(1+x^2), -inf, inf) = pi (convergent) */
    mem_free_all();
    expr = parse_str("1/(1+x^2)");
    status = integrate_improper(expr, 'x', 0, true, 0, true, &result);
    ASSERT_EQ_INT(status, IMPROP_OK, "improper: 1/(1+x^2) (-inf,inf) converges");
    if (status == IMPROP_OK)
        ASSERT_EQ_FLOAT(result, CE_PI, 0.2f, "improper: int 1/(1+x^2) = pi");
    ast_free(expr);

    /* int(e^(-x^2), 0, inf) ≈ sqrt(pi)/2 ≈ 0.8862 (Gaussian) */
    mem_free_all();
    expr = parse_str("e^(-(x^2))");
    status = integrate_improper(expr, 'x', 0.0f, false, 0, true, &result);
    if (status == IMPROP_OK) {
        ASSERT_EQ_FLOAT(result, sqrtf(CE_PI) / 2.0f, 0.15f,
                         "improper: int e^(-x^2) ≈ sqrt(pi)/2");
    }
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: SERIES CONVERGENCE TESTS                   */
/* ═══════════════════════════════════════════════════════════ */

static void test_series_v2(void)
{
    ast_node_t *expr;
    conv_info_t ci;

    printf("=== Series V2 (integral/comparison tests) ===\n");

    /* 1/n^2 converges (should be caught by p-series or integral test) */
    mem_free_all();
    expr = parse_str("1/n^2");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series_v2: 1/n^2 converges");
    ast_free(expr);

    /* 1/n^3 converges */
    mem_free_all();
    expr = parse_str("1/n^3");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series_v2: 1/n^3 converges");
    ast_free(expr);

    /* 1/sqrt(n) = 1/n^0.5 diverges (p < 1) */
    mem_free_all();
    expr = parse_str("1/sqrt(n)");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series_v2: 1/sqrt(n) diverges");
    ast_free(expr);

    /* 1/(n*ln(n)) for n>=2 — diverges (integral test) */
    /* This is tricky; the comparison test should identify it decays like ~1/n^1 */
    /* Skip — log-based series are hard to classify numerically */

    /* n/(n^2+1) diverges (behaves like 1/n) */
    mem_free_all();
    expr = parse_str("n/(n^2+1)");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "series_v2: n/(n^2+1) diverges");
    ast_free(expr);

    /* 1/(n^2+1) converges (behaves like 1/n^2) */
    mem_free_all();
    expr = parse_str("1/(n^2+1)");
    ci = series_converge(expr, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "series_v2: 1/(n^2+1) converges");
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: LAGRANGE ERROR BOUND                       */
/* ═══════════════════════════════════════════════════════════ */

static void test_lagrange_error(void)
{
    ast_node_t *expr;
    ce_float_t bound;

    printf("=== Lagrange Error Bound ===\n");

    /* Taylor of e^x at center=0, degree 4, evaluated at x=1
     * |R_4(1)| <= M * 1^5 / 5! where M = max |e^c| for c in [0,1] = e
     * So bound <= e / 120 ≈ 0.0227 */
    mem_free_all();
    expr = parse_str("e^x");
    steps_clear();
    bound = taylor_lagrange_error(expr, 'x', 0, 4, 1.0f);
    ASSERT_TRUE(bound >= 0, "lagrange: e^x bound non-negative");
    ASSERT_TRUE(bound < 0.05f, "lagrange: e^x bound < 0.05");
    ASSERT_TRUE(bound > 0.01f, "lagrange: e^x bound > 0.01");
    ast_free(expr);

    /* Taylor of sin(x) at center=0, degree 5, evaluated at x=0.5
     * The 6th derivative of sin(x) is -sin(x).
     * |R_5(0.5)| <= 1 * 0.5^6 / 720 ≈ 2.17e-5 */
    mem_free_all();
    expr = parse_str("sin(x)");
    steps_clear();
    bound = taylor_lagrange_error(expr, 'x', 0, 5, 0.5f);
    ASSERT_TRUE(bound >= 0, "lagrange: sin bound non-negative");
    ASSERT_TRUE(bound < 0.001f, "lagrange: sin bound < 0.001");
    ast_free(expr);

    /* Taylor of 1/(1-x) at center=0, degree 3, evaluated at x=0.5
     * f^(4)(x) = 24/(1-x)^5, M at x=0.5 = 24/0.03125 = 768
     * |R_3(0.5)| <= 768 * 0.5^4 / 24 = 768 * 0.0625 / 24 = 2.0 */
    mem_free_all();
    expr = parse_str("1/(1-x)");
    steps_clear();
    bound = taylor_lagrange_error(expr, 'x', 0, 3, 0.5f);
    ASSERT_TRUE(bound >= 0, "lagrange: 1/(1-x) bound non-negative");
    /* The bound should be reasonable — not tiny, not enormous */
    ASSERT_TRUE(bound < 5.0f, "lagrange: 1/(1-x) bound < 5");
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              V2: INTERVAL OF CONVERGENCE                    */
/* ═══════════════════════════════════════════════════════════ */

static void test_interval_of_convergence(void)
{
    ast_node_t *expr;
    ce_float_t R;
    char ioc_buf[60];

    printf("=== Interval of Convergence ===\n");

    /* sum(x^n/n) has R=1. Endpoints: x=-1 converges (alternating harmonic),
     * x=1 diverges (harmonic). Interval: [-1, 1) */
    mem_free_all();
    expr = parse_str("1/n");
    steps_clear();
    R = power_series_interval(expr, 'n', 0, ioc_buf, sizeof(ioc_buf));
    ASSERT_EQ_FLOAT(R, 1.0f, 0.3f, "ioc: 1/n -> R=1");
    ASSERT_TRUE(R > 0, "ioc: radius positive");
    ast_free(expr);

    /* sum(x^n/n!) has R=inf */
    mem_free_all();
    expr = parse_str("1/n!");
    steps_clear();
    R = power_series_interval(expr, 'n', 0, ioc_buf, sizeof(ioc_buf));
    ASSERT_TRUE(R > 10.0f, "ioc: 1/n! -> large R");
    ast_free(expr);

    /* sum(x^n) has R=1. Both endpoints diverge. */
    mem_free_all();
    expr = ast_number(1);
    steps_clear();
    R = power_series_interval(expr, 'n', 0, ioc_buf, sizeof(ioc_buf));
    ASSERT_EQ_FLOAT(R, 1.0f, 0.3f, "ioc: 1 -> R=1");
    ast_free(expr);

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                SYSTEMS OF EQUATIONS TESTS                    */
/* ═══════════════════════════════════════════════════════════ */

static void test_systems(void)
{
    ast_node_t *eq1, *eq2, *eq3;
    const ast_node_t *eqs[3];
    char buf[256];
    int n;

    printf("=== Systems of Equations ===\n");

    /* 2x2: x + y - 3 = 0, 2x - y - 0 = 0  →  x=1, y=2 */
    mem_free_all();
    eq1 = parse_str("x+y-3");
    eq2 = parse_str("2*x-y");
    eqs[0] = eq1; eqs[1] = eq2;
    n = algebra_solve_system(eqs, 2, "xy", buf, sizeof(buf));
    ASSERT_EQ_INT(n, 2, "sys2: solved 2 vars");
    ASSERT_STR_CONTAINS(buf, "x = 1", "sys2: x=1");
    ASSERT_STR_CONTAINS(buf, "y = 2", "sys2: y=2");
    ast_free(eq1); ast_free(eq2);

    /* 2x2: 3x + 2y - 12 = 0, x - y - 1 = 0  →  x=2.8, y=1.8 */
    mem_free_all();
    eq1 = parse_str("3*x+2*y-12");
    eq2 = parse_str("x-y-1");
    eqs[0] = eq1; eqs[1] = eq2;
    n = algebra_solve_system(eqs, 2, "xy", buf, sizeof(buf));
    ASSERT_EQ_INT(n, 2, "sys2b: solved 2 vars");
    ASSERT_STR_CONTAINS(buf, "x = 2.8", "sys2b: x=2.8");
    ASSERT_STR_CONTAINS(buf, "y = 1.8", "sys2b: y=1.8");
    ast_free(eq1); ast_free(eq2);

    /* 2x2 singular: x + y - 1 = 0, 2x + 2y - 2 = 0 → no unique solution */
    mem_free_all();
    eq1 = parse_str("x+y-1");
    eq2 = parse_str("2*x+2*y-2");
    eqs[0] = eq1; eqs[1] = eq2;
    n = algebra_solve_system(eqs, 2, "xy", buf, sizeof(buf));
    ASSERT_EQ_INT(n, 0, "sys2_sing: singular system returns 0");
    ASSERT_STR_CONTAINS(buf, "singular", "sys2_sing: says singular");
    ast_free(eq1); ast_free(eq2);

    /* 3x3: x+y+z=6, 2x-y+z=3, x+2y-z=2 → x=1, y=2, z=3 */
    mem_free_all();
    eq1 = parse_str("x+y+z-6");
    eq2 = parse_str("2*x-y+z-3");
    eq3 = parse_str("x+2*y-z-2");
    eqs[0] = eq1; eqs[1] = eq2; eqs[2] = eq3;
    n = algebra_solve_system(eqs, 3, "xyz", buf, sizeof(buf));
    ASSERT_EQ_INT(n, 3, "sys3: solved 3 vars");
    ASSERT_STR_CONTAINS(buf, "x = 1", "sys3: x=1");
    ASSERT_STR_CONTAINS(buf, "y = 2", "sys3: y=2");
    ASSERT_STR_CONTAINS(buf, "z = 3", "sys3: z=3");
    ast_free(eq1); ast_free(eq2); ast_free(eq3);

    /* 3x3: x+2y+3z=14, 2x+y+z=7, 3x+y+2z=11 → x=1, y=2, z=3 */
    mem_free_all();
    eq1 = parse_str("x+2*y+3*z-14");
    eq2 = parse_str("2*x+y+z-7");
    eq3 = parse_str("3*x+y+2*z-11");
    eqs[0] = eq1; eqs[1] = eq2; eqs[2] = eq3;
    n = algebra_solve_system(eqs, 3, "xyz", buf, sizeof(buf));
    ASSERT_EQ_INT(n, 3, "sys3b: solved 3 vars");
    ASSERT_STR_CONTAINS(buf, "x = 1", "sys3b: x=1");
    ASSERT_STR_CONTAINS(buf, "y = 2", "sys3b: y=2");
    ASSERT_STR_CONTAINS(buf, "z = 3", "sys3b: z=3");
    ast_free(eq1); ast_free(eq2); ast_free(eq3);

    /* Steps were recorded */
    ASSERT_TRUE(steps_count() > 0, "sys: steps recorded");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                   TRIANGLE SOLVER TESTS                     */
/* ═══════════════════════════════════════════════════════════ */

static void test_triangle(void)
{
    ce_float_t sides[3], angles[3];
    char buf[256];
    int r;

    printf("=== Triangle Solver ===\n");

    /* SSS: 3-4-5 right triangle */
    sides[0] = 3; sides[1] = 4; sides[2] = 5;
    angles[0] = 0; angles[1] = 0; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 1, "tri SSS: solved");
    ASSERT_EQ_FLOAT(angles[2], 90.0f, 0.05f, "tri SSS: C~90 (3-4-5)");
    ASSERT_EQ_FLOAT(angles[0], 36.87f, 0.05f, "tri SSS: A~36.87");
    ASSERT_EQ_FLOAT(angles[1], 53.13f, 0.05f, "tri SSS: B~53.13");

    /* SSS: equilateral 5-5-5 */
    sides[0] = 5; sides[1] = 5; sides[2] = 5;
    angles[0] = 0; angles[1] = 0; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 1, "tri SSS equilateral: solved");
    ASSERT_EQ_FLOAT(angles[0], 60.0f, 0.05f, "tri SSS equil: A=60");
    ASSERT_EQ_FLOAT(angles[1], 60.0f, 0.05f, "tri SSS equil: B=60");
    ASSERT_EQ_FLOAT(angles[2], 60.0f, 0.05f, "tri SSS equil: C=60");

    /* SSS: invalid (triangle inequality) */
    sides[0] = 1; sides[1] = 2; sides[2] = 10;
    angles[0] = 0; angles[1] = 0; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 0, "tri SSS invalid: fails");

    /* SAS: sides 5, 7, angle C=60 between them */
    sides[0] = 5; sides[1] = 7; sides[2] = 0;
    angles[0] = 0; angles[1] = 0; angles[2] = 60;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 1, "tri SAS: solved");
    ASSERT_TRUE(sides[2] > 5.0f && sides[2] < 7.0f, "tri SAS: c reasonable");
    ASSERT_TRUE(angles[0] > 0 && angles[0] < 180.0f, "tri SAS: A valid");
    ASSERT_TRUE(angles[1] > 0 && angles[1] < 180.0f, "tri SAS: B valid");
    /* Angle sum should be ~180 */
    ASSERT_EQ_FLOAT(angles[0]+angles[1]+angles[2], 180.0f, 0.1f,
                    "tri SAS: angle sum ~180");

    /* ASA: angles 50, 60, side b=10 (between them) */
    sides[0] = 0; sides[1] = 10; sides[2] = 0;
    angles[0] = 50; angles[1] = 60; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 1, "tri ASA: solved");
    ASSERT_EQ_FLOAT(angles[2], 70.0f, 0.01f, "tri ASA: C=70");
    ASSERT_TRUE(sides[0] > 0 && sides[2] > 0, "tri ASA: sides positive");
    ASSERT_EQ_FLOAT(angles[0]+angles[1]+angles[2], 180.0f, 0.01f,
                    "tri ASA: angle sum = 180");

    /* AAS: angles 30, 45, non-included side a=8 */
    sides[0] = 8; sides[1] = 0; sides[2] = 0;
    angles[0] = 30; angles[1] = 45; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 1, "tri AAS: solved");
    ASSERT_EQ_FLOAT(angles[2], 105.0f, 0.01f, "tri AAS: C=105");
    ASSERT_TRUE(sides[1] > 0 && sides[2] > 0, "tri AAS: sides positive");

    /* SSA: a=10, b=7, A=45 → unique solution (a > b) */
    sides[0] = 10; sides[1] = 7; sides[2] = 0;
    angles[0] = 45; angles[1] = 0; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_TRUE(r >= 1, "tri SSA unique: at least 1 solution");

    /* SSA impossible: a=3, b=10, A=80 → sin(B)>1 */
    sides[0] = 3; sides[1] = 10; sides[2] = 0;
    angles[0] = 80; angles[1] = 0; angles[2] = 0;
    r = algebra_triangle(sides, angles, buf, sizeof(buf));
    ASSERT_EQ_INT(r, 0, "tri SSA impossible: no solution");

    /* Steps recorded */
    ASSERT_TRUE(steps_count() > 0, "tri: steps recorded");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                    MEMORY AUDIT                             */
/* ═══════════════════════════════════════════════════════════ */

static void test_memory_audit(void)
{
    uint32_t ast_pool_bytes, free_stack_bytes, steps_bytes;
    uint32_t total;

    printf("=== Memory Audit ===\n");

    ast_pool_bytes   = (uint32_t)(NODE_POOL_SIZE * sizeof(ast_node_t));
    free_stack_bytes = (uint32_t)(NODE_POOL_SIZE * sizeof(uint16_t));
    steps_bytes      = (uint32_t)(MAX_STEPS * MAX_STEP_LEN);

    printf("  AST pool:    %u nodes * %u bytes = %u bytes\n",
           NODE_POOL_SIZE, (unsigned)sizeof(ast_node_t), (unsigned)ast_pool_bytes);
    printf("  Free stack:  %u * %u = %u bytes\n",
           NODE_POOL_SIZE, (unsigned)sizeof(uint16_t), (unsigned)free_stack_bytes);
    printf("  Steps buf:   %u * %u = %u bytes\n",
           MAX_STEPS, MAX_STEP_LEN, (unsigned)steps_bytes);
    printf("  ce_matrix_t:    %u bytes\n", (unsigned)sizeof(ce_matrix_t));
    printf("  eval_ctx_t:  %u bytes\n", (unsigned)sizeof(eval_ctx_t));
    printf("  poly_t:      %u bytes\n", (unsigned)sizeof(poly_t));

    total = ast_pool_bytes + free_stack_bytes + steps_bytes;
    printf("  Core total:  %u bytes (%.1f KB)\n",
           (unsigned)total, (double)total / 1024.0);

    ASSERT_TRUE(total < 51200, "audit: core memory < 50KB");
    ASSERT_TRUE(sizeof(ast_node_t) <= 64, "audit: ast_node_t <= 64 bytes");
    ASSERT_TRUE(sizeof(ce_matrix_t) <= 160, "audit: ce_matrix_t <= 160 bytes");
    ASSERT_TRUE(sizeof(eval_ctx_t) <= 280, "audit: eval_ctx_t <= 280 bytes");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*                 HARDENING / EDGE CASE TESTS                 */
/* ═══════════════════════════════════════════════════════════ */

static void test_hardening(void)
{
    ast_node_t *node;
    eval_ctx_t ctx;
    ce_float_t val;
    ce_error_t err;
    int i;

    printf("=== Hardening ===\n");

    /* Pool exhaustion: allocate nodes until NULL */
    mem_free_all();
    {
        int alloc_count = 0;
        ast_node_t *last = NULL;
        for (i = 0; i < NODE_POOL_SIZE + 10; i++) {
            node = mem_alloc_node();
            if (node) {
                alloc_count++;
                last = node;
            } else {
                break;
            }
        }
        ASSERT_EQ_INT(alloc_count, NODE_POOL_SIZE,
                      "hardening: alloced exactly NODE_POOL_SIZE nodes");
        ASSERT_TRUE(mem_alloc_node() == NULL,
                    "hardening: alloc returns NULL when exhausted");
        ASSERT_EQ_INT(mem_nodes_free(), 0,
                      "hardening: 0 free nodes when exhausted");
        (void)last;
    }
    mem_free_all();

    /* Extreme values: large number arithmetic */
    val = eval_str("999999*999999", &err);
    /* Very large result — just shouldn't crash */
    ASSERT_TRUE(err == CE_OK, "hardening: large mul no crash");

    /* Very small multiplication — 0.001 * 0.001 = 1e-6 */
    val = eval_str("0.001*0.001", &err);
    ASSERT_EQ_FLOAT(val, 0.000001f, 0.0001f, "hardening: small mul ok");

    /* Division by zero via eval */
    val = eval_str("1/0", &err);
    ASSERT_TRUE(err == CE_ERR_DIV_ZERO || fabsf(val) > 1e30f,
                "hardening: 1/0 error or inf");

    /* NaN propagation: 0/0 */
    val = eval_str("0/0", &err);
    ASSERT_TRUE(err != CE_OK || val != val,
                "hardening: 0/0 error or NaN");

    /* Deeply nested: ((((x+1)+1)+1)+1)... 25 levels */
    mem_free_all();
    {
        ast_node_t *deep = ast_variable('x');
        for (i = 0; i < 25; i++) {
            deep = ast_binop(OP_ADD, deep, ast_number(1));
            if (!deep) break;
        }
        if (deep) {
            eval_init(&ctx);
            eval_set_var(&ctx, 'x', 0.0f);
            val = eval_expr(&ctx, deep);
            ASSERT_EQ_FLOAT(val, 25.0f, 0.01f,
                            "hardening: deep nest = 25");
            ast_free(deep);
        } else {
            ASSERT_TRUE(0, "hardening: deep nest alloc failed");
        }
    }

    /* NaN through simplifier */
    mem_free_all();
    node = parse_str("0*x");
    if (node) {
        ast_node_t *simp = ast_simplify(node);
        ASSERT_TRUE(simp != NULL, "hardening: simplify 0*x non-null");
        if (simp) {
            eval_init(&ctx);
            eval_set_var(&ctx, 'x', 5.0f);
            val = eval_expr(&ctx, simp);
            ASSERT_EQ_FLOAT(val, 0.0f, 0.01f,
                            "hardening: 0*x simplifies to 0");
        }
        ast_free(simp);
    }

    /* Solve with no variable → should handle gracefully */
    mem_free_all();
    node = parse_str("42");
    if (node) {
        char sbuf[64];
        algebra_solve(node, 'x', sbuf, sizeof(sbuf));
        ASSERT_STR_CONTAINS(sbuf, "No solution",
                            "hardening: solve constant = no solution");
        ast_free(node);
    }

    /* Empty system of equations */
    {
        char sbuf[64];
        int ns = algebra_solve_system(NULL, 0, "xy", sbuf, sizeof(sbuf));
        ASSERT_EQ_INT(ns, 0, "hardening: empty system returns 0");
    }

    /* Triangle with all zeros → insufficient */
    {
        ce_float_t s[3] = {0,0,0}, a[3] = {0,0,0};
        char tbuf[64];
        int tr = algebra_triangle(s, a, tbuf, sizeof(tbuf));
        ASSERT_EQ_INT(tr, 0, "hardening: all-zero triangle fails");
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              TANGENT LINE TESTS                              */
/* ═══════════════════════════════════════════════════════════ */

static void test_tangent_line(void)
{
    ast_node_t *root;
    ce_float_t val;
    eval_ctx_t ctx;

    printf("--- tangent line ---\n");

    /* tangent(x^2, x, 3) should parse to NODE_TANGENT */
    mem_free_all();
    root = parse_str("tangent(x^2, x, 3)");
    ASSERT_TRUE(root != NULL, "tangent: parse ok");
    if (root) {
        ASSERT_EQ_INT(root->type, NODE_TANGENT, "tangent: node type");
        ASSERT_EQ_INT(root->d.tangent.var, 'x', "tangent: var is x");
        /* Evaluate point */
        eval_init(&ctx);
        val = eval_expr(&ctx, root->d.tangent.point);
        ASSERT_EQ_FLOAT(val, 3.0f, 0.01f, "tangent: point=3");

        /* Check the expression is x^2 */
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 5.0f);
        val = eval_expr(&ctx, root->d.tangent.expr);
        ASSERT_EQ_FLOAT(val, 25.0f, 0.01f, "tangent: expr=x^2 at 5");
        ast_free(root);
    }

    /* tangent line of x^2 at x=3: y=6x-9 */
    /* f(3)=9, f'(x)=2x, f'(3)=6, b=9-6*3=-9 */
    mem_free_all();
    root = parse_str("tangent(x^2, x, 3)");
    ASSERT_TRUE(root != NULL, "tangent: parse tangent(x^2,x,3) non-null");
    if (root) {
        ast_node_t *deriv_result;
        ce_float_t fa, slope, intercept;

        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        fa = eval_expr(&ctx, root->d.tangent.expr);
        ASSERT_EQ_FLOAT(fa, 9.0f, 0.01f, "tangent: f(3)=9");

        deriv_result = deriv_diff(root->d.tangent.expr, 'x');
        ASSERT_TRUE(deriv_result != NULL, "tangent: diff ok");
        if (deriv_result) {
            eval_init(&ctx);
            eval_set_var(&ctx, 'x', 3.0f);
            slope = eval_expr(&ctx, deriv_result);
            ASSERT_EQ_FLOAT(slope, 6.0f, 0.01f, "tangent: slope=6");

            intercept = fa - slope * 3.0f;
            ASSERT_EQ_FLOAT(intercept, -9.0f, 0.01f, "tangent: b=-9");
            ast_free(deriv_result);
        }
        ast_free(root);
    }

    /* tangent(sin(x), x, 0): f(0)=0, f'(0)=cos(0)=1, y=x */
    mem_free_all();
    root = parse_str("tangent(sin(x), x, 0)");
    ASSERT_TRUE(root != NULL, "tangent: parse tangent(sin(x),x,0) non-null");
    if (root) {
        ast_node_t *dp;
        ce_float_t s;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.0f);
        val = eval_expr(&ctx, root->d.tangent.expr);
        ASSERT_EQ_FLOAT(val, 0.0f, 0.01f, "tangent: sin(0)=0");

        dp = deriv_diff(root->d.tangent.expr, 'x');
        if (dp) {
            eval_init(&ctx);
            eval_set_var(&ctx, 'x', 0.0f);
            s = eval_expr(&ctx, dp);
            ASSERT_EQ_FLOAT(s, 1.0f, 0.01f, "tangent: cos(0)=1 slope");
            ast_free(dp);
        }
        ast_free(root);
    }

    /* tangent(x^3, x, 2): f(2)=8, f'(x)=3x^2, f'(2)=12, b=8-24=-16 */
    mem_free_all();
    root = parse_str("tangent(x^3, x, 2)");
    ASSERT_TRUE(root != NULL, "tangent: parse tangent(x^3,x,2) non-null");
    if (root) {
        ast_node_t *dp;
        ce_float_t fa2, slope2, b2;
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        fa2 = eval_expr(&ctx, root->d.tangent.expr);
        ASSERT_EQ_FLOAT(fa2, 8.0f, 0.01f, "tangent: x^3 at 2 = 8");

        dp = deriv_diff(root->d.tangent.expr, 'x');
        if (dp) {
            eval_init(&ctx);
            eval_set_var(&ctx, 'x', 2.0f);
            slope2 = eval_expr(&ctx, dp);
            ASSERT_EQ_FLOAT(slope2, 12.0f, 0.01f, "tangent: 3x^2 at 2 = 12");
            b2 = fa2 - slope2 * 2.0f;
            ASSERT_EQ_FLOAT(b2, -16.0f, 0.01f, "tangent: intercept -16");
            ast_free(dp);
        }
        ast_free(root);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*            LOG/EXP SIMPLIFICATION TESTS                     */
/* ═══════════════════════════════════════════════════════════ */

static void test_log_exp_simplify(void)
{
    ast_node_t *node, *simp;
    eval_ctx_t ctx;
    ce_float_t val;

    printf("--- log/exp simplification ---\n");

    /* ln(1) -> 0 */
    mem_free_all();
    node = parse_str("ln(1)");
    ASSERT_TRUE(node != NULL, "logexp: ln(1) parse");
    if (node) {
        simp = ast_simplify(node);
        ASSERT_TRUE(simp->type == NODE_NUMBER, "logexp: ln(1) simplifies to number");
        if (simp->type == NODE_NUMBER)
            ASSERT_EQ_FLOAT(simp->d.number, 0.0f, 0.001f, "logexp: ln(1)=0");
        ast_free(simp);
    }

    /* ln(e) -> 1 */
    mem_free_all();
    node = parse_str("ln(e)");
    ASSERT_TRUE(node != NULL, "logexp: parse ln(e) non-null");
    if (node) {
        simp = ast_simplify(node);
        ASSERT_TRUE(simp->type == NODE_NUMBER, "logexp: ln(e) simplifies to number");
        if (simp->type == NODE_NUMBER)
            ASSERT_EQ_FLOAT(simp->d.number, 1.0f, 0.001f, "logexp: ln(e)=1");
        ast_free(simp);
    }

    /* log(1) -> 0 */
    mem_free_all();
    node = parse_str("log(1)");
    ASSERT_TRUE(node != NULL, "logexp: parse log(1) non-null");
    if (node) {
        simp = ast_simplify(node);
        ASSERT_TRUE(simp->type == NODE_NUMBER, "logexp: log(1) simplifies to number");
        if (simp->type == NODE_NUMBER)
            ASSERT_EQ_FLOAT(simp->d.number, 0.0f, 0.001f, "logexp: log(1)=0");
        ast_free(simp);
    }

    /* log(10) -> 1 */
    mem_free_all();
    node = parse_str("log(10)");
    ASSERT_TRUE(node != NULL, "logexp: parse log(10) non-null");
    if (node) {
        simp = ast_simplify(node);
        ASSERT_TRUE(simp->type == NODE_NUMBER, "logexp: log(10) simplifies to number");
        if (simp->type == NODE_NUMBER)
            ASSERT_EQ_FLOAT(simp->d.number, 1.0f, 0.001f, "logexp: log(10)=1");
        ast_free(simp);
    }

    /* ln(e^x) -> x:  evaluate at x=5 should give 5 */
    mem_free_all();
    node = parse_str("ln(e^x)");
    ASSERT_TRUE(node != NULL, "logexp: parse ln(e^x) non-null");
    if (node) {
        simp = ast_simplify(node);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 5.0f);
        val = eval_expr(&ctx, simp);
        ASSERT_EQ_FLOAT(val, 5.0f, 0.01f, "logexp: ln(e^x)=x at 5");
        ast_free(simp);
    }

    /* exp(ln(x)) -> x: evaluate at x=7 should give 7 */
    mem_free_all();
    node = parse_str("exp(ln(x))");
    ASSERT_TRUE(node != NULL, "logexp: parse exp(ln(x)) non-null");
    if (node) {
        simp = ast_simplify(node);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 7.0f);
        val = eval_expr(&ctx, simp);
        ASSERT_EQ_FLOAT(val, 7.0f, 0.01f, "logexp: exp(ln(x))=x at 7");
        ast_free(simp);
    }

    /* e^(ln(x)) -> x: evaluate at x=3 should give 3 */
    mem_free_all();
    node = parse_str("e^(ln(x))");
    ASSERT_TRUE(node != NULL, "logexp: parse e^(ln(x)) non-null");
    if (node) {
        simp = ast_simplify(node);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        val = eval_expr(&ctx, simp);
        ASSERT_EQ_FLOAT(val, 3.0f, 0.01f, "logexp: e^(ln(x))=x at 3");
        ast_free(simp);
    }

    /* ln(exp(x)) -> x: evaluate at x=4 */
    mem_free_all();
    node = parse_str("ln(exp(x))");
    ASSERT_TRUE(node != NULL, "logexp: parse ln(exp(x)) non-null");
    if (node) {
        simp = ast_simplify(node);
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 4.0f);
        val = eval_expr(&ctx, simp);
        ASSERT_EQ_FLOAT(val, 4.0f, 0.01f, "logexp: ln(exp(x))=x at 4");
        ast_free(simp);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*           LIMIT FACTORING TESTS                             */
/* ═══════════════════════════════════════════════════════════ */

static void test_limit_factoring(void)
{
    ast_node_t *root;
    ce_float_t lim_val;
    lim_status_t ls;

    printf("--- limit factoring ---\n");

    /* lim (x^2-4)/(x-2) as x->2 = 4  (factor cancel) */
    mem_free_all();
    root = parse_str("(x^2-4)/(x-2)");
    ASSERT_TRUE(root != NULL, "limfact: parse (x^2-4)/(x-2) non-null");
    if (root) {
        ast_node_t *pt = ast_number(2);
        ls = compute_limit(root, 'x', pt, 0, &lim_val);
        ASSERT_EQ_INT(ls, LIM_OK, "limfact: (x^2-4)/(x-2) status OK");
        if (ls == LIM_OK)
            ASSERT_EQ_FLOAT(lim_val, 4.0f, 0.1f, "limfact: (x^2-4)/(x-2)=4");
        ast_free(pt);
        ast_free(root);
    }

    /* lim (x^2-1)/(x-1) as x->1 = 2 */
    mem_free_all();
    root = parse_str("(x^2-1)/(x-1)");
    ASSERT_TRUE(root != NULL, "limfact: parse (x^2-1)/(x-1) non-null");
    if (root) {
        ast_node_t *pt = ast_number(1);
        ls = compute_limit(root, 'x', pt, 0, &lim_val);
        ASSERT_EQ_INT(ls, LIM_OK, "limfact: (x^2-1)/(x-1) status OK");
        if (ls == LIM_OK)
            ASSERT_EQ_FLOAT(lim_val, 2.0f, 0.1f, "limfact: (x^2-1)/(x-1)=2");
        ast_free(pt);
        ast_free(root);
    }

    /* lim (x^3-8)/(x-2) as x->2 = 12 (x^2+2x+4 at x=2) */
    mem_free_all();
    root = parse_str("(x^3-8)/(x-2)");
    ASSERT_TRUE(root != NULL, "limfact: parse (x^3-8)/(x-2) non-null");
    if (root) {
        ast_node_t *pt = ast_number(2);
        ls = compute_limit(root, 'x', pt, 0, &lim_val);
        ASSERT_EQ_INT(ls, LIM_OK, "limfact: (x^3-8)/(x-2) status OK");
        if (ls == LIM_OK)
            ASSERT_EQ_FLOAT(lim_val, 12.0f, 0.01f, "limfact: (x^3-8)/(x-2)=12");
        ast_free(pt);
        ast_free(root);
    }

    /* lim x^2/(x) as x->0 = 0 (trivially factored) */
    mem_free_all();
    root = parse_str("x^2/x");
    ASSERT_TRUE(root != NULL, "limfact: parse x^2/x non-null");
    if (root) {
        ast_node_t *pt = ast_number(0);
        ls = compute_limit(root, 'x', pt, 0, &lim_val);
        ASSERT_EQ_INT(ls, LIM_OK, "limfact: x^2/x status OK");
        if (ls == LIM_OK)
            ASSERT_EQ_FLOAT(lim_val, 0.0f, 0.1f, "limfact: x^2/x at 0 = 0");
        ast_free(pt);
        ast_free(root);
    }

    mem_free_all();
}

