/* ═══════════════════════════════════════════════════════════ */
/*            TELESCOPING SERIES TESTS                         */
/* ═══════════════════════════════════════════════════════════ */

static void test_telescoping_series(void)
{
    ast_node_t *root;
    conv_info_t ci;

    printf("--- telescoping series ---\n");

    /* sum(1/(n*(n+1)), n, 1, inf) should converge to 1 */
    mem_free_all();
    root = parse_str("1/(n*(n+1))");
    ASSERT_TRUE(root != NULL, "telescope: parse 1/(n*(n+1)) non-null");
    if (root) {
        ci = series_converge(root, 'n');
        ASSERT_EQ_INT(ci.result, CONV_CONVERGES,
                      "telescope: 1/(n(n+1)) converges");
        if (ci.has_sum)
            ASSERT_EQ_FLOAT(ci.sum_estimate, 1.0f, 0.05f,
                            "telescope: 1/(n(n+1)) sum ~ 1");
        ast_free(root);
    }

    /* sum(1/(n*(n+2)), n, 1, inf) should converge to 3/4 = 0.75 */
    mem_free_all();
    root = parse_str("1/(n*(n+2))");
    ASSERT_TRUE(root != NULL, "telescope: parse 1/(n*(n+2)) non-null");
    if (root) {
        ci = series_converge(root, 'n');
        ASSERT_EQ_INT(ci.result, CONV_CONVERGES,
                      "telescope: 1/(n(n+2)) converges");
        if (ci.has_sum)
            ASSERT_EQ_FLOAT(ci.sum_estimate, 0.75f, 0.1f,
                            "telescope: 1/(n(n+2)) sum ~ 0.75");
        ast_free(root);
    }

    /* sum(1/(n^2+n), n, 1, inf) = sum(1/(n(n+1))) = 1 */
    mem_free_all();
    root = parse_str("1/(n^2+n)");
    ASSERT_TRUE(root != NULL, "telescope: parse 1/(n^2+n) non-null");
    if (root) {
        ci = series_converge(root, 'n');
        ASSERT_EQ_INT(ci.result, CONV_CONVERGES,
                      "telescope: 1/(n^2+n) converges");
        ast_free(root);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*           POLAR / RECTANGULAR CONVERSION TESTS               */
/* ═══════════════════════════════════════════════════════════ */

static void test_polar_rect(void)
{
    ce_float_t x, y, r, theta;

    printf("--- polar/rect conversion ---\n");

    /* polar(5, 0) -> (5, 0) */
    polar_to_rect(5.0f, 0.0f, &x, &y);
    ASSERT_EQ_FLOAT(x, 5.0f, 0.01f, "polar2rect: (5,0)->x=5");
    ASSERT_EQ_FLOAT(y, 0.0f, 0.01f, "polar2rect: (5,0)->y=0");

    /* polar(1, pi/2) -> (0, 1) */
    polar_to_rect(1.0f, CE_PI / 2.0f, &x, &y);
    ASSERT_EQ_FLOAT(x, 0.0f, 0.01f, "polar2rect: (1,pi/2)->x=0");
    ASSERT_EQ_FLOAT(y, 1.0f, 0.01f, "polar2rect: (1,pi/2)->y=1");

    /* polar(2, pi/4) -> (sqrt(2), sqrt(2)) */
    polar_to_rect(2.0f, CE_PI / 4.0f, &x, &y);
    ASSERT_EQ_FLOAT(x, 1.41421f, 0.01f, "polar2rect: (2,pi/4)->x");
    ASSERT_EQ_FLOAT(y, 1.41421f, 0.01f, "polar2rect: (2,pi/4)->y");

    /* polar(3, pi) -> (-3, 0) */
    polar_to_rect(3.0f, CE_PI, &x, &y);
    ASSERT_EQ_FLOAT(x, -3.0f, 0.01f, "polar2rect: (3,pi)->x=-3");
    ASSERT_EQ_FLOAT(y, 0.0f, 0.01f, "polar2rect: (3,pi)->y=0");

    /* rect(3, 4) -> (5, atan2(4,3)) */
    rect_to_polar(3.0f, 4.0f, &r, &theta);
    ASSERT_EQ_FLOAT(r, 5.0f, 0.01f, "rect2polar: (3,4)->r=5");
    ASSERT_EQ_FLOAT(theta, 0.9273f, 0.01f, "rect2polar: (3,4)->theta");

    /* rect(0, 0) -> (0, 0) */
    rect_to_polar(0.0f, 0.0f, &r, &theta);
    ASSERT_EQ_FLOAT(r, 0.0f, 0.01f, "rect2polar: origin->r=0");

    /* rect(-1, 0) -> (1, pi) */
    rect_to_polar(-1.0f, 0.0f, &r, &theta);
    ASSERT_EQ_FLOAT(r, 1.0f, 0.01f, "rect2polar: (-1,0)->r=1");
    ASSERT_EQ_FLOAT(theta, CE_PI, 0.01f, "rect2polar: (-1,0)->theta=pi");

    /* rect(1, 1) -> (sqrt(2), pi/4) */
    rect_to_polar(1.0f, 1.0f, &r, &theta);
    ASSERT_EQ_FLOAT(r, 1.41421f, 0.01f, "rect2polar: (1,1)->r=sqrt(2)");
    ASSERT_EQ_FLOAT(theta, CE_PI / 4.0f, 0.01f, "rect2polar: (1,1)->theta=pi/4");

    /* Round-trip: polar(rect(7, 24)) should give back (7, 24) approx */
    rect_to_polar(7.0f, 24.0f, &r, &theta);
    polar_to_rect(r, theta, &x, &y);
    ASSERT_EQ_FLOAT(x, 7.0f, 0.01f, "roundtrip: x=7");
    ASSERT_EQ_FLOAT(y, 24.0f, 0.01f, "roundtrip: y=24");
}

/* ═══════════════════════════════════════════════════════════ */
/*           POLAR/RECT PARSER INTEGRATION TESTS                */
/* ═══════════════════════════════════════════════════════════ */

static void test_polar_parse(void)
{
    ast_node_t *root;

    printf("--- polar/rect parsing ---\n");

    /* Parse polar(5, 0) */
    mem_free_all();
    root = parse_str("polar(5, 0)");
    ASSERT_TRUE(root != NULL, "polar parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->type, NODE_POLAR, "polar parse: NODE_POLAR");
        ASSERT_EQ_INT(root->d.polar.op, POLOP_TO_RECT, "polar parse: TO_RECT");
        ast_free(root);
    }

    /* Parse rect(3, 4) */
    mem_free_all();
    root = parse_str("rect(3, 4)");
    ASSERT_TRUE(root != NULL, "rect parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->type, NODE_POLAR, "rect parse: NODE_POLAR");
        ASSERT_EQ_INT(root->d.polar.op, POLOP_FROM_RECT, "rect parse: FROM_RECT");
        ast_free(root);
    }

    /* Parse arclen(x^2, x, 0, 1) */
    mem_free_all();
    root = parse_str("arclen(x^2, x, 0, 1)");
    ASSERT_TRUE(root != NULL, "arclen parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->type, NODE_POLAR, "arclen parse: NODE_POLAR");
        ASSERT_EQ_INT(root->d.polar.op, POLOP_ARCLEN, "arclen parse: ARCLEN");
        ASSERT_EQ_INT(root->d.polar.var, 'x', "arclen parse: var=x");
        ASSERT_TRUE(root->d.polar.lo != NULL, "arclen parse: has lo");
        ASSERT_TRUE(root->d.polar.hi != NULL, "arclen parse: has hi");
        ast_free(root);
    }

    /* Parse arclen(cos(t), sin(t), t, 0, pi) — parametric */
    mem_free_all();
    root = parse_str("arclen(cos(t), sin(t), t, 0, pi)");
    ASSERT_TRUE(root != NULL, "arclen_param parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->d.polar.op, POLOP_ARCLEN_PARAM,
                      "arclen_param parse: ARCLEN_PARAM");
        ASSERT_EQ_INT(root->d.polar.var, 't', "arclen_param: var=t");
        ast_free(root);
    }

    /* Parse disk(x^2, x, 0, 1) */
    mem_free_all();
    root = parse_str("disk(x^2, x, 0, 1)");
    ASSERT_TRUE(root != NULL, "disk parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->d.polar.op, POLOP_DISK, "disk parse: DISK");
        ast_free(root);
    }

    /* Parse washer(x, x^2, x, 0, 1) */
    mem_free_all();
    root = parse_str("washer(x, x^2, x, 0, 1)");
    ASSERT_TRUE(root != NULL, "washer parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->d.polar.op, POLOP_WASHER, "washer parse: WASHER");
        ASSERT_TRUE(root->d.polar.expr2 != NULL, "washer: has expr2");
        ast_free(root);
    }

    /* Parse shell(x^2, x, 0, 1) */
    mem_free_all();
    root = parse_str("shell(x^2, x, 0, 1)");
    ASSERT_TRUE(root != NULL, "shell parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->d.polar.op, POLOP_SHELL, "shell parse: SHELL");
        ast_free(root);
    }

    /* Parse surfarea(x^2, x, 0, 1) */
    mem_free_all();
    root = parse_str("surfarea(x^2, x, 0, 1)");
    ASSERT_TRUE(root != NULL, "surfarea parse: not NULL");
    if (root) {
        ASSERT_EQ_INT(root->d.polar.op, POLOP_SURFREV, "surfarea parse: SURFREV");
        ast_free(root);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*              ARC LENGTH TESTS                                */
/* ═══════════════════════════════════════════════════════════ */

static void test_arclen(void)
{
    ast_node_t *f, *xt, *yt;
    ce_float_t result;
    ce_error_t err;

    printf("--- arc length ---\n");

    /* Arc length of y=x from 0 to 1: sqrt(2) ~ 1.4142 */
    /* f'(x)=1, integrand = sqrt(1+1) = sqrt(2), length = sqrt(2)*1 */
    mem_free_all();
    f = parse_str("x");
    ASSERT_TRUE(f != NULL, "arclen: parse y=x");
    if (f) {
        steps_clear();
        result = polar_arclen(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen y=x: no error");
        ASSERT_EQ_FLOAT(result, 1.4142f, 0.02f, "arclen y=x = sqrt(2)");
        ast_free(f);
    }

    /* Arc length of y=x^2 from 0 to 1 ~ 1.4789 */
    mem_free_all();
    f = parse_str("x^2");
    if (f) {
        steps_clear();
        result = polar_arclen(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen x^2: no error");
        ASSERT_EQ_FLOAT(result, 1.4789f, 0.02f, "arclen x^2 ~ 1.4789");
        ast_free(f);
    }

    /* Arc length of y=sin(x) from 0 to pi ~ 3.8202 */
    mem_free_all();
    f = parse_str("sin(x)");
    if (f) {
        steps_clear();
        result = polar_arclen(f, 'x', 0.0f, CE_PI, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen sin(x): no error");
        ASSERT_EQ_FLOAT(result, 3.8202f, 0.05f, "arclen sin(x) ~ 3.82");
        ast_free(f);
    }

    /* Parametric arc length: circle x=cos(t), y=sin(t), t=0..2pi = 2*pi */
    mem_free_all();
    xt = parse_str("cos(t)");
    yt = parse_str("sin(t)");
    if (xt && yt) {
        steps_clear();
        result = polar_arclen_param(xt, yt, 't', 0.0f, 2.0f * CE_PI, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen_param circle: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI, 0.05f,
                        "arclen_param circle = 2*pi");
        ast_free(xt);
        ast_free(yt);
    }

    /* Parametric: x=t, y=t from 0 to 1 -> length = sqrt(2) */
    mem_free_all();
    xt = parse_str("t");
    yt = parse_str("t");
    if (xt && yt) {
        steps_clear();
        result = polar_arclen_param(xt, yt, 't', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen_param line: no error");
        ASSERT_EQ_FLOAT(result, 1.4142f, 0.02f, "arclen_param line = sqrt(2)");
        ast_free(xt);
        ast_free(yt);
    }

    /* Parametric: x=2cos(t), y=2sin(t) from 0 to pi -> half circle = 2*pi */
    mem_free_all();
    xt = parse_str("2*cos(t)");
    yt = parse_str("2*sin(t)");
    if (xt && yt) {
        steps_clear();
        result = polar_arclen_param(xt, yt, 't', 0.0f, CE_PI, &err);
        ASSERT_EQ_INT(err, CE_OK, "arclen_param half r=2: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI, 0.05f,
                        "arclen_param half circle r=2 = 2*pi");
        ast_free(xt);
        ast_free(yt);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*            SURFACE AREA OF REVOLUTION TESTS                  */
/* ═══════════════════════════════════════════════════════════ */

static void test_surfarea(void)
{
    ast_node_t *f;
    ce_float_t result;
    ce_error_t err;

    printf("--- surface area of revolution ---\n");

    /* Surface area of y=x from 0 to 1 around x-axis:
     * 2*pi*int(x*sqrt(1+1), 0, 1) = 2*pi*sqrt(2)*[x^2/2] from 0 to 1
     * = pi*sqrt(2) ~ 4.4429 */
    mem_free_all();
    f = parse_str("x");
    if (f) {
        steps_clear();
        result = polar_surfrev(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "surfrev y=x: no error");
        ASSERT_EQ_FLOAT(result, CE_PI * 1.4142f, 0.1f,
                        "surfrev y=x ~ pi*sqrt(2)");
        ast_free(f);
    }

    /* Surface area of y=1 (constant) from 0 to 1 around x-axis:
     * 2*pi*int(1*sqrt(1+0), 0, 1) = 2*pi ~ 6.2832 */
    mem_free_all();
    f = parse_str("1");
    if (f) {
        steps_clear();
        result = polar_surfrev(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "surfrev y=1: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI, 0.1f, "surfrev y=1 = 2*pi");
        ast_free(f);
    }

    /* Sphere: y=sqrt(r^2-x^2) from -r to r, with r=1:
     * SA = 4*pi*r^2 = 4*pi ~ 12.566 */
    mem_free_all();
    f = parse_str("sqrt(1-x^2)");
    if (f) {
        steps_clear();
        result = polar_surfrev(f, 'x', -0.999f, 0.999f, &err);
        ASSERT_EQ_INT(err, CE_OK, "surfrev sphere: no error");
        ASSERT_EQ_FLOAT(result, 4.0f * CE_PI, 0.2f,
                        "surfrev sphere ~ 4*pi");
        ast_free(f);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*           DISK / WASHER / SHELL METHOD TESTS                 */
/* ═══════════════════════════════════════════════════════════ */

static void test_volume_methods(void)
{
    ast_node_t *f, *g;
    ce_float_t result;
    ce_error_t err;

    printf("--- volume methods (disk/washer/shell) ---\n");

    /* ── Disk method ────────────────────────────────────── */

    /* Disk: y=1 from 0 to 1 -> pi*int(1, 0, 1) = pi ~ 3.14159 */
    mem_free_all();
    f = parse_str("1");
    if (f) {
        steps_clear();
        result = polar_disk(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "disk y=1: no error");
        ASSERT_EQ_FLOAT(result, CE_PI, 0.05f, "disk y=1 = pi");
        ast_free(f);
    }

    /* Disk: y=x from 0 to 1 -> pi*int(x^2, 0, 1) = pi/3 ~ 1.0472 */
    mem_free_all();
    f = parse_str("x");
    if (f) {
        steps_clear();
        result = polar_disk(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "disk y=x: no error");
        ASSERT_EQ_FLOAT(result, CE_PI / 3.0f, 0.02f, "disk y=x = pi/3");
        ast_free(f);
    }

    /* Disk: y=x^2 from 0 to 1 -> pi*int(x^4, 0, 1) = pi/5 ~ 0.6283 */
    mem_free_all();
    f = parse_str("x^2");
    if (f) {
        steps_clear();
        result = polar_disk(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "disk x^2: no error");
        ASSERT_EQ_FLOAT(result, CE_PI / 5.0f, 0.02f, "disk x^2 = pi/5");
        ast_free(f);
    }

    /* Sphere via disk: y=sqrt(r^2-x^2), r=2, from -2 to 2
     * V = pi*int(4-x^2, -2, 2) = pi*[4x-x^3/3] from -2 to 2
     * = pi*(8-8/3-(-8+8/3)) = pi*32/3 ~ 33.51 */
    mem_free_all();
    f = parse_str("sqrt(4-x^2)");
    if (f) {
        steps_clear();
        result = polar_disk(f, 'x', -2.0f, 2.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "disk sphere r=2: no error");
        ASSERT_EQ_FLOAT(result, CE_PI * 32.0f / 3.0f, 0.2f,
                        "disk sphere r=2 = 32pi/3");
        ast_free(f);
    }

    /* ── Washer method ─────────────────────────────────── */

    /* Washer: R=x, r=x^2 from 0 to 1
     * V = pi*int(x^2-x^4, 0, 1) = pi*(1/3-1/5) = 2pi/15 ~ 0.4189 */
    mem_free_all();
    f = parse_str("x");
    g = parse_str("x^2");
    if (f && g) {
        steps_clear();
        result = polar_washer(f, g, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "washer x,x^2: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI / 15.0f, 0.02f,
                        "washer x,x^2 = 2pi/15");
        ast_free(f);
        ast_free(g);
    }

    /* Washer: R=2, r=1 from 0 to 3 -> pi*(4-1)*3 = 9pi ~ 28.274 */
    mem_free_all();
    f = parse_str("2");
    g = parse_str("1");
    if (f && g) {
        steps_clear();
        result = polar_washer(f, g, 'x', 0.0f, 3.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "washer const: no error");
        ASSERT_EQ_FLOAT(result, 9.0f * CE_PI, 0.2f, "washer R=2,r=1 = 9pi");
        ast_free(f);
        ast_free(g);
    }

    /* ── Shell method ──────────────────────────────────── */

    /* Shell: f(x)=1 from 0 to 1: 2pi*int(x*1, 0, 1) = 2pi*(1/2) = pi */
    mem_free_all();
    f = parse_str("1");
    if (f) {
        steps_clear();
        result = polar_shell(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "shell f=1: no error");
        ASSERT_EQ_FLOAT(result, CE_PI, 0.05f, "shell f=1 = pi");
        ast_free(f);
    }

    /* Shell: f(x)=x from 0 to 1: 2pi*int(x^2, 0, 1) = 2pi/3 ~ 2.094 */
    mem_free_all();
    f = parse_str("x");
    if (f) {
        steps_clear();
        result = polar_shell(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "shell f=x: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI / 3.0f, 0.05f,
                        "shell f=x = 2pi/3");
        ast_free(f);
    }

    /* Shell: f(x)=x^2 from 0 to 1: 2pi*int(x^3, 0, 1) = 2pi/4 = pi/2 */
    mem_free_all();
    f = parse_str("x^2");
    if (f) {
        steps_clear();
        result = polar_shell(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "shell x^2: no error");
        ASSERT_EQ_FLOAT(result, CE_PI / 2.0f, 0.05f, "shell x^2 = pi/2");
        ast_free(f);
    }

    /* Shell: cone f(x)=2-2x from 0 to 1
     * V = 2pi*int(x*(2-2x), 0, 1) = 2pi*int(2x-2x^2, 0, 1)
     *   = 2pi*(1 - 2/3) = 2pi/3 ~ 2.094 */
    mem_free_all();
    f = parse_str("2-2*x");
    if (f) {
        steps_clear();
        result = polar_shell(f, 'x', 0.0f, 1.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "shell cone: no error");
        ASSERT_EQ_FLOAT(result, 2.0f * CE_PI / 3.0f, 0.05f,
                        "shell cone = 2pi/3");
        ast_free(f);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Parser depth limit                                    */
/* ═══════════════════════════════════════════════════════════ */
static void test_parser_depth_limit(void)
{
    char deep[256];
    int i;
    ast_node_t *root;

    printf("=== Parser Depth Limit ===\n");
    mem_free_all();

    /* Build a deeply nested expression: (((((...(1)...)))) */
    memset(deep, 0, sizeof(deep));
    for (i = 0; i < 60 && i < 120; i++) deep[i] = '(';
    deep[i++] = '1';
    {
        int j;
        for (j = 0; j < 60 && i < 250; j++, i++) deep[i] = ')';
    }
    deep[i] = '\0';

    root = parse_str(deep);
    ASSERT_TRUE(root == NULL, "depth 60: should fail (exceeds limit 50)");

    /* Moderate nesting should work */
    mem_free_all();
    memset(deep, 0, sizeof(deep));
    for (i = 0; i < 20; i++) deep[i] = '(';
    deep[i++] = '1';
    {
        int j;
        for (j = 0; j < 20; j++, i++) deep[i] = ')';
    }
    deep[i] = '\0';

    root = parse_str(deep);
    ASSERT_TRUE(root != NULL, "depth 20: should succeed");
    if (root) {
        eval_ctx_t ctx;
        ce_float_t val;
        eval_init(&ctx);
        val = eval_expr(&ctx, root);
        ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "deeply nested 1 = 1");
        ast_free(root);
    }
    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Power overflow detection                              */
/* ═══════════════════════════════════════════════════════════ */
static void test_power_overflow(void)
{
    ce_error_t err;
    ce_float_t val;

    printf("=== Power Overflow ===\n");
    mem_free_all();

    /* 2^200 should overflow float */
    val = eval_str("2^200", &err);
    ASSERT_TRUE(err == CE_ERR_OVERFLOW, "2^200 should overflow");
    (void)val;

    /* 10^50 should overflow float */
    val = eval_str("10^50", &err);
    ASSERT_TRUE(err == CE_ERR_OVERFLOW, "10^50 should overflow");

    /* Small powers should work */
    val = eval_str("2^10", &err);
    ASSERT_EQ_INT(err, CE_OK, "2^10 no error");
    ASSERT_EQ_FLOAT(val, 1024.0f, 0.01f, "2^10 = 1024");

    /* Negative base with integer exponent */
    val = eval_str("(-2)^3", &err);
    ASSERT_EQ_INT(err, CE_OK, "(-2)^3 no error");
    ASSERT_EQ_FLOAT(val, -8.0f, 0.01f, "(-2)^3 = -8");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Token overflow                                        */
/* ═══════════════════════════════════════════════════════════ */
static void test_token_overflow(void)
{
    char big[512];
    int i;
    tokenizer_t tok;
    ce_error_t err;

    printf("=== Token Overflow ===\n");

    /* Build an expression with more than 128 tokens: 1+1+1+1+... */
    memset(big, 0, sizeof(big));
    big[0] = '1';
    for (i = 1; i < 400 && (i*2+1) < 500; i++) {
        big[i*2-1] = '+';
        big[i*2]   = '1';
    }

    tok_init(&tok, big);
    err = tok_tokenize(&tok);
    ASSERT_TRUE(err == CE_ERR_OVERFLOW, "too many tokens -> overflow error");

    /* Moderate-length expression should succeed */
    {
        char moderate[128];
        memset(moderate, 0, sizeof(moderate));
        moderate[0] = '1';
        for (i = 1; i < 30 && (i*2+1) < 120; i++) {
            moderate[i*2-1] = '+';
            moderate[i*2]   = '2';
        }
        tok_init(&tok, moderate);
        err = tok_tokenize(&tok);
        ASSERT_EQ_INT(err, CE_OK, "moderate tokens -> success");
        ASSERT_TRUE(tok.count > 0, "moderate tokens: count > 0");
    }

    /* Empty string */
    tok_init(&tok, "");
    err = tok_tokenize(&tok);
    ASSERT_EQ_INT(err, CE_OK, "empty string -> ok");

    /* Single token */
    tok_init(&tok, "42");
    err = tok_tokenize(&tok);
    ASSERT_EQ_INT(err, CE_OK, "single number -> ok");
    ASSERT_TRUE(tok.count >= 1, "single number: at least 1 token");

    /* Nested functions stress */
    tok_init(&tok, "sin(cos(tan(ln(abs(sqrt(x))))))");
    err = tok_tokenize(&tok);
    ASSERT_EQ_INT(err, CE_OK, "nested functions -> ok");
    ASSERT_TRUE(tok.count >= 12, "nested functions: many tokens");
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Degree mode                                           */
/* ═══════════════════════════════════════════════════════════ */
static void test_degree_mode(void)
{
    ce_error_t err;
    ce_float_t val;

    printf("=== Degree Mode ===\n");
    mem_free_all();

    /* Save original setting */
    angle_mode_t saved = g_settings.angle_mode;

    /* Radian mode (default) */
    g_settings.angle_mode = ANGLE_RADIANS;
    val = eval_str("sin(pi/2)", &err);
    ASSERT_EQ_INT(err, CE_OK, "sin(pi/2) rad no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "sin(pi/2) rad = 1");

    val = eval_str("sec(pi/2)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "sec(pi/2) rad domain error");

    val = eval_str("csc(pi)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "csc(pi) rad domain error");

    val = eval_str("cot(pi)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "cot(pi) rad domain error");

    /* Degree mode */
    g_settings.angle_mode = ANGLE_DEGREES;
    val = eval_str("sin(90)", &err);
    ASSERT_EQ_INT(err, CE_OK, "sin(90) deg no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "sin(90) deg = 1");

    val = eval_str("cos(180)", &err);
    ASSERT_EQ_INT(err, CE_OK, "cos(180) deg no error");
    ASSERT_EQ_FLOAT(val, -1.0f, 0.001f, "cos(180) deg = -1");

    val = eval_str("tan(45)", &err);
    ASSERT_EQ_INT(err, CE_OK, "tan(45) deg no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "tan(45) deg = 1");

    /* Inverse trig in degree mode: asin(1) should return 90 */
    val = eval_str("asin(1)", &err);
    ASSERT_EQ_INT(err, CE_OK, "asin(1) deg no error");
    ASSERT_EQ_FLOAT(val, 90.0f, 0.01f, "asin(1) deg = 90");

    val = eval_str("acos(0)", &err);
    ASSERT_EQ_INT(err, CE_OK, "acos(0) deg no error");
    ASSERT_EQ_FLOAT(val, 90.0f, 0.01f, "acos(0) deg = 90");

    val = eval_str("atan(1)", &err);
    ASSERT_EQ_INT(err, CE_OK, "atan(1) deg no error");
    ASSERT_EQ_FLOAT(val, 45.0f, 0.01f, "atan(1) deg = 45");

    /* sec, csc, cot in degree mode */
    val = eval_str("sec(0)", &err);
    ASSERT_EQ_INT(err, CE_OK, "sec(0) deg no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "sec(0) deg = 1");

    val = eval_str("sec(90)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "sec(90) deg domain error");

    val = eval_str("csc(180)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "csc(180) deg domain error");

    val = eval_str("cot(180)", &err);
    ASSERT_EQ_INT(err, CE_ERR_DOMAIN, "cot(180) deg domain error");

    /* Restore */
    g_settings.angle_mode = saved;
    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Related rates                                         */
/* ═══════════════════════════════════════════════════════════ */
static void test_related_rates(void)
{
    ast_node_t *root;

    printf("=== Related Rates ===\n");
    mem_free_all();

    /* relrate(x^2+y^2) should parse successfully */
    root = parse_str("relrate(x^2+y^2)");
    ASSERT_TRUE(root != NULL, "relrate parse succeeds");
    if (root) {
        ASSERT_EQ_INT(root->type, NODE_POLAR, "relrate -> NODE_POLAR");
        ASSERT_EQ_INT(root->d.polar.op, POLOP_RELRATE, "op = RELRATE");
        ast_free(root);
    }

    /* relrate with equation form: relrate(x^2+y^2=z^2) */
    mem_free_all();
    root = parse_str("relrate(x^2+y^2=z^2)");
    ASSERT_TRUE(root != NULL, "relrate equation form parse succeeds");
    if (root) {
        /* The expr should be (x^2+y^2)-(z^2) */
        ASSERT_EQ_INT(root->d.polar.op, POLOP_RELRATE, "eq form op = RELRATE");
        ast_free(root);
    }

    /* Simple related rate: relrate(pi*r^2) */
    mem_free_all();
    root = parse_str("relrate(pi*r^2)");
    ASSERT_TRUE(root != NULL, "relrate pi*r^2 parses");
    if (root) ast_free(root);

    mem_free_all();
}

