/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Additional edge cases for robustness                  */
/* ═══════════════════════════════════════════════════════════ */
static void test_robustness(void)
{
    ast_node_t *root;
    ce_error_t err;
    ce_float_t val;

    printf("=== Robustness ===\n");

    /* Empty input */
    mem_free_all();
    root = parse_str("");
    ASSERT_TRUE(root == NULL, "empty input -> NULL");

    /* Just whitespace */
    mem_free_all();
    root = parse_str("   ");
    ASSERT_TRUE(root == NULL, "whitespace only -> NULL");

    /* Unmatched parenthesis */
    mem_free_all();
    root = parse_str("(1+2");
    ASSERT_TRUE(root == NULL, "unmatched paren -> NULL");

    /* Double operator */
    mem_free_all();
    root = parse_str("1++2");
    /* This should parse as 1+(+2) = 1+2 or fail */
    if (root) ast_free(root);

    /* Division by zero in expression */
    val = eval_str("1/0", &err);
    ASSERT_TRUE(err == CE_ERR_DIV_ZERO, "1/0 -> div zero");
    (void)val;

    /* sqrt of negative */
    val = eval_str("sqrt(-1)", &err);
    ASSERT_TRUE(err == CE_ERR_DOMAIN, "sqrt(-1) -> domain error");

    /* ln of zero */
    val = eval_str("ln(0)", &err);
    ASSERT_TRUE(err == CE_ERR_DOMAIN, "ln(0) -> domain error");

    /* ln of negative */
    val = eval_str("ln(-1)", &err);
    ASSERT_TRUE(err == CE_ERR_DOMAIN, "ln(-1) -> domain error");

    /* asin out of range */
    val = eval_str("asin(2)", &err);
    ASSERT_TRUE(err == CE_ERR_DOMAIN, "asin(2) -> domain error");

    /* Factorial guard */
    val = eval_str("13!", &err);
    ASSERT_EQ_FLOAT(val, 0.0f, 0.01f, "13! -> 0 (guard)");

    /* Very large sum guard */
    val = eval_str("sum(1/n,n,1,20000)", &err);
    ASSERT_TRUE(err == CE_ERR_OVERFLOW, "sum 20000 terms -> overflow");

    /* Multiple variables in expression */
    val = eval_str("x+y", &err);
    ASSERT_TRUE(err != CE_OK, "undefined vars -> error");

    /* Constants */
    val = eval_str("pi", &err);
    ASSERT_EQ_INT(err, CE_OK, "pi no error");
    ASSERT_EQ_FLOAT(val, CE_PI, 0.001f, "pi value");

    val = eval_str("e", &err);
    ASSERT_EQ_INT(err, CE_OK, "e no error");
    ASSERT_EQ_FLOAT(val, CE_E, 0.001f, "e value");

    /* Implicit multiplication edge cases */
    val = eval_str("2pi", &err);
    ASSERT_EQ_INT(err, CE_OK, "2pi no error");
    ASSERT_EQ_FLOAT(val, 2.0f * CE_PI, 0.01f, "2pi = 2*pi");

    val = eval_str("3e", &err);
    ASSERT_EQ_INT(err, CE_OK, "3e no error");
    ASSERT_EQ_FLOAT(val, 3.0f * CE_E, 0.01f, "3e = 3*e");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Simplifier additional cases                           */
/* ═══════════════════════════════════════════════════════════ */
static void test_simplifier_extra(void)
{
    ast_node_t *expr;
    char buf[128];

    printf("=== Simplifier Extra ===\n");

    /* x^1 -> x */
    mem_free_all();
    expr = parse_str("x^1");
    ASSERT_TRUE(expr != NULL, "simplify: parse x^1 non-null");
    if (expr) {
        expr = ast_simplify(expr);
        ast_to_str(expr, buf, sizeof(buf));
        ASSERT_STR_CONTAINS(buf, "x", "x^1 simplifies to x");
        ast_free(expr);
    }

    /* x^0 -> 1 */
    mem_free_all();
    expr = parse_str("x^0");
    ASSERT_TRUE(expr != NULL, "simplify: parse x^0 non-null");
    if (expr) {
        expr = ast_simplify(expr);
        ast_to_str(expr, buf, sizeof(buf));
        ASSERT_STR_CONTAINS(buf, "1", "x^0 simplifies to 1");
        ast_free(expr);
    }

    /* 0 * x -> 0 */
    mem_free_all();
    expr = parse_str("0*x");
    ASSERT_TRUE(expr != NULL, "simplify: parse 0*x non-null");
    if (expr) {
        expr = ast_simplify(expr);
        ast_to_str(expr, buf, sizeof(buf));
        ASSERT_STR_CONTAINS(buf, "0", "0*x simplifies to 0");
        ast_free(expr);
    }

    /* x/x -> 1 */
    mem_free_all();
    expr = parse_str("x/x");
    ASSERT_TRUE(expr != NULL, "simplify: parse x/x non-null");
    if (expr) {
        expr = ast_simplify(expr);
        ast_to_str(expr, buf, sizeof(buf));
        ASSERT_STR_CONTAINS(buf, "1", "x/x simplifies to 1");
        ast_free(expr);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  NEW: Matrix edge cases                                     */
/* ═══════════════════════════════════════════════════════════ */
static void test_matrix_extra(void)
{
    ce_matrix_t m, result;
    ce_float_t d;
    bool ok;

    printf("=== Matrix Extra ===\n");

    /* Identity matrix determinant = 1 */
    matrix_init(&m, 3, 3);
    m.data[0] = 1; m.data[1] = 0; m.data[2] = 0;
    m.data[3] = 0; m.data[4] = 1; m.data[5] = 0;
    m.data[6] = 0; m.data[7] = 0; m.data[8] = 1;
    d = matrix_det(&m);
    ASSERT_EQ_FLOAT(d, 1.0f, 0.001f, "identity 3x3 det = 1");

    /* Identity matrix inverse = identity */
    ok = matrix_inverse(&m, &result);
    ASSERT_TRUE(ok, "identity inverse succeeds");
    ASSERT_EQ_FLOAT(result.data[0], 1.0f, 0.001f, "inv identity [0,0] = 1");
    ASSERT_EQ_FLOAT(result.data[4], 1.0f, 0.001f, "inv identity [1,1] = 1");

    /* Singular matrix: all zeros */
    matrix_init(&m, 2, 2);
    m.data[0] = 0; m.data[1] = 0;
    m.data[2] = 0; m.data[3] = 0;
    d = matrix_det(&m);
    ASSERT_EQ_FLOAT(d, 0.0f, 0.001f, "zero matrix det = 0");

    ok = matrix_inverse(&m, &result);
    ASSERT_TRUE(!ok, "zero matrix inverse fails");

    /* Transpose */
    matrix_init(&m, 2, 3);
    m.data[0] = 1; m.data[1] = 2; m.data[2] = 3;
    m.data[3] = 4; m.data[4] = 5; m.data[5] = 6;
    matrix_transpose(&m, &result);
    ASSERT_EQ_INT(result.rows, 3, "transpose rows = 3");
    ASSERT_EQ_INT(result.cols, 2, "transpose cols = 2");
    ASSERT_EQ_FLOAT(result.data[0], 1.0f, 0.001f, "transpose [0,0] = 1");
    ASSERT_EQ_FLOAT(result.data[1], 4.0f, 0.001f, "transpose [0,1] = 4");
}

/* ═══════════════════════════════════════════════════════════ */
/*              STATISTICS MODULE TESTS                          */
/* ═══════════════════════════════════════════════════════════ */

static void test_statistics(void)
{
    ce_float_t data5[] = {4, 2, 7, 2, 5};
    ce_float_t data4[] = {10, 20, 30, 40};
    ce_float_t data1[] = {42};
    ce_float_t mode_data[] = {1, 2, 2, 3, 3, 3, 4};
    ce_float_t linreg_data[] = {1, 2, 2, 4, 3, 6, 4, 8};  /* perfect y=2x */
    ce_float_t m, b, r;
    ce_error_t err;

    printf("=== Statistics Module ===\n");

    /* stat_mean */
    ASSERT_EQ_FLOAT(stat_mean(data5, 5), 4.0f, 0.01f, "mean({4,2,7,2,5}) = 4");
    ASSERT_EQ_FLOAT(stat_mean(data4, 4), 25.0f, 0.01f, "mean({10,20,30,40}) = 25");
    ASSERT_EQ_FLOAT(stat_mean(data1, 1), 42.0f, 0.01f, "mean({42}) = 42");
    ASSERT_EQ_FLOAT(stat_mean(data5, 0), 0.0f, 0.01f, "mean(empty) = 0");

    /* stat_median (sorts in place, use copies) */
    {
        ce_float_t d[] = {5, 3, 1, 4, 2};
        ASSERT_EQ_FLOAT(stat_median(d, 5), 3.0f, 0.01f, "median odd = 3");
    }
    {
        ce_float_t d[] = {10, 40, 20, 30};
        ASSERT_EQ_FLOAT(stat_median(d, 4), 25.0f, 0.01f, "median even = 25");
    }
    {
        ce_float_t d[] = {7};
        ASSERT_EQ_FLOAT(stat_median(d, 1), 7.0f, 0.01f, "median single = 7");
    }
    ASSERT_EQ_FLOAT(stat_median(data5, 0), 0.0f, 0.01f, "median(empty) = 0");

    /* stat_mode */
    ASSERT_EQ_FLOAT(stat_mode(mode_data, 7), 3.0f, 0.01f, "mode({1,2,2,3,3,3,4}) = 3");
    ASSERT_EQ_FLOAT(stat_mode(data1, 1), 42.0f, 0.01f, "mode single = 42");

    /* stat_variance / stdev */
    {
        ce_float_t d[] = {2, 4, 4, 4, 5, 5, 7, 9};
        ce_float_t var = stat_variance(d, 8);
        ASSERT_EQ_FLOAT(var, 4.571f, 0.1f, "variance({2,4,4,4,5,5,7,9}) ~ 4.57");
        ASSERT_EQ_FLOAT(stat_stdev(d, 8), sqrtf(var), 0.01f, "stdev = sqrt(var)");
    }
    ASSERT_EQ_FLOAT(stat_variance(data1, 1), 0.0f, 0.01f, "variance(n=1) = 0");

    /* stat_min / stat_max */
    ASSERT_EQ_FLOAT(stat_min(data5, 5), 2.0f, 0.01f, "min({4,2,7,2,5}) = 2");
    ASSERT_EQ_FLOAT(stat_max(data5, 5), 7.0f, 0.01f, "max({4,2,7,2,5}) = 7");
    ASSERT_EQ_FLOAT(stat_min(data5, 0), 0.0f, 0.01f, "min(empty) = 0");
    ASSERT_EQ_FLOAT(stat_max(data5, 0), 0.0f, 0.01f, "max(empty) = 0");

    /* stat_linreg: perfect y=2x line */
    err = stat_linreg(linreg_data, 8, &m, &b, &r);
    ASSERT_TRUE(err == CE_OK, "linreg perfect line: ok");
    ASSERT_EQ_FLOAT(m, 2.0f, 0.01f, "linreg slope = 2");
    ASSERT_EQ_FLOAT(b, 0.0f, 0.1f, "linreg intercept ~ 0");
    ASSERT_EQ_FLOAT(r, 1.0f, 0.01f, "linreg r = 1");

    /* linreg too few points */
    err = stat_linreg(data1, 2, &m, &b, &r);
    ASSERT_TRUE(err == CE_ERR_DOMAIN, "linreg < 2 points: domain err");

    /* stat_ncr / stat_npr */
    ASSERT_EQ_FLOAT(stat_ncr(5, 2), 10.0f, 0.01f, "5C2 = 10");
    ASSERT_EQ_FLOAT(stat_ncr(10, 3), 120.0f, 0.01f, "10C3 = 120");
    ASSERT_EQ_FLOAT(stat_ncr(0, 0), 1.0f, 0.01f, "0C0 = 1");
    ASSERT_EQ_FLOAT(stat_ncr(5, 0), 1.0f, 0.01f, "5C0 = 1");
    ASSERT_EQ_FLOAT(stat_ncr(5, 6), 0.0f, 0.01f, "5C6 = 0 (r > n)");
    ASSERT_EQ_FLOAT(stat_npr(5, 2), 20.0f, 0.01f, "5P2 = 20");
    ASSERT_EQ_FLOAT(stat_npr(10, 3), 720.0f, 0.01f, "10P3 = 720");
    ASSERT_EQ_FLOAT(stat_npr(5, 0), 1.0f, 0.01f, "5P0 = 1");
}

/* ═══════════════════════════════════════════════════════════ */
/*              MATRIX OPERATIONS TESTS                         */
/* ═══════════════════════════════════════════════════════════ */

static void test_matrix_ops(void)
{
    ce_matrix_t a, b, c;
    bool ok;
    char buf[256];

    printf("=== Matrix Operations ===\n");

    /* matrix_add */
    matrix_init(&a, 2, 2);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 3; a.data[3] = 4;
    matrix_init(&b, 2, 2);
    b.data[0] = 5; b.data[1] = 6; b.data[2] = 7; b.data[3] = 8;
    ok = matrix_add(&a, &b, &c);
    ASSERT_TRUE(ok, "matrix_add 2x2 succeeds");
    ASSERT_EQ_FLOAT(c.data[0], 6.0f, 0.01f, "add [0,0] = 6");
    ASSERT_EQ_FLOAT(c.data[3], 12.0f, 0.01f, "add [1,1] = 12");

    /* matrix_sub */
    ok = matrix_sub(&b, &a, &c);
    ASSERT_TRUE(ok, "matrix_sub 2x2 succeeds");
    ASSERT_EQ_FLOAT(c.data[0], 4.0f, 0.01f, "sub [0,0] = 4");
    ASSERT_EQ_FLOAT(c.data[3], 4.0f, 0.01f, "sub [1,1] = 4");

    /* dimension mismatch for add */
    matrix_init(&b, 3, 3);
    ok = matrix_add(&a, &b, &c);
    ASSERT_TRUE(!ok, "add dim mismatch returns false");

    /* matrix_mul */
    matrix_init(&a, 2, 3);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 3;
    a.data[3] = 4; a.data[4] = 5; a.data[5] = 6;
    matrix_init(&b, 3, 2);
    b.data[0] = 7;  b.data[1] = 8;
    b.data[2] = 9;  b.data[3] = 10;
    b.data[4] = 11; b.data[5] = 12;
    ok = matrix_mul(&a, &b, &c);
    ASSERT_TRUE(ok, "mul 2x3 * 3x2 succeeds");
    ASSERT_EQ_INT(c.rows, 2, "mul result rows = 2");
    ASSERT_EQ_INT(c.cols, 2, "mul result cols = 2");
    ASSERT_EQ_FLOAT(c.data[0], 58.0f, 0.01f, "mul [0,0] = 58");   /* 1*7+2*9+3*11 */
    ASSERT_EQ_FLOAT(c.data[3], 154.0f, 0.01f, "mul [1,1] = 154"); /* 4*8+5*10+6*12 */

    /* mul dimension mismatch */
    matrix_init(&b, 2, 2);
    ok = matrix_mul(&a, &b, &c);
    ASSERT_TRUE(!ok, "mul dim mismatch returns false");

    /* matrix_scale */
    matrix_init(&a, 2, 2);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 3; a.data[3] = 4;
    matrix_scale(&a, 3.0f, &c);
    ASSERT_EQ_FLOAT(c.data[0], 3.0f, 0.01f, "scale [0,0] = 3");
    ASSERT_EQ_FLOAT(c.data[3], 12.0f, 0.01f, "scale [1,1] = 12");

    /* matrix_rref */
    matrix_init(&a, 2, 3);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 5;
    a.data[3] = 3; a.data[4] = 4; a.data[5] = 11;
    matrix_rref(&a);
    ASSERT_EQ_FLOAT(a.data[0], 1.0f, 0.01f, "rref [0,0] = 1");
    ASSERT_EQ_FLOAT(a.data[1], 0.0f, 0.01f, "rref [0,1] = 0");
    ASSERT_EQ_FLOAT(a.data[4], 1.0f, 0.01f, "rref [1,1] = 1");

    /* Non-trivial determinant: [[2,3],[1,4]] -> det = 5 */
    matrix_init(&a, 2, 2);
    a.data[0] = 2; a.data[1] = 3; a.data[2] = 1; a.data[3] = 4;
    ASSERT_EQ_FLOAT(matrix_det(&a), 5.0f, 0.01f, "det [[2,3],[1,4]] = 5");

    /* Non-trivial inverse */
    ok = matrix_inverse(&a, &c);
    ASSERT_TRUE(ok, "inverse of [[2,3],[1,4]] succeeds");
    ASSERT_EQ_FLOAT(c.data[0], 0.8f, 0.01f, "inv [0,0] = 4/5");
    ASSERT_EQ_FLOAT(c.data[1], -0.6f, 0.01f, "inv [0,1] = -3/5");

    /* matrix_to_str */
    matrix_init(&a, 1, 2);
    a.data[0] = 1; a.data[1] = 2;
    matrix_to_str(&a, buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "[", "to_str contains [");
    ASSERT_STR_CONTAINS(buf, "1", "to_str contains 1");
    ASSERT_STR_CONTAINS(buf, "2", "to_str contains 2");

    /* matrix_to_str tiny buffer — must still null-terminate */
    matrix_to_str(&a, buf, 3);
    ASSERT_TRUE(buf[2] == '\0' || buf[1] == '\0' || buf[0] == '\0',
                "to_str tiny buf is null-terminated");
}

/* ═══════════════════════════════════════════════════════════ */
/*              UI INPUT BUFFER TESTS                           */
/* ═══════════════════════════════════════════════════════════ */

static void test_input_buffer(void)
{
    input_buf_t ib;
    bool ok;
    int i;

    printf("=== UI Input Buffer ===\n");

    /* init */
    input_buf_init(&ib);
    ASSERT_EQ_INT(ib.len, 0, "init: len = 0");
    ASSERT_EQ_INT(ib.cursor, 0, "init: cursor = 0");

    /* insert single char */
    ok = input_buf_insert(&ib, 'A');
    ASSERT_TRUE(ok, "insert 'A' succeeds");
    ASSERT_EQ_INT(ib.len, 1, "after insert: len = 1");
    ASSERT_TRUE(ib.buf[0] == 'A', "after insert: buf[0] = 'A'");
    ASSERT_EQ_INT(ib.cursor, 1, "after insert: cursor = 1");

    /* insert string */
    ok = input_buf_insert_str(&ib, "BC");
    ASSERT_TRUE(ok, "insert_str 'BC' succeeds");
    ASSERT_EQ_INT(ib.len, 3, "after insert_str: len = 3");
    ASSERT_TRUE(ib.buf[1] == 'B' && ib.buf[2] == 'C', "insert_str content correct");

    /* backspace */
    ok = input_buf_backspace(&ib);
    ASSERT_TRUE(ok, "backspace succeeds");
    ASSERT_EQ_INT(ib.len, 2, "after backspace: len = 2");
    ASSERT_TRUE(ib.buf[1] == 'B', "after backspace: last char = B");

    /* backspace at start fails */
    input_buf_clear(&ib);
    ok = input_buf_backspace(&ib);
    ASSERT_TRUE(!ok, "backspace on empty fails");

    /* clear */
    input_buf_insert_str(&ib, "test");
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "after clear: len = 0");
    ASSERT_EQ_INT(ib.cursor, 0, "after clear: cursor = 0");

    /* overflow protection */
    input_buf_clear(&ib);
    for (i = 0; i < MAX_INPUT_LEN + 10; i++)
        input_buf_insert(&ib, 'X');
    ASSERT_TRUE(ib.len <= MAX_INPUT_LEN - 1, "overflow: len clamped");
    ASSERT_TRUE(ib.buf[ib.len] == '\0', "overflow: null-terminated");
}

static void ui_mock_release_keys(void)
{
    kb_mock_reset();
    (void)ui_poll_key();
}

static key_event_t ui_mock_press_group(uint8_t group, uint16_t mask)
{
    kb_Data[group] = mask;
    return ui_poll_key();
}

static void ui_mock_arm_second(void)
{
    key_event_t evt = ui_mock_press_group(1, kb_2nd);
    ASSERT_EQ_INT(evt.action, KEY_NONE, "keymap: 2nd arms shift state");
    ui_mock_release_keys();
}

static void ui_mock_arm_alpha(void)
{
    key_event_t evt = ui_mock_press_group(2, kb_Alpha);
    ASSERT_EQ_INT(evt.action, KEY_NONE, "keymap: alpha arms alpha state");
    ui_mock_release_keys();
}

static const gfx_mock_text_call_t *gfx_mock_find_text_exact(const char *needle)
{
    int i;

    for (i = 0; i < gfx_mock_text_call_count(); i++) {
        const gfx_mock_text_call_t *call = gfx_mock_text_call_at(i);
        if (call && strcmp(call->text, needle) == 0) return call;
    }

    return NULL;
}

