    /* ── 4. Derivatives of new functions ─────────────── */
    printf("  -- Derivatives of new functions --\n");
    {
        /* d/dx asec(x) = 1/(|x|*sqrt(x^2-1))
         * At x=2: 1/(2*sqrt(3)) ≈ 0.2887 */
        mem_free_all();
        root = parse_str("asec(x)");
        ASSERT_TRUE(root != NULL, "parse asec(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx asec(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 2.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx asec(2) no err");
                ASSERT_EQ_FLOAT(val, 1.0f / (2.0f * sqrtf(3.0f)), 0.01f,
                                "d/dx asec(x) at 2");
                ast_free(result);
            }
            ast_free(root);
        }

        /* d/dx acsc(x) = -1/(|x|*sqrt(x^2-1))
         * At x=2: -1/(2*sqrt(3)) ≈ -0.2887 */
        mem_free_all();
        root = parse_str("acsc(x)");
        ASSERT_TRUE(root != NULL, "parse acsc(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx acsc(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 2.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx acsc(2) no err");
                ASSERT_EQ_FLOAT(val, -1.0f / (2.0f * sqrtf(3.0f)), 0.01f,
                                "d/dx acsc(x) at 2");
                ast_free(result);
            }
            ast_free(root);
        }

        /* d/dx acot(x) = -1/(1+x^2)
         * At x=1: -1/2 = -0.5 */
        mem_free_all();
        root = parse_str("acot(x)");
        ASSERT_TRUE(root != NULL, "parse acot(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx acot(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 1.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx acot(1) no err");
                ASSERT_EQ_FLOAT(val, -0.5f, 0.01f,
                                "d/dx acot(x) at 1 = -0.5");
                ast_free(result);
            }
            ast_free(root);
        }

        /* d/dx sech(x) = -sech(x)*tanh(x)
         * At x=1: -sech(1)*tanh(1) ≈ -(0.6481)*(0.7616) ≈ -0.4937 */
        mem_free_all();
        root = parse_str("sech(x)");
        ASSERT_TRUE(root != NULL, "parse sech(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx sech(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 1.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx sech(1) no err");
                ce_float_t expected = -(1.0f/coshf(1.0f)) * tanhf(1.0f);
                ASSERT_EQ_FLOAT(val, expected, 0.01f,
                                "d/dx sech(x) at 1");
                ast_free(result);
            }
            ast_free(root);
        }

        /* d/dx csch(x) = -csch(x)*coth(x)
         * At x=1: -csch(1)*coth(1) */
        mem_free_all();
        root = parse_str("csch(x)");
        ASSERT_TRUE(root != NULL, "parse csch(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx csch(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 1.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx csch(1) no err");
                ce_float_t expected = -(1.0f/sinhf(1.0f)) *
                                      (coshf(1.0f)/sinhf(1.0f));
                ASSERT_EQ_FLOAT(val, expected, 0.01f,
                                "d/dx csch(x) at 1");
                ast_free(result);
            }
            ast_free(root);
        }

        /* d/dx coth(x) = -csch^2(x)
         * At x=1: -csch^2(1) = -1/sinh^2(1) */
        mem_free_all();
        root = parse_str("coth(x)");
        ASSERT_TRUE(root != NULL, "parse coth(x) for deriv");
        if (root) {
            result = deriv_diff(root, 'x');
            ASSERT_TRUE(result != NULL, "d/dx coth(x) non-null");
            if (result) {
                val = eval_at(result, 'x', 1.0f, &err);
                ASSERT_TRUE(err == CE_OK, "d/dx coth(1) no err");
                ce_float_t sh = sinhf(1.0f);
                ce_float_t expected = -1.0f / (sh * sh);
                ASSERT_EQ_FLOAT(val, expected, 0.01f,
                                "d/dx coth(x) at 1");
                ast_free(result);
            }
            ast_free(root);
        }
    }

