    /* ── 6. Steps overflow indicator ─────────────────── */
    printf("  -- Steps overflow indicator --\n");
    {
        steps_clear();
        ASSERT_TRUE(!steps_full(), "steps: not full initially");

        /* Fill up to MAX_STEPS */
        for (i = 0; i < MAX_STEPS; i++) {
            bool ok = steps_addf("Step %d", i);
            if (i < MAX_STEPS)
                ASSERT_TRUE(ok, "steps: add succeeds before full");
        }

        /* Now the buffer is full — the next add should fail */
        bool overflow_add = steps_add("This should overflow");
        ASSERT_TRUE(!overflow_add, "steps: add returns false when full");
        ASSERT_TRUE(steps_full(), "steps: full flag set after overflow");

        /* Last step should be the truncation notice */
        const char *last = steps_get(MAX_STEPS - 1);
        ASSERT_STR_CONTAINS(last, "omitted",
                            "steps: last slot has truncation notice");

        /* Count should still be MAX_STEPS */
        ASSERT_EQ_INT(steps_count(), MAX_STEPS,
                      "steps: count = MAX_STEPS after overflow");

        /* steps_addf also returns false when full */
        bool overflow_addf = steps_addf("Also overflow %d", 42);
        ASSERT_TRUE(!overflow_addf, "steps: addf returns false when full");

        /* Restore clears overflow */
        steps_restore(5);
        ASSERT_TRUE(!steps_full(), "steps: restore clears overflow");
        ASSERT_EQ_INT(steps_count(), 5,
                      "steps: count = 5 after restore");

        /* Can add again after restore */
        bool ok_after = steps_add("After restore");
        ASSERT_TRUE(ok_after, "steps: add succeeds after restore");
        ASSERT_EQ_INT(steps_count(), 6,
                      "steps: count = 6 after add");

        steps_clear();
    }

    /* ── 7. Series test_integral renamed to test_tail_ratio ─ */
    printf("  -- Series tail ratio test --\n");
