    /* ── 8. Related rates — end-to-end partial deriv ───── */
    printf("  -- Related rates end-to-end --\n");
    {
        /* relrate(x^2+y^2) — parse + verify partial derivs exist */
        mem_free_all();
        root = parse_str("relrate(x^2+y^2)");
        ASSERT_TRUE(root != NULL, "relrate: parse x^2+y^2");
        if (root) {
            ASSERT_EQ_INT(root->type, NODE_POLAR,
                          "relrate: NODE_POLAR");
            ASSERT_EQ_INT(root->d.polar.op, POLOP_RELRATE,
                          "relrate: POLOP_RELRATE");

            /* Verify the inner expression contains x and y */
            const ast_node_t *expr = root->d.polar.expr1;
            ASSERT_TRUE(ast_contains_var(expr, 'x'),
                        "relrate: expr contains x");
            ASSERT_TRUE(ast_contains_var(expr, 'y'),
                        "relrate: expr contains y");

            /* Compute partial derivatives like main.c does */
            ast_node_t *dx = deriv_diff_quiet(expr, 'x');
            ASSERT_TRUE(dx != NULL, "relrate: d/dx(x^2+y^2) non-null");
            if (dx) {
                /* d/dx(x^2+y^2) = 2x; at x=3 should be 6 */
                val = eval_at(dx, 'x', 3.0f, &err);
                ASSERT_TRUE(err == CE_OK, "relrate: eval dx no err");
                ASSERT_EQ_FLOAT(val, 6.0f, 0.1f,
                                "relrate: d/dx(x^2+y^2) at x=3 = 6");
                ast_free(dx);
            }

            ast_node_t *dy = deriv_diff_quiet(expr, 'y');
            ASSERT_TRUE(dy != NULL, "relrate: d/dy(x^2+y^2) non-null");
            if (dy) {
                /* d/dy(x^2+y^2) = 2y; at y=4 should be 8 */
                val = eval_at(dy, 'y', 4.0f, &err);
                ASSERT_TRUE(err == CE_OK, "relrate: eval dy no err");
                ASSERT_EQ_FLOAT(val, 8.0f, 0.1f,
                                "relrate: d/dy(x^2+y^2) at y=4 = 8");
                ast_free(dy);
            }

            ast_free(root);
        }

        /* relrate(pi*r^2) — circle area: dA/dt = 2*pi*r * dr/dt */
        mem_free_all();
        root = parse_str("relrate(pi*r^2)");
        ASSERT_TRUE(root != NULL, "relrate: parse pi*r^2");
        if (root) {
            const ast_node_t *expr = root->d.polar.expr1;
            ast_node_t *dr = deriv_diff_quiet(expr, 'r');
            ASSERT_TRUE(dr != NULL, "relrate: d/dr(pi*r^2) non-null");
            if (dr) {
                /* d/dr(pi*r^2) = 2*pi*r; at r=5 should be 10*pi */
                val = eval_at(dr, 'r', 5.0f, &err);
                ASSERT_TRUE(err == CE_OK, "relrate: eval dr no err");
                ASSERT_EQ_FLOAT(val, 10.0f * CE_PI, 0.5f,
                                "relrate: d/dr(pi*r^2) at r=5 = 10pi");
                ast_free(dr);
            }
            ast_free(root);
        }

        /* relrate with equation form: relrate(x^2+y^2=25) */
        mem_free_all();
        root = parse_str("relrate(x^2+y^2=25)");
        ASSERT_TRUE(root != NULL, "relrate: parse equation form");
        if (root) {
            ASSERT_EQ_INT(root->d.polar.op, POLOP_RELRATE,
                          "relrate: equation op = RELRATE");
            /* The expr should be (x^2+y^2)-(25) = x^2+y^2-25 */
            const ast_node_t *expr = root->d.polar.expr1;
            ASSERT_TRUE(expr != NULL, "relrate: equation expr non-null");
            if (expr) {
                /* d/dx: should be 2x */
                ast_node_t *dx = deriv_diff_quiet(expr, 'x');
                ASSERT_TRUE(dx != NULL,
                            "relrate: d/dx(x^2+y^2-25) non-null");
                if (dx) {
                    val = eval_at(dx, 'x', 3.0f, &err);
                    ASSERT_EQ_FLOAT(val, 6.0f, 0.1f,
                                    "relrate: eq form dx at 3 = 6");
                    ast_free(dx);
                }
            }
            ast_free(root);
        }
    }

