    /* ── 4. Step-by-step navigation (reveal count) ─────────── */
    {
        printf("  -- Step-by-step navigation --\n");

        /* Generate some steps via differentiation */
        steps_clear();
        {
            ast_node_t *root = parse_str("d/dx(x^3+2*x)");
            ASSERT_TRUE(root != NULL, "r25: parse d/dx(x^3+2*x)");
            if (root && root->type == NODE_DERIV) {
                ast_node_t *result = deriv_diff(root->d.deriv.expr, root->d.deriv.var);
                ASSERT_TRUE(result != NULL, "r25: deriv result non-null");
                uint8_t total = (uint8_t)steps_count();
                ASSERT_TRUE(total > 0, "r25: derivative produces steps");

                /* Simulate reveal: should show 1, then 2, ... up to total */
                uint8_t reveal = 1;
                ASSERT_TRUE(reveal <= total, "r25: first reveal within range");
                reveal = total;
                ASSERT_TRUE(reveal == total, "r25: all revealed = total");

                /* Edge: reveal 0 means nothing shown */
                ASSERT_TRUE(0 < total, "r25: total > 0 for non-trivial deriv");

                if (result) ast_free(result);
                ast_free(root);
            }
            mem_free_all();
        }

        /* Integration also produces steps */
        steps_clear();
        {
            ast_node_t *root = parse_str("int(x^2,x)");
            ASSERT_TRUE(root != NULL, "r25: parse int(x^2,x)");
            if (root && root->type == NODE_INTEGRAL) {
                ast_node_t *result = integrate(root->d.integral.expr, root->d.integral.var);
                ASSERT_TRUE(result != NULL, "r25: integrate result");
                uint8_t total = (uint8_t)steps_count();
                ASSERT_TRUE(total > 0, "r25: integration produces steps");

                /* Can reveal incrementally */
                uint8_t i;
                for (i = 0; i <= total; i++) {
                    ASSERT_TRUE(i <= steps_count(), "r25: reveal index in range");
                }

                if (result) ast_free(result);
                ast_free(root);
            }
            mem_free_all();
        }

        /* Steps get function: valid indices return content, invalid empty string */
        steps_clear();
        steps_add("Step 1");
        steps_add("Step 2");
        steps_add("Step 3");
        ASSERT_EQ_INT(steps_count(), 3, "r25: 3 steps added");
        ASSERT_STR_CONTAINS(steps_get(0), "Step 1", "r25: step 0 = Step 1");
        ASSERT_STR_CONTAINS(steps_get(1), "Step 2", "r25: step 1 = Step 2");
        ASSERT_STR_CONTAINS(steps_get(2), "Step 3", "r25: step 2 = Step 3");
        /* Out-of-bounds returns empty string */
        ASSERT_EQ_INT(strlen(steps_get(3)), 0, "r25: step 3 = empty (OOB)");
        ASSERT_EQ_INT(strlen(steps_get(255)), 0, "r25: step 255 = empty");
        steps_clear();
    }

