static void test_round30_pretty_rendering(void)
{
    char out[256];

    printf("=== Round 30: Pretty Math Rendering ===\n");
    mem_free_all();

    ui_format_math_pretty("x^2 + y^(10)", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "x\xC2\xB2 + y\xC2\xB9\xE2\x81\xB0") == 0,
                "r30: superscript formatting");

    ui_format_math_pretty("sqrt(x^2/4)", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "\xE2\x88\x9A(x\xC2\xB2\xE2\x81\x84" "4)") == 0,
                "r30: sqrt + fraction slash");

    ui_format_math_pretty("int(x^2,x,0,1)", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "\xE2\x88\xAB_{0}^{1} x\xC2\xB2 dx") == 0,
                "r30: definite integral with bounds");

    ui_format_math_pretty("a_1 + x_23", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "a\xE2\x82\x81 + x\xE2\x82\x82\xE2\x82\x83") == 0,
                "r30: subscript formatting");

    ui_format_math_pretty("int(x,x)+sum(n,n,1,10)+prod(k,k,1,5)", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out,
                       "\xE2\x88\xAB x dx+\xE2\x88\x91_{n=1}^{10} n+\xE2\x88\x8F_{k=1}^{5} k") == 0,
                "r30: latex-style int/sum/prod with bounds");

    ui_format_math_pretty("sum(k,k,1,n^2)", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "\xE2\x88\x91_{k=1}^{n\xC2\xB2} k") == 0,
                "r30: summation bound pretty formatting");

    ui_format_math_pretty("x^y + a / b", out, (int)sizeof(out));
    ASSERT_TRUE(strcmp(out, "x^y + a / b") == 0,
                "r30: unsupported exponents and spaced slash unchanged");

    {
        char tiny[8];
        ui_format_math_pretty("sqrt(x^23456)", tiny, (int)sizeof(tiny));
        ASSERT_TRUE(tiny[sizeof(tiny) - 1] == '\0', "r30: tiny buffer null-terminated");
    }

    ui_draw_result_colored("= sqrt(x^2/4)\nint(x,x)\nsum(n,n,1,10)");
    ASSERT_TRUE(1, "r30: colored pretty render no crash");
}

static void test_round31_factoring_fallback(void)
{
    ast_node_t *expr, *factored;
    eval_ctx_t ctx;
    ce_float_t val;
    ce_float_t probe_root = -120.7f;
    int i, root_steps = 0;
    int saw_root_120 = 0;
    char buf[256];

    printf("=== Round 31: Factoring Fallback Robustness ===\n");
    mem_free_all();
    steps_clear();

    expr = parse_str("x^4+286.2*x^3+25884.97*x^2+773793.216*x+7309888.6024");
    ASSERT_TRUE(expr != NULL, "r31: parse quartic with distant repeated roots");
    if (!expr) {
        mem_free_all();
        return;
    }

    factored = algebra_factor(expr, 'x');
    ASSERT_TRUE(factored != NULL, "r31: factor quartic non-null");
    if (!factored) {
        ast_free(expr);
        mem_free_all();
        return;
    }

    for (i = 0; i < steps_count(); i++) {
        const char *s = steps_get(i);
        ce_float_t r = 0.0f;
        if (s && sscanf(s, "Root: x = %f", &r) == 1) {
            root_steps++;
            if (fabsf(r + 120.7f) < 1.0f) {
                saw_root_120 = 1;
                probe_root = r;
            }
        }
    }

    ASSERT_TRUE(root_steps >= 1, "r31: fallback finds a root beyond fixed +/-10 starts");
    ASSERT_TRUE(saw_root_120, "r31: found root near x=-120.7");

    ast_to_str(factored, buf, sizeof(buf));
    ASSERT_STR_CONTAINS(buf, "*", "r31: factor result includes multiplicative factorization");

    eval_init(&ctx);
    eval_set_var(&ctx, 'x', probe_root);
    val = eval_expr(&ctx, factored);
    ASSERT_EQ_FLOAT(val, 0.0f, 2.0f, "r31: factored(probe root) ~= 0");

    ast_free(factored);
    ast_free(expr);
    mem_free_all();
}

/* Annihilating simplifier rules need an exact zero.  The
 * tolerant is_num(n, 0) (|n| < 1e-10) used to turn 1e-30*x into 1e-30 and
 * -(1e-30) into +1e-30, which removed a linear ODE's integrating factor. */
static void test_simplify_tiny_nonzero_operands(void)
{
    ast_node_t *r;

    printf("=== Simplify Tiny Nonzero Operands ===\n");
    mem_free_all();

    r = ast_simplify(ast_binop(OP_MUL, ast_number(1e-30f), ast_variable('x')));
    ASSERT_TRUE(r && ast_contains_var(r, 'x'), "tiny: 1e-30*x keeps x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_MUL, ast_variable('x'), ast_number(1e-30f)));
    ASSERT_TRUE(r && ast_contains_var(r, 'x'), "tiny: x*1e-30 keeps x");
    ast_free(r);
    r = ast_simplify(ast_unop(UOP_NEG, ast_number(1e-30f)));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == -1e-30f,
                "tiny: -(1e-30) folds to -1e-30");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_DIV, ast_number(1e-30f), ast_variable('x')));
    ASSERT_TRUE(r && ast_contains_var(r, 'x'), "tiny: 1e-30/x keeps x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_POW, ast_number(1e-30f), ast_variable('x')));
    ASSERT_TRUE(r && ast_contains_var(r, 'x'), "tiny: 1e-30^x keeps x");
    ast_free(r);

    /* Exact zeros still annihilate. */
    r = ast_simplify(ast_binop(OP_MUL, ast_number(0), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: 0*x -> 0");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_MUL, ast_variable('x'), ast_number(0)));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: x*0 -> 0");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_DIV, ast_number(0), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: 0/x -> 0");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_POW, ast_number(0), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: 0^x -> 0");
    ast_free(r);
    r = ast_simplify(ast_unop(UOP_NEG, ast_binop(OP_MUL, ast_number(0),
                                                 ast_variable('x'))));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: -(0*x) -> 0");
    ast_free(r);

    /* -0.0 compares equal to 0, so it still annihilates. */
    r = ast_simplify(ast_binop(OP_MUL, ast_number(-0.0f), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_NUMBER && r->d.number == 0, "tiny: -0*x -> 0");
    ast_free(r);

    /* The additive identity is exact too, so 1e-30+x keeps
     * the typed constant (it used to simplify to x). */
    r = ast_simplify(ast_binop(OP_ADD, ast_number(1e-30f), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_BINOP && r->d.binop.op == OP_ADD,
                "tiny: 1e-30+x keeps 1e-30");
    ast_free(r);
    ASSERT_EQ_INT(mem_nodes_used(), 0, "tiny: no leaked nodes");
    mem_free_all();
}

/* Build-and-check helper: is t a binop `op` whose operands are the number
 * c (on side num_left) and the variable x? */
static bool tiny_is_binop_num_var(const ast_node_t *t, binop_t op,
                                  ce_float_t c, bool num_left)
{
    const ast_node_t *n, *v;
    if (!t || t->type != NODE_BINOP || t->d.binop.op != op) return false;
    n = num_left ? t->d.binop.left : t->d.binop.right;
    v = num_left ? t->d.binop.right : t->d.binop.left;
    return n->type == NODE_NUMBER && n->d.number == c &&
           v->type == NODE_VARIABLE && v->d.variable == 'x';
}

/* Evaluate deriv_diff(parse(input)) at x = at. */
static ce_float_t tiny_deriv_at(const char *input, ce_float_t at,
                                ce_error_t *err)
{
    ast_node_t *expr, *d;
    eval_ctx_t ctx;
    ce_float_t v;
    expr = parse_str(input);
    d = expr ? deriv_diff(expr, 'x') : NULL;
    if (!d) { ast_free(expr); *err = CE_ERR_DOMAIN; return 0; }
    eval_init(&ctx);
    eval_set_var(&ctx, 'x', at);
    v = eval_expr(&ctx, d);
    *err = eval_error(&ctx);
    ast_free(d);
    ast_free(expr);
    return v;
}

/* The old ADD/SUB identities used the tolerant is_num(n, 0)
 * (|n| < 1e-10) and dropped typed constants such as 5e-11, so
 * d/dx(ln(x+5e-11)) became 1/x: 2x too large at x = 5e-11 and undefined
 * at x = 0, where the function is defined.  They now need an exact zero. */
static void test_simplify_exact_additive_identities(void)
{
    ast_node_t *r;
    ce_error_t err;
    ce_float_t v;

    printf("=== Simplify Exact Additive Identities ===\n");
    mem_free_all();

    /* Tiny nonzero constants survive every ADD/SUB identity site. */
    r = ast_simplify(ast_binop(OP_ADD, ast_number(5e-11f), ast_variable('x')));
    ASSERT_TRUE(tiny_is_binop_num_var(r, OP_ADD, 5e-11f, true) ||
                tiny_is_binop_num_var(r, OP_ADD, 5e-11f, false),
                "exact add: 5e-11+x keeps 5e-11");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_ADD, ast_variable('x'), ast_number(5e-11f)));
    ASSERT_TRUE(tiny_is_binop_num_var(r, OP_ADD, 5e-11f, false),
                "exact add: x+5e-11 keeps 5e-11");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_SUB, ast_variable('x'), ast_number(5e-11f)));
    ASSERT_TRUE(tiny_is_binop_num_var(r, OP_SUB, 5e-11f, false),
                "exact sub: x-5e-11 keeps 5e-11");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_SUB, ast_number(5e-11f), ast_variable('x')));
    ASSERT_TRUE(tiny_is_binop_num_var(r, OP_SUB, 5e-11f, true),
                "exact sub: 5e-11-x keeps 5e-11 (not -x)");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_ADD, ast_variable('x'), ast_number(1e-30f)));
    ASSERT_TRUE(tiny_is_binop_num_var(r, OP_ADD, 1e-30f, false),
                "exact add: x+1e-30 keeps 1e-30");
    ast_free(r);
    ASSERT_EQ_INT(mem_nodes_used(), 0, "exact add: no leaked nodes (tiny)");

    /* Exact zeros, including -0.0, are still identities. */
    r = ast_simplify(ast_binop(OP_ADD, ast_number(0), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_VARIABLE, "exact add: 0+x -> x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_ADD, ast_variable('x'), ast_number(0)));
    ASSERT_TRUE(r && r->type == NODE_VARIABLE, "exact add: x+0 -> x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_ADD, ast_variable('x'), ast_number(-0.0f)));
    ASSERT_TRUE(r && r->type == NODE_VARIABLE, "exact add: x+(-0) -> x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_SUB, ast_variable('x'), ast_number(0)));
    ASSERT_TRUE(r && r->type == NODE_VARIABLE, "exact sub: x-0 -> x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_SUB, ast_number(0), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_UNOP && r->d.unop.op == UOP_NEG &&
                r->d.unop.operand->type == NODE_VARIABLE,
                "exact sub: 0-x -> -x");
    ast_free(r);
    r = ast_simplify(ast_binop(OP_SUB, ast_number(-0.0f), ast_variable('x')));
    ASSERT_TRUE(r && r->type == NODE_UNOP && r->d.unop.op == UOP_NEG,
                "exact sub: (-0)-x -> -x");
    ast_free(r);
    ASSERT_EQ_INT(mem_nodes_used(), 0, "exact add: no leaked nodes (zero)");
    mem_free_all();

    /* User-visible derivatives, evaluated where x is comparable to the
     * constant.  Each value on the left is what main used to get wrong. */
    v = tiny_deriv_at("ln(x+5e-11)", 5e-11f, &err);
    ASSERT_TRUE(err == CE_OK && fabsf(v - 1e10f) <= 1e4f,
                "exact add: ln(x+5e-11)' at 5e-11 = 1e10 (was 2e10)");
    v = tiny_deriv_at("ln(x+5e-11)", 0, &err);
    ASSERT_TRUE(err == CE_OK && fabsf(v - 2e10f) <= 1e4f,
                "exact add: ln(x+5e-11)' at 0 = 2e10 (was undefined)");
    v = tiny_deriv_at("1/(x+5e-11)", 5e-11f, &err);
    ASSERT_TRUE(err == CE_OK && fabsf(v + 1e20f) <= 1e14f,
                "exact add: (1/(x+5e-11))' at 5e-11 = -1e20 (was -4e20)");
    v = tiny_deriv_at("sqrt(x+1e-30)", 0, &err);
    ASSERT_TRUE(err == CE_OK && fabsf(v - 5e14f) <= 1e9f,
                "exact add: sqrt(x+1e-30)' at 0 = 5e14 (was undefined)");
    v = tiny_deriv_at("x^2+5e-11x", 0, &err);
    ASSERT_TRUE(err == CE_OK && v == 5e-11f,
                "exact add: (x^2+5e-11x)' at 0 = 5e-11 (was 0)");
    v = tiny_deriv_at("ln(x-5e-11)", 1e-10f, &err);
    ASSERT_TRUE(err == CE_OK && fabsf(v - 2e10f) <= 1e4f,
                "exact sub: ln(x-5e-11)' at 1e-10 = 2e10 (was 1e10)");
    ASSERT_EQ_INT(mem_nodes_used(), 0, "exact add: no leaked nodes (deriv)");
    mem_free_all();
}

static void test_simplify_depth_limit(void)
{
    ast_node_t *tree, *result;

    printf("=== Simplify Depth Limit ===\n");
    mem_free_all();

    /* Normal expression still simplifies correctly */
    {
        tree = parse_str("0+x");
        result = ast_simplify(tree);
        ASSERT_TRUE(result != NULL, "simplify 0+x not NULL");
        ASSERT_TRUE(result->type == NODE_VARIABLE, "0+x simplifies to x");
        ast_free(result);
    }
    mem_free_all();

    /* Another normal expression */
    {
        tree = parse_str("1*x+0");
        result = ast_simplify(tree);
        ASSERT_TRUE(result != NULL, "simplify 1*x+0 not NULL");
        ast_free(result);
    }
    mem_free_all();

    /* Deeply nested expression: ((((x+0)+0)+0)+0)... should not crash */
    {
        int i;
        ast_node_t *expr = ast_variable('x');
        for (i = 0; i < 100 && expr; i++) {
            expr = ast_binop(OP_ADD, expr, ast_number(0));
        }
        result = ast_simplify(expr);
        ASSERT_TRUE(result != NULL, "deep nesting 100 levels doesn't crash");
        ast_free(result);
    }
    mem_free_all();

    /* Deeply nested multiplication: should not stack overflow */
    {
        int i;
        ast_node_t *expr = ast_number(1);
        for (i = 0; i < 80 && expr; i++) {
            expr = ast_binop(OP_MUL, expr, ast_number(1));
        }
        result = ast_simplify(expr);
        ASSERT_TRUE(result != NULL, "deep mul nesting doesn't crash");
        ast_free(result);
    }
    mem_free_all();

    /* Nested function calls */
    {
        ast_node_t *expr = ast_variable('x');
        int i;
        for (i = 0; i < 60 && expr; i++) {
            expr = ast_func(FN_SIN, expr);
        }
        result = ast_simplify(expr);
        ASSERT_TRUE(result != NULL, "deep func nesting doesn't crash");
        ast_free(result);
    }
    mem_free_all();

    /* Verify basic simplification still works after depth test */
    {
        tree = parse_str("x^1");
        result = ast_simplify(tree);
        ASSERT_TRUE(result != NULL, "x^1 simplifies after depth tests");
        ASSERT_TRUE(result->type == NODE_VARIABLE, "x^1 -> x");
        ast_free(result);
    }
    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*         FINANCE AMORTIZATION TESTS (Session B Feb 16)         */
/* ═══════════════════════════════════════════════════════════ */

static void test_finance_amortization(void)
{
    eval_ctx_t ctx;
    ce_float_t args[5];
    ce_float_t result;

    printf("=== Finance Amortization ===\n");
    mem_free_all();

    /* ── eff(): nominal to effective ─────────────────────── */

    /* 12% nominal, monthly compounding → ~12.68% effective */
    {
        args[0] = 0.12f;  /* nominal rate */
        args[1] = 12.0f;  /* compounding periods */
        memset(&ctx, 0, sizeof(ctx));
        result = finance_eff(args, 2, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "eff(0.12,12) no error");
        ASSERT_EQ_FLOAT(result, 0.126825f, 0.001f, "eff(0.12,12) ~ 12.68%");
    }

    /* 8% nominal, quarterly → effective */
    {
        args[0] = 0.08f;
        args[1] = 4.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_eff(args, 2, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "eff(0.08,4) no error");
        ASSERT_EQ_FLOAT(result, 0.08243f, 0.001f, "eff(0.08,4) ~ 8.24%");
    }

    /* eff with 1 period: eff = nom */
    {
        args[0] = 0.10f;
        args[1] = 1.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_eff(args, 2, &ctx);
        ASSERT_EQ_FLOAT(result, 0.10f, 0.001f, "eff(0.10,1) = 0.10");
    }

    /* ── nom(): effective to nominal ─────────────────────── */

    /* nom from eff ~ 12.68% monthly → ~ 12% nominal */
    {
        args[0] = 0.126825f;
        args[1] = 12.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_nom(args, 2, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "nom(0.1268,12) no error");
        ASSERT_EQ_FLOAT(result, 0.12f, 0.001f, "nom(0.1268,12) ~ 12%");
    }

    /* ── nom/eff round-trip ──────────────────────────────── */
    {
        ce_float_t eff_val, nom_back;
        args[0] = 0.08f;
        args[1] = 12.0f;
        memset(&ctx, 0, sizeof(ctx));
        eff_val = finance_eff(args, 2, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "eff round-trip step1 ok");

        args[0] = eff_val;
        args[1] = 12.0f;
        memset(&ctx, 0, sizeof(ctx));
        nom_back = finance_nom(args, 2, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "nom round-trip step2 ok");
        ASSERT_EQ_FLOAT(nom_back, 0.08f, 0.001f, "nom(eff(0.08,12),12) ~ 0.08");
    }

    /* ── eff/nom error cases ─────────────────────────────── */
    {
        args[0] = 0.08f;
        args[1] = 0.0f;  /* invalid: 0 periods */
        memset(&ctx, 0, sizeof(ctx));
        finance_eff(args, 2, &ctx);
        ASSERT_TRUE(ctx.error != CE_OK, "eff(0.08,0) error");
    }
    {
        args[0] = 0.08f;
        args[1] = 2.5f;  /* invalid: non-integer */
        memset(&ctx, 0, sizeof(ctx));
        finance_eff(args, 2, &ctx);
        ASSERT_TRUE(ctx.error != CE_OK, "eff(0.08,2.5) error");
    }
    {
        memset(&ctx, 0, sizeof(ctx));
        finance_nom(args, 1, &ctx);  /* too few args */
        ASSERT_TRUE(ctx.error != CE_OK, "nom too few args error");
    }

    /* ── bal(): remaining balance ─────────────────────────── */
    /* $10000 loan, 0.5% monthly rate, $200/mo payment */
    /* bal(0) should equal PV */
    {
        args[0] = 0.0f;   /* npmt = 0 */
        args[1] = 0.005f;  /* rate */
        args[2] = -10000.0f; /* PV (negative = borrowed) */
        args[3] = 200.0f;  /* PMT (positive = paying) */
        memset(&ctx, 0, sizeof(ctx));
        result = finance_bal(args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "bal(0) no error");
        ASSERT_EQ_FLOAT(result, -10000.0f, 0.01f, "bal(0) = PV");
    }

    /* bal at midpoint: should be between PV and 0 */
    {
        args[0] = 30.0f;  /* npmt = 30 */
        args[1] = 0.005f;
        args[2] = -10000.0f;
        args[3] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_bal(args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "bal(30) no error");
        ASSERT_TRUE(result > -10000.0f && result < 0.0f, "bal(30) between PV and 0");
    }

    /* bal at final payment: should be approximately 0 */
    /* For $10000 at 0.5%/mo, $200/mo: nper ~ 56.08 months */
    /* After 56 payments, balance should be near zero */
    {
        /* First compute nper */
        ce_float_t nper_args[4] = {0.005f, -10000.0f, 200.0f, 0.0f};
        ce_float_t nper_val;
        memset(&ctx, 0, sizeof(ctx));
        nper_val = finance_nper(nper_args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "nper for bal test ok");

        /* Balance after floor(nper) payments should be small */
        args[0] = floorf(nper_val);
        args[1] = 0.005f;
        args[2] = -10000.0f;
        args[3] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_bal(args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "bal(nper) no error");
        ASSERT_TRUE(fabsf(result) < 250.0f, "bal(floor(nper)) near zero");
    }

    /* bal with zero rate */
    {
        args[0] = 5.0f;
        args[1] = 0.0f;
        args[2] = -1000.0f;
        args[3] = 100.0f;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_bal(args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "bal zero rate ok");
        ASSERT_EQ_FLOAT(result, -500.0f, 0.01f, "bal(5,0,-1000,100) = -500");
    }

    /* bal error: negative npmt */
    {
        args[0] = -1.0f;
        args[1] = 0.005f;
        args[2] = -10000.0f;
        args[3] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        finance_bal(args, 4, &ctx);
        ASSERT_TRUE(ctx.error != CE_OK, "bal(-1) error");
    }

    /* ── sumprn(): sum of principal ──────────────────────── */
    /* For full loan: sumprn(1, N, rate, pv, pmt) should equal -PV (the principal paid) */
    {
        /* $10000 loan, 0.5%/mo, 60 months, compute PMT first */
        ce_float_t pmt_args[4] = {60.0f, 0.005f, -10000.0f, 0.0f};
        ce_float_t pmt_val;
        memset(&ctx, 0, sizeof(ctx));
        pmt_val = finance_pmt(pmt_args, 4, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "pmt for sumprn test ok");

        args[0] = 1.0f;    /* pmt1 */
        args[1] = 60.0f;   /* pmt2 */
        args[2] = 0.005f;  /* rate */
        args[3] = -10000.0f; /* PV */
        args[4] = pmt_val;   /* PMT */
        memset(&ctx, 0, sizeof(ctx));
        result = finance_sum_prn(args, 5, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "sumprn full range no error");
        /* sumprn(1,60) = bal(60) - bal(0). bal(60)~0, bal(0)=PV=-10000 */
        /* So sumprn ~ 0 - (-10000) = 10000 */
        ASSERT_EQ_FLOAT(result, 10000.0f, 1.0f, "sumprn(1,60) ~ PV (full principal)");
    }

    /* sumprn for partial range */
    {
        ce_float_t pmt_args[4] = {60.0f, 0.005f, -10000.0f, 0.0f};
        ce_float_t pmt_val;
        memset(&ctx, 0, sizeof(ctx));
        pmt_val = finance_pmt(pmt_args, 4, &ctx);

        args[0] = 1.0f;    /* pmt1 */
        args[1] = 12.0f;   /* pmt2 (first year) */
        args[2] = 0.005f;
        args[3] = -10000.0f;
        args[4] = pmt_val;
        memset(&ctx, 0, sizeof(ctx));
        result = finance_sum_prn(args, 5, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "sumprn partial no error");
        ASSERT_TRUE(result > 0.0f, "sumprn(1,12) positive (principal paid)");
        ASSERT_TRUE(result < 10000.0f, "sumprn(1,12) < total principal");
    }

    /* ── sumint(): sum of interest ───────────────────────── */
    {
        ce_float_t pmt_args[4] = {60.0f, 0.005f, -10000.0f, 0.0f};
        ce_float_t pmt_val, sum_prn, sum_int, total_pmt;
        memset(&ctx, 0, sizeof(ctx));
        pmt_val = finance_pmt(pmt_args, 4, &ctx);

        args[0] = 1.0f;
        args[1] = 60.0f;
        args[2] = 0.005f;
        args[3] = -10000.0f;
        args[4] = pmt_val;

        memset(&ctx, 0, sizeof(ctx));
        sum_prn = finance_sum_prn(args, 5, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "sumprn for identity ok");

        memset(&ctx, 0, sizeof(ctx));
        sum_int = finance_sum_int(args, 5, &ctx);
        ASSERT_TRUE(ctx.error == CE_OK, "sumint for identity ok");

        /* Total interest = total payments - principal */
        total_pmt = pmt_val * 60.0f;
        ASSERT_EQ_FLOAT(sum_prn + sum_int, total_pmt, 1.0f,
                         "sumprn + sumint = total payments");

        /* Interest should be positive (borrower pays more than principal) */
        ASSERT_TRUE(sum_int > 0.0f, "total interest > 0");
    }

    /* ── sumprn/sumint error: invalid range ──────────────── */
    {
        args[0] = 5.0f;   /* pmt1 > pmt2 */
        args[1] = 3.0f;
        args[2] = 0.005f;
        args[3] = -10000.0f;
        args[4] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        finance_sum_prn(args, 5, &ctx);
        ASSERT_TRUE(ctx.error != CE_OK, "sumprn invalid range error");
    }
    {
        args[0] = 0.0f;   /* pmt1 < 1 */
        args[1] = 5.0f;
        args[2] = 0.005f;
        args[3] = -10000.0f;
        args[4] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        finance_sum_prn(args, 5, &ctx);
        ASSERT_TRUE(ctx.error != CE_OK, "sumprn pmt1=0 error");
    }
    {
        memset(&ctx, 0, sizeof(ctx));
        finance_sum_int(args, 3, &ctx);  /* too few args */
        ASSERT_TRUE(ctx.error != CE_OK, "sumint too few args");
    }

    /* ── BEGIN mode test ─────────────────────────────────── */
    {
        ce_float_t bal_end, bal_begin;
        g_settings.pmt_at_begin = false;
        args[0] = 12.0f;
        args[1] = 0.005f;
        args[2] = -10000.0f;
        args[3] = 200.0f;
        memset(&ctx, 0, sizeof(ctx));
        bal_end = finance_bal(args, 4, &ctx);

        g_settings.pmt_at_begin = true;
        memset(&ctx, 0, sizeof(ctx));
        bal_begin = finance_bal(args, 4, &ctx);

        /* BEGIN mode pays interest on one less period, so balance should differ */
        ASSERT_TRUE(fabsf(bal_end - bal_begin) > 0.01f,
                     "BEGIN vs END mode bal differs");
        g_settings.pmt_at_begin = false;
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*      COMPLEX RECIPROCAL FUNCS TESTS (Session B Feb 16)        */
/* ═══════════════════════════════════════════════════════════ */

static void test_complex_reciprocal_funcs(void)
{
    ce_complex_t z, r;

    printf("=== Complex Reciprocal Functions ===\n");
    mem_free_all();

    /* ── asec(z) = acos(1/z) ─────────────────────────────── */

    /* asec(1) = acos(1) = 0 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = casec_z(z);
        ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "asec(1) re = 0");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "asec(1) im = 0");
    }

    /* asec(2) = acos(0.5) = pi/3 */
    {
        z.re = 2.0f; z.im = 0.0f;
        r = casec_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI / 3.0f, 0.02f, "asec(2) ~ pi/3");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.02f, "asec(2) im ~ 0");
    }

    /* asec(-1) = acos(-1) = pi */
    {
        z.re = -1.0f; z.im = 0.0f;
        r = casec_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI, 0.02f, "asec(-1) ~ pi");
    }

    /* ── acsc(z) = asin(1/z) ─────────────────────────────── */

    /* acsc(1) = asin(1) = pi/2 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = cacsc_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI / 2.0f, 0.02f, "acsc(1) ~ pi/2");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.02f, "acsc(1) im ~ 0");
    }

    /* acsc(2) = asin(0.5) = pi/6 */
    {
        z.re = 2.0f; z.im = 0.0f;
        r = cacsc_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI / 6.0f, 0.02f, "acsc(2) ~ pi/6");
    }

    /* ── acot(z) = atan(1/z) ─────────────────────────────── */

    /* acot(1) = atan(1) = pi/4 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = cacot_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI / 4.0f, 0.02f, "acot(1) ~ pi/4");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.02f, "acot(1) im ~ 0");
    }

    /* acot(sqrt(3)) = atan(1/sqrt(3)) = pi/6 */
    {
        z.re = sqrtf(3.0f); z.im = 0.0f;
        r = cacot_z(z);
        ASSERT_EQ_FLOAT(r.re, CE_PI / 6.0f, 0.02f, "acot(sqrt3) ~ pi/6");
    }

    /* ── sech(z) = 1/cosh(z) ────────────────────────────── */

    /* sech(0) = 1/cosh(0) = 1 */
    {
        z.re = 0.0f; z.im = 0.0f;
        r = csech_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "sech(0) re = 1");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "sech(0) im = 0");
    }

    /* sech(1) = 1/cosh(1) ~ 0.6481 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = csech_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f / coshf(1.0f), 0.01f, "sech(1) ~ 1/cosh(1)");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "sech(1) im = 0");
    }

    /* ── csch(z) = 1/sinh(z) ────────────────────────────── */

    /* csch(1) = 1/sinh(1) ~ 0.8509 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = ccsch_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f / sinhf(1.0f), 0.01f, "csch(1) ~ 1/sinh(1)");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "csch(1) im = 0");
    }

    /* csch(2) */
    {
        z.re = 2.0f; z.im = 0.0f;
        r = ccsch_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f / sinhf(2.0f), 0.01f, "csch(2) ~ 1/sinh(2)");
    }

    /* ── coth(z) = cosh(z)/sinh(z) ──────────────────────── */

    /* coth(1) = cosh(1)/sinh(1) ~ 1.3130 */
    {
        z.re = 1.0f; z.im = 0.0f;
        r = ccoth_z(z);
        ASSERT_EQ_FLOAT(r.re, coshf(1.0f) / sinhf(1.0f), 0.01f,
                         "coth(1) ~ cosh(1)/sinh(1)");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "coth(1) im = 0");
    }

    /* coth(2) */
    {
        z.re = 2.0f; z.im = 0.0f;
        r = ccoth_z(z);
        ASSERT_EQ_FLOAT(r.re, coshf(2.0f) / sinhf(2.0f), 0.01f,
                         "coth(2) ~ cosh(2)/sinh(2)");
    }

    /* ── Pure imaginary inputs ───────────────────────────── */

    /* sech(i) = 1/cosh(i) = 1/cos(1) ~ 1.8508 */
    {
        z.re = 0.0f; z.im = 1.0f;
        r = csech_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f / cosf(1.0f), 0.05f, "sech(i) re ~ 1/cos(1)");
    }

    /* csch(i) = 1/sinh(i) = -i/sin(1) → re~0, im~-1/sin(1) */
    {
        z.re = 0.0f; z.im = 1.0f;
        r = ccsch_z(z);
        ASSERT_EQ_FLOAT(r.im, -1.0f / sinf(1.0f), 0.05f, "csch(i) im ~ -1/sin(1)");
    }

    /* ── Round-trip: sec(asec(z)) ≈ z ────────────────────── */
    {
        ce_complex_t z2, sec_val, asec_val;
        z2.re = 2.0f; z2.im = 0.5f;
        asec_val = casec_z(z2);
        /* sec = 1/cos */
        sec_val = cdiv((ce_complex_t){1, 0}, ccos_z(asec_val));
        ASSERT_EQ_FLOAT(sec_val.re, z2.re, 0.1f, "sec(asec(2+0.5i)) re ~ 2");
        ASSERT_EQ_FLOAT(sec_val.im, z2.im, 0.1f, "sec(asec(2+0.5i)) im ~ 0.5");
    }

    /* ── Round-trip: csc(acsc(z)) ≈ z ────────────────────── */
    {
        ce_complex_t z2, csc_val, acsc_val;
        z2.re = 2.0f; z2.im = 0.5f;
        acsc_val = cacsc_z(z2);
        /* csc = 1/sin */
        csc_val = cdiv((ce_complex_t){1, 0}, csin_z(acsc_val));
        ASSERT_EQ_FLOAT(csc_val.re, z2.re, 0.1f, "csc(acsc(2+0.5i)) re ~ 2");
        ASSERT_EQ_FLOAT(csc_val.im, z2.im, 0.1f, "csc(acsc(2+0.5i)) im ~ 0.5");
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*        MATRIX LU PRODUCT TESTS (Session B Feb 16)             */
/* ═══════════════════════════════════════════════════════════ */

static void test_matrix_lu_product(void)
{
    ce_matrix_t A, L, U, product, inv, identity;
    bool ok;
    int i, j;

    printf("=== Matrix LU Product & Inverse ===\n");
    mem_free_all();

    /* ── 2x2 LU decomposition: L*U = A ──────────────────── */
    {
        matrix_init(&A, 2, 2);
        MAT_AT(&A, 0, 0) = 4;  MAT_AT(&A, 0, 1) = 3;
        MAT_AT(&A, 1, 0) = 6;  MAT_AT(&A, 1, 1) = 3;

        ok = matrix_lu(&A, &L, &U);
        ASSERT_TRUE(ok, "2x2 LU decomposition succeeds");

        /* L should have unit diagonal */
        ASSERT_EQ_FLOAT(MAT_AT(&L, 0, 0), 1.0f, 1e-5f, "L[0,0] = 1 (unit diag)");
        ASSERT_EQ_FLOAT(MAT_AT(&L, 1, 1), 1.0f, 1e-5f, "L[1,1] = 1 (unit diag)");

        /* L should be lower triangular (L[0,1] = 0) */
        ASSERT_EQ_FLOAT(MAT_AT(&L, 0, 1), 0.0f, 1e-5f, "L[0,1] = 0 (lower tri)");

        /* U should be upper triangular (U[1,0] = 0) */
        ASSERT_EQ_FLOAT(MAT_AT(&U, 1, 0), 0.0f, 1e-5f, "U[1,0] = 0 (upper tri)");

        /* Verify L*U = A */
        ok = matrix_mul(&L, &U, &product);
        ASSERT_TRUE(ok, "L*U multiply ok");
        ASSERT_EQ_FLOAT(MAT_AT(&product, 0, 0), 4.0f, 1e-4f, "L*U[0,0] = A[0,0]");
        ASSERT_EQ_FLOAT(MAT_AT(&product, 0, 1), 3.0f, 1e-4f, "L*U[0,1] = A[0,1]");
        ASSERT_EQ_FLOAT(MAT_AT(&product, 1, 0), 6.0f, 1e-4f, "L*U[1,0] = A[1,0]");
        ASSERT_EQ_FLOAT(MAT_AT(&product, 1, 1), 3.0f, 1e-4f, "L*U[1,1] = A[1,1]");
    }

    /* ── 3x3 LU decomposition: L*U = A ──────────────────── */
    {
        matrix_init(&A, 3, 3);
        MAT_AT(&A, 0, 0) = 2;  MAT_AT(&A, 0, 1) = -1; MAT_AT(&A, 0, 2) = 0;
        MAT_AT(&A, 1, 0) = -1; MAT_AT(&A, 1, 1) = 2;  MAT_AT(&A, 1, 2) = -1;
        MAT_AT(&A, 2, 0) = 0;  MAT_AT(&A, 2, 1) = -1; MAT_AT(&A, 2, 2) = 2;

        ok = matrix_lu(&A, &L, &U);
        ASSERT_TRUE(ok, "3x3 LU decomposition succeeds");

        /* L unit diagonal check */
        for (i = 0; i < 3; i++) {
            ASSERT_EQ_FLOAT(MAT_AT(&L, i, i), 1.0f, 1e-5f, "L diag = 1");
        }

        /* L upper triangle should be 0 */
        ASSERT_EQ_FLOAT(MAT_AT(&L, 0, 1), 0.0f, 1e-5f, "L[0,1] = 0");
        ASSERT_EQ_FLOAT(MAT_AT(&L, 0, 2), 0.0f, 1e-5f, "L[0,2] = 0");
        ASSERT_EQ_FLOAT(MAT_AT(&L, 1, 2), 0.0f, 1e-5f, "L[1,2] = 0");

        /* Verify L*U = A */
        ok = matrix_mul(&L, &U, &product);
        ASSERT_TRUE(ok, "3x3 L*U multiply ok");
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                ASSERT_EQ_FLOAT(MAT_AT(&product, i, j), MAT_AT(&A, i, j),
                                1e-4f, "3x3 L*U = A element");
            }
        }
    }

    /* ── 2x2 A * A^-1 = I ───────────────────────────────── */
    {
        matrix_init(&A, 2, 2);
        MAT_AT(&A, 0, 0) = 4;  MAT_AT(&A, 0, 1) = 7;
        MAT_AT(&A, 1, 0) = 2;  MAT_AT(&A, 1, 1) = 6;

        ok = matrix_inverse(&A, &inv);
        ASSERT_TRUE(ok, "2x2 inverse succeeds");

        ok = matrix_mul(&A, &inv, &identity);
        ASSERT_TRUE(ok, "A * A^-1 multiply ok");

        /* Check identity matrix */
        ASSERT_EQ_FLOAT(MAT_AT(&identity, 0, 0), 1.0f, 1e-4f, "I[0,0] = 1");
        ASSERT_EQ_FLOAT(MAT_AT(&identity, 0, 1), 0.0f, 1e-4f, "I[0,1] = 0");
        ASSERT_EQ_FLOAT(MAT_AT(&identity, 1, 0), 0.0f, 1e-4f, "I[1,0] = 0");
        ASSERT_EQ_FLOAT(MAT_AT(&identity, 1, 1), 1.0f, 1e-4f, "I[1,1] = 1");
    }

    /* ── 3x3 A * A^-1 = I ───────────────────────────────── */
    {
        matrix_init(&A, 3, 3);
        MAT_AT(&A, 0, 0) = 1;  MAT_AT(&A, 0, 1) = 2; MAT_AT(&A, 0, 2) = 3;
        MAT_AT(&A, 1, 0) = 0;  MAT_AT(&A, 1, 1) = 1; MAT_AT(&A, 1, 2) = 4;
        MAT_AT(&A, 2, 0) = 5;  MAT_AT(&A, 2, 1) = 6; MAT_AT(&A, 2, 2) = 0;

        ok = matrix_inverse(&A, &inv);
        ASSERT_TRUE(ok, "3x3 inverse succeeds");

        ok = matrix_mul(&A, &inv, &identity);
        ASSERT_TRUE(ok, "3x3 A * A^-1 multiply ok");

        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                ce_float_t expected = (i == j) ? 1.0f : 0.0f;
                ASSERT_EQ_FLOAT(MAT_AT(&identity, i, j), expected, 1e-3f,
                                "3x3 A*A^-1 = I element");
            }
        }
    }

    /* ── Rank verification ───────────────────────────────── */
    {
        /* Full rank 3x3 */
        matrix_init(&A, 3, 3);
        MAT_AT(&A, 0, 0) = 1; MAT_AT(&A, 0, 1) = 0; MAT_AT(&A, 0, 2) = 0;
        MAT_AT(&A, 1, 0) = 0; MAT_AT(&A, 1, 1) = 1; MAT_AT(&A, 1, 2) = 0;
        MAT_AT(&A, 2, 0) = 0; MAT_AT(&A, 2, 1) = 0; MAT_AT(&A, 2, 2) = 1;
        ASSERT_EQ_INT(matrix_rank(&A), 3, "identity rank = 3");
    }
    {
        /* Rank-deficient: row 3 = row 1 + row 2 */
        matrix_init(&A, 3, 3);
        MAT_AT(&A, 0, 0) = 1; MAT_AT(&A, 0, 1) = 2; MAT_AT(&A, 0, 2) = 3;
        MAT_AT(&A, 1, 0) = 4; MAT_AT(&A, 1, 1) = 5; MAT_AT(&A, 1, 2) = 6;
        MAT_AT(&A, 2, 0) = 5; MAT_AT(&A, 2, 1) = 7; MAT_AT(&A, 2, 2) = 9;
        ASSERT_EQ_INT(matrix_rank(&A), 2, "rank-deficient 3x3 rank = 2");
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*  PERFORMANCE BENCHMARKS                                      */
/*  Timed benchmarks for key operations — useful for tracking   */
/*  regressions and estimating eZ80 performance.                */
/* ═══════════════════════════════════════════════════════════ */

static void test_performance(void)
{
    printf("  [PERF] Performance benchmarks (1000 iterations each):\n");

    clock_t start, end;
    double elapsed;
    int iters = 1000;
    int k;

    /* 1. Tokenize + parse a complex expression */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *r = parse_str("3*x^2 + sin(x)*cos(x) - ln(x+1)/sqrt(x)");
        if (r) ast_free(r);
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    1. Parse complex expr:        %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "parse benchmark completes in <30s");

    /* 2. Evaluate a numerical expression */
    start = clock();
    for (k = 0; k < iters; k++) {
        ce_error_t err;
        (void)eval_str("3*2.5^2 + sin(1.0)*cos(1.0) - ln(2.0)/sqrt(3.0)", &err);
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    2. Eval numeric expr:         %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "eval benchmark completes in <30s");

    /* 3. Symbolic differentiation */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *expr = parse_str("x^3*sin(x^2) + ln(x)*cos(x)");
        if (expr) {
            ast_node_t *d = deriv_diff(expr, 'x');
            if (d) ast_free(d);
            ast_free(expr);
        }
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    3. Differentiate (chain+prod): %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "deriv benchmark completes in <30s");

    /* 4. Symbolic integration (power rule + trig) */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *expr = parse_str("3*x^2 + 2*x + sin(x)");
        if (expr) {
            ast_node_t *integ = integrate(expr, 'x');
            if (integ) ast_free(integ);
            ast_free(expr);
        }
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    4. Integrate (poly+trig):     %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "integrate benchmark completes in <30s");

    /* 5. Simplification */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *expr = parse_str("(x+1)*(x-1) + x^2 - 2*x + 1");
        if (expr) {
            ast_node_t *s = ast_simplify(expr);
            if (s && s != expr) ast_free(s);
            ast_free(expr);
        }
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    5. Simplify expression:       %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "simplify benchmark completes in <30s");

    /* 6. Limit evaluation (L'Hopital) */
    start = clock();
    for (k = 0; k < iters; k++) {
        ce_error_t err;
        (void)eval_str("lim(sin(x)/x,x,0)", &err);
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    6. Limit (sin(x)/x, x->0):   %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "limit benchmark completes in <30s");

    /* 7. Taylor series (degree 8) */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *expr = parse_str("sin(x)");
        if (expr) {
            ast_node_t *t = taylor_series(expr, 'x', 0.0f, 8);
            if (t) ast_free(t);
            ast_free(expr);
        }
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    7. Taylor (sin, deg 8):       %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "taylor benchmark completes in <30s");

    /* 8. Algebra — solve quadratic */
    start = clock();
    for (k = 0; k < iters; k++) {
        ast_node_t *expr = parse_str("x^2 - 5*x + 6");
        if (expr) {
            char result[256];
            algebra_solve(expr, 'x', result, sizeof(result));
            ast_free(expr);
        }
        mem_free_all();
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    8. Solve quadratic:           %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "solve benchmark completes in <30s");

    /* 9. Matrix determinant (4x4) */
    start = clock();
    for (k = 0; k < iters; k++) {
        ce_matrix_t M;
        matrix_init(&M, 4, 4);
        MAT_AT(&M, 0, 0) = 1; MAT_AT(&M, 0, 1) = 2; MAT_AT(&M, 0, 2) = 3; MAT_AT(&M, 0, 3) = 4;
        MAT_AT(&M, 1, 0) = 5; MAT_AT(&M, 1, 1) = 6; MAT_AT(&M, 1, 2) = 7; MAT_AT(&M, 1, 3) = 8;
        MAT_AT(&M, 2, 0) = 2; MAT_AT(&M, 2, 1) = 6; MAT_AT(&M, 2, 2) = 1; MAT_AT(&M, 2, 3) = 3;
        MAT_AT(&M, 3, 0) = 7; MAT_AT(&M, 3, 1) = 4; MAT_AT(&M, 3, 2) = 9; MAT_AT(&M, 3, 3) = 2;
        (void)matrix_det(&M);
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("    9. Matrix det (4x4):          %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "matrix det benchmark completes in <30s");

    /* 10. Statistics — linear regression (10 points) */
    start = clock();
    for (k = 0; k < iters; k++) {
        ce_float_t data[] = {1,2, 2,4, 3,5, 4,4, 5,5, 6,7, 7,8, 8,9, 9,11, 10,12};
        ce_float_t m, b, r;
        stat_linreg(data, 20, &m, &b, &r);
    }
    end = clock();
    elapsed = (double)(end - start) / CLOCKS_PER_SEC * 1000.0;
    printf("   10. LinReg (10 points):        %7.2f ms total (%5.3f ms/iter)\n", elapsed, elapsed / iters);
    ASSERT_TRUE(elapsed < 30000, "linreg benchmark completes in <30s");

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*           GRAPHING ENGINE                                    */
/* ═══════════════════════════════════════════════════════════ */

static void test_graph_engine(void)
{
    printf("  [GRAPH] Graphing engine tests...\n");
    graph_viewport_t vp;

    /* ── Default viewport ───────────────────────────────── */
    graph_default_viewport(&vp);
    ASSERT_EQ_FLOAT(vp.x_min, -10.0f, 0.001f, "default x_min = -10");
    ASSERT_EQ_FLOAT(vp.x_max,  10.0f, 0.001f, "default x_max = 10");
    ASSERT_EQ_FLOAT(vp.y_min,  -6.5f, 0.001f, "default y_min = -6.5");
    ASSERT_EQ_FLOAT(vp.y_max,   6.5f, 0.001f, "default y_max = 6.5");

    /* ── World-to-screen coordinate mapping ─────────────── */
    /* Center of viewport should map to center of graph region */
    {
        int cx = graph_world_to_sx(&vp, 0.0f);
        int cy = graph_world_to_sy(&vp, 0.0f);
        /* Center x: GRAPH_X0 + GRAPH_W/2 = 0 + 160 = 160 */
        ASSERT_TRUE(abs(cx - (GRAPH_X0 + GRAPH_W / 2)) <= 1,
                    "world (0,0) maps to screen center x");
        /* Center y: graph midpoint */
        int expected_cy = GRAPH_Y0 + GRAPH_AREA_H / 2;
        ASSERT_TRUE(abs(cy - expected_cy) <= 1,
                    "world (0,0) maps to screen center y");
    }

    /* Left edge */
    {
        int sx = graph_world_to_sx(&vp, -10.0f);
        ASSERT_EQ_INT(sx, GRAPH_X0, "x_min maps to left edge");
    }

    /* Right edge */
    {
        int sx = graph_world_to_sx(&vp, 10.0f);
        ASSERT_EQ_INT(sx, GRAPH_X0 + GRAPH_W - 1, "x_max maps to right edge");
    }

    /* Top edge (y_max maps to top of screen = GRAPH_Y0) */
    {
        int sy = graph_world_to_sy(&vp, 6.5f);
        ASSERT_EQ_INT(sy, GRAPH_Y0, "y_max maps to top edge");
    }

    /* Bottom edge (y_min maps to bottom of screen) */
    {
        int sy = graph_world_to_sy(&vp, -6.5f);
        ASSERT_EQ_INT(sy, GRAPH_Y0 + GRAPH_AREA_H - 1, "y_min maps to bottom edge");
    }

    /* ── Screen-to-world inverse ────────────────────────── */
    {
        ce_float_t wx = graph_sx_to_world(&vp, GRAPH_X0);
        ASSERT_EQ_FLOAT(wx, -10.0f, 0.01f, "left pixel maps to x_min");
        wx = graph_sx_to_world(&vp, GRAPH_X0 + GRAPH_W - 1);
        ASSERT_EQ_FLOAT(wx, 10.0f, 0.01f, "right pixel maps to x_max");
    }
    {
        ce_float_t wy = graph_sy_to_world(&vp, GRAPH_Y0);
        ASSERT_EQ_FLOAT(wy, 6.5f, 0.01f, "top pixel maps to y_max");
        wy = graph_sy_to_world(&vp, GRAPH_Y0 + GRAPH_AREA_H - 1);
        ASSERT_EQ_FLOAT(wy, -6.5f, 0.01f, "bottom pixel maps to y_min");
    }

    /* ── Round-trip consistency ──────────────────────────── */
    {
        ce_float_t test_vals[] = {-8.0f, -3.5f, 0.0f, 2.7f, 9.0f};
        int i;
        for (i = 0; i < 5; i++) {
            int sx = graph_world_to_sx(&vp, test_vals[i]);
            ce_float_t back = graph_sx_to_world(&vp, sx);
            ASSERT_EQ_FLOAT(back, test_vals[i], 0.15f,
                            "x round-trip consistent");
        }
    }
    {
        ce_float_t test_vals[] = {-5.0f, -2.0f, 0.0f, 3.0f, 6.0f};
        int i;
        for (i = 0; i < 5; i++) {
            int sy = graph_world_to_sy(&vp, test_vals[i]);
            ce_float_t back = graph_sy_to_world(&vp, sy);
            ASSERT_EQ_FLOAT(back, test_vals[i], 0.15f,
                            "y round-trip consistent");
        }
    }

    /* ── Clamping: out-of-range values clamp to edges ───── */
    {
        int sx = graph_world_to_sx(&vp, -100.0f);
        ASSERT_EQ_INT(sx, GRAPH_X0, "far-left clamps to GRAPH_X0");
        sx = graph_world_to_sx(&vp, 100.0f);
        ASSERT_EQ_INT(sx, GRAPH_X0 + GRAPH_W - 1, "far-right clamps");
        int sy = graph_world_to_sy(&vp, 100.0f);
        ASSERT_EQ_INT(sy, GRAPH_Y0, "far-up clamps to GRAPH_Y0");
        sy = graph_world_to_sy(&vp, -100.0f);
        ASSERT_EQ_INT(sy, GRAPH_Y0 + GRAPH_AREA_H - 1, "far-down clamps");
    }

    /* ── Zoom ───────────────────────────────────────────── */
    graph_default_viewport(&vp);
    graph_zoom(&vp, 0.5f);  /* zoom in by 2x */
    ASSERT_EQ_FLOAT(vp.x_min, -5.0f, 0.01f, "zoom in halves x range");
    ASSERT_EQ_FLOAT(vp.x_max,  5.0f, 0.01f, "zoom in halves x range");
    ASSERT_EQ_FLOAT(vp.y_min, -3.25f, 0.01f, "zoom in halves y range");
    ASSERT_EQ_FLOAT(vp.y_max,  3.25f, 0.01f, "zoom in halves y range");

    graph_default_viewport(&vp);
    graph_zoom(&vp, 2.0f);  /* zoom out by 2x */
    ASSERT_EQ_FLOAT(vp.x_min, -20.0f, 0.01f, "zoom out doubles x range");
    ASSERT_EQ_FLOAT(vp.x_max,  20.0f, 0.01f, "zoom out doubles x range");

    /* ── Pan ────────────────────────────────────────────── */
    graph_default_viewport(&vp);
    graph_pan(&vp, 5.0f, 3.0f);
    ASSERT_EQ_FLOAT(vp.x_min, -5.0f, 0.01f, "pan shifts x_min");
    ASSERT_EQ_FLOAT(vp.x_max, 15.0f, 0.01f, "pan shifts x_max");
    ASSERT_EQ_FLOAT(vp.y_min, -3.5f, 0.01f, "pan shifts y_min");
    ASSERT_EQ_FLOAT(vp.y_max,  9.5f, 0.01f, "pan shifts y_max");

    /* ── Auto-range with f(x) = x^2 ────────────────────── */
    {
        ast_node_t *expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "parse x^2 for graph");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            /* x^2 on [-10,10] ranges from 0 to 100 */
            ASSERT_TRUE(vp.y_min < 0.5f, "auto-range y_min includes 0");
            ASSERT_TRUE(vp.y_max > 50.0f, "auto-range y_max includes high values");
            ast_free(expr);
        }
    }

    /* ── Auto-range with f(x) = sin(x) ─────────────────── */
    {
        ast_node_t *expr = parse_str("sin(x)");
        ASSERT_TRUE(expr != NULL, "parse sin(x) for graph");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            /* sin(x) ranges from -1 to 1 */
            ASSERT_TRUE(vp.y_min < -0.5f, "sin auto-range covers -1");
            ASSERT_TRUE(vp.y_max > 0.5f, "sin auto-range covers 1");
            ASSERT_TRUE(vp.y_min > -3.0f, "sin auto-range not too wide");
            ASSERT_TRUE(vp.y_max < 3.0f, "sin auto-range not too wide");
            ast_free(expr);
        }
    }

    /* ── Auto-range with constant function ──────────────── */
    {
        ast_node_t *expr = parse_str("5");
        ASSERT_TRUE(expr != NULL, "parse constant 5 for graph");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            /* Constant: all y=5, so range should be centered around 5 */
            ASSERT_TRUE(vp.y_min < 5.0f, "const auto-range y_min < 5");
            ASSERT_TRUE(vp.y_max > 5.0f, "const auto-range y_max > 5");
            ast_free(expr);
        }
    }

    /* ── Trace evaluation ───────────────────────────────── */
    {
        ast_node_t *expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "parse x^2 for trace");
        if (expr) {
            graph_default_viewport(&vp);
            ce_error_t err = CE_OK;
            /* Trace at center pixel should give f(0) = 0 */
            ce_float_t y = graph_trace_eval(&vp, expr, 'x',
                                            GRAPH_X0 + GRAPH_W / 2, &err);
            ASSERT_TRUE(err == CE_OK, "trace eval no error");
            ASSERT_EQ_FLOAT(y, 0.0f, 0.1f, "trace at x=0 gives y=0");

            /* Trace at right edge: f(10) = 100 */
            y = graph_trace_eval(&vp, expr, 'x',
                                 GRAPH_X0 + GRAPH_W - 1, &err);
            ASSERT_TRUE(err == CE_OK, "trace eval right edge no error");
            ASSERT_EQ_FLOAT(y, 100.0f, 1.0f, "trace at x=10 gives y=100");
            ast_free(expr);
        }
    }

    /* ── Drawing functions run without crash ─────────────── */
    {
        ast_node_t *expr = parse_str("sin(x)");
        ASSERT_TRUE(expr != NULL, "parse sin(x) for draw test");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            /* These should not crash even with mock graphics */
            graph_draw_axes(&vp);
            graph_draw_function(&vp, expr, 'x', 0x10);
            graph_draw_shade(&vp, expr, 'x', 0.0f, 3.14f, 0xB5);
            {
                char lbuf[48];
                graph_draw_trace(&vp, expr, 'x', GRAPH_X0 + 100,
                                 lbuf, sizeof(lbuf));
                ASSERT_TRUE(strlen(lbuf) > 0, "trace label not empty");
                ASSERT_STR_CONTAINS(lbuf, "x=", "trace label has x=");
                ASSERT_STR_CONTAINS(lbuf, "y=", "trace label has y=");
            }
            ast_free(expr);
        }
    }

    /* ── Draw with discontinuous function (1/x) ─────────── */
    {
        ast_node_t *expr = parse_str("1/x");
        ASSERT_TRUE(expr != NULL, "parse 1/x for draw test");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            /* Should not crash — handles division by zero gracefully */
            graph_draw_function(&vp, expr, 'x', 0x10);
            ast_free(expr);
        }
    }

    /* ── Draw with undefined regions (sqrt(x)) ──────────── */
    {
        ast_node_t *expr = parse_str("sqrt(x)");
        ASSERT_TRUE(expr != NULL, "parse sqrt(x) for draw test");
        if (expr) {
            graph_default_viewport(&vp);
            graph_auto_range(&vp, expr, 'x');
            graph_draw_function(&vp, expr, 'x', 0x10);
            ast_free(expr);
        }
    }

    /* ── Parser integration: graph(x^2, x) ──────────────── */
    {
        ast_node_t *node = parse_str("graph(x^2,x)");
        ASSERT_TRUE(node != NULL, "parse graph(x^2,x)");
        if (node) {
            ASSERT_EQ_INT(node->type, NODE_POLAR, "graph node is NODE_POLAR");
            ASSERT_EQ_INT(node->d.polar.op, POLOP_GRAPH, "graph op is POLOP_GRAPH");
            ASSERT_EQ_INT(node->d.polar.var, 'x', "graph var is x");
            ASSERT_TRUE(node->d.polar.expr1 != NULL, "graph has expression");
            ASSERT_TRUE(node->d.polar.lo == NULL, "graph no xmin");
            ASSERT_TRUE(node->d.polar.hi == NULL, "graph no xmax");
            ast_free(node);
        }
    }

    /* ── Parser: graph(sin(t), t, 0, 6.28) with custom range ── */
    {
        ast_node_t *node = parse_str("graph(sin(t),t,0,6.28)");
        ASSERT_TRUE(node != NULL, "parse graph with custom range");
        if (node) {
            ASSERT_EQ_INT(node->d.polar.op, POLOP_GRAPH, "graph op");
            ASSERT_EQ_INT(node->d.polar.var, 't', "graph var is t");
            ASSERT_TRUE(node->d.polar.lo != NULL, "graph has xmin");
            ASSERT_TRUE(node->d.polar.hi != NULL, "graph has xmax");
            ast_free(node);
        }
    }

    /* ── Parser: graph(x^3) — single arg, default var ──── */
    {
        ast_node_t *node = parse_str("graph(x^3)");
        ASSERT_TRUE(node != NULL, "parse graph(x^3) single arg");
        if (node) {
            ASSERT_EQ_INT(node->d.polar.op, POLOP_GRAPH, "graph op");
            ASSERT_EQ_INT(node->d.polar.var, 'x', "graph default var x");
            ast_free(node);
        }
    }

    /* ── ast_to_str for graph node ──────────────────────── */
    {
        ast_node_t *node = parse_str("graph(x^2,x)");
        ASSERT_TRUE(node != NULL, "parse graph for to_str");
        if (node) {
            char buf[80];
            ast_to_str(node, buf, sizeof(buf));
            ASSERT_STR_CONTAINS(buf, "graph", "to_str contains graph");
            ASSERT_STR_CONTAINS(buf, "x", "to_str contains x");
            ast_free(node);
        }
    }

    /* ── Viewport with custom x range ───────────────────── */
    {
        vp.x_min = 0; vp.x_max = 2 * CE_PI;
        vp.y_min = -1.5f; vp.y_max = 1.5f;
        int sx0 = graph_world_to_sx(&vp, 0.0f);
        int sx_pi = graph_world_to_sx(&vp, CE_PI);
        int sx_2pi = graph_world_to_sx(&vp, 2 * CE_PI);
        ASSERT_EQ_INT(sx0, GRAPH_X0, "custom range: 0 at left");
        ASSERT_EQ_INT(sx_2pi, GRAPH_X0 + GRAPH_W - 1, "custom range: 2pi at right");
        ASSERT_TRUE(sx_pi > sx0 && sx_pi < sx_2pi, "pi in middle");
    }

    /* ── Zoom preserves center ──────────────────────────── */
    {
        graph_default_viewport(&vp);
        graph_pan(&vp, 3.0f, 2.0f);  /* center at (3, 2) */
        ce_float_t cx_before = (vp.x_min + vp.x_max) / 2;
        ce_float_t cy_before = (vp.y_min + vp.y_max) / 2;
        graph_zoom(&vp, 0.5f);
        ce_float_t cx_after = (vp.x_min + vp.x_max) / 2;
        ce_float_t cy_after = (vp.y_min + vp.y_max) / 2;
        ASSERT_EQ_FLOAT(cx_before, cx_after, 0.001f, "zoom preserves center x");
        ASSERT_EQ_FLOAT(cy_before, cy_after, 0.001f, "zoom preserves center y");
    }

    /* ── Multiple zooms compose correctly ───────────────── */
    {
        graph_default_viewport(&vp);
        graph_zoom(&vp, 0.5f);
        graph_zoom(&vp, 0.5f);
        /* Two half-zooms: range should be 1/4 of original */
        ce_float_t xrange = vp.x_max - vp.x_min;
        ASSERT_EQ_FLOAT(xrange, 5.0f, 0.01f, "double zoom gives 1/4 range");
    }

    /* ── Trace eval with different variable ──────────────── */
    {
        ast_node_t *expr = parse_str("t^3");
        ASSERT_TRUE(expr != NULL, "parse t^3 for trace");
        if (expr) {
            vp.x_min = -5; vp.x_max = 5;
            vp.y_min = -125; vp.y_max = 125;
            ce_error_t err = CE_OK;
            ce_float_t y = graph_trace_eval(&vp, expr, 't',
                                            GRAPH_X0 + GRAPH_W / 2, &err);
            ASSERT_TRUE(err == CE_OK, "trace t^3 no error");
            ASSERT_EQ_FLOAT(y, 0.0f, 0.1f, "trace t^3 at center = 0");
            ast_free(expr);
        }
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*           EQUATION GRAPHING                                   */
/* ═══════════════════════════════════════════════════════════ */

static void test_equation_graphing(void)
{
    printf("  [GRAPHEQ] Equation graphing tests...\n");
    graph_viewport_t vp;
    graph_intersection_t pts[GRAPH_MAX_INTERSECTIONS];
    int count;

    /* ── Tokenizer: grapheq token recognized ──────────── */
    {
        tokenizer_t t;
        tok_init(&t, "grapheq(x^2,2x+1,x)");
        ASSERT_EQ_INT(tok_tokenize(&t), CE_OK, "grapheq tokenizes");
        ASSERT_TRUE(t.count > 0, "grapheq has tokens");
        ASSERT_TRUE(t.tokens[0].type == TOK_GRAPHEQ,
                    "grapheq token type");
    }

    /* ── Parser: grapheq parses to NODE_POLAR ──────────── */
    {
        ast_node_t *root = parse_str("grapheq(x^2,2x+1,x)");
        ASSERT_TRUE(root != NULL, "grapheq parses");
        if (root) {
            ASSERT_TRUE(root->type == NODE_POLAR,
                        "grapheq -> NODE_POLAR");
            ASSERT_TRUE(root->d.polar.op == POLOP_GRAPHEQ,
                        "grapheq -> POLOP_GRAPHEQ");
            ASSERT_TRUE(root->d.polar.var == 'x',
                        "grapheq var = x");
            ASSERT_TRUE(root->d.polar.expr1 != NULL,
                        "grapheq has expr1 (LHS)");
            ASSERT_TRUE(root->d.polar.expr2 != NULL,
                        "grapheq has expr2 (RHS)");
            ASSERT_TRUE(root->d.polar.lo == NULL,
                        "grapheq default: no xmin");
            ASSERT_TRUE(root->d.polar.hi == NULL,
                        "grapheq default: no xmax");
            ast_free(root);
        }
    }

    /* ── Parser: grapheq with custom range ─────────────── */
    {
        ast_node_t *root = parse_str("grapheq(x^2,x+2,x,-5,5)");
        ASSERT_TRUE(root != NULL, "grapheq with range parses");
        if (root) {
            ASSERT_TRUE(root->d.polar.op == POLOP_GRAPHEQ,
                        "grapheq range -> POLOP_GRAPHEQ");
            ASSERT_TRUE(root->d.polar.lo != NULL,
                        "grapheq range has xmin");
            ASSERT_TRUE(root->d.polar.hi != NULL,
                        "grapheq range has xmax");
            ast_free(root);
        }
    }

    /* ── Parser: grapheq default var ───────────────────── */
    {
        ast_node_t *root = parse_str("grapheq(x^2,2x)");
        ASSERT_TRUE(root != NULL, "grapheq no-var parses");
        if (root) {
            ASSERT_TRUE(root->d.polar.op == POLOP_GRAPHEQ,
                        "grapheq no-var op");
            ASSERT_TRUE(root->d.polar.var == 'x',
                        "grapheq default var = x");
            ast_free(root);
        }
    }

    /* ── Parser: grapheq with t variable ───────────────── */
    {
        ast_node_t *root = parse_str("grapheq(t^2,2t,t)");
        ASSERT_TRUE(root != NULL, "grapheq t-var parses");
        if (root) {
            ASSERT_TRUE(root->d.polar.var == 't',
                        "grapheq var = t");
            ast_free(root);
        }
    }

    /* ── ast_to_str for grapheq ────────────────────────── */
    {
        ast_node_t *root = parse_str("grapheq(x^2,2x,x)");
        ASSERT_TRUE(root != NULL, "grapheq for ast_to_str");
        if (root) {
            char buf[120];
            ast_to_str(root, buf, sizeof(buf));
            ASSERT_STR_CONTAINS(buf, "grapheq",
                                "ast_to_str contains grapheq");
            ast_free(root);
        }
    }

    /* ── Auto-range for two functions ──────────────────── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("x+2");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for auto-range");
        ASSERT_TRUE(e2 != NULL, "parse x+2 for auto-range");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            graph_auto_range_two(&vp, e1, e2, 'x');
            /* x^2 at x=10 = 100, x+2 at x=10 = 12 */
            ASSERT_TRUE(vp.y_max > 90.0f,
                        "auto-range two: y_max covers x^2");
            ASSERT_TRUE(vp.y_min < -9.0f,
                        "auto-range two: y_min covers x+2 at x=-10");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: x^2 = x+2 (two crossings) ──────── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("x+2");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for isect");
        ASSERT_TRUE(e2 != NULL, "parse x+2 for isect");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            ASSERT_TRUE(count == 2,
                        "x^2 = x+2 has 2 intersections");
            /* x^2 = x+2 -> x^2-x-2=0 -> (x-2)(x+1)=0 -> x=-1,2 */
            if (count >= 2) {
                ce_float_t x0 = pts[0].x < pts[1].x ? pts[0].x : pts[1].x;
                ce_float_t x1 = pts[0].x < pts[1].x ? pts[1].x : pts[0].x;
                ASSERT_EQ_FLOAT(x0, -1.0f, 0.05f,
                                "isect x0 = -1");
                ASSERT_EQ_FLOAT(x1,  2.0f, 0.05f,
                                "isect x1 = 2");
                /* y values: at x=-1: y=1, at x=2: y=4 */
                ce_float_t y0 = pts[0].x < pts[1].x ? pts[0].y : pts[1].y;
                ce_float_t y1 = pts[0].x < pts[1].x ? pts[1].y : pts[0].y;
                ASSERT_EQ_FLOAT(y0, 1.0f, 0.1f,
                                "isect y0 = 1");
                ASSERT_EQ_FLOAT(y1, 4.0f, 0.1f,
                                "isect y1 = 4");
            }
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: sin(x) = cos(x) (many crossings) ── */
    {
        ast_node_t *e1 = parse_str("sin(x)");
        ast_node_t *e2 = parse_str("cos(x)");
        ASSERT_TRUE(e1 != NULL, "parse sin for isect");
        ASSERT_TRUE(e2 != NULL, "parse cos for isect");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* sin(x)=cos(x) at x=pi/4+n*pi, within [-10,10] */
            ASSERT_TRUE(count >= 5,
                        "sin(x)=cos(x) has >=5 intersections in [-10,10]");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: x = x (identical, near-zero diff) ── */
    {
        ast_node_t *e1 = parse_str("x");
        ast_node_t *e2 = parse_str("x");
        ASSERT_TRUE(e1 != NULL, "parse x for identical");
        ASSERT_TRUE(e2 != NULL, "parse x for identical");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* Identical functions: every sample point is an intersection
               (capped at max) */
            ASSERT_TRUE(count == GRAPH_MAX_INTERSECTIONS,
                        "identical funcs: max intersections");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: x^2 = -1 (no real crossings) ────── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("0-1");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for no-cross");
        ASSERT_TRUE(e2 != NULL, "parse -1 for no-cross");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            ASSERT_TRUE(count == 0,
                        "x^2 = -1 has 0 intersections");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: tangent case x^2 = 0 (single) ──── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("0");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for tangent");
        ASSERT_TRUE(e2 != NULL, "parse 0 for tangent");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* x^2=0 touches at x=0 (may be detected as exact crossing) */
            ASSERT_TRUE(count >= 1,
                        "x^2 = 0 has at least 1 intersection");
            if (count >= 1) {
                ASSERT_EQ_FLOAT(pts[0].x, 0.0f, 0.1f,
                                "tangent at x=0");
            }
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection with 1/x (asymptote handling) ────── */
    {
        ast_node_t *e1 = parse_str("1/x");
        ast_node_t *e2 = parse_str("x");
        ASSERT_TRUE(e1 != NULL, "parse 1/x for asym");
        ASSERT_TRUE(e2 != NULL, "parse x for asym");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* 1/x = x -> x^2 = 1 -> x = +/- 1 */
            ASSERT_TRUE(count == 2,
                        "1/x = x has 2 intersections");
            if (count >= 2) {
                ce_float_t x0 = pts[0].x < pts[1].x ? pts[0].x : pts[1].x;
                ce_float_t x1 = pts[0].x < pts[1].x ? pts[1].x : pts[0].x;
                ASSERT_EQ_FLOAT(x0, -1.0f, 0.1f,
                                "1/x=x isect at x=-1");
                ASSERT_EQ_FLOAT(x1,  1.0f, 0.1f,
                                "1/x=x isect at x=1");
            }
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: linear crossing ─────────────────── */
    {
        ast_node_t *e1 = parse_str("2x+1");
        ast_node_t *e2 = parse_str("0-x+4");
        ASSERT_TRUE(e1 != NULL, "parse 2x+1");
        ASSERT_TRUE(e2 != NULL, "parse -x+4");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* 2x+1 = -x+4 -> 3x = 3 -> x = 1, y = 3 */
            ASSERT_TRUE(count == 1,
                        "linear crossing: 1 intersection");
            if (count >= 1) {
                ASSERT_EQ_FLOAT(pts[0].x, 1.0f, 0.05f,
                                "linear crossing at x=1");
                ASSERT_EQ_FLOAT(pts[0].y, 3.0f, 0.1f,
                                "linear crossing at y=3");
            }
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection: exp(x) = x^3 ───────────────────── */
    {
        ast_node_t *e1 = parse_str("exp(x)");
        ast_node_t *e2 = parse_str("x^3");
        ASSERT_TRUE(e1 != NULL, "parse exp(x)");
        ASSERT_TRUE(e2 != NULL, "parse x^3");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* exp(x) and x^3 cross at approximately x~1.86 */
            ASSERT_TRUE(count >= 1,
                        "exp(x)=x^3 has >= 1 intersection");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Custom viewport intersection ──────────────────── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("4");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for custom vp");
        ASSERT_TRUE(e2 != NULL, "parse 4 for custom vp");
        if (e1 && e2) {
            vp.x_min = -5; vp.x_max = 5;
            vp.y_min = -1; vp.y_max = 10;
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* x^2 = 4 -> x = +/- 2 */
            ASSERT_TRUE(count == 2,
                        "x^2=4 in [-5,5]: 2 intersections");
            if (count >= 2) {
                ce_float_t x0 = pts[0].x < pts[1].x ? pts[0].x : pts[1].x;
                ce_float_t x1 = pts[0].x < pts[1].x ? pts[1].x : pts[0].x;
                ASSERT_EQ_FLOAT(x0, -2.0f, 0.05f, "x^2=4 at x=-2");
                ASSERT_EQ_FLOAT(x1,  2.0f, 0.05f, "x^2=4 at x=2");
            }
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Narrow viewport misses out-of-range intersection ── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("4");
        ASSERT_TRUE(e1 != NULL, "parse x^2 for narrow");
        ASSERT_TRUE(e2 != NULL, "parse 4 for narrow");
        if (e1 && e2) {
            vp.x_min = -1; vp.x_max = 1;
            vp.y_min = -1; vp.y_max = 5;
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* x = +/-2 are outside [-1,1] */
            ASSERT_TRUE(count == 0,
                        "x^2=4 in [-1,1]: 0 intersections");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Drawing functions run without crash ───────────── */
    {
        ast_node_t *e1 = parse_str("x^2");
        ast_node_t *e2 = parse_str("x+2");
        ASSERT_TRUE(e1 != NULL, "parse for draw test");
        ASSERT_TRUE(e2 != NULL, "parse for draw test 2");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* These use mock gfx_ functions (no-ops) */
            graph_draw_function(&vp, e1, 'x', COL_BLUE);
            graph_draw_function(&vp, e2, 'x', COL_RED);
            graph_draw_intersections(&vp, pts, count);
            ASSERT_TRUE(1, "draw two funcs + intersections no crash");

            /* Trace two */
            char lbl[48];
            graph_draw_trace_two(&vp, e1, e2, 'x',
                                 GRAPH_X0 + GRAPH_W / 2, lbl, sizeof(lbl));
            ASSERT_STR_CONTAINS(lbl, "f=",
                                "trace two label has f=");
            ASSERT_STR_CONTAINS(lbl, "g=",
                                "trace two label has g=");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Trace label with undefined function ───────────── */
    {
        ast_node_t *e1 = parse_str("1/x");
        ast_node_t *e2 = parse_str("x");
        ASSERT_TRUE(e1 != NULL, "parse 1/x for trace undef");
        ASSERT_TRUE(e2 != NULL, "parse x for trace undef");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            /* At x=0, 1/x is undefined */
            int sx_at_zero = graph_world_to_sx(&vp, 0.0f);
            char lbl[48];
            graph_draw_trace_two(&vp, e1, e2, 'x',
                                 sx_at_zero, lbl, sizeof(lbl));
            /* 1/x at 0 might give inf or div-by-zero */
            ASSERT_TRUE(strlen(lbl) > 0,
                        "trace label non-empty at singularity");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Max intersections cap ─────────────────────────── */
    {
        /* sin(10x) and 0 has many zero crossings */
        ast_node_t *e1 = parse_str("sin(10x)");
        ast_node_t *e2 = parse_str("0");
        ASSERT_TRUE(e1 != NULL, "parse sin(10x) for max cap");
        ASSERT_TRUE(e2 != NULL, "parse 0 for max cap");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            ASSERT_TRUE(count <= GRAPH_MAX_INTERSECTIONS,
                        "intersection count <= max");
            ASSERT_TRUE(count == GRAPH_MAX_INTERSECTIONS,
                        "sin(10x)=0 caps at max intersections");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Intersection with different variable ──────────── */
    {
        ast_node_t *e1 = parse_str("t^2");
        ast_node_t *e2 = parse_str("t+2");
        ASSERT_TRUE(e1 != NULL, "parse t^2 for t-var isect");
        ASSERT_TRUE(e2 != NULL, "parse t+2 for t-var isect");
        if (e1 && e2) {
            graph_default_viewport(&vp);
            count = graph_find_intersections(&vp, e1, e2, 't',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            ASSERT_TRUE(count == 2,
                        "t^2 = t+2 has 2 intersections with var t");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    /* ── Parser: grapheq with range (no var specified) ──── */
    {
        ast_node_t *root = parse_str("grapheq(x^2,x+2,-5,5)");
        ASSERT_TRUE(root != NULL, "grapheq range-no-var parses");
        if (root) {
            ASSERT_TRUE(root->d.polar.op == POLOP_GRAPHEQ,
                        "grapheq range-no-var op");
            ASSERT_TRUE(root->d.polar.lo != NULL,
                        "grapheq range-no-var has lo");
            ASSERT_TRUE(root->d.polar.hi != NULL,
                        "grapheq range-no-var has hi");
            ast_free(root);
        }
    }

    /* ── Intersection accuracy: x^3 = x (three crossings) ── */
    {
        ast_node_t *e1 = parse_str("x^3");
        ast_node_t *e2 = parse_str("x");
        ASSERT_TRUE(e1 != NULL, "parse x^3");
        ASSERT_TRUE(e2 != NULL, "parse x for cubic");
        if (e1 && e2) {
            vp.x_min = -3; vp.x_max = 3;
            vp.y_min = -5; vp.y_max = 5;
            count = graph_find_intersections(&vp, e1, e2, 'x',
                                             pts, GRAPH_MAX_INTERSECTIONS);
            /* x^3 = x -> x(x^2-1) = 0 -> x = -1, 0, 1 */
            ASSERT_TRUE(count >= 2,
                        "x^3=x has >= 2 intersections");
        }
        if (e1) ast_free(e1);
        if (e2) ast_free(e2);
    }

    mem_free_all();
}

/* ═══════════════════════════════════════════════════════════ */
/*     NEW FEATURES: NODE_LIST_ELEM, LinReg t-test, ANOVA,     */
/*                        Residuals                             */
