static void test_list_elem_access(void)
{
    printf("=== NODE_LIST_ELEM (List Element Access) ===\n");
    mem_free_all();
    list_init_all();

    /* ── Setup: populate L1 = {10,20,30,40,50} ───────── */
    {
        ce_float_t d1[] = {10, 20, 30, 40, 50};
        list_set(0, d1, 5);
    }

    /* ── Basic element access ─────────────────────────── */
    {
        ce_error_t err;
        ce_float_t val;

        printf("  -- Basic element access --\n");

        val = eval_str("L1(1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(1): no error");
        ASSERT_EQ_FLOAT(val, 10.0f, 0.01f, "L1(1) = 10");

        mem_free_all();
        val = eval_str("L1(3)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(3): no error");
        ASSERT_EQ_FLOAT(val, 30.0f, 0.01f, "L1(3) = 30");

        mem_free_all();
        val = eval_str("L1(5)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(5): no error");
        ASSERT_EQ_FLOAT(val, 50.0f, 0.01f, "L1(5) = 50");
    }

    /* ── Computed index ───────────────────────────────── */
    {
        ce_error_t err;
        ce_float_t val;

        printf("  -- Computed index --\n");
        mem_free_all();
        val = eval_str("L1(1+2)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(1+2): no error");
        ASSERT_EQ_FLOAT(val, 30.0f, 0.01f, "L1(1+2) = 30");

        mem_free_all();
        val = eval_str("L1(2*2)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(2*2): no error");
        ASSERT_EQ_FLOAT(val, 40.0f, 0.01f, "L1(2*2) = 40");
    }

    /* ── Out of bounds ────────────────────────────────── */
    {
        ce_error_t err;
        ce_float_t val;

        printf("  -- Out of bounds --\n");
        mem_free_all();
        val = eval_str("L1(0)", &err);
        ASSERT_TRUE(err != CE_OK, "L1(0): error expected");
        (void)val;

        mem_free_all();
        val = eval_str("L1(6)", &err);
        ASSERT_TRUE(err != CE_OK, "L1(6): error expected (only 5 elements)");
        (void)val;

        mem_free_all();
        val = eval_str("L1(-1)", &err);
        ASSERT_TRUE(err != CE_OK, "L1(-1): error expected");
        (void)val;
    }

    /* ── Different lists ──────────────────────────────── */
    {
        ce_error_t err;
        ce_float_t val;
        ce_float_t d2[] = {99, 88, 77};

        printf("  -- Different lists --\n");
        list_set(1, d2, 3);

        mem_free_all();
        val = eval_str("L2(1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L2(1): no error");
        ASSERT_EQ_FLOAT(val, 99.0f, 0.01f, "L2(1) = 99");

        mem_free_all();
        val = eval_str("L2(2)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L2(2): no error");
        ASSERT_EQ_FLOAT(val, 88.0f, 0.01f, "L2(2) = 88");

        mem_free_all();
        val = eval_str("L2(3)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L2(3): no error");
        ASSERT_EQ_FLOAT(val, 77.0f, 0.01f, "L2(3) = 77");
    }

    /* ── Empty list ───────────────────────────────────── */
    {
        ce_error_t err;
        ce_float_t val;
        ce_float_t empty[] = {0};

        printf("  -- Empty list --\n");
        list_set(2, empty, 0);  /* L3 = empty */

        mem_free_all();
        val = eval_str("L3(1)", &err);
        ASSERT_TRUE(err != CE_OK, "L3(1): error expected (empty list)");
        (void)val;
    }

    /* ── List element in expressions ──────────────────── */
    {
        ce_error_t err;
        ce_float_t val;

        printf("  -- List element in expressions --\n");
        mem_free_all();
        val = eval_str("L1(1)+L1(2)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(1)+L1(2): no error");
        ASSERT_EQ_FLOAT(val, 30.0f, 0.01f, "L1(1)+L1(2) = 30");

        mem_free_all();
        val = eval_str("L1(3)*2", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(3)*2: no error");
        ASSERT_EQ_FLOAT(val, 60.0f, 0.01f, "L1(3)*2 = 60");

        mem_free_all();
        val = eval_str("L1(4)-L1(1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "L1(4)-L1(1): no error");
        ASSERT_EQ_FLOAT(val, 30.0f, 0.01f, "L1(4)-L1(1) = 30");
    }

    /* ── AST node type and string representation ─────── */
    {
        ast_node_t *node;
        char buf[80];

        printf("  -- AST node type --\n");
        mem_free_all();
        node = parse_str("L1(2)");
        ASSERT_TRUE(node != NULL, "L1(2): parsed");
        if (node) {
            ASSERT_EQ_INT(node->type, NODE_LIST_ELEM, "L1(2): NODE_LIST_ELEM");
            ast_to_str(node, buf, sizeof(buf));
            ASSERT_TRUE(strlen(buf) > 0, "L1(2): non-empty string rep");
            ast_free(node);
        }
    }

    /* ── Clone and free ──────────────────────────────── */
    {
        ast_node_t *node, *clone;

        printf("  -- Clone and free --\n");
        mem_free_all();
        node = parse_str("L1(3)");
        ASSERT_TRUE(node != NULL, "L1(3): parsed for clone");
        if (node) {
            clone = ast_clone(node);
            ASSERT_TRUE(clone != NULL, "L1(3): cloned");
            if (clone) {
                ASSERT_EQ_INT(clone->type, NODE_LIST_ELEM, "clone: NODE_LIST_ELEM");
                ast_free(clone);
            }
            ast_free(node);
        }
    }

    mem_free_all();
}

static void test_linreg_ttest(void)
{
    printf("=== LinReg t-test ===\n");
    mem_free_all();

    /* ── Strong positive correlation ──────────────────── */
    {
        /* x = {1,2,3,4,5}, y = {2,4,6,8,10} → perfect correlation */
        ce_float_t data[] = {1,2, 2,4, 3,6, 4,8, 5,10};
        linreg_ttest_result_t r = stattest_linreg_ttest(data, 10);

        printf("  -- Perfect positive correlation --\n");
        ASSERT_EQ_FLOAT(r.r, 1.0f, 0.01f, "linregttest: r = 1.0");
        ASSERT_EQ_FLOAT(r.m, 2.0f, 0.01f, "linregttest: slope = 2.0");
        ASSERT_EQ_FLOAT(r.b, 0.0f, 0.1f, "linregttest: intercept ≈ 0");
        ASSERT_EQ_FLOAT(r.df, 3.0f, 0.01f, "linregttest: df = n-2 = 3");
        ASSERT_TRUE(r.p < 0.01f, "linregttest: p < 0.01 (highly significant)");
    }

    /* ── Moderate correlation ─────────────────────────── */
    {
        /* x = {1,2,3,4,5}, y = {2.1,3.8,6.2,7.9,10.5} → strong but not perfect */
        ce_float_t data[] = {1,2.1f, 2,3.8f, 3,6.2f, 4,7.9f, 5,10.5f};
        linreg_ttest_result_t r = stattest_linreg_ttest(data, 10);

        printf("  -- Strong correlation --\n");
        ASSERT_TRUE(r.r > 0.95f, "linregttest: r > 0.95");
        ASSERT_TRUE(r.t > 2.0f, "linregttest: t > 2.0");
        ASSERT_TRUE(r.p < 0.05f, "linregttest: p < 0.05 (significant)");
        ASSERT_EQ_FLOAT(r.df, 3.0f, 0.01f, "linregttest: df = 3");
    }

    /* ── Weak correlation ─────────────────────────────── */
    {
        /* Random-ish data with weak correlation */
        ce_float_t data[] = {1,5.0f, 2,3.0f, 3,7.0f, 4,4.0f, 5,6.0f};
        linreg_ttest_result_t r = stattest_linreg_ttest(data, 10);

        printf("  -- Weak correlation --\n");
        ASSERT_TRUE(fabsf(r.r) < 0.7f, "linregttest: |r| < 0.7 (weak)");
        /* p should be large (not significant) */
        ASSERT_TRUE(r.p > 0.1f, "linregttest: p > 0.1 (not significant)");
    }

    /* ── Negative correlation ─────────────────────────── */
    {
        /* y decreases as x increases */
        ce_float_t data[] = {1,10.0f, 2,8.0f, 3,6.0f, 4,4.0f, 5,2.0f};
        linreg_ttest_result_t r = stattest_linreg_ttest(data, 10);

        printf("  -- Perfect negative correlation --\n");
        ASSERT_EQ_FLOAT(r.r, -1.0f, 0.01f, "linregttest: r = -1.0");
        ASSERT_EQ_FLOAT(r.m, -2.0f, 0.01f, "linregttest: slope = -2.0");
        ASSERT_TRUE(r.t < -5.0f, "linregttest: t < -5 (large negative)");
        ASSERT_TRUE(r.p < 0.01f, "linregttest: p < 0.01");
    }

    /* ── Too few data points ──────────────────────────── */
    {
        /* Only 2 points: df = 0, can't do t-test */
        ce_float_t data[] = {1,2, 3,4};
        linreg_ttest_result_t r = stattest_linreg_ttest(data, 4);

        printf("  -- Edge: only 2 points --\n");
        ASSERT_EQ_FLOAT(r.df, 0.0f, 0.01f, "linregttest: df = 0 with 2 pts");
    }

    /* ── Parser token test ────────────────────────────── */
    {
        ast_node_t *node;

        printf("  -- Parser token --\n");
        mem_free_all();
        node = parse_str("linregttest(1,2,3,4,5,6)");
        ASSERT_TRUE(node != NULL, "linregttest(): parsed");
        if (node) {
            ASSERT_EQ_INT(node->type, NODE_STAT, "linregttest: NODE_STAT");
            ast_free(node);
        }
    }

    mem_free_all();
}

static void test_anova(void)
{
    printf("=== One-way ANOVA ===\n");
    mem_free_all();

    /* ── Equal means → F small, p large ──────────────── */
    {
        ce_float_t g1[] = {5, 5, 5, 5};
        ce_float_t g2[] = {5, 5, 5, 5};
        ce_float_t g3[] = {5, 5, 5, 5};
        const ce_float_t *groups[] = {g1, g2, g3};
        int sizes[] = {4, 4, 4};
        anova_result_t r = stattest_anova(groups, sizes, 3);

        printf("  -- Equal means --\n");
        ASSERT_EQ_FLOAT(r.F, 0.0f, 0.01f, "anova equal: F = 0");
        ASSERT_TRUE(r.p >= 0.99f, "anova equal: p ≈ 1.0");
        ASSERT_EQ_FLOAT(r.df_between, 2.0f, 0.01f, "anova equal: df_between = 2");
        ASSERT_EQ_FLOAT(r.df_within, 9.0f, 0.01f, "anova equal: df_within = 9");
    }

    /* ── Very different means → F large, p small ─────── */
    {
        ce_float_t g1[] = {1, 2, 3};
        ce_float_t g2[] = {10, 11, 12};
        ce_float_t g3[] = {20, 21, 22};
        const ce_float_t *groups[] = {g1, g2, g3};
        int sizes[] = {3, 3, 3};
        anova_result_t r = stattest_anova(groups, sizes, 3);

        printf("  -- Very different means --\n");
        ASSERT_TRUE(r.F > 50.0f, "anova different: F > 50");
        ASSERT_TRUE(r.p < 0.001f, "anova different: p < 0.001");
        ASSERT_EQ_FLOAT(r.df_between, 2.0f, 0.01f, "anova diff: df_between = 2");
        ASSERT_EQ_FLOAT(r.df_within, 6.0f, 0.01f, "anova diff: df_within = 6");
    }

    /* ── Two groups ───────────────────────────────────── */
    {
        ce_float_t g1[] = {10, 12, 14, 16, 18};
        ce_float_t g2[] = {20, 22, 24, 26, 28};
        const ce_float_t *groups[] = {g1, g2};
        int sizes[] = {5, 5};
        anova_result_t r = stattest_anova(groups, sizes, 2);

        printf("  -- Two groups --\n");
        ASSERT_TRUE(r.F > 10.0f, "anova 2-groups: F > 10");
        ASSERT_TRUE(r.p < 0.01f, "anova 2-groups: p < 0.01");
        ASSERT_EQ_FLOAT(r.df_between, 1.0f, 0.01f, "anova 2-groups: df_between = 1");
        ASSERT_EQ_FLOAT(r.df_within, 8.0f, 0.01f, "anova 2-groups: df_within = 8");
    }

    /* ── Unequal group sizes ──────────────────────────── */
    {
        ce_float_t g1[] = {5, 6, 7};
        ce_float_t g2[] = {15, 16};
        const ce_float_t *groups[] = {g1, g2};
        int sizes[] = {3, 2};
        anova_result_t r = stattest_anova(groups, sizes, 2);

        printf("  -- Unequal sizes --\n");
        ASSERT_TRUE(r.F > 5.0f, "anova unequal: F > 5");
        ASSERT_EQ_FLOAT(r.df_between, 1.0f, 0.01f, "anova unequal: df_between = 1");
        ASSERT_EQ_FLOAT(r.df_within, 3.0f, 0.01f, "anova unequal: df_within = 3");
    }

    /* ── SS decomposition check ───────────────────────── */
    {
        ce_float_t g1[] = {1, 2, 3};
        ce_float_t g2[] = {4, 5, 6};
        const ce_float_t *groups[] = {g1, g2};
        int sizes[] = {3, 3};
        anova_result_t r = stattest_anova(groups, sizes, 2);

        printf("  -- SS decomposition --\n");
        /* Verify: MS_between = SS_between / df_between */
        ASSERT_EQ_FLOAT(r.MS_between, r.SS_between / r.df_between, 0.01f,
                        "anova: MS_between = SS_between / df_between");
        /* Verify: MS_within = SS_within / df_within */
        ASSERT_EQ_FLOAT(r.MS_within, r.SS_within / r.df_within, 0.01f,
                        "anova: MS_within = SS_within / df_within");
        /* Verify: F = MS_between / MS_within */
        ASSERT_EQ_FLOAT(r.F, r.MS_between / r.MS_within, 0.01f,
                        "anova: F = MS_between / MS_within");
    }

    /* ── Edge: fewer than 2 groups ────────────────────── */
    {
        ce_float_t g1[] = {1, 2, 3};
        const ce_float_t *groups[] = {g1};
        int sizes[] = {3};
        anova_result_t r = stattest_anova(groups, sizes, 1);

        printf("  -- Edge: 1 group --\n");
        ASSERT_EQ_FLOAT(r.F, 0.0f, 0.01f, "anova 1-group: F = 0 (invalid)");
    }

    /* ── Parser token test ────────────────────────────── */
    {
        ast_node_t *node;

        printf("  -- Parser token --\n");
        mem_free_all();
        node = parse_str("anova(1,2,3,4,5,6)");
        ASSERT_TRUE(node != NULL, "anova(): parsed");
        if (node) {
            ASSERT_EQ_INT(node->type, NODE_STAT, "anova: NODE_STAT");
            ast_free(node);
        }
    }

    mem_free_all();
}

static void test_residuals(void)
{
    printf("=== Residuals ===\n");
    mem_free_all();

    /* ── Perfect fit → all residuals zero ─────────────── */
    {
        ce_float_t data[] = {1,2, 2,4, 3,6, 4,8, 5,10};
        ce_float_t out[5];
        int count;
        ce_error_t err;

        printf("  -- Perfect fit --\n");
        err = stat_residuals(data, 10, out, &count);
        ASSERT_EQ_INT(err, CE_OK, "resid perfect: no error");
        ASSERT_EQ_INT(count, 5, "resid perfect: 5 residuals");
        ASSERT_EQ_FLOAT(out[0], 0.0f, 0.01f, "resid[0] = 0");
        ASSERT_EQ_FLOAT(out[1], 0.0f, 0.01f, "resid[1] = 0");
        ASSERT_EQ_FLOAT(out[2], 0.0f, 0.01f, "resid[2] = 0");
        ASSERT_EQ_FLOAT(out[3], 0.0f, 0.01f, "resid[3] = 0");
        ASSERT_EQ_FLOAT(out[4], 0.0f, 0.01f, "resid[4] = 0");
    }

    /* ── Imperfect fit → nonzero residuals ────────────── */
    {
        ce_float_t data[] = {1,2.1f, 2,3.8f, 3,6.2f, 4,7.9f, 5,10.5f};
        ce_float_t out[5];
        int count;
        ce_error_t err;
        ce_float_t sum = 0.0f;
        int i;

        printf("  -- Imperfect fit --\n");
        err = stat_residuals(data, 10, out, &count);
        ASSERT_EQ_INT(err, CE_OK, "resid imperfect: no error");
        ASSERT_EQ_INT(count, 5, "resid imperfect: 5 residuals");
        /* Sum of residuals should be close to zero */
        for (i = 0; i < count; i++) sum += out[i];
        ASSERT_EQ_FLOAT(sum, 0.0f, 0.5f, "resid: sum ≈ 0");
    }

    /* ── Negative residuals ───────────────────────────── */
    {
        /* y values all below the fit line */
        ce_float_t data[] = {1,1, 2,3, 3,4};
        ce_float_t out[3];
        int count;
        ce_error_t err;

        printf("  -- Residuals sign check --\n");
        err = stat_residuals(data, 6, out, &count);
        ASSERT_EQ_INT(err, CE_OK, "resid sign: no error");
        ASSERT_EQ_INT(count, 3, "resid sign: 3 residuals");
        /* At least one should be nonzero if fit isn't perfect */
    }

    /* ── Too few points ───────────────────────────────── */
    {
        ce_float_t data[] = {1, 2};
        ce_float_t out[1];
        int count;
        ce_error_t err;

        printf("  -- Too few points --\n");
        err = stat_residuals(data, 2, out, &count);
        /* 1 point → linreg needs >= 2 pairs */
        ASSERT_TRUE(err != CE_OK, "resid 1-point: error expected");
    }

    /* ── Parser token test ────────────────────────────── */
    {
        ast_node_t *node;

        printf("  -- Parser token --\n");
        mem_free_all();
        node = parse_str("resid(1,2,3,4,5,6)");
        ASSERT_TRUE(node != NULL, "resid(): parsed");
        if (node) {
            ASSERT_EQ_INT(node->type, NODE_STAT, "resid: NODE_STAT");
            ast_free(node);
        }
    }

    mem_free_all();
}

