static void test_recents_tracking(void)
{
    menu_item_t a = { "d/dx(        derivative", "d/dx(" };
    menu_item_t b = { "int(         indefinite", "int(" };
    menu_item_t c = { "lim(         limit",      "lim(" };
    const menu_item_t *page;
    uint8_t count;

    printf("  -- Recents: initially empty --\n");
    /* Recents should start empty (or we can test after resetting) */
    /* Note: recents persist across tests in static memory, so test behavior */

    printf("  -- Recents: add items --\n");
    ui_menu_add_recent(&a);
    ASSERT_TRUE(ui_menu_recents_count() >= 1, "recents: count >= 1 after add");
    page = ui_menu_get_page(0);
    ASSERT_TRUE(page != NULL, "recents: page 0 not NULL");
    ASSERT_TRUE(strcmp(page[0].insert_str, "d/dx(") == 0,
                "recents: first item is d/dx(");

    printf("  -- Recents: most recent at top --\n");
    ui_menu_add_recent(&b);
    page = ui_menu_get_page(0);
    ASSERT_TRUE(strcmp(page[0].insert_str, "int(") == 0,
                "recents: int( is now first");
    ASSERT_TRUE(strcmp(page[1].insert_str, "d/dx(") == 0,
                "recents: d/dx( moved to second");

    printf("  -- Recents: no duplicates (move to front) --\n");
    ui_menu_add_recent(&a);  /* d/dx( again */
    page = ui_menu_get_page(0);
    ASSERT_TRUE(strcmp(page[0].insert_str, "d/dx(") == 0,
                "recents: d/dx( moved back to first");
    ASSERT_TRUE(strcmp(page[1].insert_str, "int(") == 0,
                "recents: int( is now second");

    printf("  -- Recents: third item --\n");
    ui_menu_add_recent(&c);
    page = ui_menu_get_page(0);
    ASSERT_TRUE(strcmp(page[0].insert_str, "lim(") == 0,
                "recents: lim( is now first");
    count = ui_menu_get_count(0);
    ASSERT_TRUE(count >= 3, "recents: count >= 3");

    printf("  -- Recents: max capacity --\n");
    {
        int i;
        /* static: ui_menu_add_recent() keeps these pointers in the
         * module-level recents list after this block returns, and later
         * tests (test_tabbed_menu_architecture) read them (strcmp, draw). Block-scoped
         * arrays left that list pointing into a dead stack frame. */
        static char labels[12][32];
        static char inserts[12][16];
        menu_item_t items[12];
        for (i = 0; i < 12; i++) {
            snprintf(labels[i], sizeof(labels[i]), "func%d(   test%d", i, i);
            snprintf(inserts[i], sizeof(inserts[i]), "func%d(", i);
            items[i].label = labels[i];
            items[i].insert_str = inserts[i];
            ui_menu_add_recent(&items[i]);
        }
        count = ui_menu_get_count(0);
        ASSERT_TRUE(count <= 10, "recents: max 10 items");
        page = ui_menu_get_page(0);
        ASSERT_TRUE(strcmp(page[0].insert_str, "func11(") == 0,
                    "recents: most recent func11( at top");
    }
}

