static void test_ux_clear_key(void)
{
    /* Feature 1: CLEAR key behavior — clear content first, exit second */
    input_buf_t ib;

    printf("  -- Input buffer: clear content first --\n");
    input_buf_init(&ib);
    input_buf_insert_str(&ib, "3+4");
    ASSERT_EQ_INT(ib.len, 3, "input has 3 chars after insert");
    /* First CLEAR: should clear content */
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "input cleared to 0 after first clear");

    printf("  -- Input buffer: second clear on empty is no-op --\n");
    /* Already empty — CLEAR again should be a no-op (nothing to clear) */
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "input still 0 after second clear on empty");

    printf("  -- Input buffer: insert then partial clear sequence --\n");
    input_buf_init(&ib);
    input_buf_insert_str(&ib, "sin(x)+cos(x)");
    ASSERT_TRUE(ib.len == 13, "sin(x)+cos(x) has 13 chars");
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "input cleared after expression");
    /* Insert again after clear */
    input_buf_insert_str(&ib, "2x");
    ASSERT_EQ_INT(ib.len, 2, "can insert after clear");

    printf("  -- Input buffer: graph eq entry scenario --\n");
    /* Graph equation entry: CLEAR clears input first, exit mode second */
    input_buf_init(&ib);
    input_buf_insert_str(&ib, "x^2");
    ASSERT_EQ_INT(ib.len, 3, "graph eq input has content");
    /* Simulate first CLEAR: clear input */
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "graph eq input cleared on first CLEAR");
    /* Second CLEAR would exit graph_eq_entry mode — can't test state machine
       directly in unit tests but we verify the buffer logic works */

    printf("  -- Input buffer: long expression clear --\n");
    input_buf_init(&ib);
    input_buf_insert_str(&ib, "integrate(x^3+2*x^2-5*x+1,x,0,10)");
    ASSERT_TRUE(ib.len > 0, "long expression inserted");
    input_buf_clear(&ib);
    ASSERT_EQ_INT(ib.len, 0, "long expression cleared");
    ASSERT_EQ_INT(ib.cursor, 0, "cursor reset to 0 after clear");
}

static void test_ux_cancel_computation(void)
{
    /* Feature 2: Cancel mid-calculation via check_cancel() */

    printf("  -- check_cancel: default returns false --\n");
    tice_mock_set_cancel(false);
    ASSERT_TRUE(!check_cancel(), "check_cancel() returns false by default");

    printf("  -- check_cancel: set true returns true --\n");
    tice_mock_set_cancel(true);
    ASSERT_TRUE(check_cancel(), "check_cancel() returns true when set");

    printf("  -- check_cancel: reset to false --\n");
    tice_mock_set_cancel(false);
    ASSERT_TRUE(!check_cancel(), "check_cancel() returns false after reset");

    printf("  -- CE_ERR_CANCELLED enum exists --\n");
    ASSERT_TRUE(CE_ERR_CANCELLED > CE_OK, "CE_ERR_CANCELLED is a valid error code");
    ASSERT_TRUE(CE_ERR_CANCELLED != CE_ERR_SYNTAX, "CE_ERR_CANCELLED distinct from SYNTAX");
    ASSERT_TRUE(CE_ERR_CANCELLED != CE_ERR_DOMAIN, "CE_ERR_CANCELLED distinct from DOMAIN");
    ASSERT_TRUE(CE_ERR_CANCELLED != CE_ERR_OVERFLOW, "CE_ERR_CANCELLED distinct from OVERFLOW");

    printf("  -- Cancel during SUM: sum(x,x,1,1000) --\n");
    tice_mock_set_cancel(true);
    {
        ast_node_t *root = parse_str("sum(x,x,1,1000)");
        ASSERT_TRUE(root != NULL, "parsed sum(x,x,1,1000)");
        if (root) {
            eval_ctx_t ctx;
            eval_init(&ctx);
            eval_expr(&ctx, root);
            /* Should have been cancelled */
            ASSERT_TRUE(ctx.error != CE_OK, "sum was interrupted by cancel");
            ast_free(root);
        }
    }
    tice_mock_set_cancel(false);

    printf("  -- Cancel during PRODUCT: prod(x,x,1,1000) --\n");
    tice_mock_set_cancel(true);
    {
        ast_node_t *root = parse_str("prod(x,x,1,1000)");
        ASSERT_TRUE(root != NULL, "parsed prod(x,x,1,1000)");
        if (root) {
            eval_ctx_t ctx;
            eval_init(&ctx);
            eval_expr(&ctx, root);
            ASSERT_TRUE(ctx.error != CE_OK, "product was interrupted by cancel");
            ast_free(root);
        }
    }
    tice_mock_set_cancel(false);

    printf("  -- Cancel during trapezoidal integration --\n");
    tice_mock_set_cancel(true);
    {
        ast_node_t *expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "parsed x^2 for trapezoidal");
        if (expr) {
            numint_result_t res = integrate_trapezoidal(expr, 'x', 0.0f, 10.0f, 10000);
            ASSERT_TRUE(res.error == CE_ERR_CANCELLED, "trapezoidal cancelled");
            ast_free(expr);
        }
    }
    tice_mock_set_cancel(false);

    printf("  -- Cancel during Simpson's integration --\n");
    tice_mock_set_cancel(true);
    {
        ast_node_t *expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "parsed x^2 for Simpson");
        if (expr) {
            numint_result_t res = integrate_simpson(expr, 'x', 0.0f, 10.0f, 10000);
            ASSERT_TRUE(res.error == CE_ERR_CANCELLED, "simpson cancelled");
            ast_free(expr);
        }
    }
    tice_mock_set_cancel(false);

    printf("  -- Normal SUM works when cancel is false --\n");
    tice_mock_set_cancel(false);
    {
        ast_node_t *root = parse_str("sum(x,x,1,10)");
        ASSERT_TRUE(root != NULL, "parsed sum(x,x,1,10)");
        if (root) {
            eval_ctx_t ctx;
            eval_init(&ctx);
            ce_float_t val = eval_expr(&ctx, root);
            ASSERT_TRUE(ctx.error == CE_OK, "sum(x,x,1,10) completed without cancel");
            ASSERT_EQ_FLOAT(val, 55.0f, 0.01f, "sum(x,x,1,10) = 55");
            ast_free(root);
        }
    }

    printf("  -- Normal trapezoidal works when cancel is false --\n");
    tice_mock_set_cancel(false);
    {
        ast_node_t *expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "parsed x^2 for normal trap");
        if (expr) {
            numint_result_t res = integrate_trapezoidal(expr, 'x', 0.0f, 1.0f, 100);
            ASSERT_TRUE(res.error == CE_OK, "trapezoidal completed normally");
            ASSERT_EQ_FLOAT(res.value, 0.3333f, 0.01f, "trap(x^2,0,1) ≈ 1/3");
            ast_free(expr);
        }
    }
}

static void test_ux_progress_indicator(void)
{
    /* Feature 3: Progress indicator — mock versions are no-ops */

    printf("  -- progress_start: no-op on desktop --\n");
    progress_start();
    /* If we get here, it didn't crash */
    ASSERT_TRUE(1, "progress_start() is safe no-op");

    printf("  -- progress_check: no-op on desktop --\n");
    progress_check();
    ASSERT_TRUE(1, "progress_check() is safe no-op");

    printf("  -- progress cycle: start then multiple checks --\n");
    progress_start();
    progress_check();
    progress_check();
    progress_check();
    ASSERT_TRUE(1, "multiple progress_check() calls are safe");

    printf("  -- progress during integration (no crash) --\n");
    tice_mock_set_cancel(false);
    {
        ast_node_t *expr = parse_str("x^3");
        ASSERT_TRUE(expr != NULL, "parsed x^3 for progress test");
        if (expr) {
            /* Large n_steps will trigger progress_check via (i & 0xFF)==0 */
            numint_result_t res = integrate_trapezoidal(expr, 'x', 0.0f, 1.0f, 1000);
            ASSERT_TRUE(res.error == CE_OK, "integration with progress succeeded");
            ASSERT_EQ_FLOAT(res.value, 0.25f, 0.01f, "trap(x^3,0,1) ≈ 1/4");
            ast_free(expr);
        }
    }

    printf("  -- progress during sum (no crash) --\n");
    {
        ast_node_t *root = parse_str("sum(x^2,x,1,500)");
        ASSERT_TRUE(root != NULL, "parsed sum(x^2,x,1,500)");
        if (root) {
            eval_ctx_t ctx;
            eval_init(&ctx);
            ce_float_t val = eval_expr(&ctx, root);
            ASSERT_TRUE(ctx.error == CE_OK, "sum with progress completed OK");
            /* sum(x^2,x,1,500) = 500*501*1001/6 = 41791750 */
            ASSERT_TRUE(val > 4.0e7f, "sum(x^2,1,500) is large positive");
            ast_free(root);
        }
    }
}

static void test_ux_history_persistence(void)
{
    /* Feature 4: History persistence via AppVars (mock returns failure) */

    printf("  -- fileioc mock: ti_Open returns 0 (failure) --\n");
    {
        ti_var_t slot = ti_Open("TEST", "w");
        ASSERT_EQ_INT(slot, 0, "ti_Open returns 0 on desktop mock");
    }

    printf("  -- fileioc mock: ti_Close returns 0 --\n");
    {
        int ret = ti_Close(1);
        ASSERT_EQ_INT(ret, 0, "ti_Close returns 0 on desktop mock");
    }

    printf("  -- fileioc mock: ti_Write returns 0 --\n");
    {
        int data = 42;
        size_t ret = ti_Write(&data, sizeof(data), 1, 1);
        ASSERT_EQ_INT((int)ret, 0, "ti_Write returns 0 on desktop mock");
    }

    printf("  -- fileioc mock: ti_Read returns 0 --\n");
    {
        int data = 0;
        size_t ret = ti_Read(&data, sizeof(data), 1, 1);
        ASSERT_EQ_INT((int)ret, 0, "ti_Read returns 0 on desktop mock");
    }

    printf("  -- fileioc mock: ti_SetArchiveStatus returns 0 --\n");
    {
        int ret = ti_SetArchiveStatus(1, 1);
        ASSERT_EQ_INT(ret, 0, "ti_SetArchiveStatus returns 0 on desktop mock");
    }

    printf("  -- History: ti_Open w/ various modes all fail --\n");
    {
        ASSERT_EQ_INT(ti_Open("CEHISTOR", "r"), 0, "open read fails");
        ASSERT_EQ_INT(ti_Open("CEHISTOR", "w"), 0, "open write fails");
        ASSERT_EQ_INT(ti_Open("CEHISTOR", "a"), 0, "open append fails");
        ASSERT_EQ_INT(ti_Open("ANYTHING", "r"), 0, "open any name fails");
    }

    printf("  -- History: graceful degradation (no crash on load/save failure) --\n");
    /* On desktop, history_save/load are in main.c which isn't compiled.
       But the mock file I/O ensures that if they were called, ti_Open
       returns 0 and the functions bail out gracefully without crash.
       We verify the mock correctness here. */
    {
        ti_var_t slot = ti_Open("CEHISTOR", "w");
        ASSERT_EQ_INT(slot, 0, "can't open appvar on desktop");
        /* Since slot is 0 (invalid), history_save would return early */
        /* Verify that write with invalid slot doesn't crash */
        size_t w = ti_Write("test", 4, 1, slot);
        ASSERT_EQ_INT((int)w, 0, "write with slot 0 returns 0");
    }
}

static void test_ux_error_codes(void)
{
    /* Verify all error enum values are distinct and ordered */
    printf("  -- Error enum: all values are distinct --\n");
    ce_error_t codes[] = {
        CE_OK, CE_ERR_SYNTAX, CE_ERR_MEMORY, CE_ERR_OVERFLOW,
        CE_ERR_DIV_ZERO, CE_ERR_DOMAIN, CE_ERR_UNDEFINED,
        CE_ERR_TOO_COMPLEX, CE_ERR_INTERNAL, CE_ERR_CANCELLED
    };
    int ncodes = sizeof(codes) / sizeof(codes[0]);
    ASSERT_EQ_INT(ncodes, 10, "10 error codes total");
    for (int i = 0; i < ncodes; i++) {
        for (int j = i + 1; j < ncodes; j++) {
            ASSERT_TRUE(codes[i] != codes[j], "error codes are distinct");
        }
    }

    printf("  -- CE_ERR_CANCELLED is the last enum value --\n");
    ASSERT_TRUE(CE_ERR_CANCELLED == 9, "CE_ERR_CANCELLED == 9 (last)");
}

