static void test_mathprint_measure(void)
{
    mp_bbox_t b;
    ast_node_t *n;

    printf("  -- MathPrint measure: numbers --\n");
    mem_free_all();
    n = ast_number(42);
    b = mp_measure(n);
    ASSERT_TRUE(b.w > 0, "mp number width > 0");
    ASSERT_EQ_INT(b.w, 16, "mp '42' width = 2 chars * 8");
    ASSERT_EQ_INT(b.ascent, MP_HALF_H, "mp number ascent = HALF_H");
    ASSERT_EQ_INT(b.descent, MP_HALF_H, "mp number descent = HALF_H");
    ast_free(n);

    printf("  -- MathPrint measure: variable --\n");
    n = ast_variable('x');
    b = mp_measure(n);
    ASSERT_EQ_INT(b.w, MP_CHAR_W, "mp variable width = CHAR_W");
    ASSERT_EQ_INT(b.ascent, MP_HALF_H, "mp variable ascent");
    ast_free(n);

    printf("  -- MathPrint measure: constant pi --\n");
    n = ast_constant(CONST_PI);
    b = mp_measure(n);
    ASSERT_EQ_INT(b.w, 16, "mp 'pi' width = 2 chars * 8");
    ast_free(n);

    printf("  -- MathPrint measure: fraction --\n");
    mem_free_all();
    /* 1/2 */
    n = ast_binop(OP_DIV, ast_number(1), ast_number(2));
    b = mp_measure(n);
    /* Width = max(8, 8) + 2*2 = 12 */
    ASSERT_EQ_INT(b.w, 12, "mp fraction 1/2 width");
    /* Ascent = H(num) + FRAC_PAD = 8 + 2 = 10 */
    ASSERT_EQ_INT(b.ascent, 10, "mp fraction ascent = H(num) + pad");
    ASSERT_EQ_INT(b.descent, 10, "mp fraction descent = H(den) + pad");
    ASSERT_TRUE(MP_BBOX_H(b) == 20, "mp fraction total height = 20");
    ast_free(n);

    printf("  -- MathPrint measure: exponent --\n");
    mem_free_all();
    /* x^2 */
    n = ast_binop(OP_POW, ast_variable('x'), ast_number(2));
    b = mp_measure(n);
    /* Width = base_w + exp_w = 8 + 8 = 16 */
    ASSERT_EQ_INT(b.w, 16, "mp x^2 width = 16");
    /* Ascent = base.ascent + max(0, H(exp) - OVERLAP) = 4 + max(0, 8-2) = 10 */
    ASSERT_EQ_INT(b.ascent, 10, "mp x^2 ascent = 10");
    ASSERT_EQ_INT(b.descent, MP_HALF_H, "mp x^2 descent = HALF_H");
    ast_free(n);

    printf("  -- MathPrint measure: addition --\n");
    mem_free_all();
    /* x + 1 */
    n = ast_binop(OP_ADD, ast_variable('x'), ast_number(1));
    b = mp_measure(n);
    /* Width = x_w + op_pad + '+' + op_pad + 1_w = 8 + 2 + 8 + 2 + 8 = 28 */
    ASSERT_EQ_INT(b.w, 28, "mp x+1 width = 28");
    ASSERT_EQ_INT(b.ascent, MP_HALF_H, "mp add ascent");
    ast_free(n);

    printf("  -- MathPrint measure: sqrt --\n");
    mem_free_all();
    n = ast_func(FN_SQRT, ast_variable('x'));
    b = mp_measure(n);
    /* Width = RADICAL_HOOK_W + inner_w + 1 = 6 + 8 + 1 = 15 */
    ASSERT_EQ_INT(b.w, 15, "mp sqrt(x) width = 15");
    /* Ascent = inner.ascent + RADICAL_PAD + 1 = 4 + 2 + 1 = 7 */
    ASSERT_EQ_INT(b.ascent, 7, "mp sqrt ascent");
    ast_free(n);

    printf("  -- MathPrint measure: negation --\n");
    mem_free_all();
    n = ast_unop(UOP_NEG, ast_variable('x'));
    b = mp_measure(n);
    /* Width = '-' + x = 8 + 8 = 16 */
    ASSERT_EQ_INT(b.w, 16, "mp -x width = 16");
    ast_free(n);

    printf("  -- MathPrint measure: factorial --\n");
    mem_free_all();
    n = ast_unop(UOP_FACT, ast_number(5));
    b = mp_measure(n);
    /* Width = '5' + '!' = 8 + 8 = 16 */
    ASSERT_EQ_INT(b.w, 16, "mp 5! width = 16");
    ast_free(n);

    printf("  -- MathPrint measure: sin(x) --\n");
    mem_free_all();
    n = ast_func(FN_SIN, ast_variable('x'));
    b = mp_measure(n);
    /* Width = 'sin' + '(' + 'x' + ')' = 24 + 4 + 8 + 4 = 40 */
    ASSERT_EQ_INT(b.w, 40, "mp sin(x) width = 40");
    ast_free(n);

    printf("  -- MathPrint measure: NULL node --\n");
    b = mp_measure(NULL);
    ASSERT_EQ_INT(b.w, 0, "mp NULL width = 0");
    ASSERT_EQ_INT(b.ascent, 0, "mp NULL ascent = 0");
    ASSERT_EQ_INT(b.descent, 0, "mp NULL descent = 0");
}

static void test_mathprint_draw(void)
{
    ast_node_t *n;

    printf("  -- MathPrint draw: number --\n");
    mem_free_all();
    gfx_mock_reset();
    n = ast_number(7);
    gfx_SetTextFGColor(0x00);
    gfx_SetColor(0x00);
    mp_draw(n, 10, 100);
    ASSERT_TRUE(gfx_mock_text_contains("7"), "mp draw 7: text contains '7'");
    {
        const gfx_mock_text_call_t *call = gfx_mock_text_call_at(0);
        ASSERT_TRUE(call != NULL, "mp draw 7: has text call");
        if (call) {
            ASSERT_EQ_INT(call->x, 10, "mp draw 7: x = 10");
            ASSERT_EQ_INT(call->y, 96, "mp draw 7: y = yc - HALF_H = 96");
        }
    }
    ast_free(n);

    printf("  -- MathPrint draw: fraction --\n");
    mem_free_all();
    gfx_mock_reset();
    /* 1/2 */
    n = ast_binop(OP_DIV, ast_number(1), ast_number(2));
    mp_draw(n, 20, 100);
    /* Should have: text "1" (numerator), text "2" (denominator), horiz line (bar) */
    ASSERT_TRUE(gfx_mock_text_contains("1"), "mp draw 1/2: numerator '1'");
    ASSERT_TRUE(gfx_mock_text_contains("2"), "mp draw 1/2: denominator '2'");
    ASSERT_TRUE(gfx_mock_horiz_line_count >= 1, "mp draw 1/2: fraction bar drawn");
    /* Numerator should be above center (y < 100-4) */
    {
        const gfx_mock_text_call_t *c0 = gfx_mock_text_call_at(0);
        if (c0) {
            ASSERT_TRUE(c0->y < 100, "mp draw 1/2: numerator above center");
        }
    }
    ast_free(n);

    printf("  -- MathPrint draw: exponent --\n");
    mem_free_all();
    gfx_mock_reset();
    /* x^2 */
    n = ast_binop(OP_POW, ast_variable('x'), ast_number(2));
    mp_draw(n, 0, 100);
    ASSERT_TRUE(gfx_mock_text_contains("x"), "mp draw x^2: base 'x'");
    ASSERT_TRUE(gfx_mock_text_contains("2"), "mp draw x^2: exponent '2'");
    /* Exponent y should be above base y */
    {
        int i;
        int base_y = -1, exp_y = -1;
        for (i = 0; i < gfx_mock_text_call_count(); i++) {
            const gfx_mock_text_call_t *c = gfx_mock_text_call_at(i);
            if (c && strcmp(c->text, "x") == 0) base_y = c->y;
            if (c && strcmp(c->text, "2") == 0) exp_y = c->y;
        }
        ASSERT_TRUE(base_y >= 0 && exp_y >= 0, "mp x^2: found both text calls");
        ASSERT_TRUE(exp_y < base_y, "mp x^2: exponent drawn above base");
    }
    ast_free(n);

    printf("  -- MathPrint draw: sqrt --\n");
    mem_free_all();
    gfx_mock_reset();
    n = ast_func(FN_SQRT, ast_number(9));
    mp_draw(n, 0, 100);
    ASSERT_TRUE(gfx_mock_text_contains("9"), "mp draw sqrt(9): radicand '9'");
    /* Should have lines for radical hook + vinculum */
    ASSERT_TRUE(gfx_mock_line_count >= 2 || gfx_mock_horiz_line_count >= 1,
                "mp draw sqrt(9): radical lines drawn");
    ast_free(n);

    printf("  -- MathPrint draw: addition --\n");
    mem_free_all();
    gfx_mock_reset();
    n = ast_binop(OP_ADD, ast_variable('x'), ast_number(1));
    mp_draw(n, 0, 100);
    ASSERT_TRUE(gfx_mock_text_contains("x"), "mp draw x+1: has 'x'");
    ASSERT_TRUE(gfx_mock_text_contains("+"), "mp draw x+1: has '+'");
    ASSERT_TRUE(gfx_mock_text_contains("1"), "mp draw x+1: has '1'");
    ast_free(n);

    printf("  -- MathPrint draw: sin(x) --\n");
    mem_free_all();
    gfx_mock_reset();
    n = ast_func(FN_SIN, ast_variable('x'));
    mp_draw(n, 0, 100);
    ASSERT_TRUE(gfx_mock_text_contains("sin"), "mp draw sin(x): has 'sin'");
    ASSERT_TRUE(gfx_mock_text_contains("x"), "mp draw sin(x): has 'x'");
    ast_free(n);
}

static void test_mathprint_complex_expressions(void)
{
    ast_node_t *n;
    mp_bbox_t b;

    printf("  -- MathPrint: nested fraction --\n");
    mem_free_all();
    gfx_mock_reset();
    /* (1/2) / 3 — fraction of fraction */
    n = ast_binop(OP_DIV,
            ast_binop(OP_DIV, ast_number(1), ast_number(2)),
            ast_number(3));
    b = mp_measure(n);
    ASSERT_TRUE(b.w > 0, "mp nested frac width > 0");
    ASSERT_TRUE(b.ascent > 10, "mp nested frac ascent > simple frac");
    mp_draw(n, 0, 120);
    ASSERT_TRUE(gfx_mock_text_contains("1"), "mp nested frac: has '1'");
    ASSERT_TRUE(gfx_mock_text_contains("2"), "mp nested frac: has '2'");
    ASSERT_TRUE(gfx_mock_text_contains("3"), "mp nested frac: has '3'");
    ASSERT_TRUE(gfx_mock_horiz_line_count >= 2, "mp nested frac: 2+ fraction bars");
    ast_free(n);

    printf("  -- MathPrint: fraction in exponent --\n");
    mem_free_all();
    gfx_mock_reset();
    /* x^(1/2) */
    n = ast_binop(OP_POW,
            ast_variable('x'),
            ast_binop(OP_DIV, ast_number(1), ast_number(2)));
    b = mp_measure(n);
    ASSERT_TRUE(b.w > 0, "mp x^(1/2) width > 0");
    ASSERT_TRUE(b.ascent > 10, "mp x^(1/2) tall");
    mp_draw(n, 0, 120);
    ASSERT_TRUE(gfx_mock_horiz_line_count >= 1, "mp x^(1/2): has fraction bar");
    ast_free(n);

    printf("  -- MathPrint: multiplication auto-parens --\n");
    mem_free_all();
    gfx_mock_reset();
    /* 2*(x+1) — should add parens around x+1 */
    n = ast_binop(OP_MUL,
            ast_number(2),
            ast_binop(OP_ADD, ast_variable('x'), ast_number(1)));
    b = mp_measure(n);
    ASSERT_TRUE(b.w > 0, "mp 2*(x+1) width > 0");
    mp_draw(n, 0, 100);
    /* The (x+1) should have parentheses rendered */
    ASSERT_TRUE(gfx_mock_text_contains("x"), "mp 2*(x+1): has 'x'");
    ast_free(n);

    printf("  -- MathPrint: derivative d/dx --\n");
    mem_free_all();
    gfx_mock_reset();
    {
        ast_node_t *deriv = mem_alloc_node();
        if (deriv) {
            deriv->type = NODE_DERIV;
            deriv->d.deriv.var = 'x';
            deriv->d.deriv.expr = ast_binop(OP_POW, ast_variable('x'), ast_number(2));
            b = mp_measure(deriv);
            ASSERT_TRUE(b.w > 0, "mp d/dx(x^2) width > 0");
            mp_draw(deriv, 0, 100);
            ASSERT_TRUE(gfx_mock_text_contains("d"), "mp deriv: has 'd'");
            ASSERT_TRUE(gfx_mock_text_contains("dx"), "mp deriv: has 'dx'");
            ASSERT_TRUE(gfx_mock_horiz_line_count >= 1, "mp deriv: fraction bar");
        }
    }

    printf("  -- MathPrint: radical/fraction/exponent combo --\n");
    mem_free_all();
    gfx_mock_reset();
    n = ast_binop(OP_DIV,
            ast_func(FN_SQRT,
                ast_binop(OP_ADD,
                    ast_binop(OP_POW, ast_variable('x'), ast_number(2)),
                    ast_number(1))),
            ast_binop(OP_POW, ast_variable('x'), ast_number(3)));
    b = mp_measure(n);
    ASSERT_TRUE(b.w > 0, "mp combo width > 0");
    ASSERT_TRUE(b.ascent > 10, "mp combo ascent > baseline");
    mp_draw(n, 0, 120);
    ASSERT_TRUE(gfx_mock_text_contains("x"), "mp combo: has variable x");
    ASSERT_TRUE(gfx_mock_text_contains("3"), "mp combo: has exponent 3");
    ASSERT_TRUE(gfx_mock_horiz_line_count >= 1, "mp combo: has fraction bar");
    ASSERT_TRUE(gfx_mock_line_count >= 2 || gfx_mock_horiz_line_count >= 2,
                "mp combo: has radical stroke/vinculum");
    ast_free(n);

    mem_free_all();
}

static void test_mathprint_cursor_nav(void)
{
    input_buf_t ib;
    bool moved;

    printf("  -- MathPrint cursor: fraction down --\n");
    input_buf_init(&ib);
    /* Type "a/b" */
    input_buf_insert(&ib, 'a');
    input_buf_insert(&ib, '/');
    input_buf_insert(&ib, 'b');
    ib.cursor = 0;  /* cursor at 'a' (numerator) */
    moved = mp_cursor_down(&ib);
    ASSERT_TRUE(moved, "mp cursor down from numerator");
    ASSERT_TRUE(ib.cursor > 1, "mp cursor moved past '/'");

    printf("  -- MathPrint cursor: fraction up --\n");
    ib.cursor = 2;  /* cursor at 'b' (denominator) */
    moved = mp_cursor_up(&ib);
    ASSERT_TRUE(moved, "mp cursor up from denominator");
    ASSERT_TRUE(ib.cursor <= 1, "mp cursor moved to numerator");

    printf("  -- MathPrint cursor: exponent up --\n");
    input_buf_init(&ib);
    input_buf_insert(&ib, 'x');
    input_buf_insert(&ib, '^');
    input_buf_insert(&ib, '2');
    ib.cursor = 0;  /* cursor at base */
    moved = mp_cursor_up(&ib);
    ASSERT_TRUE(moved, "mp cursor up to exponent");
    ASSERT_TRUE(ib.cursor == 2, "mp cursor at exponent pos");

    printf("  -- MathPrint cursor: exponent down --\n");
    ib.cursor = 2;  /* cursor in exponent */
    moved = mp_cursor_down(&ib);
    ASSERT_TRUE(moved, "mp cursor down from exponent");
    ASSERT_TRUE(ib.cursor == 1, "mp cursor at base end");

    printf("  -- MathPrint cursor: empty buffer --\n");
    input_buf_init(&ib);
    moved = mp_cursor_up(&ib);
    ASSERT_TRUE(!moved, "mp cursor up on empty = no move");
    moved = mp_cursor_down(&ib);
    ASSERT_TRUE(!moved, "mp cursor down on empty = no move");

    printf("  -- MathPrint cursor: no fraction --\n");
    input_buf_init(&ib);
    input_buf_insert(&ib, 'x');
    input_buf_insert(&ib, '+');
    input_buf_insert(&ib, 'y');
    ib.cursor = 1;
    moved = mp_cursor_up(&ib);
    ASSERT_TRUE(!moved, "mp cursor up with no fraction = no move");
    moved = mp_cursor_down(&ib);
    ASSERT_TRUE(!moved, "mp cursor down with no fraction = no move");

    printf("  -- MathPrint cursor: slash inside parens not treated as top-level fraction --\n");
    input_buf_init(&ib);
    input_buf_insert_str(&ib, "(a/b)+c");
    ib.cursor = ib.len; /* cursor at end, outside parenthesized fraction */
    moved = mp_cursor_up(&ib);
    ASSERT_TRUE(!moved, "mp cursor up ignores slash nested in parentheses");
}

