    gfx_mock_reset();
    input_buf_init(&ib);
    ok = mp_try_draw_input(&ib);
    ASSERT_TRUE(!ok, "mp input empty: returns false");

    printf("  -- MathPrint try_draw_input: incomplete expr --\n");
