        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "s(0)")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "sstep: recseq step shows s(0)");

        /* Should show individual term values */
        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "s(1)") ||
                strstr(steps_get(i), "s(2)")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "sstep: recseq shows computed terms");

