        ASSERT_TRUE(err == CE_OK, "estep: geomsum eval ok");
        /* S = 1*(1-0.5^10)/(1-0.5) = (1-1/1024)/0.5 ≈ 1.998 */
        ASSERT_EQ_FLOAT(val, 1.998047f, 0.01f, "estep: geomsum(1,0.5,10)");

        ASSERT_TRUE(steps_count() > 0, "estep: geomsum has steps");

