/* ---------- Polar/Arc Length Step Validation --------------- */
static void test_polar_step_validation(void)
{
    ast_node_t *expr;
    ce_float_t val;
    ce_error_t err;
    int i, found;
    bool symbolic_ok;

    printf("=== Polar Step Validation ===\n");

    /* ── 1. Cartesian arc length: y = x from 0 to 1 ─────── */
    {
        printf("  -- polar steps: cartesian arclen --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("x");
        ASSERT_TRUE(expr != NULL, "pstep: parse x for arclen");
        val = polar_arclen(expr, 'x', 0.0f, 1.0f, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: arclen ok");
        /* sqrt(2) ≈ 1.4142 */
        ASSERT_EQ_FLOAT(val, 1.4142f, 0.05f,
                         "pstep: arclen(x, 0, 1) = sqrt(2)");

        ASSERT_TRUE(steps_count() > 0, "pstep: arclen has steps");

        /* Should mention "Arc length" header */
        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Arc length") ||
                strstr(steps_get(i), "arc len")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: arclen step says 'Arc length'");

        /* Should show the derivative f'(x) */
        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "f'") ||
                strstr(steps_get(i), "d") ||
                strstr(steps_get(i), "dx")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: arclen step shows derivative");

        ast_free(expr);
    }

    /* ── 2. Surface area of revolution: y = x from 0 to 1 ─ */
    {
        printf("  -- polar steps: surface area --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("x");
        ASSERT_TRUE(expr != NULL, "pstep: parse x for surfarea");
        val = integrate_surfarea(expr, 'x', 0.0f, 1.0f, &symbolic_ok, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: surfarea ok");
        /* SA = 2pi * int(x*sqrt(2), 0, 1) = 2pi*sqrt(2)/2 = pi*sqrt(2) ≈ 4.443 */
        ASSERT_EQ_FLOAT(val, 4.443f, 0.1f,
                         "pstep: surfarea(x, 0, 1) ~ pi*sqrt(2)");

        ASSERT_TRUE(steps_count() > 0, "pstep: surfarea has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Surface area") ||
                strstr(steps_get(i), "surface area") ||
                strstr(steps_get(i), "SurfArea")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: surfarea step says 'Surface area'");

        ast_free(expr);
    }

    /* ── 3. Disk method volume: y = x from 0 to 1 ───────── */
    {
        printf("  -- polar steps: disk volume --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("x");
        ASSERT_TRUE(expr != NULL, "pstep: parse x for disk");
        val = integrate_disk(expr, 'x', 0.0f, 1.0f, &symbolic_ok, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: disk ok");
        /* V = pi * int(x^2, 0, 1) = pi/3 ≈ 1.047 */
        ASSERT_EQ_FLOAT(val, 1.047f, 0.05f,
                         "pstep: disk(x, 0, 1) ~ pi/3");

        ASSERT_TRUE(steps_count() > 0, "pstep: disk has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Disk") ||
                strstr(steps_get(i), "disk")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: disk step says 'Disk'");

        ast_free(expr);
    }

    /* ── 4. Shell method volume: y = x from 0 to 1 ──────── */
    {
        printf("  -- polar steps: shell volume --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("x");
        ASSERT_TRUE(expr != NULL, "pstep: parse x for shell");
        val = integrate_shell(expr, 'x', 0.0f, 1.0f, &symbolic_ok, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: shell ok");
        /* V = 2pi * int(x*x, 0, 1) = 2pi/3 ≈ 2.094 */
        ASSERT_EQ_FLOAT(val, 2.094f, 0.05f,
                         "pstep: shell(x, 0, 1) ~ 2pi/3");

        ASSERT_TRUE(steps_count() > 0, "pstep: shell has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Shell") ||
                strstr(steps_get(i), "shell")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: shell step says 'Shell'");

        ast_free(expr);
    }

    /* ── 5. Arc length (symbolic integration path): y = x^2 */
    {
        printf("  -- polar steps: arclen symbolic --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("x^2");
        ASSERT_TRUE(expr != NULL, "pstep: parse x^2 for arclen");
        val = integrate_arclength(expr, 'x', 0.0f, 1.0f, &symbolic_ok, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: arclen x^2 ok");
        /* Actual arc length of x^2 from 0 to 1 ≈ 1.4789 */
        ASSERT_EQ_FLOAT(val, 1.4789f, 0.1f,
                         "pstep: arclen(x^2, 0, 1) ~ 1.479");

        ASSERT_TRUE(steps_count() > 0, "pstep: arclen x^2 has steps");

        /* Should show integral formula */
        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Arc length") ||
                strstr(steps_get(i), "arc len") ||
                strstr(steps_get(i), "int(sqrt")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: arclen x^2 step shows formula");

        ast_free(expr);
    }

    /* 6. Parametric arc length: x=t, y=t^2 on [0,1] */
    {
        ast_node_t *xt;
        ast_node_t *yt;

        printf("  -- polar steps: parametric arclen --\n");
        mem_free_all();
        steps_clear();

        xt = parse_str("t");
        yt = parse_str("t^2");
        ASSERT_TRUE(xt != NULL && yt != NULL, "pstep: parse parametric pair");
        val = polar_arclen_param(xt, yt, 't', 0.0f, 1.0f, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: parametric arclen ok");
        ASSERT_EQ_FLOAT(val, 1.4789f, 0.1f,
                         "pstep: arclen_param(t,t^2,0,1) ~ 1.479");
        ASSERT_TRUE(steps_count() > 0, "pstep: parametric arclen has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Param arc len")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: parametric arclen has setup header");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "dx/dt") ||
                strstr(steps_get(i), "dy/dt")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: parametric arclen shows intermediate derivatives");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "S =")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: parametric arclen includes final length step");

        ast_free(xt);
        ast_free(yt);
    }

    /* 7. Polar arc length: r=1 on [0,2pi] gives circumference 2pi */
    {
        printf("  -- polar steps: polar arclen --\n");
        mem_free_all();
        steps_clear();

        expr = parse_str("1");
        ASSERT_TRUE(expr != NULL, "pstep: parse r=1");
        val = polar_arclen_polar(expr, 't', 0.0f, 2.0f * CE_PI, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: polar arclen ok");
        ASSERT_EQ_FLOAT(val, 2.0f * CE_PI, 0.05f,
                         "pstep: polar arclen r=1 over [0,2pi] = 2pi");
        ASSERT_TRUE(steps_count() > 0, "pstep: polar arclen has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Polar arc len")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: polar arclen has setup header");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "dr/dt")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: polar arclen shows derivative step");

        ast_free(expr);
    }

    /* 8. Washer volume: R=2, r=1 on [0,1] gives 3*pi */
    {
        ast_node_t *outer;
        ast_node_t *inner;

        printf("  -- polar steps: washer volume --\n");
        mem_free_all();
        steps_clear();

        outer = parse_str("2");
        inner = parse_str("1");
        ASSERT_TRUE(outer != NULL && inner != NULL, "pstep: parse washer radii");
        val = polar_washer(outer, inner, 'x', 0.0f, 1.0f, &err);
        ASSERT_TRUE(err == CE_OK, "pstep: washer volume ok");
        ASSERT_EQ_FLOAT(val, 3.0f * CE_PI, 0.05f,
                         "pstep: washer(R=2,r=1,0,1) = 3*pi");
        ASSERT_TRUE(steps_count() > 0, "pstep: washer has steps");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "Washer")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: washer includes method header");

        found = 0;
        for (i = 0; i < steps_count(); i++) {
            if (strstr(steps_get(i), "V =")) { found = 1; break; }
        }
        ASSERT_TRUE(found, "pstep: washer includes final volume step");

        ast_free(outer);
        ast_free(inner);
    }

    mem_free_all();
}

