static void test_settings_toggle(void)
{
    printf("=== Settings Toggle ===\n");

    /* Solve mode toggle */
    g_settings.solve_mode = SOLVE_FULL_AUTO;
    g_settings.solve_mode = (g_settings.solve_mode == SOLVE_FULL_AUTO)
                            ? SOLVE_STEP_BY_STEP : SOLVE_FULL_AUTO;
    ASSERT_EQ_INT(g_settings.solve_mode, SOLVE_STEP_BY_STEP,
                  "toggle: full_auto → step_by_step");
    g_settings.solve_mode = (g_settings.solve_mode == SOLVE_FULL_AUTO)
                            ? SOLVE_STEP_BY_STEP : SOLVE_FULL_AUTO;
    ASSERT_EQ_INT(g_settings.solve_mode, SOLVE_FULL_AUTO,
                  "toggle: step_by_step → full_auto");

    /* Integ method cycle */
    g_settings.integ_method = METHOD_AUTO;
    g_settings.integ_method = (integ_method_t)((g_settings.integ_method + 1) % 5);
    ASSERT_EQ_INT(g_settings.integ_method, METHOD_USUB,
                  "cycle: AUTO → USUB");
    g_settings.integ_method = (integ_method_t)((g_settings.integ_method + 1) % 5);
    ASSERT_EQ_INT(g_settings.integ_method, METHOD_PARTS,
                  "cycle: USUB → PARTS");
    g_settings.integ_method = (integ_method_t)((g_settings.integ_method + 1) % 5);
    ASSERT_EQ_INT(g_settings.integ_method, METHOD_TRIGSUB,
                  "cycle: PARTS → TRIGSUB");
    g_settings.integ_method = (integ_method_t)((g_settings.integ_method + 1) % 5);
    ASSERT_EQ_INT(g_settings.integ_method, METHOD_PARTIAL_FRAC,
                  "cycle: TRIGSUB → PARTIAL_FRAC");
    g_settings.integ_method = (integ_method_t)((g_settings.integ_method + 1) % 5);
    ASSERT_EQ_INT(g_settings.integ_method, METHOD_AUTO,
                  "cycle: PARTIAL_FRAC → AUTO");
}

