static void test_show_work_modes(void)
{
    printf("=== Show Work Modes ===\n");

    /* Mode 1: Full Auto + Show Work ON (default) — steps generated */
    g_settings.show_steps = true;
    g_settings.solve_mode = SOLVE_FULL_AUTO;
    steps_clear();
    {
        ast_node_t *root = parse_str("d/dx(x^2)");
        ASSERT_TRUE(root != NULL, "mode1: parse d/dx(x^2)");
        if (root) {
            ast_node_t *res = deriv_diff(root->d.deriv.expr, root->d.deriv.var);
            ASSERT_TRUE(res != NULL, "mode1: deriv succeeds");
            ASSERT_TRUE(steps_count() > 0, "mode1: steps recorded");
            gfx_mock_reset();
            ui_draw_steps(0);
            ASSERT_TRUE(gfx_mock_text_contains("Steps:"),
                        "mode1: full auto draws full step list");
            if (res) ast_free(res);
            ast_free(root);
        }
    }
    mem_free_all();

    /* Mode 2: Step-by-Step + Show Work ON — checkpoints work */
    g_settings.show_steps = true;
    g_settings.solve_mode = SOLVE_STEP_BY_STEP;
    steps_clear();
    steps_add("Step A");
    steps_add_checkpoint("Operation 1");
    steps_add("Step B");
    steps_add_checkpoint("Operation 2");
    steps_add("Step C");
    ASSERT_EQ_INT(steps_checkpoint_count(), 2, "mode2: 2 checkpoints");
    /* Checkpoint 0 inserted after 1 step: step index = 1 */
    ASSERT_EQ_INT(steps_get_checkpoint_step(0), 1, "mode2: ckpt 0 at step 1");
    /* Checkpoint 1 inserted after 2 steps: step index = 2 */
    ASSERT_EQ_INT(steps_get_checkpoint_step(1), 2, "mode2: ckpt 1 at step 2");
    gfx_mock_reset();
    ui_draw_steps_checkpoint(1);
    ASSERT_TRUE(gfx_mock_text_contains("Steps: (op 1/2)"),
                "mode2: checkpoint header rendered");
    ASSERT_TRUE(gfx_mock_text_contains("Step A"),
                "mode2: first checkpoint shows completed work");
    ASSERT_TRUE(gfx_mock_text_contains("Next: Operation 2"),
                "mode2: prompt names next operation");

    /* Mode 3: Full Auto + Show Work OFF — no steps displayed */
    g_settings.show_steps = false;
    g_settings.solve_mode = SOLVE_FULL_AUTO;
    ASSERT_TRUE(!g_settings.show_steps, "mode3: show_steps OFF");

    /* Mode 4: Step-by-Step + Show Work OFF — checkpoints only */
    g_settings.show_steps = false;
    g_settings.solve_mode = SOLVE_STEP_BY_STEP;
    ASSERT_TRUE(!g_settings.show_steps && g_settings.solve_mode == SOLVE_STEP_BY_STEP,
                "mode4: step-by-step + work off");
    gfx_mock_reset();
    ui_draw_checkpoint_results(1);
    ASSERT_TRUE(gfx_mock_text_contains("Checkpoints: (1/2)"),
                "mode4: checkpoint-only header rendered");
    ASSERT_TRUE(gfx_mock_text_contains("Operation 1 -> Step B"),
                "mode4: checkpoint summary shows result only");
    ASSERT_TRUE(!gfx_mock_text_contains("Step C"),
                "mode4: unrevealed checkpoint work stays hidden");
}

static void test_method_selection(void)
{
    printf("=== Method Selection ===\n");
    mem_free_all();
    steps_clear();

    /* Auto method: integrate x^2 → x^3/3 */
    g_settings.integ_method = METHOD_AUTO;
    {
        ast_node_t *expr = parse_str("x^2");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "method: parse x^2");
        if (!expr) return;
        result = integrate(expr, 'x');
        ASSERT_TRUE(result != NULL, "method: auto integrates x^2");
        if (result) ast_free(result);
        ast_free(expr);
    }
    mem_free_all();
    steps_clear();

    /* Forced u-sub: integrate 2x*sin(x^2) */
    g_settings.integ_method = METHOD_USUB;
    {
        ast_node_t *expr = parse_str("2*x*sin(x^2)");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "method: parse 2x*sin(x^2)");
        if (!expr) return;
        result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_USUB, NULL);
        ASSERT_TRUE(result != NULL, "method: u-sub works on 2x*sin(x^2)");
        if (result) ast_free(result);
        ast_free(expr);
    }
    mem_free_all();
    steps_clear();

    /* Forced by-parts: integrate x*e^x */
    g_settings.integ_method = METHOD_PARTS;
    {
        ast_node_t *expr = parse_str("x*exp(x)");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "method: parse x*exp(x)");
        if (!expr) return;
        result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_PARTS, NULL);
        ASSERT_TRUE(result != NULL, "method: by-parts works on x*e^x");
        if (result) ast_free(result);
        ast_free(expr);
    }
    mem_free_all();
    steps_clear();

    /* Forced partial fractions: integrate 1/(x*(x+1)) */
    g_settings.integ_method = METHOD_PARTIAL_FRAC;
    {
        ast_node_t *expr = parse_str("1/(x*(x+1))");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "method: parse 1/(x*(x+1))");
        if (!expr) return;
        result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_PARTIAL_FRAC, NULL);
        ASSERT_TRUE(result != NULL, "method: partial fractions works on rational form");
        if (result) ast_free(result);
        ast_free(expr);
    }
    mem_free_all();
    steps_clear();

    /* Invalid method: trig sub on x^2 — may fail gracefully */
    g_settings.integ_method = METHOD_TRIGSUB;
    {
        ast_node_t *expr = parse_str("x^2");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "method: parse x^2 for trigsub");
        if (!expr) return;
        result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_TRIGSUB, NULL);
        /* May return NULL — that's valid; engine correctly reports failure */
        ASSERT_TRUE(integrate_last_failure_reason() != NULL,
                    "method: failure reason always non-NULL");
        if (result) ast_free(result);
        ast_free(expr);
    }
    mem_free_all();
}

static void test_method_decision_report(void)
{
    printf("=== Method Decision Menu ===\n");
    mem_free_all();
    steps_clear();

    {
        ast_node_t *expr = parse_str("int(1/(x*(x+1)),x)");
        method_report_t report;
        int applicable_count = 0;
        int i;

        ASSERT_TRUE(expr != NULL, "decision: parse rational integral");
        if (!expr) return;

        solver_get_methods(expr, &report);
        ASSERT_EQ_INT((int)report.options[0].method, (int)SOLVE_METHOD_AUTO,
                      "decision: auto listed first");
        ASSERT_EQ_INT((int)report.recommended,
                      (int)SOLVE_METHOD_INTEGRATE_PARTIAL_FRAC,
                      "decision: partial fractions recommended");

        for (i = 0; i < report.count; i++) {
            if (report.options[i].applicable &&
                (report.options[i].method == SOLVE_METHOD_INTEGRATE_USUB ||
                 report.options[i].method == SOLVE_METHOD_INTEGRATE_PARTIAL_FRAC)) {
                applicable_count++;
            }
        }
        ASSERT_TRUE(applicable_count >= 1,
                    "decision: at least one forced integration method available");
        ast_free(expr);
    }
    mem_free_all();
}

