static void test_history_stack_behavior(void)
{
    printf("=== History Stack ===\n");

    history_clear();

    ASSERT_TRUE(history_push("2+3", "= 5", 5.0f, true),
                "hist_stack: push numeric result");
    ASSERT_TRUE(history_push("d/dx(x^2)", "2*x", 0.0f, false),
                "hist_stack: push symbolic result");

    {
        input_buf_t ib;
        char recall[MAX_INPUT_LEN];
        input_buf_init(&ib);
        input_buf_insert_str(&ib, "sin(x)");
        ASSERT_TRUE(strcmp(ib.buf, "sin(x)") == 0,
                    "hist_stack: current input saved");

        ASSERT_EQ_INT(history_navigate_back(), 0, "hist_stack: up -> most recent");
        ASSERT_TRUE(history_get_reentry_text(0, recall, sizeof(recall)),
                    "hist_stack: symbolic reentry available");
        input_buf_clear(&ib);
        input_buf_insert_str(&ib, recall);
        ASSERT_TRUE(strcmp(ib.buf, "2*x") == 0,
                    "hist_stack: recalls stored result, not original input");

        ASSERT_EQ_INT(history_navigate_back(), 1, "hist_stack: up -> older result");
        ASSERT_TRUE(history_get_reentry_text(1, recall, sizeof(recall)),
                    "hist_stack: numeric reentry available");
        input_buf_clear(&ib);
        input_buf_insert_str(&ib, recall);
        ASSERT_TRUE(strcmp(ib.buf, "5") == 0,
                    "hist_stack: strips leading equals for re-entry");

        ASSERT_EQ_INT(history_navigate_forward(), 0, "hist_stack: down -> newer result");
        ASSERT_TRUE(history_get_reentry_text(0, recall, sizeof(recall)),
                    "hist_stack: newer result recall");
        input_buf_clear(&ib);
        input_buf_insert_str(&ib, recall);
        ASSERT_TRUE(strcmp(ib.buf, "2*x") == 0,
                    "hist_stack: forward returns to newer result");

        ASSERT_EQ_INT(history_navigate_forward(), -1, "hist_stack: down -> input line");
        input_buf_clear(&ib);
        input_buf_insert_str(&ib, "sin(x)");
        ASSERT_TRUE(strcmp(ib.buf, "sin(x)") == 0,
                    "hist_stack: caller can restore saved input");
    }

    history_navigate_reset();
    history_clear();
}

