static void test_checkpoint_navigation_sim(void)
{
    printf("=== Checkpoint Navigation Simulation ===\n");
    steps_clear();

    /* Simulate a multi-operation solve: expand → factor → simplify */
    steps_add("Rewrite expression");
    steps_add_checkpoint("Expand");
    steps_add("Distribute (a+b)^2");
    steps_add("= a^2 + 2ab + b^2");
    steps_add_checkpoint("Factor");
    steps_add("Find roots");
    steps_add("Root: x = 1");
    steps_add("Root: x = -1");
    steps_add_checkpoint("Simplify");
    steps_add("Combine like terms");
    steps_add("Final form");

    ASSERT_EQ_INT(steps_count(), 8, "nav: 8 steps total");
    ASSERT_EQ_INT(steps_checkpoint_count(), 3, "nav: 3 checkpoints");

    /* Simulate checkpoint-based reveal:
     * ckpt_reveal=0: show steps 0..0 (up to ckpt 0's step index)
     * ckpt_reveal=1: show steps 0..2 (up to ckpt 1's step index)
     * ckpt_reveal=2: show steps 0..5 (up to ckpt 2's step index)
     * ckpt_reveal=3: show all steps 0..7 */
    {
        int show0 = steps_get_checkpoint_step(0);
        int show1 = steps_get_checkpoint_step(1);
        int show2 = steps_get_checkpoint_step(2);
        ASSERT_EQ_INT(show0, 1, "nav: ckpt 0 gates at step 1");
        ASSERT_EQ_INT(show1, 3, "nav: ckpt 1 gates at step 3");
        ASSERT_EQ_INT(show2, 6, "nav: ckpt 2 gates at step 6");
    }

    /* Verify checkpoint descriptions */
    ASSERT_TRUE(strcmp(steps_get_checkpoint(0), "Expand") == 0, "nav: ckpt 0 = Expand");
    ASSERT_TRUE(strcmp(steps_get_checkpoint(1), "Factor") == 0, "nav: ckpt 1 = Factor");
    ASSERT_TRUE(strcmp(steps_get_checkpoint(2), "Simplify") == 0, "nav: ckpt 2 = Simplify");
}

