static void test_integ_method_with_strategy(void)
{
    printf("=== Integration Method Strategy API ===\n");
    mem_free_all();
    steps_clear();

    /* Strategy report should produce non-empty output */
    {
        ast_node_t *expr = parse_str("x*sin(x)");
        char report[256];
        ASSERT_TRUE(expr != NULL, "strat: parse x*sin(x)");
        if (expr) {
            integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
            ASSERT_TRUE(strlen(report) > 0, "strat: report non-empty");
            ast_free(expr);
        }
    }
    mem_free_all();
    steps_clear();

    /* Auto strategy on a simple polynomial */
    {
        ast_node_t *expr = parse_str("3*x^2+2*x+1");
        ast_node_t *result;
        ASSERT_TRUE(expr != NULL, "strat: parse 3x^2+2x+1");
        if (expr) {
            result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_AUTO, NULL);
            ASSERT_TRUE(result != NULL, "strat: auto on polynomial works");
            if (result) ast_free(result);
            ast_free(expr);
        }
    }
    mem_free_all();
}

