static void test_solver_null_expr(void)
{
    printf("=== Solver Null Expression ===\n");

    {
        solve_result_t result;
        solver_solve_full(NULL, &result);
        ASSERT_TRUE(result.complete, "null_expr: complete");
        ASSERT_EQ_INT((int)result.error, (int)CE_ERR_SYNTAX,
                      "null_expr: error=CE_ERR_SYNTAX");
    }

    /* Solver init should zero-fill result */
    {
        solve_result_t result;
        memset(&result, 0xFF, sizeof(result));
        solver_init(&result);
        ASSERT_EQ_INT(result.step_count, 0, "null_expr: init zero steps");
        ASSERT_EQ_INT(result.current_step, 0, "null_expr: init zero current");
        ASSERT_TRUE(!result.complete, "null_expr: init not complete");
    }

    /* Solver method name for valid methods */
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_AUTO), "Auto",
                        "null_expr: method_name(AUTO)");
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_DIRECT_EVAL), "Direct",
                        "null_expr: method_name(DIRECT_EVAL)");

    /* Solver method applicable with NULL */
    ASSERT_TRUE(!solver_method_applicable(NULL, SOLVE_METHOD_DIFFERENTIATE),
                "null_expr: method_applicable(NULL) = false");
    ASSERT_TRUE(!solver_method_applicable(NULL, SOLVE_METHOD_INTEGRATE_AUTO),
                "null_expr: integral method NULL = false");
}

