static void test_history_edge_cases_extended(void)
{
    printf("=== History Edge Cases Extended ===\n");

    history_clear();

    ASSERT_TRUE(history_push("alpha", "\n\t= \t42 \r\n", 42.0f, true),
                "history_edge: push whitespace result");
    ASSERT_TRUE(history_push("beta+1", "=\t \n", 0.0f, false),
                "history_edge: push blank prefixed result");

    {
        char buf[32];
        char tiny[2];

        ASSERT_TRUE(history_get_reentry_text(1, buf, sizeof(buf)),
                    "history_edge: whitespace result copied");
        ASSERT_TRUE(strcmp(buf, "42") == 0,
                    "history_edge: trims newlines tabs and prefix");

        ASSERT_TRUE(history_get_reentry_text(0, buf, sizeof(buf)),
                    "history_edge: blank result falls back");
        ASSERT_TRUE(strcmp(buf, "beta+1") == 0,
                    "history_edge: blank prefixed result uses input");

        ASSERT_TRUE(history_get_reentry_text(1, tiny, sizeof(tiny)),
                    "history_edge: tiny buffer still succeeds");
        ASSERT_TRUE(strcmp(tiny, "4") == 0,
                    "history_edge: tiny buffer truncates safely");

        ASSERT_TRUE(!history_get_reentry_text(0, NULL, sizeof(buf)),
                    "history_edge: NULL out rejected");
        ASSERT_TRUE(!history_get_reentry_text(0, buf, 0),
                    "history_edge: zero-size buffer rejected");
    }

    ASSERT_EQ_INT(history_navigate_back(), 0, "history_edge: nav back to newest");
    ASSERT_EQ_INT(history_navigate_position(), 0, "history_edge: nav position updated");
    ASSERT_TRUE(history_push("gamma", "= 7", 7.0f, true),
                "history_edge: push while navigating");
    ASSERT_EQ_INT(history_navigate_position(), -1,
                  "history_edge: push resets navigation state");

    history_clear();
}

static void test_history_truncation_and_metadata(void)
{
    char long_input[HISTORY_EXPR_LEN + 32];
    char long_result[HISTORY_RESULT_LEN + 32];
    int i;

    printf("=== History Truncation And Metadata ===\n");

    for (i = 0; i < (int)sizeof(long_input) - 1; i++) {
        long_input[i] = (char)('a' + (i % 26));
    }
    long_input[sizeof(long_input) - 1] = '\0';

    for (i = 0; i < (int)sizeof(long_result) - 1; i++) {
        long_result[i] = (char)('A' + (i % 26));
    }
    long_result[sizeof(long_result) - 1] = '\0';

    history_clear();
    ASSERT_TRUE(history_push(long_input, long_result, 0.0f, false),
                "history_trunc: push long entry");
    ASSERT_EQ_INT(history_count(), 1, "history_trunc: count=1");

    {
        const history_entry_t *entry = history_get(0);
        ASSERT_TRUE(entry != NULL, "history_trunc: entry exists");
        if (entry) {
            ASSERT_EQ_INT((int)strlen(entry->input), HISTORY_EXPR_LEN - 1,
                          "history_trunc: input truncated to max-1");
            ASSERT_EQ_INT((int)strlen(entry->result), HISTORY_RESULT_LEN - 1,
                          "history_trunc: result truncated to max-1");
            ASSERT_EQ_INT((int)entry->input[HISTORY_EXPR_LEN - 1], '\0',
                          "history_trunc: input is null terminated");
            ASSERT_EQ_INT((int)entry->result[HISTORY_RESULT_LEN - 1], '\0',
                          "history_trunc: result is null terminated");
            ASSERT_TRUE(!entry->has_numeric, "history_trunc: has_numeric preserved");
            ASSERT_TRUE(entry->in_use, "history_trunc: entry marked in use");
            ASSERT_EQ_INT((int)entry->input[0], (int)long_input[0],
                          "history_trunc: input prefix preserved");
            ASSERT_EQ_INT((int)entry->result[0], (int)long_result[0],
                          "history_trunc: result prefix preserved");
        }
    }

    history_clear();
}

static void test_calc2_step_order_hardening(void)
{
    ce_error_t err;
    ce_float_t val;

    printf("=== Calc2 Step Order Hardening ===\n");
    g_settings.show_steps = true;

    {
        ast_node_t *rhs;
        char sol[256];
        static const char *const expected_steps[] = {
            "ODE separable:",
            "Separate:",
            "Integrate both sides",
            "Solution:"
        };

        mem_free_all();
        steps_clear();
        rhs = parse_str("x*y");

        ASSERT_TRUE(rhs != NULL, "step-order: parse separable ODE rhs");
        if (rhs) {
            ASSERT_TRUE(ode_solve_separable(rhs, 'x', 'y', sol, sizeof(sol)),
                        "step-order: solve separable ODE");
            ASSERT_STR_CONTAINS(sol, "=", "step-order: separable ODE result has equation");
            ASSERT_STR_CONTAINS(sol, "+ C", "step-order: separable ODE includes constant");
            ASSERT_TRUE(steps_count() > 0, "step-order: separable ODE records steps");
            ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                        "step-order: separable ODE steps stay ordered");
            ast_free(rhs);
        }
        mem_free_all();
    }

    {
        ast_node_t *rhs;
        char sol[256];
        static const char *const expected_steps[] = {
            "ODE linear:",
            "P(x) =",
            "Q(x) =",
            "Integrating factor",
            "Solution:"
        };

        mem_free_all();
        steps_clear();
        rhs = parse_str("x-y");

        ASSERT_TRUE(rhs != NULL, "step-order: parse linear ODE rhs");
        if (rhs) {
            ASSERT_TRUE(ode_solve_linear(rhs, 'x', 'y', sol, sizeof(sol)),
                        "step-order: solve linear ODE");
            ASSERT_STR_CONTAINS(sol, "y =", "step-order: linear ODE solves for y");
            ASSERT_STR_CONTAINS(sol, "exp", "step-order: linear ODE uses integrating factor");
            ASSERT_TRUE(steps_count() > 0, "step-order: linear ODE records steps");
            ASSERT_TRUE(steps_contain_in_order(expected_steps, 5),
                        "step-order: linear ODE steps stay ordered");
            ast_free(rhs);
        }
        mem_free_all();
    }

    {
        static const char *const expected_steps[] = {
            "Euler method:",
            "n=0:",
            "n=1:",
            "n=2:",
            "Euler result:"
        };

        mem_free_all();
        steps_clear();

        val = eval_str("euler(x+y,x,y,0,1,0.3,0.1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: Euler eval ok");
        ASSERT_EQ_FLOAT(val, 1.362f, 0.001f, "step-order: Euler y(0.3) matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: Euler records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 5),
                    "step-order: Euler steps stay ordered");
    }

    {
        ast_node_t *root;
        eval_ctx_t ctx;
        static const char *const expected_steps[] = {
            "Partial derivative w.r.t. x",
            "Then partial w.r.t. y",
            "Result:"
        };

        mem_free_all();
        steps_clear();
        root = parse_str("pdiff(x^2*y^3,x,y)");

        ASSERT_TRUE(root != NULL, "step-order: parse mixed partial");
        if (root) {
            eval_init(&ctx);
            ASSERT_TRUE(eval_set_var(&ctx, 'x', 2.0f), "step-order: bind x for mixed partial");
            ASSERT_TRUE(eval_set_var(&ctx, 'y', 3.0f), "step-order: bind y for mixed partial");
            val = eval_expr(&ctx, root);
            ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "step-order: mixed partial eval ok");
            ASSERT_EQ_FLOAT(val, 108.0f, 0.01f, "step-order: mixed partial matches expected");
            ASSERT_TRUE(steps_count() > 0, "step-order: mixed partial records steps");
            ASSERT_TRUE(steps_contain_in_order(expected_steps, 3),
                        "step-order: mixed partial steps stay ordered");
            ast_free(root);
        }
        mem_free_all();
    }

    {
        ast_node_t *root;
        eval_ctx_t ctx;
        static const char *const expected_steps[] = {
            "Gradient:",
            "d/dx =",
            "d/dy =",
            "= ("
        };

        mem_free_all();
        steps_clear();
        root = parse_str("gradient(x^2+y^2,x,y)");

        ASSERT_TRUE(root != NULL, "step-order: parse gradient");
        if (root) {
            eval_init(&ctx);
            ASSERT_TRUE(eval_set_var(&ctx, 'x', 3.0f), "step-order: bind x for gradient");
            ASSERT_TRUE(eval_set_var(&ctx, 'y', 4.0f), "step-order: bind y for gradient");
            val = eval_expr(&ctx, root);
            ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "step-order: gradient eval ok");
            ASSERT_EQ_FLOAT(val, 10.0f, 0.01f, "step-order: gradient magnitude matches expected");
            ASSERT_TRUE(steps_count() > 0, "step-order: gradient records steps");
            ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                        "step-order: gradient steps stay ordered");
            ast_free(root);
        }
        mem_free_all();
    }

    {
        static const char *const expected_steps[] = {
            "Double integral over",
            "Using 20x20 Simpson's rule",
            "Result ="
        };

        mem_free_all();
        steps_clear();

        val = eval_str("dblint(x+y,x,0,1,y,0,1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: dblint eval ok");
        ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "step-order: dblint matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: dblint records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 3),
                    "step-order: dblint steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Finding critical points",
            "f'(x) =",
            "local maximum",
            "local minimum"
        };

        mem_free_all();
        steps_clear();

        val = eval_str("critical(x^3-3*x,x)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: critical eval ok");
        ASSERT_EQ_FLOAT(val, 2.0f, 0.01f, "step-order: critical finds two points");
        ASSERT_TRUE(steps_count() > 0, "step-order: critical records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: critical steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Newton's method:",
            "x_{n+1}",
            "Iter 1:",
            "Converged: root"
        };

        mem_free_all();
        steps_clear();

        val = eval_str("newton(x^2-4,x,3)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: Newton eval ok");
        ASSERT_EQ_FLOAT(val, 2.0f, 0.001f, "step-order: Newton root matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: Newton records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: Newton steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Bisection:",
            "f(a)=",
            "Iter 1:",
            "Converged: root"
        };

        mem_free_all();
        steps_clear();

        val = eval_str("bisect(x^2-4,x,0,3)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: bisection eval ok");
        ASSERT_EQ_FLOAT(val, 2.0f, 0.001f, "step-order: bisection root matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: bisection records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: bisection steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Secant method:",
            "x_{n+1}",
            "Iter 1:",
            "Converged: root"
        };

        mem_free_all();
        steps_clear();

        val = eval_str("secant(x^2-4,x,1,3)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: secant eval ok");
        ASSERT_EQ_FLOAT(val, 2.0f, 0.001f, "step-order: secant root matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: secant records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: secant steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Quotient:",
            "Remainder:"
        };

        mem_free_all();
        steps_clear();

        val = eval_str_at("polydiv(x^3-6*x^2+11*x-6,x-1,x)", 'x', 4.0f, &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: polydiv eval ok");
        ASSERT_EQ_FLOAT(val, 2.0f, 0.01f, "step-order: polydiv quotient evaluates correctly");
        ASSERT_TRUE(steps_count() > 0, "step-order: polydiv records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 2),
                    "step-order: polydiv steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Product n=1 to 5",
            "n=1:",
            "n=5:",
            "Product ="
        };

        mem_free_all();
        steps_clear();

        val = eval_str("prod(n,n,1,5)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: product eval ok");
        ASSERT_EQ_FLOAT(val, 120.0f, 0.01f, "step-order: product matches expected");
        ASSERT_TRUE(steps_count() > 0, "step-order: product records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: product steps stay ordered");
    }

    {
        static const char *const expected_steps[] = {
            "Slope field for y' = f(x,y)",
            "slope",
            "Slope field samples:",
            "Average |slope| ="
        };

        mem_free_all();
        steps_clear();

        val = eval_str("slopefield(x-y,x,y,-1,1,-1,1)", &err);
        ASSERT_EQ_INT(err, CE_OK, "step-order: slopefield eval ok");
        ASSERT_TRUE(val > 0.0f, "step-order: slopefield mean abs slope positive");
        ASSERT_TRUE(steps_count() > 0, "step-order: slopefield records steps");
        ASSERT_TRUE(steps_contain_in_order(expected_steps, 4),
                    "step-order: slopefield steps stay ordered");
    }
}

static void test_symbolic_input_macro_sequence_hardening(void)
{
    char out[256];
    char err_msg[128];
    ce_error_t err;
    ce_float_t val;

    printf("=== Symbolic Input, Macro, and Sequence Hardening ===\n");
    g_settings.show_steps = true;

    {
        ast_node_t *expr;
        ce_float_t terms[8];
        static const char *const expected_steps[] = {
            "Recursive seq:",
            "s(0) = 2",
            "s(1) = -2",
            "s(4) = 2",
            "Computed 5 terms"
        };
        int n;

        mem_free_all();
        steps_clear();
        expr = parse_str("-x");

        ASSERT_TRUE(expr != NULL, "sym-hard: parse alternating recseq expr");
        if (expr) {
            n = series_recseq(expr, 'x', 2.0f, 4, terms, 8);
            ASSERT_EQ_INT(n, 5, "sym-hard: alternating recseq term count");
            ASSERT_EQ_FLOAT(terms[0], 2.0f, 0.0001f, "sym-hard: recseq term 0");
            ASSERT_EQ_FLOAT(terms[1], -2.0f, 0.0001f, "sym-hard: recseq term 1");
            ASSERT_EQ_FLOAT(terms[2], 2.0f, 0.0001f, "sym-hard: recseq term 2");
            ASSERT_EQ_FLOAT(terms[3], -2.0f, 0.0001f, "sym-hard: recseq term 3");
            ASSERT_EQ_FLOAT(terms[4], 2.0f, 0.0001f, "sym-hard: recseq term 4");
            ASSERT_TRUE(steps_count() > 0, "sym-hard: alternating recseq records steps");
            ASSERT_TRUE(steps_contain_in_order(expected_steps, 5),
                        "sym-hard: alternating recseq steps stay ordered");
            ast_free(expr);
        }
        mem_free_all();
    }

    {
        ast_node_t *expr;
        ce_float_t terms[30];
        int n;

        mem_free_all();
        steps_clear();
        expr = parse_str("0.5*x+1");

        ASSERT_TRUE(expr != NULL, "sym-hard: parse affine recseq expr");
        if (expr) {
            n = series_recseq(expr, 'x', 0.0f, 25, terms, 30);
            ASSERT_EQ_INT(n, 26, "sym-hard: affine recseq term count");
            ASSERT_EQ_FLOAT(terms[1], 1.0f, 0.0001f, "sym-hard: affine recseq term 1");
            ASSERT_EQ_FLOAT(terms[2], 1.5f, 0.0001f, "sym-hard: affine recseq term 2");
            ASSERT_EQ_FLOAT(terms[3], 1.75f, 0.0001f, "sym-hard: affine recseq term 3");
            ASSERT_TRUE(step_index_containing_from("Sequence converges to", 0) >= 0,
                        "sym-hard: affine recseq reports convergence");
            ASSERT_TRUE(step_index_containing_from("Computed 26 terms", 0) >= 0,
                        "sym-hard: affine recseq reports total terms");
            ast_free(expr);
        }
        mem_free_all();
    }

    {
        ast_node_t *root;
        ast_node_t *result = NULL;
        eval_ctx_t ctx;

        mem_free_all();
        steps_clear();
        root = parse_str("d/dx x^3");

        ASSERT_TRUE(root != NULL, "sym-hard: parse natural derivative shorthand");
        if (root) {
            result = deriv_diff(root->d.deriv.expr, root->d.deriv.var);
            ASSERT_TRUE(result != NULL, "sym-hard: derive natural derivative shorthand");
            if (result) {
                eval_init(&ctx);
                ASSERT_TRUE(eval_set_var(&ctx, 'x', 2.0f), "sym-hard: bind x for shorthand derivative");
                val = eval_expr(&ctx, result);
                ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "sym-hard: shorthand derivative eval ok");
                ASSERT_EQ_FLOAT(val, 12.0f, 0.01f, "sym-hard: shorthand derivative matches expected");
                ASSERT_TRUE(steps_count() > 0, "sym-hard: shorthand derivative records steps");
                ASSERT_TRUE(step_index_containing_from("Power rule on", 0) >= 0,
                            "sym-hard: shorthand derivative uses power rule");
                ast_free(result);
            }
            ast_free(root);
        }
        mem_free_all();
    }

    {
        ast_node_t *root;
        ast_node_t *result = NULL;
        eval_ctx_t ctx;

        mem_free_all();
        steps_clear();
        root = parse_str("int(x^2)dx");

        ASSERT_TRUE(root != NULL, "sym-hard: parse natural integral shorthand");
        if (root) {
            result = integrate(root->d.integral.expr, root->d.integral.var);
            ASSERT_TRUE(result != NULL, "sym-hard: integrate natural shorthand");
            if (result) {
                eval_init(&ctx);
                ASSERT_TRUE(eval_set_var(&ctx, 'x', 3.0f), "sym-hard: bind x for shorthand integral");
                val = eval_expr(&ctx, result);
                ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "sym-hard: shorthand integral eval ok");
                ASSERT_EQ_FLOAT(val, 9.0f, 0.01f, "sym-hard: shorthand integral matches expected");
                ASSERT_TRUE(steps_count() > 0, "sym-hard: shorthand integral records steps");
                ASSERT_TRUE(step_index_containing_from("Power rule: int(x^n)", 0) >= 0,
                            "sym-hard: shorthand integral uses power rule");
                ast_free(result);
            }
            ast_free(root);
        }
        mem_free_all();
    }

    macros_init();
    ASSERT_EQ_INT(macros_try_command("macro(inc(x),x+1)",
                                     out, sizeof(out), err_msg, sizeof(err_msg)),
                  MACRO_CMD_OK, "sym-hard: define increment macro");
    ASSERT_EQ_INT(macros_try_command("macro(square(t),(inc(t))*(inc(t)))",
                                     out, sizeof(out), err_msg, sizeof(err_msg)),
                  MACRO_CMD_OK, "sym-hard: define nested square macro");
    ASSERT_TRUE(macros_expand("square(2)", out, sizeof(out), err_msg, sizeof(err_msg)),
                "sym-hard: expand nested macro");
    ASSERT_STR_CONTAINS(out, "(2)", "sym-hard: nested macro preserves substituted argument");
    ASSERT_STR_CONTAINS(out, "+1", "sym-hard: nested macro expands inner body");
    err = CE_OK;
    ASSERT_EQ_FLOAT(eval_str("square(2)", &err), 9.0f, 0.01f,
                    "sym-hard: nested macro evaluates correctly");
    ASSERT_EQ_INT(err, CE_OK, "sym-hard: nested macro eval ok");

    macros_init();
    ASSERT_EQ_INT(macros_try_command("macro(a(x),b(x))",
                                     out, sizeof(out), err_msg, sizeof(err_msg)),
                  MACRO_CMD_OK, "sym-hard: define first mutually recursive macro");
    ASSERT_EQ_INT(macros_try_command("macro(b(x),a(x))",
                                     out, sizeof(out), err_msg, sizeof(err_msg)),
                  MACRO_CMD_OK, "sym-hard: define second mutually recursive macro");
    ASSERT_TRUE(!macros_expand("a(1)", out, sizeof(out), err_msg, sizeof(err_msg)),
                "sym-hard: mutual recursion expansion blocked");
    ASSERT_STR_CONTAINS(err_msg, "too deep",
                        "sym-hard: mutual recursion reports depth guard");
}

static void test_slopefield_and_comparison(void) {
    graph_viewport_t vp;
    ast_node_t *e;
    conv_info_t ci;
    vp.x_min = -3; vp.x_max = 3; vp.y_min = -3; vp.y_max = 3;
    mem_free_all();
    e = parse_str("x+y");
    ASSERT_TRUE(e != NULL, "sf: parse x+y");
    graph_draw_slopefield(&vp, e, 'x', 'y', 11, 11, COL_BLUE);
    ast_free(e); mem_free_all(); steps_clear();
    e = parse_str("1/n^2");
    ci = series_converge(e, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "cmp: 1/n^2 conv");
    ast_free(e); mem_free_all(); steps_clear();

    /* Slopefield with zero grid should not crash (after div-by-zero fix) */
    mem_free_all();
    e = parse_str("x*y");
    ASSERT_TRUE(e != NULL, "sf: parse x*y");
    graph_draw_slopefield(&vp, e, 'x', 'y', 0, 0, COL_BLUE);
    ast_free(e); mem_free_all(); steps_clear();

    /* Slopefield with 1x1 grid */
    e = parse_str("x+1");
    ASSERT_TRUE(e != NULL, "sf: parse x+1");
    graph_draw_slopefield(&vp, e, 'x', 'y', 1, 1, COL_RED);
    ast_free(e); mem_free_all(); steps_clear();

    /* Series comparison test: harmonic diverges */
    e = parse_str("1/n");
    ci = series_converge(e, 'n');
    ASSERT_EQ_INT(ci.result, CONV_DIVERGES, "cmp: 1/n diverges");
    ast_free(e); mem_free_all(); steps_clear();

    /* Series: geometric converges */
    e = parse_str("(1/2)^n");
    ci = series_converge(e, 'n');
    ASSERT_EQ_INT(ci.result, CONV_CONVERGES, "cmp: (1/2)^n converges");
    ast_free(e); mem_free_all(); steps_clear();

    /* Series: alternating 1/n converges conditionally */
    e = parse_str("(-1)^n/n");
    ci = series_converge(e, 'n');
    ASSERT_TRUE(ci.result == CONV_CONVERGES || ci.result == CONV_INCONCLUSIVE,
                "cmp: alt 1/n converges or inconclusive");
    ast_free(e); mem_free_all(); steps_clear();

    /* Slopefield with larger grid */
    e = parse_str("sin(x)*cos(y)");
    ASSERT_TRUE(e != NULL, "sf: parse sin(x)*cos(y)");
    graph_draw_slopefield(&vp, e, 'x', 'y', 5, 5, COL_BLUE);
    ast_free(e); mem_free_all(); steps_clear();
}
