static void test_ipc_state_defaults(void)
{
    ce_shared_state_t state;

    printf("=== IPC State Defaults ===\n");

    memset(&state, 0xFF, sizeof(state));
    ce_state_defaults(&state);

    ASSERT_EQ_INT(state.magic, CE_IPC_MAGIC, "ipc-defaults: magic");
    ASSERT_EQ_INT(state.version, CE_IPC_VERSION, "ipc-defaults: version");
    ASSERT_EQ_INT(state.settings.angle_mode, ANGLE_RADIANS, "ipc-defaults: radians");
    ASSERT_TRUE(state.settings.show_steps, "ipc-defaults: show_steps true");
    ASSERT_EQ_INT(state.settings.precision, 6, "ipc-defaults: precision 6");
    ASSERT_EQ_INT(state.settings.complex_mode, COMPLEX_OFF, "ipc-defaults: complex off");
    ASSERT_TRUE(!state.settings.pmt_at_begin, "ipc-defaults: pmt end");
    ASSERT_EQ_INT(state.settings.step_detail, STEP_ALL, "ipc-defaults: step_detail all");
    ASSERT_EQ_FLOAT(state.last_answer, 0.0f, 1e-9f, "ipc-defaults: last_answer 0");
    ASSERT_EQ_INT(state.has_pending_response, 0, "ipc-defaults: no pending response");
    ASSERT_EQ_INT(state.hist_count, 0, "ipc-defaults: hist_count 0");
    ASSERT_EQ_INT(state.hist_write, 0, "ipc-defaults: hist_write 0");

    /* null pointer guard */
    ce_state_defaults(NULL); /* should not crash */
}

static void test_ipc_state_save_load(void)
{
    ce_shared_state_t original, loaded;

    printf("=== IPC State Save/Load ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    /* Set up a state with known values */
    ce_state_defaults(&original);
    original.settings.angle_mode = ANGLE_DEGREES;
    original.settings.precision = 4;
    original.last_answer = 42.5f;
    original.has_pending_response = 1;
    strncpy(original.pending_module, "CEALG", 8);
    strncpy(original.last_expression, "x^2+1", MAX_INPUT_LEN - 1);
    original.hist_count = 3;
    original.hist_write = 3;
    strncpy(original.history[0], "2+3", MAX_INPUT_LEN - 1);
    strncpy(original.history[1], "d/dx(x^2)", MAX_INPUT_LEN - 1);
    strncpy(original.history[2], "int(x,x)", MAX_INPUT_LEN - 1);

    ASSERT_TRUE(ce_state_save(&original), "ipc-state: save succeeds");

    /* Load it back */
    memset(&loaded, 0, sizeof(loaded));
    ASSERT_TRUE(ce_state_load(&loaded), "ipc-state: load succeeds");
    ASSERT_EQ_INT(loaded.magic, CE_IPC_MAGIC, "ipc-state: loaded magic");
    ASSERT_EQ_INT(loaded.version, CE_IPC_VERSION, "ipc-state: loaded version");
    ASSERT_EQ_INT(loaded.settings.angle_mode, ANGLE_DEGREES, "ipc-state: loaded angle degrees");
    ASSERT_EQ_INT(loaded.settings.precision, 4, "ipc-state: loaded precision");
    ASSERT_EQ_FLOAT(loaded.last_answer, 42.5f, 1e-6f, "ipc-state: loaded last_answer");
    ASSERT_EQ_INT(loaded.has_pending_response, 1, "ipc-state: loaded has_pending");
    ASSERT_TRUE(strcmp(loaded.pending_module, "CEALG") == 0, "ipc-state: loaded pending module");
    ASSERT_TRUE(strcmp(loaded.last_expression, "x^2+1") == 0, "ipc-state: loaded last_expression");
    ASSERT_EQ_INT(loaded.hist_count, 3, "ipc-state: loaded hist_count");
    ASSERT_EQ_INT(loaded.hist_write, 3, "ipc-state: loaded hist_write");
    ASSERT_TRUE(strcmp(loaded.history[0], "2+3") == 0, "ipc-state: loaded history[0]");
    ASSERT_TRUE(strcmp(loaded.history[1], "d/dx(x^2)") == 0, "ipc-state: loaded history[1]");
    ASSERT_TRUE(strcmp(loaded.history[2], "int(x,x)") == 0, "ipc-state: loaded history[2]");

    /* Load with invalid magic => fallback to defaults */
    fileioc_mock_reset();
    original.magic = 0x0000;
    ce_state_save(&original);
    memset(&loaded, 0xFF, sizeof(loaded));
    ASSERT_TRUE(!ce_state_load(&loaded), "ipc-state: bad magic => load returns false");
    ASSERT_EQ_INT(loaded.magic, CE_IPC_MAGIC, "ipc-state: bad magic => defaults applied");
    ASSERT_EQ_INT(loaded.settings.angle_mode, ANGLE_RADIANS, "ipc-state: bad magic => angle radians");

    /* Load with invalid version => fallback to defaults */
    fileioc_mock_reset();
    ce_state_defaults(&original);
    original.version = 99;
    ce_state_save(&original);
    ASSERT_TRUE(!ce_state_load(&loaded), "ipc-state: bad version => load returns false");
    ASSERT_EQ_INT(loaded.version, CE_IPC_VERSION, "ipc-state: bad version => defaults version");

    /* Load with no saved data => fallback to defaults */
    fileioc_mock_reset();
    memset(&loaded, 0xFF, sizeof(loaded));
    ASSERT_TRUE(!ce_state_load(&loaded), "ipc-state: no data => load returns false");
    ASSERT_EQ_INT(loaded.magic, CE_IPC_MAGIC, "ipc-state: no data => defaults magic");

    /* Null pointer guards */
    ASSERT_TRUE(!ce_state_load(NULL), "ipc-state: load null returns false");

    /* hist_count/hist_write clamping */
    fileioc_mock_reset();
    ce_state_defaults(&original);
    original.hist_count = 200;  /* > CE_HISTORY_SIZE */
    original.hist_write = 200;
    ce_state_save(&original);
    ASSERT_TRUE(ce_state_load(&loaded), "ipc-state: oversized hist => load ok");
    ASSERT_EQ_INT(loaded.hist_count, 0, "ipc-state: oversized hist_count clamped to 0");
    ASSERT_EQ_INT(loaded.hist_write, 0, "ipc-state: oversized hist_write clamped to 0");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_request_roundtrip(void)
{
    ce_request_t req, loaded;

    printf("=== IPC Request Round-Trip ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    req.domain = CE_DOMAIN_CALC;
    req.flags = CE_REQ_FLAG_HAD_EQUALS;
    req.ast_size = 0;
    req.settings.angle_mode = ANGLE_DEGREES;
    req.settings.precision = 8;
    req.last_answer = 3.14f;
    strncpy(req.caller, "CALCENG", 8);
    strncpy(req.return_to, "CEALG", 8);
    strncpy(req.expression, "d/dx(x^3)", MAX_INPUT_LEN - 1);

    ASSERT_TRUE(ce_request_write(&req), "ipc-req: write succeeds");

    memset(&loaded, 0, sizeof(loaded));
    ASSERT_TRUE(ce_request_read(&loaded), "ipc-req: read succeeds");
    ASSERT_EQ_INT(loaded.magic, CE_IPC_MAGIC, "ipc-req: loaded magic");
    ASSERT_EQ_INT(loaded.version, CE_IPC_VERSION, "ipc-req: loaded version");
    ASSERT_EQ_INT(loaded.domain, CE_DOMAIN_CALC, "ipc-req: loaded domain");
    ASSERT_EQ_INT(loaded.flags, CE_REQ_FLAG_HAD_EQUALS, "ipc-req: loaded flags");
    ASSERT_EQ_INT(loaded.settings.angle_mode, ANGLE_DEGREES, "ipc-req: loaded angle mode");
    ASSERT_EQ_INT(loaded.settings.precision, 8, "ipc-req: loaded precision");
    ASSERT_EQ_FLOAT(loaded.last_answer, 3.14f, 1e-6f, "ipc-req: loaded last_answer");
    ASSERT_TRUE(strcmp(loaded.caller, "CALCENG") == 0, "ipc-req: loaded caller");
    ASSERT_TRUE(strcmp(loaded.return_to, "CEALG") == 0, "ipc-req: loaded return_to");
    ASSERT_TRUE(strcmp(loaded.expression, "d/dx(x^3)") == 0, "ipc-req: loaded expression");

    /* Bad magic => read fails */
    fileioc_mock_reset();
    req.magic = 0xBEEF;
    ce_request_write(&req);
    ASSERT_TRUE(!ce_request_read(&loaded), "ipc-req: bad magic => read fails");

    /* Bad version => read fails */
    fileioc_mock_reset();
    req.magic = CE_IPC_MAGIC;
    req.version = 99;
    ce_request_write(&req);
    ASSERT_TRUE(!ce_request_read(&loaded), "ipc-req: bad version => read fails");

    /* Oversized ast_size clamped */
    fileioc_mock_reset();
    req.version = CE_IPC_VERSION;
    req.flags = CE_REQ_FLAG_HAS_AST;
    req.ast_size = CE_AST_WIRE_MAX + 100;
    ce_request_write(&req);
    ASSERT_TRUE(ce_request_read(&loaded), "ipc-req: oversized ast => read ok");
    ASSERT_EQ_INT(loaded.ast_size, 0, "ipc-req: oversized ast_size clamped to 0");

    /* Flags sanitized: spurious bits stripped */
    fileioc_mock_reset();
    req.flags = 0xFF;
    req.ast_size = 100;
    ce_request_write(&req);
    ASSERT_TRUE(ce_request_read(&loaded), "ipc-req: flags sanitized => read ok");
    ASSERT_EQ_INT(loaded.flags, (CE_REQ_FLAG_HAD_EQUALS | CE_REQ_FLAG_HAS_AST),
                  "ipc-req: only valid flags preserved");

    /* No data => read fails */
    fileioc_mock_reset();
    ASSERT_TRUE(!ce_request_read(&loaded), "ipc-req: no data => read fails");

    /* Null pointer guard */
    ASSERT_TRUE(!ce_request_read(NULL), "ipc-req: null read returns false");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_response_roundtrip(void)
{
    ce_response_t resp, loaded;

    printf("=== IPC Response Round-Trip ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&resp, 0, sizeof(resp));
    resp.magic = CE_IPC_MAGIC;
    resp.version = CE_IPC_VERSION;
    resp.ok = 1;
    resp.show_steps = 1;
    resp.settings.angle_mode = ANGLE_RADIANS;
    resp.settings.precision = 6;
    resp.last_answer = 99.9f;
    strncpy(resp.result, "2*x", MAX_RESULT_LEN - 1);
    resp.error[0] = '\0';
    resp.step_count = 2;
    strncpy(resp.steps[0], "Power rule: d/dx(x^2) = 2*x", MAX_STEP_LEN - 1);
    strncpy(resp.steps[1], "= (2*x)", MAX_STEP_LEN - 1);

    ASSERT_TRUE(ce_response_write(&resp), "ipc-resp: write succeeds");

    memset(&loaded, 0, sizeof(loaded));
    ASSERT_TRUE(ce_response_read(&loaded), "ipc-resp: read succeeds");
    ASSERT_EQ_INT(loaded.magic, CE_IPC_MAGIC, "ipc-resp: loaded magic");
    ASSERT_EQ_INT(loaded.version, CE_IPC_VERSION, "ipc-resp: loaded version");
    ASSERT_EQ_INT(loaded.ok, 1, "ipc-resp: loaded ok");
    ASSERT_EQ_INT(loaded.show_steps, 1, "ipc-resp: loaded show_steps");
    ASSERT_EQ_FLOAT(loaded.last_answer, 99.9f, 1e-5f, "ipc-resp: loaded last_answer");
    ASSERT_TRUE(strcmp(loaded.result, "2*x") == 0, "ipc-resp: loaded result");
    ASSERT_EQ_INT(loaded.error[0], '\0', "ipc-resp: loaded error empty");
    ASSERT_EQ_INT(loaded.step_count, 2, "ipc-resp: loaded step_count");
    ASSERT_STR_CONTAINS(loaded.steps[0], "Power rule", "ipc-resp: step 0 text");
    ASSERT_STR_CONTAINS(loaded.steps[1], "= (2*x)", "ipc-resp: step 1 text");

    /* Bad magic => read fails */
    fileioc_mock_reset();
    resp.magic = 0xDEAD;
    ce_response_write(&resp);
    ASSERT_TRUE(!ce_response_read(&loaded), "ipc-resp: bad magic => read fails");

    /* Bad version => read fails */
    fileioc_mock_reset();
    resp.magic = CE_IPC_MAGIC;
    resp.version = 0;
    ce_response_write(&resp);
    ASSERT_TRUE(!ce_response_read(&loaded), "ipc-resp: bad version => read fails");

    /* Oversized step_count clamped */
    fileioc_mock_reset();
    resp.version = CE_IPC_VERSION;
    resp.step_count = MAX_STEPS + 50;
    ce_response_write(&resp);
    ASSERT_TRUE(ce_response_read(&loaded), "ipc-resp: oversized steps => read ok");
    ASSERT_EQ_INT(loaded.step_count, MAX_STEPS, "ipc-resp: step_count clamped to MAX_STEPS");

    /* No data => read fails */
    fileioc_mock_reset();
    ASSERT_TRUE(!ce_response_read(&loaded), "ipc-resp: no data => read fails");

    /* Null pointer guard */
    ASSERT_TRUE(!ce_response_read(NULL), "ipc-resp: null read returns false");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_response_delete(void)
{
    ce_response_t resp, loaded;

    printf("=== IPC Response Delete ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&resp, 0, sizeof(resp));
    resp.magic = CE_IPC_MAGIC;
    resp.version = CE_IPC_VERSION;
    resp.ok = 1;
    strncpy(resp.result, "deleted_test", MAX_RESULT_LEN - 1);

    ASSERT_TRUE(ce_response_write(&resp), "ipc-delete: write succeeds");
    ASSERT_TRUE(ce_response_read(&loaded), "ipc-delete: read before delete ok");

    ce_response_delete();

    /* After delete, read should fail */
    ASSERT_TRUE(!ce_response_read(&loaded), "ipc-delete: read after delete fails");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_response_from_runtime(void)
{
    ce_response_t resp;
    settings_t saved = g_settings;

    printf("=== IPC Response From Runtime ===\n");

    steps_clear();
    mem_free_all();

    /* Test with result and no error */
    g_settings.angle_mode = ANGLE_DEGREES;
    g_settings.precision = 4;
    steps_add("Step 1: apply rule");
    steps_add("Step 2: simplify");
    steps_add("= (result)");

    memset(&resp, 0xFF, sizeof(resp));
    ce_response_from_runtime(&resp, true, true, "2*x", NULL, 123.456f);

    ASSERT_EQ_INT(resp.magic, CE_IPC_MAGIC, "ipc-from-rt: magic");
    ASSERT_EQ_INT(resp.version, CE_IPC_VERSION, "ipc-from-rt: version");
    ASSERT_EQ_INT(resp.ok, 1, "ipc-from-rt: ok");
    ASSERT_EQ_INT(resp.show_steps, 1, "ipc-from-rt: show_steps");
    ASSERT_EQ_INT(resp.settings.angle_mode, ANGLE_DEGREES, "ipc-from-rt: angle_mode");
    ASSERT_EQ_INT(resp.settings.precision, 4, "ipc-from-rt: precision");
    ASSERT_EQ_FLOAT(resp.last_answer, 123.456f, 1e-3f, "ipc-from-rt: last_answer");
    ASSERT_TRUE(strcmp(resp.result, "2*x") == 0, "ipc-from-rt: result");
    ASSERT_EQ_INT(resp.error[0], '\0', "ipc-from-rt: no error");
    ASSERT_EQ_INT(resp.step_count, 3, "ipc-from-rt: 3 steps");
    ASSERT_STR_CONTAINS(resp.steps[0], "Step 1", "ipc-from-rt: step 0");
    ASSERT_STR_CONTAINS(resp.steps[1], "Step 2", "ipc-from-rt: step 1");
    ASSERT_STR_CONTAINS(resp.steps[2], "= (result)", "ipc-from-rt: step 2");

    /* Test with error and no result */
    steps_clear();
    memset(&resp, 0xFF, sizeof(resp));
    ce_response_from_runtime(&resp, false, false, NULL, "Syntax error", 0.0f);

    ASSERT_EQ_INT(resp.ok, 0, "ipc-from-rt-err: not ok");
    ASSERT_EQ_INT(resp.show_steps, 0, "ipc-from-rt-err: no steps");
    ASSERT_EQ_INT(resp.result[0], '\0', "ipc-from-rt-err: no result text");
    ASSERT_TRUE(strcmp(resp.error, "Syntax error") == 0, "ipc-from-rt-err: error message");
    ASSERT_EQ_INT(resp.step_count, 0, "ipc-from-rt-err: 0 steps");
    ASSERT_EQ_FLOAT(resp.last_answer, 0.0f, 1e-9f, "ipc-from-rt-err: last_answer 0");

    /* Null pointer guard */
    ce_response_from_runtime(NULL, true, true, "x", NULL, 1.0f); /* should not crash */

    g_settings = saved;
    steps_clear();
}

static void test_ipc_program_archiving(void)
{
    printf("=== IPC Program Archiving ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    /* Add a program to the mock store */
    fileioc_mock_add_program("CEALG", 0);

    /* Verify it's in RAM */
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 0,
                  "ipc-archive: initially in RAM");

    /* Set archived */
    ASSERT_TRUE(ce_program_set_archived("CEALG", true), "ipc-archive: set archived succeeds");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 1,
                  "ipc-archive: now archived");

    /* Set back to RAM */
    ASSERT_TRUE(ce_program_set_archived("CEALG", false), "ipc-archive: set unarchived succeeds");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 0,
                  "ipc-archive: back in RAM");

    /* Already in RAM — should return true without change */
    ASSERT_TRUE(ce_program_set_archived("CEALG", false), "ipc-archive: already in RAM noop");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 0,
                  "ipc-archive: still in RAM");

    /* Already archived — should return true without change */
    ce_program_set_archived("CEALG", true);
    ASSERT_TRUE(ce_program_set_archived("CEALG", true), "ipc-archive: already archived noop");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 1,
                  "ipc-archive: still archived");

    /* ce_program_ensure_ram is shorthand for set_archived(name, false) */
    ASSERT_TRUE(ce_program_ensure_ram("CEALG"), "ipc-archive: ensure_ram succeeds");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 0,
                  "ipc-archive: ensure_ram puts in RAM");

    /* Non-existent program => false */
    ASSERT_TRUE(!ce_program_set_archived("NONEXIST", true),
                "ipc-archive: nonexistent program fails");

    /* Null/empty name guard */
    ASSERT_TRUE(!ce_program_set_archived(NULL, true), "ipc-archive: null name fails");
    ASSERT_TRUE(!ce_program_set_archived("", true), "ipc-archive: empty name fails");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

