static void test_ipc_state_persistence_cycle(void)
{
    ce_shared_state_t state, loaded;
    int i;

    printf("=== IPC State Persistence Cycle ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    /* Fill all history slots and verify round-trip */
    ce_state_defaults(&state);
    state.hist_count = CE_HISTORY_SIZE;
    state.hist_write = 0; /* wrapped around */
    for (i = 0; i < CE_HISTORY_SIZE; i++) {
        snprintf(state.history[i], MAX_INPUT_LEN, "expr_%d", i);
    }
    state.last_answer = -1.5f;
    state.settings.complex_mode = COMPLEX_RECT;

    ASSERT_TRUE(ce_state_save(&state), "ipc-persist: save full history");
    memset(&loaded, 0, sizeof(loaded));
    ASSERT_TRUE(ce_state_load(&loaded), "ipc-persist: load full history");

    ASSERT_EQ_INT(loaded.hist_count, CE_HISTORY_SIZE, "ipc-persist: all history slots");
    ASSERT_EQ_INT(loaded.hist_write, 0, "ipc-persist: hist_write 0 (wrapped)");
    for (i = 0; i < CE_HISTORY_SIZE; i++) {
        char msg[64], expected[32];
        snprintf(expected, sizeof(expected), "expr_%d", i);
        snprintf(msg, sizeof(msg), "ipc-persist: history[%d]", i);
        ASSERT_TRUE(strcmp(loaded.history[i], expected) == 0, msg);
    }
    ASSERT_EQ_FLOAT(loaded.last_answer, -1.5f, 1e-6f, "ipc-persist: negative last_answer");
    ASSERT_EQ_INT(loaded.settings.complex_mode, COMPLEX_RECT, "ipc-persist: complex rect");

    /* Overwrite and reload */
    ce_state_defaults(&state);
    state.last_answer = 0.001f;
    ASSERT_TRUE(ce_state_save(&state), "ipc-persist: overwrite save");
    memset(&loaded, 0xFF, sizeof(loaded));
    ASSERT_TRUE(ce_state_load(&loaded), "ipc-persist: overwrite load");
    ASSERT_EQ_FLOAT(loaded.last_answer, 0.001f, 1e-6f, "ipc-persist: overwritten value");
    ASSERT_EQ_INT(loaded.hist_count, 0, "ipc-persist: cleared history");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

