static void test_astwire_all_node_types(void)
{
    printf("=== AST Wire All Node Types ===\n");

    /* Arithmetic and functions */
    assert_astwire_roundtrip("x+y", "astwire-all: addition");
    assert_astwire_roundtrip("x-y", "astwire-all: subtraction");
    assert_astwire_roundtrip("x*y", "astwire-all: multiplication");
    assert_astwire_roundtrip("x/y", "astwire-all: division");
    assert_astwire_roundtrip("x^y", "astwire-all: power");
    assert_astwire_roundtrip("-x", "astwire-all: negation");
    assert_astwire_roundtrip("sin(x)", "astwire-all: sin");
    assert_astwire_roundtrip("cos(x)", "astwire-all: cos");
    assert_astwire_roundtrip("tan(x)", "astwire-all: tan");
    assert_astwire_roundtrip("ln(x)", "astwire-all: ln");
    assert_astwire_roundtrip("log(x)", "astwire-all: log");
    assert_astwire_roundtrip("sqrt(x)", "astwire-all: sqrt");
    assert_astwire_roundtrip("abs(x)", "astwire-all: abs");
    assert_astwire_roundtrip("asin(x)", "astwire-all: asin");
    assert_astwire_roundtrip("acos(x)", "astwire-all: acos");
    assert_astwire_roundtrip("atan(x)", "astwire-all: atan");
    assert_astwire_roundtrip("sinh(x)", "astwire-all: sinh");
    assert_astwire_roundtrip("cosh(x)", "astwire-all: cosh");
    assert_astwire_roundtrip("tanh(x)", "astwire-all: tanh");

    /* Calculus constructs */
    assert_astwire_roundtrip("d/dx(x^3)", "astwire-all: derivative");
    assert_astwire_roundtrip("int(x^2,x)", "astwire-all: indefinite integral");
    assert_astwire_roundtrip("int(x,x,0,1)", "astwire-all: definite integral");
    assert_astwire_roundtrip("lim(sin(x)/x,x,0)", "astwire-all: limit");
    assert_astwire_roundtrip("sum(1/n,n,1,10)", "astwire-all: sum");
    assert_astwire_roundtrip("prod(n,n,1,5)", "astwire-all: product");

    /* Numbers and constants */
    assert_astwire_roundtrip("42", "astwire-all: integer");
    assert_astwire_roundtrip("3.14", "astwire-all: float");
    assert_astwire_roundtrip("pi", "astwire-all: pi constant");
    assert_astwire_roundtrip("e", "astwire-all: e constant");

    /* Variables */
    assert_astwire_roundtrip("x", "astwire-all: variable x");
    assert_astwire_roundtrip("y", "astwire-all: variable y");
    assert_astwire_roundtrip("n", "astwire-all: variable n");

    /* Complex expressions */
    assert_astwire_roundtrip("sin(x)^2+cos(x)^2", "astwire-all: trig identity");
    assert_astwire_roundtrip("(x+1)*(x-1)", "astwire-all: product of sums");
    assert_astwire_roundtrip("x^2+2*x+1", "astwire-all: quadratic");
    assert_astwire_roundtrip("e^(i*pi)", "astwire-all: euler formula");
    assert_astwire_roundtrip("d/dx(sin(x)*cos(x))", "astwire-all: product rule");
}

static void test_astwire_stress(void)
{
    uint8_t buf[CE_AST_WIRE_MAX + 2];
    uint16_t size = 0;
    ast_node_t *root;

    printf("=== AST Wire Stress ===\n");

    /* Nested binary ops — build a long chain: x+x+x+...+x */
    root = ast_variable('x');
    {
        int i;
        for (i = 0; i < 50 && root; i++) {
            root = ast_binop(OP_ADD, root, ast_variable('x'));
        }
    }
    ASSERT_TRUE(root != NULL, "astwire-stress: 50-deep chain built");
    if (root) {
        ASSERT_TRUE(ce_ast_serialize(root, buf, (uint16_t)sizeof(buf), &size),
                    "astwire-stress: serialize 50-deep chain");
        ASSERT_TRUE(size > 0, "astwire-stress: non-zero serialized size");
        {
            ast_node_t *restored = ce_ast_deserialize(buf, size);
            ASSERT_TRUE(restored != NULL, "astwire-stress: deserialize 50-deep chain");
            if (restored) ast_free(restored);
        }
        ast_free(root);
    }
    mem_free_all();

    /* Nested functions: sin(sin(sin(...(x)...))) */
    root = ast_variable('x');
    {
        int i;
        for (i = 0; i < 30 && root; i++) {
            root = ast_func(FN_SIN, root);
        }
    }
    ASSERT_TRUE(root != NULL, "astwire-stress: 30-deep func chain built");
    if (root) {
        ASSERT_TRUE(ce_ast_serialize(root, buf, (uint16_t)sizeof(buf), &size),
                    "astwire-stress: serialize 30-deep func chain");
        {
            ast_node_t *restored = ce_ast_deserialize(buf, size);
            ASSERT_TRUE(restored != NULL, "astwire-stress: deserialize 30-deep func chain");
            if (restored) ast_free(restored);
        }
        ast_free(root);
    }
    mem_free_all();
}

