/* ═══════════════════════════════════════════════════════════════════════
 * Pass 38: Step Quality — Statistics and Finance
 *
 * Verifies that statistics and finance calculations produce correct
 * results with the expected format, correct show_steps flag, and proper
 * numeric values. Tests mean, stdev, median, pv, fv, pmt functions.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_step_quality_stats_and_finance(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Step Quality: Stats and Finance ===\n");

    /* mean(2,4,6) = 4 */
    ASSERT_TRUE(processor_run_expr("mean(2,4,6)", &resp, &domain, &program),
                "sq-stat: mean run");
    ASSERT_TRUE(resp.ok, "sq-stat: mean ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_STAT, (int)domain, "sq-stat: mean domain=STAT");
    ASSERT_STR_CONTAINS(resp.result, "mean", "sq-stat: mean result has label");
    ASSERT_STR_CONTAINS(resp.result, "4", "sq-stat: mean(2,4,6) = 4");
    ASSERT_TRUE(!resp.show_steps, "sq-stat: mean show_steps=false");
    ASSERT_EQ_INT(resp.step_count, 0, "sq-stat: mean has no steps");
    mem_free_all(); steps_clear();

    /* mean(10,20,30) = 20 */
    ASSERT_TRUE(processor_run_expr("mean(10,20,30)", &resp, &domain, &program),
                "sq-stat: mean3 run");
    ASSERT_TRUE(resp.ok, "sq-stat: mean3 ok");
    ASSERT_STR_CONTAINS(resp.result, "20", "sq-stat: mean(10,20,30) = 20");
    ASSERT_TRUE(!resp.show_steps, "sq-stat: mean3 show_steps=false");
    mem_free_all(); steps_clear();

    /* median(1,3,5,7,9) = 5 */
    ASSERT_TRUE(processor_run_expr("median(1,3,5,7,9)", &resp, &domain, &program),
                "sq-stat: median run");
    ASSERT_TRUE(resp.ok, "sq-stat: median ok");
    ASSERT_STR_CONTAINS(resp.result, "5", "sq-stat: median(1,3,5,7,9) = 5");
    ASSERT_TRUE(!resp.show_steps, "sq-stat: median show_steps=false");
    mem_free_all(); steps_clear();

    /* stdev of {2,4,4,4,5,5,7,9} = 2 */
    ASSERT_TRUE(processor_run_expr("stdev(2,4,4,4,5,5,7,9)", &resp, &domain, &program),
                "sq-stat: stdev run");
    ASSERT_TRUE(resp.ok, "sq-stat: stdev ok");
    ASSERT_STR_CONTAINS(resp.result, "stdev", "sq-stat: stdev result has label");
    ASSERT_STR_CONTAINS(resp.result, "2", "sq-stat: stdev ~ 2");
    ASSERT_TRUE(!resp.show_steps, "sq-stat: stdev show_steps=false");
    mem_free_all(); steps_clear();

    /* variance(1,2,3,4,5) — may be called var or variance */
    ASSERT_TRUE(processor_run_expr("variance(1,2,3,4,5)", &resp, &domain, &program),
                "sq-stat: variance run");
    ASSERT_TRUE(resp.ok, "sq-stat: variance ok");
    ASSERT_TRUE(!resp.show_steps, "sq-stat: variance show_steps=false");
    mem_free_all(); steps_clear();

    /* Sample stdev of one value is undefined: refuse, never "stdev = 0". */
    (void)processor_run_expr("stdev(5)", &resp, &domain, &program);
    ASSERT_TRUE(!resp.ok, "sq-stat: stdev(5) refused");
    ASSERT_STR_CONTAINS(resp.error, "2+ values", "sq-stat: stdev(5) says why");
    mem_free_all(); steps_clear();

    /* polydiv(...) answers quotient and remainder through the processor
     * (CEAPDV builds with CE_PROC_ALG_SOLVE=0). */
    ASSERT_TRUE(processor_run_expr("polydiv(x^3-1,x-1,x)", &resp, &domain, &program),
                "sq-alg: polydiv run");
    ASSERT_TRUE(resp.ok, "sq-alg: polydiv ok");
    ASSERT_STR_CONTAINS(resp.result, "Q = x^2+x+1", "sq-alg: polydiv quotient");
    ASSERT_STR_CONTAINS(resp.result, "R = 0", "sq-alg: polydiv remainder 0");
    mem_free_all(); steps_clear();
    ASSERT_TRUE(processor_run_expr("polydiv(x^2+1,x+1,x)", &resp, &domain, &program),
                "sq-alg: polydiv rem run");
    ASSERT_TRUE(resp.ok, "sq-alg: polydiv rem ok");
    ASSERT_STR_CONTAINS(resp.result, "Q = x-1", "sq-alg: polydiv rem quotient");
    ASSERT_STR_CONTAINS(resp.result, "R = 2", "sq-alg: polydiv rem remainder 2");
    mem_free_all(); steps_clear();
    /* A fractional power is not a polynomial term: refuse, never truncate
     * x^1.5 to x (it used to answer Q = 1, R = 0). */
    (void)processor_run_expr("polydiv(x^1.5,x,x)", &resp, &domain, &program);
    ASSERT_TRUE(!resp.ok, "sq-alg: polydiv(x^1.5,x,x) refused");
    ASSERT_STR_CONTAINS(resp.error, "polynomial division", "sq-alg: polydiv x^1.5 says why");
    mem_free_all(); steps_clear();
    (void)processor_run_expr("polydiv(x^3-1,x^0.5,x)", &resp, &domain, &program);
    ASSERT_TRUE(!resp.ok, "sq-alg: polydiv by x^0.5 refused");
    mem_free_all(); steps_clear();
    ASSERT_TRUE(processor_run_expr("polydiv(x^2.0-1,x-1,x)", &resp, &domain, &program),
                "sq-alg: polydiv x^2.0 run");
    ASSERT_STR_CONTAINS(resp.result, "Q = x+1", "sq-alg: integral float power still divides");
    mem_free_all(); steps_clear();

    /* pv(0.05,10,0,1000) ≈ -887.014 */
    ASSERT_TRUE(processor_run_expr("pv(0.05,10,0,1000)", &resp, &domain, &program),
                "sq-fin: pv run");
    ASSERT_TRUE(resp.ok, "sq-fin: pv ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_FIN, (int)domain, "sq-fin: pv domain=FIN");
    ASSERT_STR_CONTAINS(resp.result, "pv", "sq-fin: pv result has label");
    ASSERT_STR_CONTAINS(resp.result, "-887", "sq-fin: pv ~ -887");
    ASSERT_TRUE(!resp.show_steps, "sq-fin: pv show_steps=false");
    ASSERT_EQ_INT(resp.step_count, 0, "sq-fin: pv has no steps");
    mem_free_all(); steps_clear();

    /* fv(0.05,10,-100,0) — FV of 10 payments of 100 at 5% */
    ASSERT_TRUE(processor_run_expr("fv(0.05,10,-100,0)", &resp, &domain, &program),
                "sq-fin: fv run");
    ASSERT_TRUE(resp.ok, "sq-fin: fv ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_FIN, (int)domain, "sq-fin: fv domain=FIN");
    ASSERT_STR_CONTAINS(resp.result, "fv", "sq-fin: fv result has label");
    ASSERT_TRUE(!resp.show_steps, "sq-fin: fv show_steps=false");
    mem_free_all(); steps_clear();

    /* pmt(0.05,10,1000,0) — monthly payment */
    ASSERT_TRUE(processor_run_expr("pmt(0.05,10,1000,0)", &resp, &domain, &program),
                "sq-fin: pmt run");
    ASSERT_TRUE(resp.ok, "sq-fin: pmt ok");
    ASSERT_STR_CONTAINS(resp.result, "pmt", "sq-fin: pmt result has label");
    ASSERT_TRUE(!resp.show_steps, "sq-fin: pmt show_steps=false");
    mem_free_all(); steps_clear();

    /* nper(0.05,-100,0,1000) — number of periods */
    ASSERT_TRUE(processor_run_expr("nper(0.05,-100,0,1000)", &resp, &domain, &program),
                "sq-fin: nper run");
    ASSERT_TRUE(resp.ok, "sq-fin: nper ok");
    ASSERT_STR_CONTAINS(resp.result, "nper", "sq-fin: nper result has label");
    ASSERT_TRUE(!resp.show_steps, "sq-fin: nper show_steps=false");
    mem_free_all(); steps_clear();
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 38: Step Quality — Matrix Operations
 *
 * Verifies that matrix operations produce correct results with the proper
 * format. Tests det, transpose, inverse, rref for 2x2 and 3x3 matrices.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_step_quality_matrix_ops(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Step Quality: Matrix Operations ===\n");

    /* det(mat(1,2;3,4)) = -2 */
    ASSERT_TRUE(processor_run_expr("det(mat(1,2;3,4))", &resp, &domain, &program),
                "sq-mat: det1 run");
    ASSERT_TRUE(resp.ok, "sq-mat: det1 ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_MATRIX, (int)domain, "sq-mat: det1 domain=MATRIX");
    ASSERT_STR_CONTAINS(resp.result, "det = -2", "sq-mat: det(1,2;3,4) = -2");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: det has show_steps=false");
    ASSERT_EQ_INT(resp.step_count, 0, "sq-mat: det has no steps");
    mem_free_all(); steps_clear();

    /* det(mat(3,0;0,5)) = 15 */
    ASSERT_TRUE(processor_run_expr("det(mat(3,0;0,5))", &resp, &domain, &program),
                "sq-mat: det2 run");
    ASSERT_TRUE(resp.ok, "sq-mat: det2 ok");
    ASSERT_STR_CONTAINS(resp.result, "det = 15", "sq-mat: det(3,0;0,5) = 15");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: det2 show_steps=false");
    mem_free_all(); steps_clear();

    /* det(mat(1,0,0;0,2,0;0,0,3)) = 6 (3x3 diagonal) */
    ASSERT_TRUE(processor_run_expr("det(mat(1,0,0;0,2,0;0,0,3))", &resp, &domain, &program),
                "sq-mat: det3x3 run");
    ASSERT_TRUE(resp.ok, "sq-mat: det3x3 ok");
    ASSERT_STR_CONTAINS(resp.result, "det = 6", "sq-mat: det(3x3 diagonal) = 6");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: det3x3 show_steps=false");
    mem_free_all(); steps_clear();

    /* transpose(mat(1,2;3,4)) → [[1,3],[2,4]] */
    ASSERT_TRUE(processor_run_expr("transpose(mat(1,2;3,4))", &resp, &domain, &program),
                "sq-mat: trans run");
    ASSERT_TRUE(resp.ok, "sq-mat: trans ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_MATRIX, (int)domain, "sq-mat: trans domain=MATRIX");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: trans show_steps=false");
    /* The transpose matrix string should contain the elements in column-major order */
    ASSERT_STR_CONTAINS(resp.result, "1", "sq-mat: trans result not empty");
    mem_free_all(); steps_clear();

    /* inv(mat(1,0;0,1)) → identity */
    ASSERT_TRUE(processor_run_expr("inv(mat(1,0;0,1))", &resp, &domain, &program),
                "sq-mat: inv-id run");
    ASSERT_TRUE(resp.ok, "sq-mat: inv-id ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_MATRIX, (int)domain, "sq-mat: inv-id domain=MATRIX");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: inv-id show_steps=false");
    ASSERT_STR_CONTAINS(resp.result, "1", "sq-mat: identity inverse contains 1");
    mem_free_all(); steps_clear();

    /* inv(mat(2,0;0,4)) → [[0.5,0],[0,0.25]] */
    ASSERT_TRUE(processor_run_expr("inv(mat(2,0;0,4))", &resp, &domain, &program),
                "sq-mat: inv-diag run");
    ASSERT_TRUE(resp.ok, "sq-mat: inv-diag ok");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: inv-diag show_steps=false");
    /* Result should contain 0.5 (inverse of 2) */
    ASSERT_STR_CONTAINS(resp.result, "0.5", "sq-mat: inv(2,0;0,4) has 0.5");
    mem_free_all(); steps_clear();

    /* rref(mat(1,2;3,4)) → [[1,0],[0,1]] (full rank) */
    ASSERT_TRUE(processor_run_expr("rref(mat(1,2;3,4))", &resp, &domain, &program),
                "sq-mat: rref run");
    ASSERT_TRUE(resp.ok, "sq-mat: rref ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_MATRIX, (int)domain, "sq-mat: rref domain=MATRIX");
    ASSERT_TRUE(!resp.show_steps, "sq-mat: rref show_steps=false");
    /* RREF of full-rank 2x2 is identity: "[1 0]\n[0 1]" using %.4g format */
    ASSERT_STR_CONTAINS(resp.result, "[1 0]", "sq-mat: rref first row is [1 0]");
    mem_free_all(); steps_clear();
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 38: Step Quality — Probability and Polar Conversions
 *
 * Verifies probability distributions produce correct numeric results and
 * that polar coordinate conversions produce correct results with steps.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_step_quality_prob_and_polar(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Step Quality: Probability and Polar ===\n");

    /* binompdf(10,0.5,3) ≈ 0.117188 */
    ASSERT_TRUE(processor_run_expr("binompdf(10,0.5,3)", &resp, &domain, &program),
                "sq-prob: binompdf run");
    ASSERT_TRUE(resp.ok, "sq-prob: binompdf ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_PROB, (int)domain, "sq-prob: binompdf domain=PROB");
    ASSERT_STR_CONTAINS(resp.result, "0.117188", "sq-prob: binompdf(10,0.5,3) ~ 0.117188");
    ASSERT_TRUE(!resp.show_steps, "sq-prob: binompdf show_steps=false");
    ASSERT_EQ_INT(resp.step_count, 0, "sq-prob: binompdf has no steps");
    mem_free_all(); steps_clear();

    /* binomcdf(10,0.5,3) — cumulative binomial */
    ASSERT_TRUE(processor_run_expr("binomcdf(10,0.5,3)", &resp, &domain, &program),
                "sq-prob: binomcdf run");
    ASSERT_TRUE(resp.ok, "sq-prob: binomcdf ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_PROB, (int)domain, "sq-prob: binomcdf domain=PROB");
    ASSERT_TRUE(!resp.show_steps, "sq-prob: binomcdf show_steps=false");
    /* binomcdf(10,0.5,3) ≈ 0.171875 */
    ASSERT_STR_CONTAINS(resp.result, "0.171875", "sq-prob: binomcdf(10,0.5,3) ~ 0.171875");
    mem_free_all(); steps_clear();

    /* normalcdf(-1,1) ≈ 0.6827 */
    ASSERT_TRUE(processor_run_expr("normalcdf(-1,1)", &resp, &domain, &program),
                "sq-prob: normalcdf run");
    ASSERT_TRUE(resp.ok, "sq-prob: normalcdf ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_PROB, (int)domain, "sq-prob: normalcdf domain=PROB");
    ASSERT_TRUE(!resp.show_steps, "sq-prob: normalcdf show_steps=false");
    ASSERT_STR_CONTAINS(resp.result, "0.68", "sq-prob: normalcdf(-1,1) ~ 0.68");
    mem_free_all(); steps_clear();

    /* poissonpdf(3,3) — Poisson PDF at k=3 with lambda=3 */
    ASSERT_TRUE(processor_run_expr("poissonpdf(3,3)", &resp, &domain, &program),
                "sq-prob: poissonpdf run");
    ASSERT_TRUE(resp.ok, "sq-prob: poissonpdf ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_PROB, (int)domain, "sq-prob: poissonpdf domain=PROB");
    ASSERT_TRUE(!resp.show_steps, "sq-prob: poissonpdf show_steps=false");
    mem_free_all(); steps_clear();

    /* geometpdf(0.3,3) — geometric P(X=3) with p=0.3 */
    ASSERT_TRUE(processor_run_expr("geometpdf(0.3,3)", &resp, &domain, &program),
                "sq-prob: geometpdf run");
    ASSERT_TRUE(resp.ok, "sq-prob: geometpdf ok");
    ASSERT_EQ_INT((int)CE_DOMAIN_PROB, (int)domain, "sq-prob: geometpdf domain=PROB");
    ASSERT_TRUE(!resp.show_steps, "sq-prob: geometpdf show_steps=false");
    /* geometpdf(0.3,3) = 0.3 * 0.7^2 = 0.147 */
    ASSERT_STR_CONTAINS(resp.result, "0.147", "sq-prob: geometpdf(0.3,3) ~ 0.147");
    mem_free_all(); steps_clear();

    /* polar(1,0) → polar-to-rect: x = 1, y = 0 (3 steps) */
    ASSERT_TRUE(processor_run_expr("polar(1,0)", &resp, &domain, &program),
                "sq-polar: polrect run");
    ASSERT_TRUE(resp.ok, "sq-polar: polrect ok");
    ASSERT_STR_CONTAINS(resp.result, "x = 1", "sq-polar: polar(1,0) x = 1");
    ASSERT_STR_CONTAINS(resp.result, "y = 0", "sq-polar: polar(1,0) y = 0");
    ASSERT_TRUE(resp.show_steps, "sq-polar: polar-to-rect show_steps=true");
    ASSERT_EQ_INT(resp.step_count, 3, "sq-polar: polar-to-rect has 3 steps");
    ASSERT_TRUE(response_step_contains(&resp, "r = 1"),
                "sq-polar: step 1 shows r");
    ASSERT_TRUE(response_step_contains(&resp, "x = r*cos"),
                "sq-polar: step 2 shows x = r*cos");
    ASSERT_TRUE(response_step_contains(&resp, "y = r*sin"),
                "sq-polar: step 3 shows y = r*sin");
    mem_free_all(); steps_clear();

    /* rect(1,0) → rect-to-polar: r = 1, theta = 0 */
    ASSERT_TRUE(processor_run_expr("rect(1,0)", &resp, &domain, &program),
                "sq-polar: rectpol run");
    ASSERT_TRUE(resp.ok, "sq-polar: rectpol ok");
    ASSERT_STR_CONTAINS(resp.result, "r = 1", "sq-polar: rect(1,0) r = 1");
    ASSERT_TRUE(resp.show_steps, "sq-polar: rect-to-polar show_steps=true");
    mem_free_all(); steps_clear();

    /* polar(0,0) → x = 0, y = 0 */
    ASSERT_TRUE(processor_run_expr("polar(0,0)", &resp, &domain, &program),
                "sq-polar: polar00 run");
    ASSERT_TRUE(resp.ok, "sq-polar: polar00 ok");
    ASSERT_STR_CONTAINS(resp.result, "x = 0", "sq-polar: polar(0,0) x = 0");
    ASSERT_STR_CONTAINS(resp.result, "y = 0", "sq-polar: polar(0,0) y = 0");
    mem_free_all(); steps_clear();
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 38: All Problem Types — Final Answer Correctness
 *
 * Systematic sweep across all 18 domains and their key problem types.
 * Verifies the final answer correctness for 30+ diverse calculations.
 * Each test calls ce_processor_run and checks result/domain/ok flag.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_all_problem_types_final_answers(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;
    size_t i;

    /* Table of (expression, expected_result_fragment, expected_domain) */
    struct {
        const char *expr;
        const char *fragment;
        ce_domain_t domain;
    } cases[] = {
        /* CORE — arithmetic evaluation */
        { "2+3",            "5",              CE_DOMAIN_CORE },
        { "10-4",           "6",              CE_DOMAIN_CORE },
        { "3*7",            "21",             CE_DOMAIN_CORE },
        { "100/4",          "25",             CE_DOMAIN_CORE },
        { "2^10",           "1024",           CE_DOMAIN_CORE },
        /* ALG — equation solving */
        { "solve(x+5=10,x)", "x = 5",         CE_DOMAIN_ALG },
        { "solve(2*x=8,x)",   "x = 4",        CE_DOMAIN_ALG },
        { "solve(x^2=9,x)",   "x = 3",        CE_DOMAIN_ALG },
        /* ALG_EXPFAC — factor and expand */
        { "factor(x^2-4,x)",   "(x-2)*(x+2)", CE_DOMAIN_ALG_EXPFAC },
        { "expand((x+2)^2,x)", "x^2",           CE_DOMAIN_ALG_EXPFAC },
        /* ALG_GEO — geometric algebra */
        { "line(0,0,2,2)",     "y = 1*x",       CE_DOMAIN_ALG_GEO },
        /* CALC — differentiation */
        { "d/dx(x^4)",      "4x^3",        CE_DOMAIN_CALC },
        { "d/dx(sin(x))",   "cos(x)",         CE_DOMAIN_CALC },
        { "d/dx(e^x)",      "e^x",            CE_DOMAIN_CALC },
        /* CALC_TANGENT — tangent line */
        { "tangent(x^2,x,2)", "4*x",          CE_DOMAIN_CALC_TANGENT },
        /* CALC_LIMIT — limits */
        { "lim(x^2,x,3)",   "9",              CE_DOMAIN_CALC_LIMIT },
        { "lim(sin(x)/x,x,0)", "1",           CE_DOMAIN_CALC_LIMIT },
        /* CALC_INT — integration */
        { "int(1,x)",       "x",              CE_DOMAIN_CALC_INT },
        { "int(x,x)",       "x^2",            CE_DOMAIN_CALC_INT },
        { "int(x^3,x)",     "x^4",            CE_DOMAIN_CALC_INT },
        /* CALC_SERIES — Taylor series */
        { "taylor(cos(x),x,0,4)", "x^4",     CE_DOMAIN_CALC_SERIES },
        /* CALC_SEQ — series convergence */
        { "sum(1/n^2,n,1,inf)", "converges", CE_DOMAIN_CALC_SEQ },
        /* STAT — statistics */
        { "mean(4,8,12)",       "8",          CE_DOMAIN_STAT },
        { "median(1,2,3,4,5)",  "3",          CE_DOMAIN_STAT },
        /* PROB — probability */
        { "binompdf(5,0.5,2)",  "0.3125",     CE_DOMAIN_PROB },
        /* MATRIX — linear algebra */
        { "det(mat(5,0;0,2))",  "det = 10",   CE_DOMAIN_MATRIX },
        { "det(mat(0,1;1,0))",  "det = -1",   CE_DOMAIN_MATRIX },
        /* GRAPH — graphing */
        { "graph(x^2,x)",       "Graph module", CE_DOMAIN_GRAPH },
        /* FIN — finance */
        { "fv(0.1,5,0,1000)",   "fv",         CE_DOMAIN_FIN },
    };

    printf("=== All Problem Types Final Answers ===\n");

    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        char msg[160];

        mem_free_all();
        steps_clear();
        memset(&resp, 0, sizeof(resp));

        snprintf(msg, sizeof(msg), "all-types[%u]: run %s", (unsigned)i, cases[i].expr);
        ASSERT_TRUE(processor_run_expr(cases[i].expr, &resp, &domain, &program), msg);

        snprintf(msg, sizeof(msg), "all-types[%u]: ok for %s", (unsigned)i, cases[i].expr);
        ASSERT_TRUE(resp.ok, msg);

        snprintf(msg, sizeof(msg), "all-types[%u]: domain for %s", (unsigned)i, cases[i].expr);
        ASSERT_EQ_INT((int)cases[i].domain, (int)domain, msg);

        snprintf(msg, sizeof(msg), "all-types[%u]: result '%s' in %s",
                 (unsigned)i, cases[i].fragment, cases[i].expr);
        ASSERT_STR_CONTAINS(resp.result, cases[i].fragment, msg);
    }

    mem_free_all();
    steps_clear();
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 38: Settings Propagation Through IPC
 *
 * Verifies that all settings fields (angle_mode, integ_method,
 * complex_mode, show_steps, precision, solve_mode) propagate correctly
 * through the complete IPC round-trip: launcher state → CE_REQ → worker
 * load → worker response → CE_RESP → launcher re-read.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_settings_propagation_ipc(void)
{
    ce_request_t req, worker_req;
    ce_response_t worker_resp, launcher_resp;
    ce_shared_state_t state;
    ast_node_t *root = NULL;
    bool had_equals = false;
    settings_t saved_settings = g_settings;
    ce_float_t saved_last_answer = g_last_answer;

    printf("=== Settings Propagation Through IPC ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();
    steps_clear();
    mem_free_all();

    /* ── Round A: Non-default settings propagate to worker ─── */
    {
        settings_t custom;
        custom.angle_mode    = ANGLE_DEGREES;
        custom.show_steps    = false;
        custom.precision     = 4;
        custom.complex_mode  = COMPLEX_RECT;
        custom.pmt_at_begin  = true;
        custom.step_detail   = STEP_COMPACT;
        custom.solve_mode    = SOLVE_STEP_BY_STEP;
        custom.integ_method  = METHOD_USUB;

        ce_state_defaults(&state);
        state.settings = custom;
        state.last_answer = 3.14159f;
        ASSERT_TRUE(ce_state_save(&state), "set-prop: save custom state");

        memset(&req, 0, sizeof(req));
        req.magic = CE_IPC_MAGIC;
        req.version = CE_IPC_VERSION;
        req.domain = CE_DOMAIN_CALC;
        req.settings = custom;
        req.last_answer = state.last_answer;
        strncpy(req.caller, "CALCENG", 8);
        strncpy(req.return_to, "CALCENG", 8);
        strncpy(req.expression, "d/dx(x^2)", MAX_INPUT_LEN - 1);

        ASSERT_TRUE(ce_request_write(&req), "set-prop: write req with custom settings");

        /* Worker loads */
        root = NULL; had_equals = false;
        g_settings = state.settings;
        g_last_answer = state.last_answer;
        steps_clear();

        memset(&worker_req, 0, sizeof(worker_req));
        memset(&worker_resp, 0, sizeof(worker_resp));
        ASSERT_TRUE(ce_module_runtime_load(&worker_req, &worker_resp, &state,
                                           &root, &had_equals),
                    "set-prop: runtime load");

        /* Verify all settings fields arrived in worker */
        ASSERT_EQ_INT((int)worker_req.settings.angle_mode, (int)ANGLE_DEGREES,
                      "set-prop: angle_mode=DEG propagated to worker");
        ASSERT_TRUE(!worker_req.settings.show_steps,
                    "set-prop: show_steps=false propagated to worker");
        ASSERT_EQ_INT(worker_req.settings.precision, 4,
                      "set-prop: precision=4 propagated to worker");
        ASSERT_EQ_INT((int)worker_req.settings.complex_mode, (int)COMPLEX_RECT,
                      "set-prop: complex_mode=RECT propagated to worker");
        ASSERT_TRUE(worker_req.settings.pmt_at_begin,
                    "set-prop: pmt_at_begin=true propagated to worker");
        ASSERT_EQ_INT((int)worker_req.settings.solve_mode, (int)SOLVE_STEP_BY_STEP,
                      "set-prop: solve_mode=SBS propagated to worker");
        ASSERT_EQ_INT((int)worker_req.settings.integ_method, (int)METHOD_USUB,
                      "set-prop: integ_method=USUB propagated to worker");
        ASSERT_EQ_FLOAT(worker_req.last_answer, 3.14159f, 1e-4f,
                        "set-prop: last_answer=pi propagated to worker");

        /* Worker computes and builds response */
        memset(&worker_resp, 0, sizeof(worker_resp));
        g_settings = worker_req.settings;
        ASSERT_TRUE(ce_processor_run(worker_req.expression, &worker_resp),
                    "set-prop: processor run");
        ASSERT_TRUE(worker_resp.ok, "set-prop: processor result ok");
        ASSERT_STR_CONTAINS(worker_resp.result, "2x", "set-prop: d/dx(x^2)=2*x");

        /* Worker finishes: settings propagate into response */
        ce_module_runtime_finish(&worker_req, &worker_resp, &state);

        /* Launcher re-entry */
        memset(&state, 0xFF, sizeof(state));
        ASSERT_TRUE(ce_state_load(&state), "set-prop: re-entry state load");
        ASSERT_EQ_INT(state.has_pending_response, 1,
                      "set-prop: has_pending_response = 1 after finish");
        ASSERT_TRUE(ce_response_read(&launcher_resp), "set-prop: read resp");
        ASSERT_EQ_INT(launcher_resp.ok, 1, "set-prop: launcher resp ok");

        /* Verify settings round-tripped through CE_RESP */
        ASSERT_EQ_INT((int)launcher_resp.settings.angle_mode, (int)ANGLE_DEGREES,
                      "set-prop: angle_mode round-tripped to launcher");
        ASSERT_TRUE(!launcher_resp.settings.show_steps,
                    "set-prop: show_steps=false round-tripped to launcher");
        ASSERT_EQ_INT(launcher_resp.settings.precision, 4,
                      "set-prop: precision=4 round-tripped to launcher");
        ASSERT_EQ_INT((int)launcher_resp.settings.complex_mode, (int)COMPLEX_RECT,
                      "set-prop: complex_mode=RECT round-tripped to launcher");
        ASSERT_TRUE(launcher_resp.settings.pmt_at_begin,
                    "set-prop: pmt_at_begin=true round-tripped to launcher");
        ASSERT_EQ_INT((int)launcher_resp.settings.solve_mode, (int)SOLVE_STEP_BY_STEP,
                      "set-prop: solve_mode=SBS round-tripped to launcher");
        ASSERT_EQ_INT((int)launcher_resp.settings.integ_method, (int)METHOD_USUB,
                      "set-prop: integ_method=USUB round-tripped to launcher");

        state.has_pending_response = 0;
        state.settings = launcher_resp.settings;
        state.last_answer = launcher_resp.last_answer;
        ASSERT_TRUE(ce_state_save(&state), "set-prop: clear pending");
        ce_response_delete();
        ASSERT_TRUE(!ce_response_read(&launcher_resp), "set-prop: CE_RESP deleted");

        mem_free_all();
        steps_clear();
        fileioc_mock_reset();
    }

    /* ── Round B: Default radians setting, verify not contaminated ── */
    {
        settings_t rad_settings;
        ce_state_defaults(&state);
        rad_settings = state.settings;
        /* Default is ANGLE_RADIANS */
        ASSERT_EQ_INT((int)rad_settings.angle_mode, (int)ANGLE_RADIANS,
                      "set-prop: default angle_mode is RADIANS");

        memset(&req, 0, sizeof(req));
        req.magic = CE_IPC_MAGIC;
        req.version = CE_IPC_VERSION;
        req.domain = CE_DOMAIN_STAT;
        req.settings = rad_settings;
        req.last_answer = 0.0f;
        strncpy(req.caller, "CALCENG", 8);
        strncpy(req.return_to, "CALCENG", 8);
        strncpy(req.expression, "mean(1,2,3)", MAX_INPUT_LEN - 1);

        ASSERT_TRUE(ce_request_write(&req),  "set-prop-b: write req");
        ASSERT_TRUE(ce_state_save(&state),    "set-prop-b: save state");

        root = NULL; had_equals = false;
        g_settings = state.settings;
        g_last_answer = 0.0f;
        steps_clear();

        memset(&worker_req, 0, sizeof(worker_req));
        memset(&worker_resp, 0, sizeof(worker_resp));
        ASSERT_TRUE(ce_module_runtime_load(&worker_req, &worker_resp, &state,
                                           &root, &had_equals),
                    "set-prop-b: runtime load");

        ASSERT_EQ_INT((int)worker_req.settings.angle_mode, (int)ANGLE_RADIANS,
                      "set-prop-b: default angle_mode=RAD preserved");
        ASSERT_EQ_INT((int)worker_req.settings.integ_method, (int)METHOD_AUTO,
                      "set-prop-b: default integ_method=AUTO preserved");

        memset(&worker_resp, 0, sizeof(worker_resp));
        g_settings = worker_req.settings;
        ASSERT_TRUE(ce_processor_run(worker_req.expression, &worker_resp),
                    "set-prop-b: processor run");
        ASSERT_TRUE(worker_resp.ok, "set-prop-b: mean result ok");
        ASSERT_STR_CONTAINS(worker_resp.result, "2", "set-prop-b: mean(1,2,3)=2");

        ce_module_runtime_finish(&worker_req, &worker_resp, &state);

        memset(&state, 0xFF, sizeof(state));
        ASSERT_TRUE(ce_state_load(&state), "set-prop-b: re-entry load");
        ASSERT_EQ_INT(state.has_pending_response, 1,
                      "set-prop-b: has_pending = 1");
        ASSERT_TRUE(ce_response_read(&launcher_resp), "set-prop-b: read resp");
        ASSERT_EQ_INT(launcher_resp.ok, 1, "set-prop-b: resp ok");
        ASSERT_EQ_INT((int)launcher_resp.settings.angle_mode, (int)ANGLE_RADIANS,
                      "set-prop-b: RAD setting round-tripped");

        state.has_pending_response = 0;
        state.settings = launcher_resp.settings;
        state.last_answer = launcher_resp.last_answer;
        ASSERT_TRUE(ce_state_save(&state), "set-prop-b: clear pending");
        ce_response_delete();

        mem_free_all();
        steps_clear();
        fileioc_mock_reset();
    }

    g_settings = saved_settings;
    g_last_answer = saved_last_answer;
    fileioc_mock_disable();
    fileioc_mock_reset();
}

