        ce_module_runtime_finish(&worker_req, &worker_resp, &state);

        memset(&state, 0xFF, sizeof(state));
        ASSERT_TRUE(ce_state_load(&state), "dc-geo: re-entry load");
        ASSERT_EQ_INT(state.has_pending_response, 1, "dc-geo: has_pending = 1");
        ASSERT_TRUE(ce_response_read(&launcher_resp), "dc-geo: read resp");
        ASSERT_EQ_INT(launcher_resp.ok, 1, "dc-geo: launcher resp ok");
