static void test_solver_all_method_names(void)
{
    int m;

    printf("=== Solver All Method Names ===\n");

    /* Four method names not covered by the existing method_names test */
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_SERIES), "Series",
                        "method_name: SERIES");
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_TANGENT), "Tangent",
                        "method_name: TANGENT");
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_INTEGRATE_TRIGSUB), "trig",
                        "method_name: INTEGRATE_TRIGSUB");
    ASSERT_STR_CONTAINS(solver_method_name(SOLVE_METHOD_INTEGRATE_PARTIAL_FRAC), "partial",
                        "method_name: INTEGRATE_PARTIAL_FRAC");

    /* Verify total count */
    ASSERT_EQ_INT((int)SOLVE_METHOD_COUNT, 16, "method_count = 16");

    /* Every method in range returns a non-NULL, non-empty name */
    for (m = 0; m < (int)SOLVE_METHOD_COUNT; m++) {
        const char *name = solver_method_name((solve_method_t)m);
        ASSERT_TRUE(name != NULL, "method_name: all non-NULL");
        ASSERT_TRUE((int)strlen(name) > 0, "method_name: all non-empty");
    }
}

static void test_solver_tangent_and_taylor(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Solver Tangent And Taylor ===\n");

    /* tangent(x^2, x, 2): f'(2)=4, f(2)=4, line y=4x-4 */
    ASSERT_TRUE(processor_run_expr("tangent(x^2,x,2)", &resp, &domain, &program),
                "tangent: processor run");
    ASSERT_TRUE(resp.ok, "tangent: ok");
    ASSERT_STR_CONTAINS(resp.result, "4", "tangent: slope 4 in result");
    ASSERT_TRUE(resp.step_count >= 2, "tangent: at least 2 steps");

    /* taylor(exp(x), x, 0, 3): 1 + x + x^2/2 + x^3/6 */
    ASSERT_TRUE(processor_run_expr("taylor(exp(x),x,0,3)", &resp, &domain, &program),
                "taylor: processor run");
    ASSERT_TRUE(resp.ok, "taylor: ok");
    ASSERT_STR_CONTAINS(resp.result, "x^3", "taylor: has x^3 term");
    ASSERT_TRUE(resp.step_count >= 3, "taylor: at least 3 steps");
}

static void test_solver_factor_and_expand(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Solver Factor And Expand ===\n");

    /* factor(x^2-9, x) => (x-3)*(x+3) */
    ASSERT_TRUE(processor_run_expr("factor(x^2-9,x)", &resp, &domain, &program),
                "factor: processor run");
    ASSERT_TRUE(resp.ok, "factor: ok");
    ASSERT_STR_CONTAINS(resp.result, "3", "factor: result contains 3");
    ASSERT_TRUE(resp.step_count >= 2, "factor: at least 2 steps");

    /* expand((x+2)^2) => x^2 + 4*x + 4 */
    ASSERT_TRUE(processor_run_expr("expand((x+2)^2)", &resp, &domain, &program),
                "expand: processor run");
    ASSERT_TRUE(resp.ok, "expand: ok");
    ASSERT_STR_CONTAINS(resp.result, "x^2", "expand: result contains x^2");
    ASSERT_STR_CONTAINS(resp.result, "4", "expand: result contains 4");
    ASSERT_TRUE(resp.step_count >= 1, "expand: at least 1 step");
}

