static void test_solver_method_applicable_extended(void)
{
    printf("=== Solver Method Applicable Extended ===\n");
    mem_free_all();
    steps_clear();

    /* FACTOR and EXPAND not applicable to a plain numeric constant */
    {
        ast_node_t *expr = parse_str("5");
        ASSERT_TRUE(expr != NULL, "applicable: parse constant 5");
        if (expr) {
            ASSERT_TRUE(!solver_method_applicable(expr, SOLVE_METHOD_FACTOR),
                        "applicable: factor not applicable to constant");
            ASSERT_TRUE(!solver_method_applicable(expr, SOLVE_METHOD_EXPAND),
                        "applicable: expand not applicable to constant");
            ASSERT_TRUE(solver_method_applicable(expr, SOLVE_METHOD_DIRECT_EVAL),
                        "applicable: direct-eval applicable to constant");
            ast_free(expr);
        }
    }
    mem_free_all();
    steps_clear();

    /* DIFFERENTIATE applicable to a derivative node (d/dx syntax) */
    {
        ast_node_t *expr = parse_str("d/dx(x^2)");
        ASSERT_TRUE(expr != NULL, "applicable: parse d/dx(x^2)");
        if (expr) {
            ASSERT_TRUE(solver_method_applicable(expr, SOLVE_METHOD_DIFFERENTIATE),
                        "applicable: differentiate applicable to deriv node");
            ast_free(expr);
        }
    }
    mem_free_all();
    steps_clear();

    /* SOLVE_EQUATION applicable to solve node */
    {
        ast_node_t *expr = parse_str("solve(x^2=9,x)");
        ASSERT_TRUE(expr != NULL, "applicable: parse solve node");
        if (expr) {
            ASSERT_TRUE(solver_method_applicable(expr, SOLVE_METHOD_SOLVE_EQUATION),
                        "applicable: solve_equation applicable to solve node");
            ast_free(expr);
        }
    }
    mem_free_all();
    steps_clear();
}

static void test_solver_consecutive_calls(void)
{
    printf("=== Solver Consecutive Calls ===\n");
    mem_free_all();
    steps_clear();

    /* Call 1: differentiate x^3 => 3*x^2 (using correct d/dx syntax) */
    {
        solve_result_t result;
        ast_node_t *expr = parse_str("d/dx(x^3)");
        ASSERT_TRUE(expr != NULL, "consecutive: parse d/dx(x^3)");
        if (expr) {
            solver_solve_full(expr, &result);
            ASSERT_TRUE(result.complete, "consecutive: deriv complete");
            ASSERT_EQ_INT((int)result.error, (int)CE_OK, "consecutive: deriv no error");
            ASSERT_STR_CONTAINS(result.final_result, "x^2", "consecutive: deriv has x^2");
        }
    }
    mem_free_all();
    steps_clear();

    /* Call 2: integrate 2*x => x^2 + C */
    {
        solve_result_t result;
        ast_node_t *expr = parse_str("int(2*x,x)");
        ASSERT_TRUE(expr != NULL, "consecutive: parse int(2*x,x)");
        if (expr) {
            solver_solve_full(expr, &result);
            ASSERT_TRUE(result.complete, "consecutive: integral complete");
            ASSERT_EQ_INT((int)result.error, (int)CE_OK, "consecutive: integral no error");
            ASSERT_STR_CONTAINS(result.final_result, "x^2", "consecutive: integral has x^2");
        }
    }
    mem_free_all();
    steps_clear();

    /* Call 3: arithmetic 3+4 => 7 */
    {
        solve_result_t result;
        ast_node_t *expr = parse_str("3+4");
        ASSERT_TRUE(expr != NULL, "consecutive: parse 3+4");
        if (expr) {
            solver_solve_full(expr, &result);
            ASSERT_TRUE(result.complete, "consecutive: arith complete");
            ASSERT_EQ_INT((int)result.error, (int)CE_OK, "consecutive: arith no error");
            ASSERT_STR_CONTAINS(result.final_result, "7", "consecutive: arith result 7");
            ast_free(expr);
        }
    }
    mem_free_all();
    steps_clear();
}

static void test_solver_solve_equation_extended(void)
{
    ce_response_t resp;
    ce_domain_t domain;
    const char *program = NULL;

    printf("=== Solver Solve Equation Extended ===\n");

    /* Linear: x + 5 = 0 => x = -5 */
    ASSERT_TRUE(processor_run_expr("solve(x+5=0,x)", &resp, &domain, &program),
                "solve_eq_ext: linear processor run");
    ASSERT_TRUE(resp.ok, "solve_eq_ext: linear ok");
    ASSERT_STR_CONTAINS(resp.result, "-5", "solve_eq_ext: x=-5");

    /* Linear: 2*x = 6 => x = 3 */
    ASSERT_TRUE(processor_run_expr("solve(2*x=6,x)", &resp, &domain, &program),
                "solve_eq_ext: 2x=6 processor run");
    ASSERT_TRUE(resp.ok, "solve_eq_ext: 2x=6 ok");
    ASSERT_STR_CONTAINS(resp.result, "3", "solve_eq_ext: x=3");

    /* Quadratic: x^2 - 5*x + 6 = 0 => x=2 or x=3 */
    ASSERT_TRUE(processor_run_expr("solve(x^2-5*x+6=0,x)", &resp, &domain, &program),
                "solve_eq_ext: quadratic processor run");
    ASSERT_TRUE(resp.ok, "solve_eq_ext: quadratic ok");
    ASSERT_STR_CONTAINS(resp.result, "2", "solve_eq_ext: root x=2");
    ASSERT_STR_CONTAINS(resp.result, "3", "solve_eq_ext: root x=3");
    ASSERT_TRUE(resp.step_count >= 4, "solve_eq_ext: quadratic has steps");
}

static void test_complex_special_values(void)
{
    ce_complex_t z, r;

    printf("=== Complex Special Values ===\n");

    /* ctan(pi/4) = 1 */
    z.re = (ce_float_t)CE_PI / 4.0f; z.im = 0.0f;
    r = ctan_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "ctan(pi/4) re = 1");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "ctan(pi/4) im = 0");

    /* csec(0) = 1/cos(0) = 1 */
    z.re = 0.0f; z.im = 0.0f;
    r = csec_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "csec(0) re = 1");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "csec(0) im = 0");

    /* ccsc(pi/2) = 1/sin(pi/2) = 1 */
    z.re = (ce_float_t)CE_PI / 2.0f; z.im = 0.0f;
    r = ccsc_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "ccsc(pi/2) re = 1");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "ccsc(pi/2) im = 0");

    /* ccot(pi/4) = cos/sin = 1 */
    z.re = (ce_float_t)CE_PI / 4.0f; z.im = 0.0f;
    r = ccot_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "ccot(pi/4) re = 1");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "ccot(pi/4) im = 0");

    /* casin(0) = 0 */
    z.re = 0.0f; z.im = 0.0f;
    r = casin_z(z);
    ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "casin(0) re = 0");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "casin(0) im = 0");

    /* cacos(1) = 0 */
    z.re = 1.0f; z.im = 0.0f;
    r = cacos_z(z);
    ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "cacos(1) re = 0");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "cacos(1) im = 0");

    /* catan(0) = 0 */
    z.re = 0.0f; z.im = 0.0f;
    r = catan_z(z);
    ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "catan(0) re = 0");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "catan(0) im = 0");

    /* casin(1) = pi/2 */
    z.re = 1.0f; z.im = 0.0f;
    r = casin_z(z);
    ASSERT_EQ_FLOAT(r.re, (ce_float_t)CE_PI / 2.0f, 0.01f, "casin(1) re = pi/2");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "casin(1) im = 0");
}

static void test_complex_hyperbolic_identities(void)
{
    printf("=== Complex Hyperbolic Identities ===\n");

    /* csinh(0)=0, ccosh(0)=1, ctanh(0)=0 */
    {
        ce_complex_t z, s, c, t;
        z.re = 0.0f; z.im = 0.0f;
        s = csinh_z(z);
        c = ccosh_z(z);
        t = ctanh_z(z);
        ASSERT_EQ_FLOAT(s.re, 0.0f, 0.01f, "csinh(0) re = 0");
        ASSERT_EQ_FLOAT(s.im, 0.0f, 0.01f, "csinh(0) im = 0");
        ASSERT_EQ_FLOAT(c.re, 1.0f, 0.01f, "ccosh(0) re = 1");
        ASSERT_EQ_FLOAT(c.im, 0.0f, 0.01f, "ccosh(0) im = 0");
        ASSERT_EQ_FLOAT(t.re, 0.0f, 0.01f, "ctanh(0) re = 0");
        ASSERT_EQ_FLOAT(t.im, 0.0f, 0.01f, "ctanh(0) im = 0");
    }

    /* ccosh(1)~=1.5431, csinh(1)~=1.1752; identity cosh^2-sinh^2=1 */
    {
        ce_complex_t z, s, c;
        ce_float_t identity;
        z.re = 1.0f; z.im = 0.0f;
        s = csinh_z(z);
        c = ccosh_z(z);
        ASSERT_EQ_FLOAT(s.re, 1.1752f, 0.001f, "csinh(1) ~= 1.1752");
        ASSERT_EQ_FLOAT(s.im, 0.0f, 0.01f, "csinh(1) im = 0");
        ASSERT_EQ_FLOAT(c.re, 1.5431f, 0.001f, "ccosh(1) ~= 1.5431");
        ASSERT_EQ_FLOAT(c.im, 0.0f, 0.01f, "ccosh(1) im = 0");
        identity = c.re * c.re - s.re * s.re;
        ASSERT_EQ_FLOAT(identity, 1.0f, 0.01f, "cosh^2(1)-sinh^2(1) = 1");
    }

    /* ctanh(1) ~= 0.7616 */
    {
        ce_complex_t z, t;
        z.re = 1.0f; z.im = 0.0f;
        t = ctanh_z(z);
        ASSERT_EQ_FLOAT(t.re, 0.7616f, 0.001f, "ctanh(1) ~= 0.7616");
        ASSERT_EQ_FLOAT(t.im, 0.0f, 0.01f, "ctanh(1) im = 0");
    }

    /* casinh(0) = 0 */
    {
        ce_complex_t z, r;
        z.re = 0.0f; z.im = 0.0f;
        r = casinh_z(z);
        ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "casinh(0) re = 0");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "casinh(0) im = 0");
    }

    /* cacosh(1) = 0 */
    {
        ce_complex_t z, r;
        z.re = 1.0f; z.im = 0.0f;
        r = cacosh_z(z);
        ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "cacosh(1) re = 0");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "cacosh(1) im = 0");
    }

    /* catanh(0) = 0 */
    {
        ce_complex_t z, r;
        z.re = 0.0f; z.im = 0.0f;
        r = catanh_z(z);
        ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "catanh(0) re = 0");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "catanh(0) im = 0");
    }
}

static void test_complex_power_and_log(void)
{
    printf("=== Complex Power And Log ===\n");

    /* cln(-1) = i*pi: ln|-1|=0, arg(-1)=pi */
    {
        ce_complex_t z, r;
        z.re = -1.0f; z.im = 0.0f;
        r = cln_z(z);
        ASSERT_EQ_FLOAT(r.re, 0.0f, 0.01f, "cln(-1) re = 0");
        ASSERT_EQ_FLOAT(r.im, (ce_float_t)CE_PI, 0.01f, "cln(-1) im = pi");
    }

    /* cln(e) ~= 1 */
    {
        ce_complex_t z, r;
        z.re = 2.71828f; z.im = 0.0f;
        r = cln_z(z);
        ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "cln(e) re = 1");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "cln(e) im = 0");
    }

    /* ce_cpow(i, 2) = i^2 = -1 */
    {
        ce_complex_t base, exp_c, r;
        base.re = 0.0f; base.im = 1.0f;
        exp_c.re = 2.0f; exp_c.im = 0.0f;
        r = ce_cpow(base, exp_c);
        ASSERT_EQ_FLOAT(r.re, -1.0f, 0.01f, "i^2 re = -1");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.05f, "i^2 im ~ 0");
    }

    /* ce_cpow(4, 0.5) = sqrt(4) = 2 */
    {
        ce_complex_t base, exp_c, r;
        base.re = 4.0f; base.im = 0.0f;
        exp_c.re = 0.5f; exp_c.im = 0.0f;
        r = ce_cpow(base, exp_c);
        ASSERT_EQ_FLOAT(r.re, 2.0f, 0.01f, "4^0.5 re = 2");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "4^0.5 im = 0");
    }

    /* ce_cpow(2, 3) = 8 */
    {
        ce_complex_t base, exp_c, r;
        base.re = 2.0f; base.im = 0.0f;
        exp_c.re = 3.0f; exp_c.im = 0.0f;
        r = ce_cpow(base, exp_c);
        ASSERT_EQ_FLOAT(r.re, 8.0f, 0.05f, "2^3 re = 8");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.05f, "2^3 im = 0");
    }

    /* ce_cpow(1, 3) = 1 */
    {
        ce_complex_t base, exp_c, r;
        base.re = 1.0f; base.im = 0.0f;
        exp_c.re = 3.0f; exp_c.im = 0.0f;
        r = ce_cpow(base, exp_c);
        ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "1^3 re = 1");
        ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "1^3 im = 0");
    }
}

static void test_complex_evaluator_with_ast(void)
{
    eval_ctx_t ctx;

    printf("=== Complex Evaluator With AST ===\n");
    mem_free_all();
    g_settings.complex_mode = COMPLEX_RECT;

    /* 1+2i = {1, 2} (explicit imaginary literal) */
    {
        ast_node_t *root;
        ce_complex_t cv;
        g_settings.complex_mode = COMPLEX_RECT;
        root = parse_str("1+2i");
        ASSERT_TRUE(root != NULL, "ceval_ast: parse 1+2i");
        if (root) {
            eval_init(&ctx);
            cv = ceval_expr(&ctx, root);
            ASSERT_EQ_FLOAT(cv.re, 1.0f, 0.01f, "ceval_ast 1+2i re = 1");
            ASSERT_EQ_FLOAT(cv.im, 2.0f, 0.01f, "ceval_ast 1+2i im = 2");
            ast_free(root);
        }
    }
    mem_free_all();

    /* i*i = i^2 = -1 + 0i */
    {
        ast_node_t *root;
        ce_complex_t cv;
        g_settings.complex_mode = COMPLEX_RECT;
        root = parse_str("i*i");
        ASSERT_TRUE(root != NULL, "ceval_ast: parse i*i");
        if (root) {
            eval_init(&ctx);
            cv = ceval_expr(&ctx, root);
            ASSERT_EQ_FLOAT(cv.re, -1.0f, 0.01f, "ceval_ast i*i re = -1");
            ASSERT_EQ_FLOAT(cv.im, 0.0f, 0.01f, "ceval_ast i*i im = 0");
            ast_free(root);
        }
    }
    mem_free_all();

    /* sin(0) = 0 via complex path */
    {
        ast_node_t *root;
        ce_complex_t cv;
        g_settings.complex_mode = COMPLEX_RECT;
        root = parse_str("sin(0)");
        ASSERT_TRUE(root != NULL, "ceval_ast: parse sin(0)");
        if (root) {
            eval_init(&ctx);
            cv = ceval_expr(&ctx, root);
            ASSERT_EQ_FLOAT(cv.re, 0.0f, 0.01f, "ceval_ast sin(0) re = 0");
            ASSERT_EQ_FLOAT(cv.im, 0.0f, 0.01f, "ceval_ast sin(0) im = 0");
            ast_free(root);
        }
    }
    mem_free_all();

    /* cos(0) = 1 via complex path */
    {
        ast_node_t *root;
        ce_complex_t cv;
        g_settings.complex_mode = COMPLEX_RECT;
        root = parse_str("cos(0)");
        ASSERT_TRUE(root != NULL, "ceval_ast: parse cos(0)");
        if (root) {
            eval_init(&ctx);
            cv = ceval_expr(&ctx, root);
            ASSERT_EQ_FLOAT(cv.re, 1.0f, 0.01f, "ceval_ast cos(0) re = 1");
            ASSERT_EQ_FLOAT(cv.im, 0.0f, 0.01f, "ceval_ast cos(0) im = 0");
            ast_free(root);
        }
    }
    mem_free_all();
}

static void test_history_navigation_edge_cases(void)
{
    printf("=== History Navigation Edge Cases ===\n");

    history_clear();

    /* forward from initial position stays at -1 */
    ASSERT_EQ_INT(history_navigate_position(), -1, "nav_edge: initial=-1");
    ASSERT_EQ_INT(history_navigate_forward(), -1, "nav_edge: forward from -1 stays -1");

    /* single-entry: back goes to 0, back again stays, forward returns to -1 */
    history_push("x", "1", 1.0f, true);
    ASSERT_EQ_INT(history_navigate_back(), 0, "nav_edge: back to 0");
    ASSERT_EQ_INT(history_navigate_back(), 0, "nav_edge: back again stays 0");
    ASSERT_EQ_INT(history_navigate_forward(), -1, "nav_edge: forward to -1");
    ASSERT_EQ_INT(history_navigate_forward(), -1, "nav_edge: forward again stays -1");

    /* get returns NULL and count = 0 after clear */
    history_clear();
    ASSERT_TRUE(history_get(0) == NULL, "nav_edge: get after clear = NULL");
    ASSERT_EQ_INT(history_count(), 0, "nav_edge: count after clear = 0");

    /* push during navigation resets position to -1 */
    history_push("a", "1", 1.0f, true);
    history_push("b", "2", 2.0f, true);
    history_navigate_back();
    history_navigate_back();
    ASSERT_EQ_INT(history_navigate_position(), 1, "nav_edge: at position 1");
    ASSERT_TRUE(history_push("c", "3", 3.0f, true), "nav_edge: push during nav");
    ASSERT_EQ_INT(history_navigate_position(), -1, "nav_edge: push resets nav to -1");
    ASSERT_EQ_INT(history_count(), 3, "nav_edge: count=3 after push");
    ASSERT_STR_CONTAINS(history_get_input(0), "c", "nav_edge: newest is c");

    history_clear();
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 40: Module Forward Guards, Null Write Guards, Transfer Package Catalog
 *
 * New coverage areas:
 *  - ce_module_runtime_forward(): all null/empty arg guards, missing-program
 *    error path, and no-response error path (os_RunPrgm mock does nothing).
 *  - Null pointer guards on ce_request_write, ce_response_write, ce_state_save,
 *    and ce_response_from_runtime when passed NULL.
 *  - Transfer package program name constants: non-empty, <=8 chars, domain
 *    mapping consistency, AppVar name constraints.
 * ═══════════════════════════════════════════════════════════════════════ */

static void test_ipc_module_forward_guards(void)
{
    ce_request_t req;
    ce_response_t resp;
    ce_shared_state_t state;
    char err[128];
    settings_t saved_settings = g_settings;
    ce_float_t saved_last_answer = g_last_answer;

    printf("=== IPC Module Forward Guards ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();
    steps_clear();
    mem_free_all();

    /* Build a minimal valid request */
    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    req.domain = CE_DOMAIN_ALG;
    req.settings.angle_mode = ANGLE_RADIANS;
    req.settings.precision = 6;
    req.settings.show_steps = true;
    req.settings.complex_mode = COMPLEX_OFF;
    req.settings.pmt_at_begin = false;
    req.settings.step_detail = STEP_ALL;
    req.settings.solve_mode = SOLVE_FULL_AUTO;
    req.settings.integ_method = METHOD_AUTO;
    strncpy(req.caller, "CALCENG", 8);
    strncpy(req.return_to, "CALCENG", 8);
    strncpy(req.expression, "x+1", MAX_INPUT_LEN - 1);
    ce_state_defaults(&state);
    memset(&resp, 0, sizeof(resp));
    g_settings = state.settings;
    g_last_answer = 0.0f;

    /* NULL caller */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward(NULL, "CEALG", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: null caller => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: null caller => Invalid in error");

    /* Empty caller */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("", "CEALG", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: empty caller => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: empty caller => Invalid in error");

    /* NULL program */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", NULL, &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: null program => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: null program => Invalid in error");

    /* Empty program */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: empty program => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: empty program => Invalid in error");

    /* NULL req */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "CEALG", NULL, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: null req => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: null req => Invalid in error");

    /* NULL state */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "CEALG", &req, NULL, &resp,
                                           err, sizeof(err)),
                "mfwd: null state => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: null state => Invalid in error");

    /* NULL resp */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "CEALG", &req, &state, NULL,
                                           err, sizeof(err)),
                "mfwd: null resp => false");
    ASSERT_STR_CONTAINS(err, "Invalid", "mfwd: null resp => Invalid in error");

    /* NULL err_buf is safe — must not crash */
    ASSERT_TRUE(!ce_module_runtime_forward(NULL, "CEALG", &req, &state, &resp,
                                           NULL, 0),
                "mfwd: null err_buf no crash, still returns false");

    /* Zero-length err_buf: writes nothing but must not crash */
    err[0] = 'X';
    ASSERT_TRUE(!ce_module_runtime_forward(NULL, "CEALG", &req, &state, &resp,
                                           err, 0),
                "mfwd: zero err_buf_size no crash");
    ASSERT_EQ_INT(err[0], 'X', "mfwd: zero buf => buffer untouched");

    /* Program NOT registered in mock → ce_program_ensure_ram fails → "Module X missing" */
    fileioc_mock_reset();
    ce_state_defaults(&state);
    g_settings = state.settings;
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "MISSINGX", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: missing program => false");
    ASSERT_STR_CONTAINS(err, "MISSINGX", "mfwd: missing program => name in error");
    ASSERT_TRUE(ce_state_load(&state), "mfwd: missing program state reload");
    ASSERT_STR_EQ(state.pending_module, "CALCENG",
                  "mfwd: missing program restores caller as pending module");

    /* Program exists in mock RAM but os_RunPrgm (mock) does not write CE_RESP
     * → ce_response_read fails → "No module response" */
    fileioc_mock_reset();
    ce_state_defaults(&state);
    g_settings = state.settings;
    g_last_answer = 0.0f;
    fileioc_mock_add_program("CEALG", 0);   /* register as RAM program */
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CALCENG", "CEALG", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: no CE_RESP written => false");
    ASSERT_STR_CONTAINS(err, "No module response",
                        "mfwd: no CE_RESP => 'No module response' in err");
    ASSERT_TRUE(ce_state_load(&state), "mfwd: no response state reload");
    ASSERT_STR_EQ(state.pending_module, "CALCENG",
                  "mfwd: no response keeps caller pending for recovery");

    fileioc_mock_reset();
    ce_state_defaults(&state);
    state.has_pending_response = 0;
    strncpy(state.pending_module, "CEASLV", sizeof(state.pending_module) - 1);
    err[0] = '\0';
    ASSERT_TRUE(!ce_module_runtime_forward("CEALG", "CEASLA", &req, &state, &resp,
                                           err, sizeof(err)),
                "mfwd: active child blocks re-entry forward");
    ASSERT_STR_CONTAINS(err, "busy", "mfwd: active child reports busy runtime");

    g_settings = saved_settings;
    g_last_answer = saved_last_answer;
    fileioc_mock_disable();
    fileioc_mock_reset();
    steps_clear();
    mem_free_all();
}

static void test_ipc_module_runtime_resume_forward(void)
{
    ce_request_t req;
    ce_response_t resp;
    ce_shared_state_t state;
    ce_shared_state_t saved_state;

    printf("=== IPC Module Runtime Resume Forward ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    strncpy(req.caller, "CALCENG", sizeof(req.caller) - 1);
    strncpy(req.return_to, "CEALG", sizeof(req.return_to) - 1);
    strncpy(req.expression, "x^2=4", sizeof(req.expression) - 1);
    ASSERT_TRUE(ce_request_write(&req), "resume-fwd: request write succeeds");

    ce_state_defaults(&state);
    state.has_pending_response = 1;
    strncpy(state.pending_module, "CEASLV", sizeof(state.pending_module) - 1);
    ASSERT_TRUE(ce_state_save(&state), "resume-fwd: state write succeeds");
    g_settings = state.settings;
    g_last_answer = 4.0f;
    ce_response_from_runtime(&resp, true, false, "x = 2 or x = -2", "", 4.0f);
    ASSERT_TRUE(ce_response_write(&resp), "resume-fwd: child response write succeeds");

    fileioc_mock_add_program("CEALG", 0);
    fileioc_mock_add_program("CEASLV", 0);

    ASSERT_TRUE(ce_module_runtime_resume_forward("CEALG", &req, &state),
                "resume-fwd: matching return_to resumes");
    ASSERT_TRUE(ce_state_load(&saved_state), "resume-fwd: saved state reloads");
    ASSERT_STR_EQ(saved_state.pending_module, "CEALG",
                  "resume-fwd: parent becomes pending module");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEASLV", OS_TYPE_PRGM), 1,
                  "resume-fwd: child module re-archived");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 0,
                  "resume-fwd: parent remains in RAM for launcher cleanup");

    fileioc_mock_reset();
    ce_state_defaults(&state);
    state.has_pending_response = 1;
    strncpy(state.pending_module, "CEASLV", sizeof(state.pending_module) - 1);
    strncpy(req.return_to, "CECLIM", sizeof(req.return_to) - 1);
    ASSERT_TRUE(ce_request_write(&req), "resume-fwd: mismatch request write succeeds");
    ASSERT_TRUE(ce_state_save(&state), "resume-fwd: mismatch state write succeeds");
    fileioc_mock_add_program("CEASLV", 0);
    ASSERT_TRUE(!ce_module_runtime_resume_forward("CEALG", &req, &state),
                "resume-fwd: mismatched return_to ignored");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEASLV", OS_TYPE_PRGM), 0,
                  "resume-fwd: ignored path leaves child untouched");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_module_runtime_recover_child_failure(void)
{
    ce_request_t req;
    ce_response_t bad_resp;
    ce_shared_state_t state;
    ce_shared_state_t saved_state;
    char err[128];

    printf("=== IPC Module Runtime Recover Child Failure ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    strncpy(req.caller, "CALCENG", sizeof(req.caller) - 1);
    strncpy(req.return_to, "CEALG", sizeof(req.return_to) - 1);
    strncpy(req.expression, "solve(x^2=4,x)", sizeof(req.expression) - 1);
    ASSERT_TRUE(ce_request_write(&req), "recover-fwd: request write succeeds");

    ce_state_defaults(&state);
    state.has_pending_response = 0;
    strncpy(state.pending_module, "CEASLV", sizeof(state.pending_module) - 1);
    ASSERT_TRUE(ce_state_save(&state), "recover-fwd: unanswered child state saved");
    fileioc_mock_add_program("CEALG", 0);
    fileioc_mock_add_program("CEASLV", 0);

    err[0] = '\0';
    ASSERT_TRUE(ce_module_runtime_recover_child_failure("CEALG", "CEALG",
                                                        &req, &state,
                                                        err, sizeof(err)),
                "recover-fwd: unanswered child recovered");
    ASSERT_STR_CONTAINS(err, "CEASLV", "recover-fwd: error names child");
    ASSERT_STR_CONTAINS(err, "no IPC response", "recover-fwd: unanswered child mentions IPC");
    ASSERT_TRUE(ce_state_load(&saved_state), "recover-fwd: recovered state reloads");
    ASSERT_EQ_INT(saved_state.has_pending_response, 0,
                  "recover-fwd: pending response cleared");
    ASSERT_STR_EQ(saved_state.pending_module, "CEALG",
                  "recover-fwd: parent marked pending after recovery");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEASLV", OS_TYPE_PRGM), 1,
                  "recover-fwd: child archived after unanswered recovery");

    fileioc_mock_reset();
    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    strncpy(req.caller, "CALCENG", sizeof(req.caller) - 1);
    strncpy(req.return_to, "CEALG", sizeof(req.return_to) - 1);
    strncpy(req.expression, "solve(x^2=4,x)", sizeof(req.expression) - 1);
    ASSERT_TRUE(ce_request_write(&req), "recover-fwd: invalid response request write succeeds");
    ce_state_defaults(&state);
    state.has_pending_response = 1;
    strncpy(state.pending_module, "CEASLV", sizeof(state.pending_module) - 1);
    ASSERT_TRUE(ce_state_save(&state), "recover-fwd: invalid response state save");
    memset(&bad_resp, 0, sizeof(bad_resp));
    bad_resp.magic = 0;
    bad_resp.version = CE_IPC_VERSION;
    ASSERT_TRUE(ce_response_write(&bad_resp), "recover-fwd: invalid response payload written");
    fileioc_mock_add_program("CEALG", 0);
    fileioc_mock_add_program("CEASLV", 0);

    err[0] = '\0';
    ASSERT_TRUE(ce_module_runtime_recover_child_failure("CEALG", "CEALG",
                                                        &req, &state,
                                                        err, sizeof(err)),
                "recover-fwd: invalid child response recovered");
    ASSERT_STR_CONTAINS(err, "invalid IPC data",
                        "recover-fwd: invalid response reports IPC corruption");
    ASSERT_TRUE(!ce_response_read(&bad_resp),
                "recover-fwd: invalid response removed during recovery");

    fileioc_mock_reset();
    memset(&req, 0, sizeof(req));
    req.magic = CE_IPC_MAGIC;
    req.version = CE_IPC_VERSION;
    strncpy(req.caller, "CALCENG", sizeof(req.caller) - 1);
    strncpy(req.return_to, "CALCENG", sizeof(req.return_to) - 1);
    strncpy(req.expression, "2+2", sizeof(req.expression) - 1);
    ASSERT_TRUE(ce_request_write(&req), "recover-launcher: request write succeeds");
    ce_state_defaults(&state);
    state.has_pending_response = 0;
    strncpy(state.pending_module, "CEALG", sizeof(state.pending_module) - 1);
    ASSERT_TRUE(ce_state_save(&state), "recover-launcher: state save succeeds");
    fileioc_mock_add_program("CEALG", 0);

    err[0] = '\0';
    ASSERT_TRUE(ce_module_runtime_recover_child_failure("CALCENG", "",
                                                        &req, &state,
                                                        err, sizeof(err)),
                "recover-launcher: launcher recovers unanswered worker");
    ASSERT_TRUE(ce_state_load(&saved_state), "recover-launcher: state reloads");
    ASSERT_EQ_INT(saved_state.pending_module[0], '\0',
                  "recover-launcher: pending module cleared");
    ASSERT_EQ_INT(saved_state.has_pending_response, 0,
                  "recover-launcher: pending response remains cleared");
    ASSERT_EQ_INT(fileioc_mock_is_archived("CEALG", OS_TYPE_PRGM), 1,
                  "recover-launcher: worker archived after recovery");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_ipc_null_write_guards(void)
{
    printf("=== IPC Null Write Guards ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    /* ce_response_from_runtime(NULL,...): null guard early-returns, no crash */
    ce_response_from_runtime(NULL, true, false, "result", "error", 1.0f);
    ASSERT_TRUE(1, "null-write: ce_response_from_runtime(NULL) no crash");

    /* ce_request_write(NULL): write_struct_appvar passes NULL to ti_Write which
     * returns 0 (mock guards !data), so the write fails → returns false. */
    ASSERT_TRUE(!ce_request_write(NULL),
                "null-write: ce_request_write(NULL) returns false");

    /* ce_response_write(NULL): same path → false */
    ASSERT_TRUE(!ce_response_write(NULL),
                "null-write: ce_response_write(NULL) returns false");

    /* ce_state_save(NULL): write_struct_appvar("CE_STATE", NULL, sizeof(state))
     * → ti_Write with NULL data → mock returns 0 → false */
    ASSERT_TRUE(!ce_state_save(NULL),
                "null-write: ce_state_save(NULL) returns false");

    /* ce_response_delete on an empty store: no crash, no-op */
    fileioc_mock_reset();
    ce_response_delete();
    ASSERT_TRUE(1, "null-write: ce_response_delete on empty store no crash");

    /* ce_state_load(NULL): null guard → returns false immediately */
    ASSERT_TRUE(!ce_state_load(NULL),
                "null-write: ce_state_load(NULL) returns false");

    fileioc_mock_disable();
    fileioc_mock_reset();
}

static void test_transfer_package_program_catalog(void)
{
    printf("=== Transfer Package Program Catalog ===\n");

    /* All 9 top-level program name constants must be non-empty */
    ASSERT_TRUE(strlen(CE_PRGM_CORE) > 0,     "catalog: CE_PRGM_CORE non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_ALG) > 0,      "catalog: CE_PRGM_ALG non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_CALC) > 0,     "catalog: CE_PRGM_CALC non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_LIMSER) > 0,   "catalog: CE_PRGM_LIMSER non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_MAT) > 0,      "catalog: CE_PRGM_MAT non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_STATPROB) > 0, "catalog: CE_PRGM_STATPROB non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_GRAPH) > 0,    "catalog: CE_PRGM_GRAPH non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_FIN) > 0,      "catalog: CE_PRGM_FIN non-empty");
    ASSERT_TRUE(strlen(CE_PRGM_LISTCMPLX) > 0,"catalog: CE_PRGM_LISTCMPLX non-empty");

    /* TI-84 CE OS enforces 8-char max program name */
    ASSERT_TRUE(strlen(CE_PRGM_CORE) <= 8,     "catalog: CE_PRGM_CORE <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_ALG) <= 8,      "catalog: CE_PRGM_ALG <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_CALC) <= 8,     "catalog: CE_PRGM_CALC <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_LIMSER) <= 8,   "catalog: CE_PRGM_LIMSER <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_MAT) <= 8,      "catalog: CE_PRGM_MAT <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_STATPROB) <= 8, "catalog: CE_PRGM_STATPROB <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_GRAPH) <= 8,    "catalog: CE_PRGM_GRAPH <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_FIN) <= 8,      "catalog: CE_PRGM_FIN <=8 chars");
    ASSERT_TRUE(strlen(CE_PRGM_LISTCMPLX) <= 8,"catalog: CE_PRGM_LISTCMPLX <=8 chars");

    /* All 3 AppVar runtime names must be non-empty and <=8 chars
     * (CE_REQ, CE_RESP, CE_STATE are created at runtime — no pre-install needed) */
    ASSERT_TRUE(strlen(CE_APPVAR_REQ) > 0,   "catalog: CE_APPVAR_REQ non-empty");
    ASSERT_TRUE(strlen(CE_APPVAR_RESP) > 0,  "catalog: CE_APPVAR_RESP non-empty");
    ASSERT_TRUE(strlen(CE_APPVAR_STATE) > 0, "catalog: CE_APPVAR_STATE non-empty");
    ASSERT_TRUE(strlen(CE_APPVAR_REQ) <= 8,   "catalog: CE_APPVAR_REQ <=8 chars");
    ASSERT_TRUE(strlen(CE_APPVAR_RESP) <= 8,  "catalog: CE_APPVAR_RESP <=8 chars");
    ASSERT_TRUE(strlen(CE_APPVAR_STATE) <= 8, "catalog: CE_APPVAR_STATE <=8 chars");

    /* AppVars are distinct from each other */
    ASSERT_TRUE(strcmp(CE_APPVAR_REQ, CE_APPVAR_RESP) != 0,
                "catalog: CE_REQ != CE_RESP");
    ASSERT_TRUE(strcmp(CE_APPVAR_REQ, CE_APPVAR_STATE) != 0,
                "catalog: CE_REQ != CE_STATE");
    ASSERT_TRUE(strcmp(CE_APPVAR_RESP, CE_APPVAR_STATE) != 0,
                "catalog: CE_RESP != CE_STATE");

    /* Domain co-routing: LIMIT+SERIES+SEQ all go to LIMSER (one dispatcher) */
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_CALC_LIMIT),
                       ce_domain_program(CE_DOMAIN_CALC_SERIES)) == 0,
                "catalog: LIMIT and SERIES share LIMSER dispatcher");
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_CALC_SEQ),
                       ce_domain_program(CE_DOMAIN_CALC_LIMIT)) == 0,
                "catalog: SEQ also routes to LIMSER");

    /* STAT and PROB both go to STATPROB */
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_STAT),
                       ce_domain_program(CE_DOMAIN_PROB)) == 0,
                "catalog: STAT and PROB share STATPROB dispatcher");

    /* ALG family all route to the same top-level ALG dispatcher */
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_ALG),
                       ce_domain_program(CE_DOMAIN_ALG_ADV)) == 0,
                "catalog: ALG and ALG_ADV share ALG dispatcher");
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_ALG_EXPFAC),
                       ce_domain_program(CE_DOMAIN_ALG_GEO)) == 0,
                "catalog: ALG_EXPFAC and ALG_GEO share ALG dispatcher");

    /* CMPLX routes to LISTCMPLX (shared with list operations) */
    ASSERT_TRUE(strcmp(ce_domain_program(CE_DOMAIN_CMPLX),
                       CE_PRGM_LISTCMPLX) == 0,
                "catalog: CMPLX -> LISTCMPLX");

    /* IPC magic/version constants: magic != 0, version != 0 */
    ASSERT_TRUE(CE_IPC_MAGIC != 0,   "catalog: IPC magic non-zero");
    ASSERT_TRUE(CE_IPC_VERSION != 0, "catalog: IPC version non-zero");
    ASSERT_TRUE(CE_AST_WIRE_MAX > 0, "catalog: AST wire max > 0");
    ASSERT_TRUE(CE_HISTORY_SIZE > 0, "catalog: history size > 0");
}

/* ═══════════════════════════════════════════════════════════════════════
 * Pass 41: Desktop engine edge-case expansion
 * ═══════════════════════════════════════════════════════════════════════ */

/* ── Trig inverse round-trips ───────────────────────────────────────── */
static void test_pass41_trig_roundtrip(void)
{
    ce_error_t err;
    ce_float_t val;

    printf("=== Pass 41: Trig Roundtrip ===\n");
    mem_free_all();

    /* asin(sin(x)) = x for x in [-pi/2, pi/2] */
    val = eval_str("asin(sin(0.3))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: asin(sin(0.3)) no error");
    ASSERT_EQ_FLOAT(val, 0.3f, 0.01f, "trig-rt: asin(sin(0.3)) = 0.3");

    val = eval_str("asin(sin(0.7))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: asin(sin(0.7)) no error");
    ASSERT_EQ_FLOAT(val, 0.7f, 0.01f, "trig-rt: asin(sin(0.7)) = 0.7");

    /* acos(cos(x)) = x for x in [0, pi] */
    val = eval_str("acos(cos(0.4))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: acos(cos(0.4)) no error");
    ASSERT_EQ_FLOAT(val, 0.4f, 0.01f, "trig-rt: acos(cos(0.4)) = 0.4");

    val = eval_str("acos(cos(1.2))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: acos(cos(1.2)) no error");
    ASSERT_EQ_FLOAT(val, 1.2f, 0.01f, "trig-rt: acos(cos(1.2)) = 1.2");

    /* atan(tan(x)) = x for x in (-pi/2, pi/2) */
    val = eval_str("atan(tan(0.5))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: atan(tan(0.5)) no error");
    ASSERT_EQ_FLOAT(val, 0.5f, 0.01f, "trig-rt: atan(tan(0.5)) = 0.5");

    val = eval_str("atan(tan(1.0))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: atan(tan(1.0)) no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.01f, "trig-rt: atan(tan(1.0)) = 1.0");

    /* sin(asin(x)) = x for x in [-1, 1] */
    val = eval_str("sin(asin(0.6))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: sin(asin(0.6)) no error");
    ASSERT_EQ_FLOAT(val, 0.6f, 0.01f, "trig-rt: sin(asin(0.6)) = 0.6");

    /* cos(acos(x)) = x for x in [-1, 1] */
    val = eval_str("cos(acos(0.8))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: cos(acos(0.8)) no error");
    ASSERT_EQ_FLOAT(val, 0.8f, 0.01f, "trig-rt: cos(acos(0.8)) = 0.8");

    /* tan(atan(x)) = x for all real x */
    val = eval_str("tan(atan(2.5))", &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: tan(atan(2.5)) no error");
    ASSERT_EQ_FLOAT(val, 2.5f, 0.01f, "trig-rt: tan(atan(2.5)) = 2.5");

    /* Pythagorean identity: sin(x)^2 + cos(x)^2 = 1 at x=1 */
    val = eval_str_at("sin(x)^2+cos(x)^2", 'x', 1.0f, &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: sin^2+cos^2 at 1 no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 0.001f, "trig-rt: sin^2+cos^2=1");

    /* Pythagorean: 1 + tan(x)^2 = sec(x)^2 at x=0.5 */
    val = eval_str_at("1+tan(x)^2", 'x', 0.5f, &err);
    ASSERT_TRUE(err == CE_OK, "trig-rt: 1+tan^2 at 0.5 no error");
    {
        ce_error_t e2;
        ce_float_t sec_sq = eval_str_at("1/cos(x)^2", 'x', 0.5f, &e2);
        if (err == CE_OK && e2 == CE_OK) {
            ASSERT_EQ_FLOAT(val, sec_sq, 0.01f, "trig-rt: 1+tan^2=sec^2");
        }
    }

    mem_free_all();
}

/* ── Stats with uniform multi-element data ──────────────────────────── */
static void test_pass41_stats_uniform_multielem(void)
{
    printf("=== Pass 41: Stats Uniform Multi-Elem ===\n");
    mem_free_all();

    {
        /* stdev of N identical elements (N > 1) must be 0 */
        ce_float_t d4[4] = {5.0f, 5.0f, 5.0f, 5.0f};
        ASSERT_EQ_FLOAT(stat_stdev(d4, 4), 0.0f, 1e-5f,
                        "stats-uni: stdev({5,5,5,5}) = 0");
        ASSERT_EQ_FLOAT(stat_variance(d4, 4), 0.0f, 1e-5f,
                        "stats-uni: var({5,5,5,5}) = 0");
        ASSERT_EQ_FLOAT(stat_mean(d4, 4), 5.0f, 1e-5f,
                        "stats-uni: mean({5,5,5,5}) = 5");

        ce_float_t d2[2] = {7.0f, 7.0f};
        ASSERT_EQ_FLOAT(stat_stdev(d2, 2), 0.0f, 1e-5f,
                        "stats-uni: stdev({7,7}) = 0");
        ASSERT_EQ_FLOAT(stat_mean(d2, 2), 7.0f, 1e-5f,
                        "stats-uni: mean({7,7}) = 7");

        /* stdev({1,3}) = sqrt(2) (population stdev) */
        ce_float_t d1_3[2] = {1.0f, 3.0f};
        ce_float_t sd = stat_stdev(d1_3, 2);
        /* sample stdev = sqrt(((1-2)^2+(3-2)^2)/2) = 1
         * population stdev = sqrt(((1-2)^2+(3-2)^2)/2) = 1 depending on implementation */
        ASSERT_TRUE(sd >= 0.9f && sd <= 1.5f,
                    "stats-uni: stdev({1,3}) is in [0.9,1.5]");

        /* mean of {1,2,3,4,5} = 3 */
        ce_float_t d5[5] = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f};
        ASSERT_EQ_FLOAT(stat_mean(d5, 5), 3.0f, 1e-5f,
                        "stats-uni: mean({1,2,3,4,5}) = 3");

        /* variance({1,2,3,4,5}): population var = (1+0+0+0+1+4)*? Actually 2 */
        /* mean=3, deviations: -2,-1,0,1,2; squares: 4,1,0,1,4 sum=10; /5=2 */
        ce_float_t var5 = stat_variance(d5, 5);
        ASSERT_TRUE(var5 >= 1.9f && var5 <= 2.5f,
                    "stats-uni: var({1..5}) ~ 2");

        /* stdev({2,4,4,4,5,5,7,9}) ~ 2 (well-known example) */
        ce_float_t d8[8] = {2.0f, 4.0f, 4.0f, 4.0f, 5.0f, 5.0f, 7.0f, 9.0f};
        ce_float_t sd8 = stat_stdev(d8, 8);
        ASSERT_TRUE(sd8 >= 1.9f && sd8 <= 2.2f,
                    "stats-uni: stdev({2,4,4,4,5,5,7,9}) ~ 2");

        /* mode of {1,1,2,3} = 1 */
        ce_float_t dm[4] = {1.0f, 1.0f, 2.0f, 3.0f};
        ASSERT_EQ_FLOAT(stat_mode(dm, 4), 1.0f, 0.01f,
                        "stats-uni: mode({1,1,2,3}) = 1");

        /* median of sorted {1,2,3} = 2 */
        ce_float_t dm3[3] = {1.0f, 2.0f, 3.0f};
        ASSERT_EQ_FLOAT(stat_median(dm3, 3), 2.0f, 0.01f,
                        "stats-uni: median({1,2,3}) = 2");

        /* median of {1,2,3,4} = 2.5 (already sorts in-place) */
        ce_float_t dm4[4] = {1.0f, 2.0f, 3.0f, 4.0f};
        ASSERT_EQ_FLOAT(stat_median(dm4, 4), 2.5f, 0.01f,
                        "stats-uni: median({1,2,3,4}) = 2.5");
    }

    mem_free_all();
}

/* ── Limits at negative infinity ─────────────────────────────────────── */
static void test_pass41_limits_at_neg_inf(void)
{
    ast_node_t *expr, *point;
    ce_float_t  result;
    lim_status_t status;

    printf("=== Pass 41: Limits at -inf ===\n");

    /* lim x→-inf of e^x = 0 */
    mem_free_all();
    expr  = parse_str("e^x");
    point = ast_unop(UOP_NEG, ast_constant(CONST_INF));
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_TRUE(status == LIM_OK || status == LIM_FAILED,
                "lim-neginf: e^x at -inf status valid");
    if (status == LIM_OK) {
        ASSERT_EQ_FLOAT(result, 0.0f, 0.05f, "lim-neginf: e^x at -inf = 0");
    }
    ast_free(expr); ast_free(point);

    /* lim x→-inf of 1/x = 0 */
    mem_free_all();
    expr  = parse_str("1/x");
    point = ast_unop(UOP_NEG, ast_constant(CONST_INF));
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_TRUE(status == LIM_OK || status == LIM_FAILED,
                "lim-neginf: 1/x at -inf status valid");
    if (status == LIM_OK) {
        ASSERT_EQ_FLOAT(result, 0.0f, 0.05f, "lim-neginf: 1/x at -inf = 0");
    }
    ast_free(expr); ast_free(point);

    /* lim x→-inf of x^2/(x^2+1) = 1 */
    mem_free_all();
    expr  = parse_str("x^2/(x^2+1)");
    point = ast_unop(UOP_NEG, ast_constant(CONST_INF));
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_TRUE(status == LIM_OK || status == LIM_FAILED,
                "lim-neginf: x^2/(x^2+1) at -inf status valid");
    if (status == LIM_OK) {
        ASSERT_EQ_FLOAT(result, 1.0f, 0.1f, "lim-neginf: x^2/(x^2+1) = 1");
    }
    ast_free(expr); ast_free(point);

    /* lim x→-inf of (x+1)/(x-1) = 1 */
    mem_free_all();
    expr  = parse_str("(x+1)/(x-1)");
    point = ast_unop(UOP_NEG, ast_constant(CONST_INF));
    status = compute_limit(expr, 'x', point, 0, &result);
    ASSERT_TRUE(status == LIM_OK || status == LIM_FAILED,
                "lim-neginf: (x+1)/(x-1) at -inf status valid");
    if (status == LIM_OK) {
        ASSERT_EQ_FLOAT(result, 1.0f, 0.1f, "lim-neginf: (x+1)/(x-1) = 1");
    }
    ast_free(expr); ast_free(point);

    mem_free_all();
}

/* ── Continuity: essential discontinuity ────────────────────────────── */
static void test_pass41_continuity_essential(void)
{
    ast_node_t *expr, *pt;
    continuity_t ct;

    printf("=== Pass 41: Continuity Essential ===\n");

    /* sin(1/x) at x=0 → essential discontinuity */
    mem_free_all();
    expr = parse_str("sin(1/x)");
    pt   = ast_number(0.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_TRUE(ct == CONT_ESSENTIAL || ct == CONT_INFINITE || ct == CONT_FAILED,
                "cont-ess: sin(1/x) at 0 is essential/infinite");
    ast_free(expr); ast_free(pt);

    /* cos(1/x) at x=0 → essential discontinuity */
    mem_free_all();
    expr = parse_str("cos(1/x)");
    pt   = ast_number(0.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_TRUE(ct == CONT_ESSENTIAL || ct == CONT_INFINITE || ct == CONT_FAILED,
                "cont-ess: cos(1/x) at 0 is essential/infinite");
    ast_free(expr); ast_free(pt);

    /* x^2 at x=3 → continuous */
    mem_free_all();
    expr = parse_str("x^2");
    pt   = ast_number(3.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_EQ_INT(ct, CONT_CONTINUOUS, "cont-ess: x^2 at 3 is continuous");
    ast_free(expr); ast_free(pt);

    /* ln(x) at x=1 → continuous */
    mem_free_all();
    expr = parse_str("ln(x)");
    pt   = ast_number(1.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_TRUE(ct == CONT_CONTINUOUS || ct == CONT_FAILED,
                "cont-ess: ln(x) at 1 is continuous or failed");
    ast_free(expr); ast_free(pt);

    /* 1/x^2 at x=0 → infinite discontinuity */
    mem_free_all();
    expr = parse_str("1/x^2");
    pt   = ast_number(0.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_TRUE(ct == CONT_INFINITE || ct == CONT_ESSENTIAL,
                "cont-ess: 1/x^2 at 0 is infinite");
    ast_free(expr); ast_free(pt);

    /* (x^2-4)/(x-2) at x=2 → removable */
    mem_free_all();
    expr = parse_str("(x^2-4)/(x-2)");
    pt   = ast_number(2.0f);
    ct   = limits_continuity(expr, 'x', pt);
    ASSERT_TRUE(ct == CONT_REMOVABLE || ct == CONT_CONTINUOUS,
                "cont-ess: (x^2-4)/(x-2) at 2 is removable");
    ast_free(expr); ast_free(pt);

    mem_free_all();
}

/* ── series_limit_comparison: extended cases ────────────────────────── */
static void test_pass41_series_limit_comparison_ext(void)
{
    ast_node_t *a, *b;
    conv_result_t out;
    ce_float_t    L;
    bool          ok;

    printf("=== Pass 41: Series Limit Comparison Extended ===\n");

    /* 1/n^2 vs 1/n^3: both converge, ratio → inf (LCT inconclusive but ratio finite) */
    mem_free_all();
    a = parse_str("1/n^2");
    b = parse_str("1/n^3");
    ok = series_limit_comparison(a, b, 'n', &out, &L);
    /* lim |a_n/b_n| = lim n^3/n^2 = lim n = inf → LCT not applicable → returns false */
    /* Either false or the test gracefully rejects */
    if (ok) {
        /* If it claims a result, ratio should be large/positive */
        ASSERT_TRUE(L > 0.0f, "slc-ext: 1/n^2 vs 1/n^3 ratio positive if applicable");
    } else {
        ASSERT_TRUE(!ok, "slc-ext: 1/n^2 vs 1/n^3 LCT returns false (infinite ratio)");
    }
    ast_free(a); ast_free(b);

    /* 1/n^2 vs 1/n: a converges, b diverges, ratio → 0 → LCT inconclusive */
    mem_free_all();
    a = parse_str("1/n^2");
    b = parse_str("1/n");
    ok = series_limit_comparison(a, b, 'n', &out, &L);
    /* lim (1/n^2)/(1/n) = lim 1/n = 0 → LCT inconclusive */
    if (ok) {
        ASSERT_TRUE(L >= 0.0f, "slc-ext: 1/n^2 vs 1/n limit non-negative");
    } else {
        ASSERT_TRUE(!ok, "slc-ext: 1/n^2 vs 1/n LCT returns false (zero ratio)");
    }
    ast_free(a); ast_free(b);

    /* 2/n^2 vs 1/n^2: ratio = 2 (finite positive) → both share convergence */
    mem_free_all();
    a = parse_str("2/n^2");
    b = parse_str("1/n^2");
    ok = series_limit_comparison(a, b, 'n', &out, &L);
    if (ok) {
        ASSERT_TRUE(L > 0.0f && L < 1000.0f,
                    "slc-ext: 2/n^2 vs 1/n^2 ratio finite positive");
        ASSERT_EQ_FLOAT(L, 2.0f, 0.5f, "slc-ext: 2/n^2 vs 1/n^2 ratio ~ 2");
        /* Both converge (p-series with p=2 > 1) */
        ASSERT_EQ_INT(out, CONV_CONVERGES, "slc-ext: 2/n^2 converges with 1/n^2");
    }
    ast_free(a); ast_free(b);

    /* n/(n+1) vs 1: ratio → 1 → both share divergence */
    mem_free_all();
    a = parse_str("n/(n+1)");
    b = parse_str("1");
    ok = series_limit_comparison(a, b, 'n', &out, &L);
    if (ok) {
        ASSERT_TRUE(L > 0.5f && L < 2.0f,
                    "slc-ext: n/(n+1) vs 1 ratio ~ 1");
    }
    ast_free(a); ast_free(b);

    mem_free_all();
}

/* ── power_series_radius extended ───────────────────────────────────── */
static void test_pass41_power_series_radius_ext(void)
{
    ast_node_t *expr;
    ce_float_t  R;

    printf("=== Pass 41: Power Series Radius Extended ===\n");

    /* a_n = 1/2^n → R = 2 (ratio: a_n/a_{n+1} = 2^{n+1}/2^n = 2) */
    mem_free_all();
    expr = parse_str("1/2^n");
    R = power_series_radius(expr, 'n');
    ASSERT_TRUE(R > 1.5f && R < 2.5f, "psr-ext: 1/2^n radius ~ 2");
    ast_free(expr);

    /* a_n = 1/3^n → R = 3 */
    mem_free_all();
    expr = parse_str("1/3^n");
    R = power_series_radius(expr, 'n');
    ASSERT_TRUE(R > 2.5f && R < 3.5f, "psr-ext: 1/3^n radius ~ 3");
    ast_free(expr);

    /* a_n = 1 (constant) → R = 1 (geometric series) */
    mem_free_all();
    expr = parse_str("1");
    R = power_series_radius(expr, 'n');
    ASSERT_TRUE(R > 0.5f && R < 1.5f, "psr-ext: a_n=1 radius ~ 1");
    ast_free(expr);

    /* a_n = n+1 → R = 1 (ratio: (n+1)/(n+2) → 1) */
    mem_free_all();
    expr = parse_str("n+1");
    R = power_series_radius(expr, 'n');
    ASSERT_TRUE(R > 0.5f && R < 1.5f, "psr-ext: a_n=n+1 radius ~ 1");
    ast_free(expr);

    mem_free_all();
}

/* ── 3x3 matrix determinant and scale laws ──────────────────────────── */
static void test_pass41_matrix_3x3_det_scale(void)
{
    ce_matrix_t a, b;

    printf("=== Pass 41: Matrix 3x3 Det & Scale ===\n");

    /* det([[1,2,3],[4,5,6],[7,8,0]])
     * = 1*(5*0-6*8) - 2*(4*0-6*7) + 3*(4*8-5*7)
     * = 1*(0-48) - 2*(0-42) + 3*(32-35)
     * = -48 + 84 - 9 = 27 */
    matrix_init(&a, 3, 3);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 3;
    a.data[3] = 4; a.data[4] = 5; a.data[5] = 6;
    a.data[6] = 7; a.data[7] = 8; a.data[8] = 0;
    ASSERT_EQ_FLOAT(matrix_det(&a), 27.0f, 0.5f,
                    "3x3-det: [[1,2,3],[4,5,6],[7,8,0]] = 27");

    /* Scale by 2: det(2A) = 2^3 * det(A) = 8 * 27 = 216 */
    matrix_scale(&a, 2.0f, &b);
    ASSERT_EQ_FLOAT(matrix_det(&b), 216.0f, 1.0f,
                    "3x3-det: det(2A) = 8*det(A) = 216");

    /* det([[1,0,0],[0,2,0],[0,0,3]]) = 6 (diagonal) */
    matrix_init(&a, 3, 3);
    a.data[0] = 1; a.data[1] = 0; a.data[2] = 0;
    a.data[3] = 0; a.data[4] = 2; a.data[5] = 0;
    a.data[6] = 0; a.data[7] = 0; a.data[8] = 3;
    ASSERT_EQ_FLOAT(matrix_det(&a), 6.0f, 0.01f,
                    "3x3-det: diagonal det = product of diagonal");

    /* det of identity = 1 */
    matrix_init(&a, 3, 3);
    a.data[0] = 1; a.data[1] = 0; a.data[2] = 0;
    a.data[3] = 0; a.data[4] = 1; a.data[5] = 0;
    a.data[6] = 0; a.data[7] = 0; a.data[8] = 1;
    ASSERT_EQ_FLOAT(matrix_det(&a), 1.0f, 0.01f,
                    "3x3-det: identity det = 1");

    /* det of singular matrix = 0 */
    matrix_init(&a, 3, 3);
    a.data[0] = 1; a.data[1] = 2; a.data[2] = 3;
    a.data[3] = 4; a.data[4] = 5; a.data[5] = 6;
    a.data[6] = 7; a.data[7] = 8; a.data[8] = 9;
    ASSERT_EQ_FLOAT(matrix_det(&a), 0.0f, 0.5f,
                    "3x3-det: singular (row3=row1+row2) det = 0");

    /* matrix_add/sub round-trip: A + B - B = A */
    {
        ce_matrix_t B, ApB, ApBmB;
        bool ok;

        matrix_init(&a, 2, 2);
        a.data[0] = 3; a.data[1] = 7;
        a.data[2] = 1; a.data[3] = -2;

        matrix_init(&B, 2, 2);
        B.data[0] = 5; B.data[1] = -3;
        B.data[2] = 0; B.data[3] = 4;

        ok = matrix_add(&a, &B, &ApB);
        ASSERT_TRUE(ok, "3x3-det: A+B succeeds");
        ok = matrix_sub(&ApB, &B, &ApBmB);
        ASSERT_TRUE(ok, "3x3-det: (A+B)-B succeeds");
        ASSERT_EQ_FLOAT(ApBmB.data[0], a.data[0], 0.01f, "3x3-det: (A+B)-B[0]=A[0]");
        ASSERT_EQ_FLOAT(ApBmB.data[1], a.data[1], 0.01f, "3x3-det: (A+B)-B[1]=A[1]");
        ASSERT_EQ_FLOAT(ApBmB.data[2], a.data[2], 0.01f, "3x3-det: (A+B)-B[2]=A[2]");
        ASSERT_EQ_FLOAT(ApBmB.data[3], a.data[3], 0.01f, "3x3-det: (A+B)-B[3]=A[3]");
    }
}

/* ── History reentry text stripping ─────────────────────────────────── */
static void test_pass41_history_reentry_and_numeric(void)
{
    char buf[128];
    bool ok;

    printf("=== Pass 41: History Reentry & Numeric ===\n");

    history_clear();

    /* Push entry with result prefixed "= " — reentry should strip it */
    ok = history_push("2+3", "= 5", 5.0f, true);
    ASSERT_TRUE(ok, "hist-reentry: push ok");

    ok = history_get_reentry_text(0, buf, sizeof(buf));
    ASSERT_TRUE(ok, "hist-reentry: get_reentry_text ok");
    /* Result is "= 5" — reentry should return "5" (stripped) */
    ASSERT_TRUE(strstr(buf, "=") == NULL || buf[0] != '=',
                "hist-reentry: reentry text strips leading '= '");
    ASSERT_STR_CONTAINS(buf, "5", "hist-reentry: reentry text contains result value");

    /* Entry without numeric: reentry should return input */
    history_push("x^2", "x^2", 0.0f, false);
    ok = history_get_reentry_text(0, buf, sizeof(buf));
    ASSERT_TRUE(ok, "hist-reentry: non-numeric reentry ok");
    /* Most recent is x^2 */
    ASSERT_STR_CONTAINS(buf, "x", "hist-reentry: non-numeric reentry returns input");

    /* Verify LIFO: push A, B, C → get(0)=C, get(1)=B, get(2)=A */
    history_clear();
    history_push("1+1", "= 2", 2.0f, true);
    history_push("3*4", "= 12", 12.0f, true);
    history_push("sqrt(9)", "= 3", 3.0f, true);

    ASSERT_EQ_INT(history_count(), 3, "hist-reentry: count=3 after 3 pushes");
    ASSERT_STR_CONTAINS(history_get_input(0), "sqrt", "hist-reentry: [0]=sqrt(9)");
    ASSERT_STR_CONTAINS(history_get_input(1), "3*4",  "hist-reentry: [1]=3*4");
    ASSERT_STR_CONTAINS(history_get_input(2), "1+1",  "hist-reentry: [2]=1+1");

    /* Numeric values stored correctly */
    {
        const history_entry_t *e;
        e = history_get(0);
        ASSERT_TRUE(e != NULL && e->has_numeric, "hist-reentry: [0] has_numeric");
        if (e) ASSERT_EQ_FLOAT(e->numeric_result, 3.0f, 0.01f,
                               "hist-reentry: [0] numeric=3");

        e = history_get(1);
        ASSERT_TRUE(e != NULL && e->has_numeric, "hist-reentry: [1] has_numeric");
        if (e) ASSERT_EQ_FLOAT(e->numeric_result, 12.0f, 0.01f,
                               "hist-reentry: [1] numeric=12");

        e = history_get(2);
        ASSERT_TRUE(e != NULL && e->has_numeric, "hist-reentry: [2] has_numeric");
        if (e) ASSERT_EQ_FLOAT(e->numeric_result, 2.0f, 0.01f,
                               "hist-reentry: [2] numeric=2");
    }

    /* history_get_reentry_text for out-of-range returns false */
    ok = history_get_reentry_text(99, buf, sizeof(buf));
    ASSERT_TRUE(!ok, "hist-reentry: out-of-range returns false");

    history_clear();
}

/* ── eval: boundary/zero-value special expressions ──────────────────── */
