    ASSERT_TRUE(err == CE_OK, "zero-bnd: abs(0) no error");
    ASSERT_EQ_FLOAT(val, 0.0f, 1e-5f, "zero-bnd: abs(0) = 0");

    /* sqrt(0) = 0 */
    val = eval_str("sqrt(0)", &err);
