    ASSERT_EQ_FLOAT(val, 0.0f, 1e-5f, "zero-bnd: sqrt(0) = 0");

    /* e^0 = 1 */
    val = eval_str("e^0", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: e^0 no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 1e-4f, "zero-bnd: e^0 = 1");

