    ASSERT_TRUE(err == CE_OK, "zero-bnd: ln(1) no error");
    ASSERT_EQ_FLOAT(val, 0.0f, 1e-5f, "zero-bnd: ln(1) = 0");

    /* sin(0) = 0 */
    val = eval_str("sin(0)", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: sin(0) no error");
    ASSERT_EQ_FLOAT(val, 0.0f, 1e-5f, "zero-bnd: sin(0) = 0");

    /* cos(0) = 1 */
    val = eval_str("cos(0)", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: cos(0) no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 1e-5f, "zero-bnd: cos(0) = 1");

    /* tan(0) = 0 */
    val = eval_str("tan(0)", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: tan(0) no error");
    ASSERT_EQ_FLOAT(val, 0.0f, 1e-5f, "zero-bnd: tan(0) = 0");

    /* abs(-5) = 5 */
    val = eval_str("abs(-5)", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: abs(-5) no error");
    ASSERT_EQ_FLOAT(val, 5.0f, 1e-5f, "zero-bnd: abs(-5) = 5");

    /* 1^0 = 1 */
    val = eval_str("1^0", &err);
    ASSERT_TRUE(err == CE_OK, "zero-bnd: 1^0 no error");
    ASSERT_EQ_FLOAT(val, 1.0f, 1e-5f, "zero-bnd: 1^0 = 1");

    /* 0^1 = 0 */
    val = eval_str("0^1", &err);
