/* ── 7. ode_solve_separable: extended cases including dy/dx = y ─────────── */
static void test_pass42_ode_separable_extended(void)
{
    char sol[256];
    bool ok;
    ast_node_t *rhs;

    printf("=== Pass 42: ODE separable extended cases ===\n");
    mem_free_all();

    /* dy/dx = y → y = C*e^x → solution should reference 'e' or 'exp' */
    rhs = parse_str("y");
    ASSERT_TRUE(rhs != NULL, "ode-ext: parse y");
    ok = ode_solve_separable(rhs, 'x', 'y', sol, sizeof(sol));
    ASSERT_TRUE(ok, "ode-ext: dy/dx=y separable ok");
    if (ok) {
        /* Result should contain 'e' (exponential) or 'C' */
        ASSERT_TRUE(strstr(sol, "e") != NULL || strstr(sol, "exp") != NULL ||
                    strstr(sol, "C") != NULL,
                    "ode-ext: dy/dx=y solution references exp or constant");
    }
    ast_free(rhs);

    /* dy/dx = x → y = x^2/2 + C → solution contains x^2 or x */
    mem_free_all();
    rhs = parse_str("x");
    ASSERT_TRUE(rhs != NULL, "ode-ext: parse x");
    ok = ode_solve_separable(rhs, 'x', 'y', sol, sizeof(sol));
    ASSERT_TRUE(ok, "ode-ext: dy/dx=x separable ok");
    if (ok) {
        ASSERT_TRUE(strstr(sol, "x") != NULL || strstr(sol, "C") != NULL,
                    "ode-ext: dy/dx=x solution contains x or C");
    }
    ast_free(rhs);

    /* dy/dx = 1 → y = x + C → solution contains x or C */
    mem_free_all();
    rhs = parse_str("1");
    ASSERT_TRUE(rhs != NULL, "ode-ext: parse 1");
    ok = ode_solve_separable(rhs, 'x', 'y', sol, sizeof(sol));
    ASSERT_TRUE(ok, "ode-ext: dy/dx=1 separable ok");
    if (ok) {
        ASSERT_TRUE(strstr(sol, "x") != NULL || strstr(sol, "C") != NULL,
                    "ode-ext: dy/dx=1 solution contains x or C");
    }
    ast_free(rhs);

    /* dy/dx = 2*x → y = x^2 + C */
    mem_free_all();
    rhs = parse_str("2*x");
    ASSERT_TRUE(rhs != NULL, "ode-ext: parse 2*x");
    ok = ode_solve_separable(rhs, 'x', 'y', sol, sizeof(sol));
    ASSERT_TRUE(ok, "ode-ext: dy/dx=2x separable ok");
    if (ok) {
        ASSERT_TRUE(strstr(sol, "x") != NULL,
                    "ode-ext: dy/dx=2x solution contains x");
    }
    ast_free(rhs);

    mem_free_all();
}

/* ── 8. integrate_strategy_report: verify report content for key integrands */
static void test_pass42_integrate_strategy_report_contents(void)
{
    ast_node_t *expr;
    char report[512];

    printf("=== Pass 42: integrate_strategy_report contents ===\n");
    mem_free_all();

    /* sin(x): trig function → report should mention trig or substitution */
    expr = parse_str("sin(x)");
    ASSERT_TRUE(expr != NULL, "strat-rpt: parse sin(x)");
    if (expr) {
        report[0] = '\0';
        integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
        ASSERT_TRUE(report[0] != '\0', "strat-rpt: sin(x) report non-empty");
        ast_free(expr);
    }

    /* x*e^x → integration by parts → report should mention parts or IBP */
    mem_free_all();
    expr = parse_str("x*e^x");
    ASSERT_TRUE(expr != NULL, "strat-rpt: parse x*e^x");
    if (expr) {
        report[0] = '\0';
        integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
        ASSERT_TRUE(report[0] != '\0', "strat-rpt: x*e^x report non-empty");
        ast_free(expr);
    }

    /* 1/(x^2+1) → trig sub or arctan → report non-empty */
    mem_free_all();
    expr = parse_str("1/(x^2+1)");
    ASSERT_TRUE(expr != NULL, "strat-rpt: parse 1/(x^2+1)");
    if (expr) {
        report[0] = '\0';
        integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
        ASSERT_TRUE(report[0] != '\0', "strat-rpt: 1/(x^2+1) report non-empty");
        ast_free(expr);
    }

    /* x^2 → polynomial → direct integration */
    mem_free_all();
    expr = parse_str("x^2");
    ASSERT_TRUE(expr != NULL, "strat-rpt: parse x^2");
    if (expr) {
        report[0] = '\0';
        integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
        ASSERT_TRUE(report[0] != '\0', "strat-rpt: x^2 report non-empty");
        ast_free(expr);
    }

    /* 2*x*sin(x^2) → u-substitution (u=x^2) */
    mem_free_all();
    expr = parse_str("2*x*sin(x^2)");
    ASSERT_TRUE(expr != NULL, "strat-rpt: parse 2x*sin(x^2)");
    if (expr) {
        report[0] = '\0';
        integrate_strategy_report(expr, 'x', report, (int)sizeof(report));
        ASSERT_TRUE(report[0] != '\0', "strat-rpt: 2x*sin(x^2) report non-empty");
        ast_free(expr);
    }

    mem_free_all();
}

/* ── 9. csech / ccsch / ccoth: extended complex values and identity ──────── */
static void test_pass42_complex_recip_hyp_extended(void)
{
    ce_complex_t z, r, product;

    printf("=== Pass 42: csech/ccsch/ccoth extended complex values ===\n");

    /* csech({0,0}) = 1/cosh(0) = 1/1 = {1, 0} */
    z.re = 0.0f; z.im = 0.0f;
    r = csech_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.0f, 0.01f, "csech: sech(0) real = 1");
    ASSERT_EQ_FLOAT(r.im, 0.0f, 0.01f, "csech: sech(0) imag = 0");

    /* csech({1,0}) = 1/cosh(1) ≈ 1/1.5431 ≈ 0.6481 */
    z.re = 1.0f; z.im = 0.0f;
    r = csech_z(z);
    ASSERT_EQ_FLOAT(r.re, 0.6481f, 0.01f, "csech: sech(1) real ≈ 0.6481");
    ASSERT_EQ_FLOAT(r.im, 0.0f,    0.01f, "csech: sech(1) imag = 0");

    /* ccsch({1,0}) = 1/sinh(1) ≈ 1/1.1752 ≈ 0.8509 */
    z.re = 1.0f; z.im = 0.0f;
    r = ccsch_z(z);
    ASSERT_EQ_FLOAT(r.re, 0.8509f, 0.02f, "ccsch: csch(1) real ≈ 0.8509");
    ASSERT_EQ_FLOAT(r.im, 0.0f,    0.01f, "ccsch: csch(1) imag = 0");

    /* ccoth({1,0}) = cosh(1)/sinh(1) ≈ 1.3130 */
    z.re = 1.0f; z.im = 0.0f;
    r = ccoth_z(z);
    ASSERT_EQ_FLOAT(r.re, 1.3130f, 0.02f, "ccoth: coth(1) real ≈ 1.313");
    ASSERT_EQ_FLOAT(r.im, 0.0f,    0.01f, "ccoth: coth(1) imag = 0");

    /* Identity: csech(z) * ccosh(z) = 1 for z = {0.5, 0} */
    {
        ce_complex_t cosh_val;
        z.re = 0.5f; z.im = 0.0f;
        r = csech_z(z);
        cosh_val = ccosh_z(z);
        product = cmul(r, cosh_val);
        ASSERT_EQ_FLOAT(product.re, 1.0f, 0.02f, "csech: sech(z)*cosh(z).re = 1");
        ASSERT_EQ_FLOAT(product.im, 0.0f, 0.02f, "csech: sech(z)*cosh(z).im = 0");
    }

    /* ccoth({2,0}) = cosh(2)/sinh(2) ≈ 3.7622/3.6269 ≈ 1.0373 */
    z.re = 2.0f; z.im = 0.0f;
    r = ccoth_z(z);
    ASSERT_TRUE(r.re > 1.0f && r.re < 1.15f, "ccoth: coth(2) ≈ 1.037");

    /* csech for large real: approaches 0 as z→+inf */
    z.re = 10.0f; z.im = 0.0f;
    r = csech_z(z);
    ASSERT_TRUE(fabsf(r.re) < 0.01f, "csech: sech(10) ≈ 0");
}

/* ── 10. matrix_to_str: non-square, floats, negatives ───────────────────── */
static void test_pass42_matrix_to_str_nonsquare(void)
{
    ce_matrix_t m;
    char buf[256];
    int n;

    printf("=== Pass 42: matrix_to_str non-square and float/negative values ===\n");

    /* 2x3 matrix with integer values */
    matrix_init(&m, 2, 3);
    MAT_AT(&m, 0, 0) =  1; MAT_AT(&m, 0, 1) =  2; MAT_AT(&m, 0, 2) =  3;
    MAT_AT(&m, 1, 0) =  4; MAT_AT(&m, 1, 1) =  5; MAT_AT(&m, 1, 2) =  6;
    n = matrix_to_str(&m, buf, (int)sizeof(buf));
    ASSERT_TRUE(n > 0, "m2str: 2x3 returns positive length");
    ASSERT_STR_CONTAINS(buf, "1", "m2str: 2x3 contains '1'");
    ASSERT_STR_CONTAINS(buf, "6", "m2str: 2x3 contains '6'");

    /* 3x1 column vector with a negative value */
    matrix_init(&m, 3, 1);
    MAT_AT(&m, 0, 0) =  5;
    MAT_AT(&m, 1, 0) = -3;
    MAT_AT(&m, 2, 0) =  7;
    n = matrix_to_str(&m, buf, (int)sizeof(buf));
    ASSERT_TRUE(n > 0, "m2str: 3x1 returns positive length");
    ASSERT_STR_CONTAINS(buf, "5", "m2str: 3x1 contains '5'");
    ASSERT_STR_CONTAINS(buf, "-3", "m2str: 3x1 contains '-3'");
    ASSERT_STR_CONTAINS(buf, "7", "m2str: 3x1 contains '7'");

    /* 1x4 row vector */
    matrix_init(&m, 1, 4);
    MAT_AT(&m, 0, 0) = 10; MAT_AT(&m, 0, 1) = 20;
    MAT_AT(&m, 0, 2) = 30; MAT_AT(&m, 0, 3) = 40;
    n = matrix_to_str(&m, buf, (int)sizeof(buf));
    ASSERT_TRUE(n > 0, "m2str: 1x4 returns positive length");
    ASSERT_STR_CONTAINS(buf, "10", "m2str: 1x4 contains '10'");
    ASSERT_STR_CONTAINS(buf, "40", "m2str: 1x4 contains '40'");

    /* 2x2 with float values */
    matrix_init(&m, 2, 2);
    MAT_AT(&m, 0, 0) =  1.5f; MAT_AT(&m, 0, 1) = -2.5f;
    MAT_AT(&m, 1, 0) =  0.0f; MAT_AT(&m, 1, 1) =  3.14f;
    n = matrix_to_str(&m, buf, (int)sizeof(buf));
    ASSERT_TRUE(n > 0, "m2str: 2x2 float returns positive length");
    ASSERT_STR_CONTAINS(buf, "1", "m2str: 2x2 float buf has content");

    /* Zero matrix 2x2 */
    matrix_init(&m, 2, 2);
    MAT_AT(&m, 0, 0) = 0; MAT_AT(&m, 0, 1) = 0;
    MAT_AT(&m, 1, 0) = 0; MAT_AT(&m, 1, 1) = 0;
    n = matrix_to_str(&m, buf, (int)sizeof(buf));
    ASSERT_TRUE(n > 0, "m2str: zero 2x2 returns positive length");
    ASSERT_STR_CONTAINS(buf, "0", "m2str: zero matrix contains '0'");
}

/* ── 11. deriv_nth: n=0 identity and 4th-order cycles ───────────────────── */
static void test_pass42_deriv_nth_cycle_and_zero(void)
{
    ast_node_t *expr, *d;
    eval_ctx_t ctx;
    ce_float_t v_orig, v_d;

    printf("=== Pass 42: deriv_nth n=0 identity and cycle tests ===\n");
    mem_free_all();

    /* n=0: deriv_nth(expr, var, 0) should return expr unchanged (identity) */
    expr = parse_str("x^3+2*x");
    ASSERT_TRUE(expr != NULL, "dnth: parse x^3+2x");
    d = deriv_nth(expr, 'x', 0);
    ASSERT_TRUE(d != NULL, "dnth: n=0 returns non-null");
    if (d) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 2.0f);
        v_orig = eval_expr(&ctx, expr);
        v_d    = eval_expr(&ctx, d);
        ASSERT_EQ_FLOAT(v_orig, v_d, 0.01f, "dnth: n=0 same value as expr at x=2");
        ast_free(d);
    }
    ast_free(expr);

    /* d^4/dx^4 [sin(x)] = sin(x) (4th derivative cycles back) */
    mem_free_all();
    expr = parse_str("sin(x)");
    ASSERT_TRUE(expr != NULL, "dnth: parse sin(x)");
    d = deriv_nth(expr, 'x', 4);
    ASSERT_TRUE(d != NULL, "dnth: 4th derivative of sin(x) non-null");
    if (d) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 1.0f);
        v_orig = eval_expr(&ctx, expr);
        v_d    = eval_expr(&ctx, d);
        ASSERT_EQ_FLOAT(v_orig, v_d, 0.05f, "dnth: d4/dx4[sin(x)] = sin(x) at x=1");
        ast_free(d);
    }
    ast_free(expr);

    /* d^4/dx^4 [cos(x)] = cos(x) */
    mem_free_all();
    expr = parse_str("cos(x)");
    ASSERT_TRUE(expr != NULL, "dnth: parse cos(x)");
    d = deriv_nth(expr, 'x', 4);
    ASSERT_TRUE(d != NULL, "dnth: 4th derivative of cos(x) non-null");
    if (d) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 0.5f);
        v_orig = eval_expr(&ctx, expr);
        v_d    = eval_expr(&ctx, d);
        ASSERT_EQ_FLOAT(v_orig, v_d, 0.05f, "dnth: d4/dx4[cos(x)] = cos(x) at x=0.5");
        ast_free(d);
    }
    ast_free(expr);

    /* d^4/dx^4 [x^4] = 24 (constant) */
    mem_free_all();
    expr = parse_str("x^4");
    ASSERT_TRUE(expr != NULL, "dnth: parse x^4");
    d = deriv_nth(expr, 'x', 4);
    ASSERT_TRUE(d != NULL, "dnth: 4th derivative of x^4 non-null");
    if (d) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 99.0f); /* should be constant regardless of x */
        v_d = eval_expr(&ctx, d);
        ASSERT_EQ_FLOAT(v_d, 24.0f, 0.5f, "dnth: d4/dx4[x^4] = 24");
        ast_free(d);
    }
    ast_free(expr);

    /* n=1: should equal first derivative */
    mem_free_all();
    expr = parse_str("x^2");
    ASSERT_TRUE(expr != NULL, "dnth: parse x^2 for n=1");
    d = deriv_nth(expr, 'x', 1);
    ASSERT_TRUE(d != NULL, "dnth: n=1 of x^2 non-null");
    if (d) {
        eval_init(&ctx);
        eval_set_var(&ctx, 'x', 3.0f);
        v_d = eval_expr(&ctx, d); /* should be 2*x = 6 */
        ASSERT_EQ_FLOAT(v_d, 6.0f, 0.1f, "dnth: n=1 d/dx[x^2] at x=3 = 6");
        ast_free(d);
    }
    ast_free(expr);

    mem_free_all();
}

/* ── 12. algebra_unit_circle: Q2/Q3/Q4 missing angles ─────────────────── */
static void test_pass42_unit_circle_q2_q3_q4(void)
{
    char res[128];
    int ok;

    printf("=== Pass 42: unit_circle Q2/Q3/Q4 missing angles ===\n");

    /* 120° (Q2): sin=√3/2, cos=-1/2, tan=-√3 */
    ok = algebra_unit_circle(120.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 120° ok");
    ASSERT_STR_CONTAINS(res, "120", "uc: 120° result has angle");

    /* 150° (Q2): sin=1/2, cos=-√3/2, tan=-1/√3 */
    ok = algebra_unit_circle(150.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 150° ok");
    ASSERT_STR_CONTAINS(res, "150", "uc: 150° result has angle");

    /* 240° (Q3): sin=-√3/2, cos=-1/2, tan=√3 */
    ok = algebra_unit_circle(240.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 240° ok");
    ASSERT_STR_CONTAINS(res, "240", "uc: 240° result has angle");

    /* 300° (Q4): sin=-√3/2, cos=1/2, tan=-√3 */
    ok = algebra_unit_circle(300.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 300° ok");
    ASSERT_STR_CONTAINS(res, "300", "uc: 300° result has angle");

    /* 330° (Q4): sin=-1/2, cos=√3/2, tan=-1/√3 */
    ok = algebra_unit_circle(330.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 330° ok");
    ASSERT_STR_CONTAINS(res, "330", "uc: 330° result has angle");

    /* 225° (Q3): sin=-√2/2, cos=-√2/2, tan=1 */
    ok = algebra_unit_circle(225.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 225° ok");
    ASSERT_STR_CONTAINS(res, "225", "uc: 225° result has angle");

    /* 270° already tested; verify 90° and 270° are still consistent */
    ok = algebra_unit_circle(90.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 90° regression ok");

    ok = algebra_unit_circle(270.0f, res, sizeof(res));
    ASSERT_TRUE(ok, "uc: 270° regression ok");
}

/* ── 13. algebra_rational_roots: extended polynomial cases ──────────────── */
static void test_pass42_rational_roots_extended(void)
{
    ast_node_t *expr;
    char buf[256];
    int n;

    printf("=== Pass 42: algebra_rational_roots extended cases ===\n");
    mem_free_all();

    /* x^2 - 4 = (x-2)(x+2): candidates ±1, ±2, ±4 */
    expr = parse_str("x^2-4");
    ASSERT_TRUE(expr != NULL, "rrt-ext: parse x^2-4");
    n = algebra_rational_roots(expr, 'x', buf, sizeof(buf));
    ASSERT_TRUE(n > 0, "rrt-ext: x^2-4 has candidates");
    ASSERT_STR_CONTAINS(buf, "2", "rrt-ext: x^2-4 contains 2");
    ast_free(expr);

    /* 3*x^2 - 7*x + 2: candidates ±1, ±2, ±1/3, ±2/3 */
    mem_free_all();
    expr = parse_str("3*x^2-7*x+2");
    ASSERT_TRUE(expr != NULL, "rrt-ext: parse 3x^2-7x+2");
    n = algebra_rational_roots(expr, 'x', buf, sizeof(buf));
    ASSERT_TRUE(n > 0, "rrt-ext: 3x^2-7x+2 has candidates");
    ast_free(expr);

    /* x^4 - 16 = (x^2-4)(x^2+4): candidates include ±1,±2,±4,±8,±16 */
    mem_free_all();
    expr = parse_str("x^4-16");
    ASSERT_TRUE(expr != NULL, "rrt-ext: parse x^4-16");
    n = algebra_rational_roots(expr, 'x', buf, sizeof(buf));
    ASSERT_TRUE(n > 0, "rrt-ext: x^4-16 has candidates");
    ASSERT_STR_CONTAINS(buf, "2", "rrt-ext: x^4-16 candidates include 2");
    ast_free(expr);

    /* x^2 + 1 (no real roots): still lists candidates ±1 */
    mem_free_all();
    expr = parse_str("x^2+1");
    ASSERT_TRUE(expr != NULL, "rrt-ext: parse x^2+1");
    n = algebra_rational_roots(expr, 'x', buf, sizeof(buf));
    ASSERT_TRUE(n > 0, "rrt-ext: x^2+1 lists rational candidates");
    ast_free(expr);

    /* Constant polynomial: 5 (no variable) → 0 roots */
    mem_free_all();
    expr = parse_str("5");
    ASSERT_TRUE(expr != NULL, "rrt-ext: parse constant 5");
    n = algebra_rational_roots(expr, 'x', buf, sizeof(buf));
    /* Either 0 (no polynomial) or graceful no-candidate result */
    ASSERT_TRUE(n >= 0, "rrt-ext: constant returns >=0");
    ast_free(expr);

    mem_free_all();
}

/* ── 14. algebra_dec_to_frac: edge cases with max_denom and large values ── */
static void test_pass42_dec_to_frac_edge_cases(void)
{
    char res[64];
    int ok;

    printf("=== Pass 42: algebra_dec_to_frac edge cases ===\n");

    /* max_denom=1: any non-integer should fail or round to integer */
    ok = algebra_dec_to_frac(0.7f, 1, res, sizeof(res));
    /* Either fails (0) or returns the nearest integer representation */
    ASSERT_TRUE(ok == 0 || ok == 1, "d2f-edge: max_denom=1 result is 0 or 1");

    /* Exactly 0: should return 0/1 or "0" */
    ok = algebra_dec_to_frac(0.0f, 1000, res, sizeof(res));
    ASSERT_TRUE(ok, "d2f-edge: 0.0 succeeds");
    ASSERT_STR_CONTAINS(res, "0", "d2f-edge: 0.0 result contains '0'");

    /* Exactly 1: should return 1/1 or "1" */
    ok = algebra_dec_to_frac(1.0f, 1000, res, sizeof(res));
    ASSERT_TRUE(ok, "d2f-edge: 1.0 succeeds");
    ASSERT_STR_CONTAINS(res, "1", "d2f-edge: 1.0 result contains '1'");

    /* 0.1 = 1/10 */
    ok = algebra_dec_to_frac(0.1f, 100, res, sizeof(res));
    ASSERT_TRUE(ok, "d2f-edge: 0.1 succeeds");
    ASSERT_STR_CONTAINS(res, "10", "d2f-edge: 0.1 = x/10");

    /* 3.0 / 7 ≈ 0.42857 = 3/7 */
    ok = algebra_dec_to_frac(3.0f / 7.0f, 10000, res, sizeof(res));
    ASSERT_TRUE(ok, "d2f-edge: 3/7 succeeds");
    ASSERT_STR_CONTAINS(res, "7", "d2f-edge: 3/7 denominator 7");

    /* Negative value: -0.5 = -1/2 */
    ok = algebra_dec_to_frac(-0.5f, 1000, res, sizeof(res));
    ASSERT_TRUE(ok, "d2f-edge: -0.5 succeeds");
    ASSERT_STR_CONTAINS(res, "2", "d2f-edge: -0.5 has denom 2");
}

/* ── 15. matrix_mul: identity law and dimension mismatch rejection ────────  */
static void test_pass42_matrix_mul_identity_law(void)
{
    ce_matrix_t A, I3, result;
    bool ok;
    int r, c;

    printf("=== Pass 42: matrix_mul identity law and mismatch rejection ===\n");

    /* 3x3 identity matrix */
    matrix_init(&I3, 3, 3);
    MAT_AT(&I3, 0, 0) = 1; MAT_AT(&I3, 0, 1) = 0; MAT_AT(&I3, 0, 2) = 0;
    MAT_AT(&I3, 1, 0) = 0; MAT_AT(&I3, 1, 1) = 1; MAT_AT(&I3, 1, 2) = 0;
    MAT_AT(&I3, 2, 0) = 0; MAT_AT(&I3, 2, 1) = 0; MAT_AT(&I3, 2, 2) = 1;

    /* Arbitrary 3x3 matrix A */
    matrix_init(&A, 3, 3);
    MAT_AT(&A, 0, 0) = 2; MAT_AT(&A, 0, 1) = -1; MAT_AT(&A, 0, 2) = 3;
    MAT_AT(&A, 1, 0) = 5; MAT_AT(&A, 1, 1) =  4; MAT_AT(&A, 1, 2) = 0;
    MAT_AT(&A, 2, 0) = -2;MAT_AT(&A, 2, 1) =  7; MAT_AT(&A, 2, 2) = 1;

    /* A * I = A */
    ok = matrix_mul(&A, &I3, &result);
    ASSERT_TRUE(ok, "mmul: A*I succeeds");
    for (r = 0; r < 3; r++) {
        for (c = 0; c < 3; c++) {
            ASSERT_EQ_FLOAT(MAT_AT(&result, r, c), MAT_AT(&A, r, c), 0.01f,
                            "mmul: (A*I)[r][c] = A[r][c]");
        }
    }

    /* I * A = A */
    ok = matrix_mul(&I3, &A, &result);
    ASSERT_TRUE(ok, "mmul: I*A succeeds");
    for (r = 0; r < 3; r++) {
        for (c = 0; c < 3; c++) {
            ASSERT_EQ_FLOAT(MAT_AT(&result, r, c), MAT_AT(&A, r, c), 0.01f,
                            "mmul: (I*A)[r][c] = A[r][c]");
        }
    }

    /* Dimension mismatch: 2x3 * 2x3 should fail */
    {
        ce_matrix_t B;
        matrix_init(&A, 2, 3);
        matrix_init(&B, 2, 3);
        ok = matrix_mul(&A, &B, &result);
        ASSERT_TRUE(!ok, "mmul: 2x3 * 2x3 fails (cols≠rows)");
    }

    /* 3x2 * 2x3 = 3x3: valid dimensions */
    {
        ce_matrix_t B;
        matrix_init(&A, 3, 2);
        MAT_AT(&A, 0, 0) = 1; MAT_AT(&A, 0, 1) = 2;
        MAT_AT(&A, 1, 0) = 3; MAT_AT(&A, 1, 1) = 4;
        MAT_AT(&A, 2, 0) = 5; MAT_AT(&A, 2, 1) = 6;

        matrix_init(&B, 2, 3);
        MAT_AT(&B, 0, 0) = 7; MAT_AT(&B, 0, 1) = 8; MAT_AT(&B, 0, 2) = 9;
        MAT_AT(&B, 1, 0) = 1; MAT_AT(&B, 1, 1) = 2; MAT_AT(&B, 1, 2) = 3;

        ok = matrix_mul(&A, &B, &result);
        ASSERT_TRUE(ok, "mmul: 3x2 * 2x3 succeeds");
        /* result[0][0] = 1*7 + 2*1 = 9 */
        ASSERT_EQ_FLOAT(MAT_AT(&result, 0, 0), 9.0f,  0.01f, "mmul: [0][0] = 9");
        /* result[0][1] = 1*8 + 2*2 = 12 */
        ASSERT_EQ_FLOAT(MAT_AT(&result, 0, 1), 12.0f, 0.01f, "mmul: [0][1] = 12");
        /* result[2][2] = 5*9 + 6*3 = 45+18 = 63 */
        ASSERT_EQ_FLOAT(MAT_AT(&result, 2, 2), 63.0f, 0.01f, "mmul: [2][2] = 63");
    }
}

