static void test_pass42_finance_amortization_boundary_windows(void)
{
    bool saved_begin = g_settings.pmt_at_begin;
    eval_ctx_t ctx;
    ce_float_t pmt_args[4];
    ce_float_t bal_args[4];
    ce_float_t window_args[5];
    ce_float_t pmt;
    ce_float_t bal0, bal1, bal12, prn1, int1, prn12, int12;

    printf("=== Pass 42: Finance Amortization Boundary Windows ===\n");

    g_settings.pmt_at_begin = false;

    eval_init(&ctx);
    pmt_args[0] = 12.0f;
    pmt_args[1] = 0.01f;
    pmt_args[2] = -1000.0f;
    pmt_args[3] = 0.0f;
    pmt = finance_pmt(pmt_args, 4, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: payment seed ok");

    eval_init(&ctx);
    bal_args[0] = 0.0f;
    bal_args[1] = 0.01f;
    bal_args[2] = -1000.0f;
    bal_args[3] = pmt;
    bal0 = finance_bal(bal_args, 4, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: balance 0 ok");
    ASSERT_EQ_FLOAT(bal0, -1000.0f, 0.01f, "fin-amort: balance 0 equals PV");

    eval_init(&ctx);
    bal_args[0] = 1.0f;
    bal1 = finance_bal(bal_args, 4, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: balance 1 ok");
    ASSERT_TRUE(bal1 > bal0, "fin-amort: balance moves toward zero after one payment");

    eval_init(&ctx);
    bal_args[0] = 12.0f;
    bal12 = finance_bal(bal_args, 4, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: balance 12 ok");
    ASSERT_EQ_FLOAT(bal12, 0.0f, 0.05f, "fin-amort: balance 12 closes loan");

    window_args[0] = 1.0f;
    window_args[1] = 1.0f;
    window_args[2] = 0.01f;
    window_args[3] = -1000.0f;
    window_args[4] = pmt;
    eval_init(&ctx);
    prn1 = finance_sum_prn(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: sumprn payment 1 ok");
    eval_init(&ctx);
    int1 = finance_sum_int(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: sumint payment 1 ok");
    ASSERT_EQ_FLOAT(prn1, bal1 - bal0, 0.01f, "fin-amort: principal window = bal1-bal0");
    ASSERT_EQ_FLOAT(prn1 + int1, pmt, 0.01f, "fin-amort: payment 1 principal+interest = payment");

    window_args[0] = 1.0f;
    window_args[1] = 12.0f;
    eval_init(&ctx);
    prn12 = finance_sum_prn(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: sumprn full window ok");
    eval_init(&ctx);
    int12 = finance_sum_int(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_OK, "fin-amort: sumint full window ok");
    ASSERT_EQ_FLOAT(prn12, 1000.0f, 0.05f, "fin-amort: full principal window retires PV");
    ASSERT_EQ_FLOAT(prn12 + int12, pmt * 12.0f, 0.05f, "fin-amort: full window totals to all payments");

    window_args[0] = 0.0f;
    window_args[1] = 1.0f;
    eval_init(&ctx);
    prn1 = finance_sum_prn(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_ERR_DOMAIN, "fin-amort: sumprn rejects payment 0");
    ASSERT_EQ_FLOAT(prn1, 0.0f, 0.001f, "fin-amort: invalid sumprn returns 0");

    window_args[0] = 3.0f;
    window_args[1] = 2.0f;
    eval_init(&ctx);
    int1 = finance_sum_int(window_args, 5, &ctx);
    ASSERT_EQ_INT(eval_error(&ctx), CE_ERR_DOMAIN, "fin-amort: sumint rejects reversed window");
    ASSERT_EQ_FLOAT(int1, 0.0f, 0.001f, "fin-amort: invalid sumint returns 0");

    g_settings.pmt_at_begin = saved_begin;
}

