/* ── 6. Processor extended: new domains, step count, last_answer ─────────── */
static void test_pass47_processor_domain_extended(void)
{
    ce_response_t resp;
    ce_domain_t   domain;
    const char   *program;

    printf("=== Pass 47: Processor Domain Extended ===\n");

    /* Taylor series: result is a polynomial, routes to LIMSER */
    ASSERT_TRUE(processor_run_expr("taylor(sin(x),x,0,5)", &resp, &domain, &program),
                "p47-proc: taylor(sin(x)) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: taylor(sin(x)) resp.ok = true");
    ASSERT_EQ_INT((int)domain, (int)CE_DOMAIN_CALC_SERIES,
                  "p47-proc: taylor domain = CE_DOMAIN_CALC_SERIES");
    ASSERT_STR_EQ(program, CE_PRGM_LIMSER,
                  "p47-proc: taylor routes to CE_PRGM_LIMSER");
    ASSERT_TRUE(resp.result[0] != '\0',
                "p47-proc: taylor result string is non-empty");

    /* Taylor of exp(x): polynomial output */
    ASSERT_TRUE(processor_run_expr("taylor(exp(x),x,0,3)", &resp, &domain, &program),
                "p47-proc: taylor(exp(x)) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: taylor(exp(x)) resp.ok = true");
    ASSERT_TRUE(resp.result[0] != '\0',
                "p47-proc: taylor(exp(x)) result string is non-empty");

    /* Tangent line: tangent(x^2, x, 1) → 2x - 1 */
    ASSERT_TRUE(processor_run_expr("tangent(x^2,x,1)", &resp, &domain, &program),
                "p47-proc: tangent(x^2,x,1) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: tangent(x^2,x,1) resp.ok = true");
    ASSERT_EQ_INT((int)domain, (int)CE_DOMAIN_CALC_TANGENT,
                  "p47-proc: tangent domain = CE_DOMAIN_CALC_TANGENT");
    ASSERT_TRUE(resp.result[0] != '\0',
                "p47-proc: tangent result string is non-empty");

    /* Probability: binomcdf routes to STATPROB */
    ASSERT_TRUE(processor_run_expr("binomcdf(10,0.5,5)", &resp, &domain, &program),
                "p47-proc: binomcdf(10,0.5,5) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: binomcdf resp.ok = true");
    ASSERT_EQ_INT((int)domain, (int)CE_DOMAIN_PROB,
                  "p47-proc: binomcdf domain = CE_DOMAIN_PROB");
    ASSERT_STR_EQ(program, CE_PRGM_STATPROB,
                  "p47-proc: binomcdf routes to CE_PRGM_STATPROB");
    ASSERT_TRUE(resp.result[0] != '\0',
                "p47-proc: binomcdf result string is non-empty");

    /* Derivative step count: d/dx(x^4) should produce at least 1 step */
    ASSERT_TRUE(processor_run_expr("d/dx(x^4)", &resp, &domain, &program),
                "p47-proc: d/dx(x^4) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: d/dx(x^4) resp.ok = true");
    ASSERT_TRUE(resp.step_count > 0,
                "p47-proc: d/dx(x^4) resp.step_count > 0 (steps recorded)");
    ASSERT_STR_CONTAINS(resp.result, "4",
                        "p47-proc: d/dx(x^4) result contains '4'");

    /* last_answer propagation: 2+2 → last_answer=4 in resp */
    ASSERT_TRUE(processor_run_expr("2+2", &resp, &domain, &program),
                "p47-proc: 2+2 processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: 2+2 resp.ok = true");
    ASSERT_EQ_FLOAT(resp.last_answer, 4.0f, 0.01f,
                    "p47-proc: resp.last_answer = 4 after evaluating 2+2");

    /* Solve equation: routes to ALG domain */
    ASSERT_TRUE(processor_run_expr("solve(x^2=4,x)", &resp, &domain, &program),
                "p47-proc: solve(x^2=4,x) processed without error");
    ASSERT_TRUE(resp.ok,
                "p47-proc: solve(x^2=4,x) resp.ok = true");
    ASSERT_EQ_INT((int)domain, (int)CE_DOMAIN_ALG,
                  "p47-proc: solve domain = CE_DOMAIN_ALG");
    ASSERT_TRUE(resp.result[0] != '\0',
                "p47-proc: solve result string is non-empty");

    /* Malformed expression: processor must not crash */
    memset(&resp, 0, sizeof(resp));
    ce_processor_run("undefined_fn_xyz(x,y,z,w)", &resp);
    ASSERT_TRUE(true,
                "p47-proc: unknown function expression does not crash processor");

    mem_free_all();
    steps_clear();
}


/* == Pass 48: Real Hardware Verification Parity ==============================
 *
 * Code-side guarantees backing docs/HARDWARE-PARITY-CHECKLIST.md.
 * Five test functions:
 *   1. Section 6 core correctness (13 smoke expressions)
 *   2. Section 7 edge cases and failure paths
 *   3. IPC state survival: settings, Ans, history, has_pending_response
 *   4. VAT pressure simulation (10 rapid domain switches)
 *   5. Enter-path hardware parity (empty input, rapid ENTER, pending pickup)
 */

/* -- 1. Core correctness smoke test -- Section 6 --------------------------- */
static void test_pass48_hardware_smoke_core_correctness(void)
{
    ce_response_t resp;
    ce_domain_t   domain;
    const char   *program;
    list_t        seq_out;

    printf("=== Pass 48: Hardware Smoke -- Core Correctness ===\n");

    /* 1. 2+2 -> 4 */
    ASSERT_TRUE(processor_run_expr("2+2", &resp, &domain, &program),
                "hw-smoke: 2+2 processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: 2+2 resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "4", "hw-smoke: 2+2 result contains '4'");
    ASSERT_EQ_FLOAT(resp.last_answer, 4.0f, 0.001f,
                    "hw-smoke: 2+2 last_answer = 4");

    /* 2. 1/3+1/6 -> 0.5 */
    ASSERT_TRUE(processor_run_expr("1/3+1/6", &resp, &domain, &program),
                "hw-smoke: 1/3+1/6 processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: 1/3+1/6 resp.ok = true");
    ASSERT_EQ_FLOAT(resp.last_answer, 0.5f, 0.001f,
                    "hw-smoke: 1/3+1/6 last_answer = 0.5");

    /* 3. factor(x^2-5x+6,x) -> (x-2)(x-3) */
    ASSERT_TRUE(processor_run_expr("factor(x^2-5x+6,x)", &resp, &domain, &program),
                "hw-smoke: factor(x^2-5x+6,x) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: factor(x^2-5x+6) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "x-2",
                        "hw-smoke: factor result contains 'x-2'");
    ASSERT_STR_CONTAINS(resp.result, "x-3",
                        "hw-smoke: factor result contains 'x-3'");

    /* 4. solve(x^2-5x+6=0,x) -> roots 2 and 3 */
    ASSERT_TRUE(processor_run_expr("solve(x^2-5x+6=0,x)", &resp, &domain, &program),
                "hw-smoke: solve(x^2-5x+6=0,x) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: solve(x^2-5x+6=0) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "2",
                        "hw-smoke: solve result contains root '2'");
    ASSERT_STR_CONTAINS(resp.result, "3",
                        "hw-smoke: solve result contains root '3'");

    /* 5. d/dx(x^3) -> 3*x^2 */
    ASSERT_TRUE(processor_run_expr("d/dx(x^3)", &resp, &domain, &program),
                "hw-smoke: d/dx(x^3) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: d/dx(x^3) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "3",
                        "hw-smoke: d/dx(x^3) result contains '3'");

    /* 6. int(x^2,x) -> x^3/3 + C */
    ASSERT_TRUE(processor_run_expr("int(x^2,x)", &resp, &domain, &program),
                "hw-smoke: int(x^2,x) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: int(x^2,x) resp.ok = true");
    ASSERT_TRUE(resp.result[0] != '\0',
                "hw-smoke: int(x^2,x) result non-empty");

    /* 7. lim(sin(x)/x,x,0) -> 1 */
    ASSERT_TRUE(processor_run_expr("lim(sin(x)/x,x,0)", &resp, &domain, &program),
                "hw-smoke: lim(sin(x)/x,x,0) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: lim(sin(x)/x,x,0) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "1",
                        "hw-smoke: lim(sin(x)/x,x,0) result contains '1'");

    /* 8. taylor(sin(x),x,0,5) -> polynomial */
    ASSERT_TRUE(processor_run_expr("taylor(sin(x),x,0,5)", &resp, &domain, &program),
                "hw-smoke: taylor(sin(x),x,0,5) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: taylor(sin(x),x,0,5) resp.ok = true");
    ASSERT_TRUE(resp.result[0] != '\0',
                "hw-smoke: taylor(sin(x),x,0,5) result non-empty");

    /* 9. det(mat(1,2;3,4)) -> -2 */
    ASSERT_TRUE(processor_run_expr("det(mat(1,2;3,4))", &resp, &domain, &program),
                "hw-smoke: det(mat(1,2;3,4)) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: det(mat(1,2;3,4)) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "-2",
                        "hw-smoke: det(mat(1,2;3,4)) result contains '-2'");

    /* 10. mean(1,2,3,4,5) -> 3 */
    ASSERT_TRUE(processor_run_expr("mean(1,2,3,4,5)", &resp, &domain, &program),
                "hw-smoke: mean(1,2,3,4,5) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: mean(1,2,3,4,5) resp.ok = true");
    ASSERT_STR_CONTAINS(resp.result, "3",
                        "hw-smoke: mean(1,2,3,4,5) result contains '3'");

    /* 11. normalcdf(-1,1) ~= 0.6827 (standard normal: mu=0, sigma=1) */
    ASSERT_TRUE(processor_run_expr("normalcdf(-1,1)", &resp, &domain, &program),
                "hw-smoke: normalcdf(-1,1) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: normalcdf(-1,1) resp.ok = true");
    ASSERT_TRUE(resp.result[0] != '\0',
                "hw-smoke: normalcdf(-1,1) result non-empty");
    ASSERT_EQ_FLOAT(resp.last_answer, 0.6827f, 0.01f,
                    "hw-smoke: normalcdf(-1,1) last_answer ~= 0.6827");

    /* 12. fv(0.05,10,100,0) -> finite numeric result */
    ASSERT_TRUE(processor_run_expr("fv(0.05,10,100,0)", &resp, &domain, &program),
                "hw-smoke: fv(0.05,10,100,0) processed without error");
    ASSERT_TRUE(resp.ok, "hw-smoke: fv(0.05,10,100,0) resp.ok = true");
    ASSERT_TRUE(resp.result[0] != '\0',
                "hw-smoke: fv(0.05,10,100,0) result non-empty");
    ASSERT_TRUE(resp.last_answer != 0.0f,
                "hw-smoke: fv result is non-zero");

    /* 13. seq(x,x,1,5,1) -> 5-element list via list_seq API */
    mem_free_all();
    list_seq(1.0f, 5.0f, 1.0f, &seq_out);
    ASSERT_EQ_INT((int)seq_out.len, 5,
                  "hw-smoke: list_seq(1,5,1) produces 5 elements");
    ASSERT_EQ_FLOAT(seq_out.data[0], 1.0f, 0.001f, "hw-smoke: seq[0] = 1");
    ASSERT_EQ_FLOAT(seq_out.data[2], 3.0f, 0.001f, "hw-smoke: seq[2] = 3");
    ASSERT_EQ_FLOAT(seq_out.data[4], 5.0f, 0.001f, "hw-smoke: seq[4] = 5");

    mem_free_all();
    steps_clear();
}

/* -- 2. Edge cases and failure paths -- Section 7 -------------------------- */
static void test_pass48_hardware_smoke_edge_cases(void)
{
    ast_node_t   *expr;
    ast_node_t   *pt_node;
    lim_status_t  lim_st;
    ce_float_t    lim_result;
    continuity_t  ct;
    ce_float_t    terms[10];
    int           n;
    ce_response_t resp;

    printf("=== Pass 48: Hardware Smoke -- Edge Cases ===\n");

    /* 1. lim(1/x,x,0) -> two-sided DNE (left->-inf, right->+inf) */
    mem_free_all();
    expr = parse_str("1/x");
    ASSERT_TRUE(expr != NULL, "hw-edge: 1/x parses for limit check");
    if (expr) {
        pt_node = ast_number(0.0f);
        ASSERT_TRUE(pt_node != NULL, "hw-edge: point node 0 allocated");
        if (pt_node) {
            lim_st = compute_limit(expr, 'x', pt_node, 0, &lim_result);
            ASSERT_TRUE(lim_st != LIM_OK,
                        "hw-edge: lim(1/x,x,0) two-sided is not LIM_OK");
        }
    }
    mem_free_all();

    /* 2. continuity(1/x,x,0) -> infinite discontinuity */
    expr = parse_str("1/x");
    ASSERT_TRUE(expr != NULL, "hw-edge: 1/x parses for continuity");
    if (expr) {
        pt_node = ast_number(0.0f);
        ASSERT_TRUE(pt_node != NULL, "hw-edge: point node 0 for continuity");
        if (pt_node) {
            ct = limits_continuity(expr, 'x', pt_node);
            ASSERT_TRUE(ct == CONT_INFINITE || ct == CONT_ESSENTIAL ||
                        ct == CONT_JUMP,
                        "hw-edge: 1/x at 0 is a non-continuous discontinuity");
        }
    }
    mem_free_all();

    /* 3. 1/0 via processor -> does not crash; produces error or result */
    memset(&resp, 0, sizeof(resp));
    ce_processor_run("1/0", &resp);
    ASSERT_TRUE(true, "hw-edge: ce_processor_run(1/0) does not crash");
    ASSERT_TRUE(!resp.ok || resp.error[0] != '\0' || resp.result[0] != '\0',
                "hw-edge: 1/0 produces non-crash output");

    /* 4. sqrt(-1) in real mode -> does not crash */
    g_settings.complex_mode = COMPLEX_OFF;
    memset(&resp, 0, sizeof(resp));
    ce_processor_run("sqrt(-1)", &resp);
    ASSERT_TRUE(true, "hw-edge: ce_processor_run(sqrt(-1)) does not crash");
    g_settings.complex_mode = COMPLEX_OFF;

    /* 5. recseq(x/2+1,x,10,5) -> 6 terms (init + 5 recurrences)
     *    terms: 10, 6, 4, 3, 2.5, 2.25 */
    mem_free_all();
    expr = parse_str("x/2+1");
    ASSERT_TRUE(expr != NULL, "hw-edge: recseq expr 'x/2+1' parses");
    if (expr) {
        n = series_recseq(expr, 'x', 10.0f, 5, terms, 10);
        ASSERT_EQ_INT(n, 6, "hw-edge: recseq(x/2+1,x,10,5) returns 6 terms");
        ASSERT_EQ_FLOAT(terms[0], 10.0f, 0.001f, "hw-edge: recseq[0] = 10");
        ASSERT_EQ_FLOAT(terms[1],  6.0f, 0.001f, "hw-edge: recseq[1] = 6");
        ASSERT_EQ_FLOAT(terms[2],  4.0f, 0.001f, "hw-edge: recseq[2] = 4");
        ASSERT_EQ_FLOAT(terms[3],  3.0f, 0.001f, "hw-edge: recseq[3] = 3");
        ASSERT_EQ_FLOAT(terms[4],  2.5f, 0.001f, "hw-edge: recseq[4] = 2.5");
        ASSERT_EQ_FLOAT(terms[5], 2.25f, 0.001f, "hw-edge: recseq[5] = 2.25");
    }

    /* 5b. k=4 variant -> 5 elements */
    mem_free_all();
    expr = parse_str("x/2+1");
    ASSERT_TRUE(expr != NULL, "hw-edge: recseq re-parses for k=4 check");
    if (expr) {
        n = series_recseq(expr, 'x', 10.0f, 4, terms, 10);
        ASSERT_EQ_INT(n, 5, "hw-edge: recseq(x/2+1,x,10,4) returns 5 terms");
        ASSERT_EQ_FLOAT(terms[4], 2.5f, 0.001f,
                        "hw-edge: 5-term recseq[4] = 2.5");
    }

    mem_free_all();
    steps_clear();
}

/* -- 3. IPC state survival full cycle -------------------------------------- */
static void test_pass48_ipc_state_survival_full_cycle(void)
{
    ce_shared_state_t state_a;
    ce_shared_state_t state_b;
    ce_request_t      req;
    ce_response_t     resp;
    int               i;

    printf("=== Pass 48: IPC State Survival Full Cycle ===\n");

    fileioc_mock_enable();
    fileioc_mock_reset();

    /* 1. Settings survive full save/load cycle */
    memset(&state_a, 0, sizeof(state_a));
    state_a.magic                 = CE_IPC_MAGIC;
    state_a.version               = CE_IPC_VERSION;
    state_a.settings.angle_mode   = ANGLE_DEGREES;
    state_a.settings.show_steps   = false;
    state_a.settings.precision    = 4;
    state_a.settings.complex_mode = COMPLEX_RECT;
    state_a.settings.pmt_at_begin = true;
    state_a.last_answer           = 42.0f;
    strncpy(state_a.last_expression, "2+2",
            sizeof(state_a.last_expression) - 1);
    ASSERT_TRUE(ce_state_save(&state_a),
                "hw-ipc-surv: save state_a with custom settings");
    memset(&state_b, 0, sizeof(state_b));
    ASSERT_TRUE(ce_state_load(&state_b),
                "hw-ipc-surv: load state_b succeeds");
    ASSERT_EQ_INT((int)state_b.settings.angle_mode, (int)ANGLE_DEGREES,
                  "hw-ipc-surv: angle_mode=DEGREES survives save/load");
    ASSERT_EQ_INT((int)state_b.settings.show_steps, 0,
                  "hw-ipc-surv: show_steps=false survives save/load");
    ASSERT_EQ_INT((int)state_b.settings.precision, 4,
                  "hw-ipc-surv: precision=4 survives save/load");
    ASSERT_EQ_INT((int)state_b.settings.complex_mode, (int)COMPLEX_RECT,
                  "hw-ipc-surv: complex_mode=RECT survives save/load");
    ASSERT_EQ_INT((int)state_b.settings.pmt_at_begin, 1,
                  "hw-ipc-surv: pmt_at_begin=true survives save/load");
    ASSERT_EQ_FLOAT(state_b.last_answer, 42.0f, 0.001f,
                    "hw-ipc-surv: last_answer=42 survives save/load");
    ASSERT_STR_EQ(state_b.last_expression, "2+2",
                  "hw-ipc-surv: last_expression='2+2' survives save/load");

    /* 2. Ans survives request round-trip */
    fileioc_mock_reset();
    memset(&req, 0, sizeof(req));
    req.magic       = CE_IPC_MAGIC;
    req.version     = CE_IPC_VERSION;
    req.domain      = (uint8_t)CE_DOMAIN_CALC;
    req.last_answer = 42.0f;
    strncpy(req.expression, "Ans*2", sizeof(req.expression) - 1);
    ASSERT_TRUE(ce_request_write(&req),
                "hw-ipc-surv: write Ans*2 request with last_answer=42");
    memset(&req, 0, sizeof(req));
    ASSERT_TRUE(ce_request_read(&req),
                "hw-ipc-surv: read Ans*2 request");
    ASSERT_EQ_FLOAT(req.last_answer, 42.0f, 0.001f,
                    "hw-ipc-surv: Ans=42 survives request round-trip");
    ASSERT_STR_EQ(req.expression, "Ans*2",
                  "hw-ipc-surv: expression='Ans*2' survives");

    /* 3. last_answer propagates through response */
    fileioc_mock_reset();
    memset(&resp, 0, sizeof(resp));
    resp.magic       = CE_IPC_MAGIC;
    resp.version     = CE_IPC_VERSION;
    resp.ok          = 1;
    resp.last_answer = 84.0f;
    strncpy(resp.result, "= 84", sizeof(resp.result) - 1);
    ASSERT_TRUE(ce_response_write(&resp),
                "hw-ipc-surv: write response with last_answer=84");
    memset(&resp, 0, sizeof(resp));
    ASSERT_TRUE(ce_response_read(&resp),
                "hw-ipc-surv: read response with last_answer=84");
    ASSERT_EQ_FLOAT(resp.last_answer, 84.0f, 0.001f,
                    "hw-ipc-surv: last_answer=84 survives response round-trip");
    ASSERT_STR_EQ(resp.result, "= 84",
                  "hw-ipc-surv: result='= 84' survives response round-trip");

    /* 4. has_pending_response survives and can be cleared */
    fileioc_mock_reset();
    memset(&state_a, 0, sizeof(state_a));
    state_a.magic                = CE_IPC_MAGIC;
    state_a.version              = CE_IPC_VERSION;
    state_a.has_pending_response = 1;
    strncpy(state_a.pending_module, "CEALG",
            sizeof(state_a.pending_module) - 1);
    ASSERT_TRUE(ce_state_save(&state_a),
                "hw-ipc-surv: save state with has_pending_response=1");
    memset(&state_b, 0, sizeof(state_b));
    ASSERT_TRUE(ce_state_load(&state_b),
                "hw-ipc-surv: load state with has_pending_response=1");
    ASSERT_EQ_INT((int)state_b.has_pending_response, 1,
                  "hw-ipc-surv: has_pending_response=1 survives save/load");
    ASSERT_STR_EQ(state_b.pending_module, "CEALG",
                  "hw-ipc-surv: pending_module='CEALG' survives");
    state_b.has_pending_response = 0;
    state_b.pending_module[0]    = '\0';
    ASSERT_TRUE(ce_state_save(&state_b),
                "hw-ipc-surv: save state after clearing pending_response");
    memset(&state_a, 0, sizeof(state_a));
    ASSERT_TRUE(ce_state_load(&state_a),
                "hw-ipc-surv: load state after pending clear");
    ASSERT_EQ_INT((int)state_a.has_pending_response, 0,
                  "hw-ipc-surv: has_pending_response=0 confirmed after clear");

    /* 5. History: 3 entries survive full save/load cycle */
    fileioc_mock_reset();
    memset(&state_a, 0, sizeof(state_a));
    state_a.magic   = CE_IPC_MAGIC;
    state_a.version = CE_IPC_VERSION;
    {
        static const char *exprs[3] = {
            "2+2", "d/dx(x^3)", "solve(x^2=4,x)"
        };
        for (i = 0; i < 3; i++) {
            strncpy(state_a.history[state_a.hist_write], exprs[i],
                    MAX_INPUT_LEN - 1);
            state_a.history[state_a.hist_write][MAX_INPUT_LEN - 1] = '\0';
            state_a.hist_write = (uint8_t)((state_a.hist_write + 1) %
                                           CE_HISTORY_SIZE);
            if (state_a.hist_count < CE_HISTORY_SIZE) state_a.hist_count++;
        }
    }
    ASSERT_TRUE(ce_state_save(&state_a),
                "hw-ipc-surv: save state with 3 history entries");
    memset(&state_b, 0, sizeof(state_b));
    ASSERT_TRUE(ce_state_load(&state_b),
                "hw-ipc-surv: load state with 3 history entries");
    ASSERT_EQ_INT((int)state_b.hist_count, 3,
                  "hw-ipc-surv: hist_count=3 survives");
    ASSERT_STR_EQ(state_b.history[0], "2+2",
                  "hw-ipc-surv: history[0]='2+2' survives");
    ASSERT_STR_EQ(state_b.history[1], "d/dx(x^3)",
                  "hw-ipc-surv: history[1]='d/dx(x^3)' survives");
    ASSERT_STR_EQ(state_b.history[2], "solve(x^2=4,x)",
                  "hw-ipc-surv: history[2]='solve(x^2=4,x)' survives");

    fileioc_mock_reset();
    fileioc_mock_disable();
    mem_free_all();
    steps_clear();
}

/* -- 4. VAT pressure simulation: 10 rapid cross-domain switches ------------ */
static void test_pass48_vat_pressure_rapid_domain_switch(void)
{
    ce_response_t resp;
    ce_domain_t   domain;
    const char   *program;
    settings_t    saved_settings;
    char          msg[128];
    int           i;

    static const struct {
        const char  *expr;
        ce_domain_t  expected_domain;
    } cases[] = {
        { "2+2",                   CE_DOMAIN_CORE        },
        { "factor(x^2-1,x)",       CE_DOMAIN_ALG_EXPFAC  },
        { "det(mat(1,0;0,1))",     CE_DOMAIN_MATRIX      },
        { "mean(1,2,3)",           CE_DOMAIN_STAT        },
        { "pv(0.05,10,0,1000)",    CE_DOMAIN_FIN         },
        { "lim(sin(x)/x,x,0)",     CE_DOMAIN_CALC_LIMIT  },
        { "int(x^2,x,0,1)",        CE_DOMAIN_CALC_INT    },
        { "taylor(cos(x),x,0,4)",  CE_DOMAIN_CALC_SERIES },
        { "normalcdf(0,1)",        CE_DOMAIN_PROB        },
        { "d/dx(x^4)",             CE_DOMAIN_CALC        },
    };
    int ncases = (int)(sizeof(cases) / sizeof(cases[0]));

    printf("=== Pass 48: VAT Pressure Rapid Domain Switch ===\n");

    saved_settings = g_settings;

    for (i = 0; i < ncases; i++) {
        bool ok;
        mem_free_all();
        steps_clear();

        ok = processor_run_expr(cases[i].expr, &resp, &domain, &program);
        snprintf(msg, sizeof(msg),
                 "hw-vat: case %d '%s' processed", i, cases[i].expr);
        ASSERT_TRUE(ok, msg);

        snprintf(msg, sizeof(msg),
                 "hw-vat: case %d '%s' resp.ok", i, cases[i].expr);
        ASSERT_TRUE(resp.ok, msg);

        snprintf(msg, sizeof(msg),
                 "hw-vat: case %d '%s' domain matches", i, cases[i].expr);
        ASSERT_EQ_INT((int)domain, (int)cases[i].expected_domain, msg);

        snprintf(msg, sizeof(msg),
                 "hw-vat: case %d angle_mode unchanged", i);
        ASSERT_EQ_INT((int)g_settings.angle_mode,
                      (int)saved_settings.angle_mode, msg);

        snprintf(msg, sizeof(msg),
                 "hw-vat: case %d show_steps unchanged", i);
        ASSERT_EQ_INT((int)g_settings.show_steps,
                      (int)saved_settings.show_steps, msg);
    }

    mem_free_all();
    ASSERT_TRUE((int)mem_nodes_free() >= 400,
                "hw-vat: pool has >=400 free nodes after 10 rapid domain switches");

    mem_free_all();
    steps_clear();
}

/* -- 5. Enter-path hardware parity ----------------------------------------- */
static void test_pass48_enter_path_hardware_parity(void)
{
    ce_response_t     resp;
    ce_response_t     resp1, resp2;
    ce_domain_t       dom1, dom2;
    const char       *prog1, *prog2;
    ce_shared_state_t state;
    ce_request_t      mrt_req;
    ce_response_t     mrt_resp;
    ce_shared_state_t mrt_state;
    ast_node_t       *mrt_root;
    bool              mrt_had_eq;
    tokenizer_t       tok;
    parser_t          par;
    ast_node_t       *root;

    printf("=== Pass 48: Enter-Path Hardware Parity ===\n");

    /* 5a. Empty input -> parser yields NULL root (no crash) */
    mem_free_all();
    tok_init(&tok, "");
    (void)tok_tokenize(&tok);
    parser_init(&par, &tok);
    root = parser_parse(&par);
    ASSERT_TRUE(root == NULL,
                "hw-ep: parser_parse on empty input returns NULL");
    mem_free_all();

    /* 5b. ce_processor_run with empty string -> false + error message */
    memset(&resp, 0, sizeof(resp));
    ASSERT_TRUE(!ce_processor_run("", &resp),
                "hw-ep: ce_processor_run empty string returns false");
    ASSERT_TRUE(resp.error[0] != '\0',
                "hw-ep: ce_processor_run empty string sets error message");

    /* 5c. Rapid ENTER: same expression twice -> identical results */
    processor_run_expr("2+2", &resp1, &dom1, &prog1);
    mem_free_all();
    steps_clear();
    processor_run_expr("2+2", &resp2, &dom2, &prog2);
    ASSERT_TRUE(resp1.ok && resp2.ok,
                "hw-ep: rapid ENTER: both 2+2 runs succeed");
    ASSERT_EQ_INT((int)dom1, (int)dom2,
                  "hw-ep: rapid ENTER: domain identical across two ENTER presses");
    ASSERT_STR_EQ(prog1, prog2,
                  "hw-ep: rapid ENTER: target program identical across two runs");
    ASSERT_EQ_FLOAT(resp1.last_answer, resp2.last_answer, 0.001f,
                    "hw-ep: rapid ENTER: last_answer identical across two runs");
    ASSERT_STR_EQ(resp1.result, resp2.result,
                  "hw-ep: rapid ENTER: result string identical across two runs");

    /* 5d. has_pending_response=1 -> startup picks up result correctly */
    fileioc_mock_enable();
    fileioc_mock_reset();

    memset(&resp, 0, sizeof(resp));
    resp.magic       = CE_IPC_MAGIC;
    resp.version     = CE_IPC_VERSION;
    resp.ok          = 1;
    resp.last_answer = 4.0f;
    strncpy(resp.result, "= 4", sizeof(resp.result) - 1);
    ASSERT_TRUE(ce_response_write(&resp),
                "hw-ep: worker response write succeeds");

    memset(&state, 0, sizeof(state));
    state.magic                = CE_IPC_MAGIC;
    state.version              = CE_IPC_VERSION;
    state.has_pending_response = 1;
    strncpy(state.last_expression, "2+2",
            sizeof(state.last_expression) - 1);
    ASSERT_TRUE(ce_state_save(&state),
                "hw-ep: launcher saves state with has_pending_response=1");
    memset(&state, 0, sizeof(state));
    ASSERT_TRUE(ce_state_load(&state),
                "hw-ep: launcher loads state on startup");
    ASSERT_EQ_INT((int)state.has_pending_response, 1,
                  "hw-ep: has_pending_response=1 detected at startup");
    memset(&resp, 0, sizeof(resp));
    ASSERT_TRUE(ce_response_read(&resp),
                "hw-ep: launcher reads pending response");
    ASSERT_TRUE(resp.ok, "hw-ep: pending response ok=1");
    ASSERT_EQ_FLOAT(resp.last_answer, 4.0f, 0.001f,
                    "hw-ep: pending response last_answer=4");
    ASSERT_STR_EQ(resp.result, "= 4",
                  "hw-ep: pending response result='= 4'");
    state.has_pending_response = 0;
    ASSERT_TRUE(ce_state_save(&state),
                "hw-ep: launcher clears has_pending_response");
    ce_response_delete();
    memset(&state, 0, sizeof(state));
    ASSERT_TRUE(ce_state_load(&state),
                "hw-ep: load state after pending clear");
    ASSERT_EQ_INT((int)state.has_pending_response, 0,
                  "hw-ep: has_pending_response=0 confirmed after clear");

    /* 5e. ce_module_runtime_load with no request -> false */
    fileioc_mock_reset();
    mrt_root   = NULL;
    mrt_had_eq = false;
    ASSERT_TRUE(!ce_module_runtime_load(&mrt_req, &mrt_resp,
                                        &mrt_state, &mrt_root, &mrt_had_eq),
                "hw-ep: module_runtime_load with no request returns false");
    ASSERT_TRUE(!mrt_resp.ok,
                "hw-ep: module_runtime_load failure leaves resp.ok=false");
    ASSERT_TRUE(mrt_resp.error[0] != '\0',
                "hw-ep: module_runtime_load failure sets error message");

    /* 5f. NULL args -> false (no crash) */
    ASSERT_TRUE(!ce_module_runtime_load(NULL, &mrt_resp,
                                        &mrt_state, &mrt_root, &mrt_had_eq),
                "hw-ep: module_runtime_load(NULL req) returns false");
    ASSERT_TRUE(!ce_module_runtime_load(&mrt_req, NULL,
                                        &mrt_state, &mrt_root, &mrt_had_eq),
                "hw-ep: module_runtime_load(NULL resp) returns false");

    /* 5g. ce_program_ensure_ram for non-existent program -> false */
    {
        bool ens = ce_program_ensure_ram("NXPRGM");
        ASSERT_TRUE(!ens,
                    "hw-ep: ce_program_ensure_ram for missing program returns false");
    }

    fileioc_mock_reset();
    fileioc_mock_disable();
    mem_free_all();
    steps_clear();
}

