    mp_tmpl_init(&tmpl, MP_TMPL_DERIV);
    ASSERT_EQ_INT(tmpl.num_slots, 2, "DERIV: 2 slots");

    mp_tmpl_init(&tmpl, MP_TMPL_LIMIT);
    ASSERT_EQ_INT(tmpl.num_slots, 3, "LIMIT: 3 slots");

    mp_tmpl_init(&tmpl, MP_TMPL_SUM);
    ASSERT_EQ_INT(tmpl.num_slots, 4, "SUM: 4 slots");

    mp_tmpl_init(&tmpl, MP_TMPL_PRODUCT);
    ASSERT_EQ_INT(tmpl.num_slots, 4, "PRODUCT: 4 slots");

    mp_tmpl_init(&tmpl, MP_TMPL_FRACTION);
