/* ── T73.10  integrate_definite step says DIVERGES for non-finite F ── */
static void test_pass73_definite_step_nonfinite_guard(void)
{
    /* int(ln(x), x, 0, 1):
     * F(x) = x*ln(x) - x.  At x=0: F(0) = 0*(-inf)-0 = 0 (L'Hopital),
     * but the eval_ctx may give NaN.  With the guard, if it's non-finite
     * integrate_definite sets CE_ERR_OVERFLOW so caller can fall back.
     *
     * More reliable: int(1/x^2, x, 0, 1) — F(x)=-1/x, F(0)→-inf
     * The new guard should catch F_lo = -inf and return CE_ERR_OVERFLOW. */
    ast_node_t *expr;
    ce_error_t err;
    int step_idx;

    mem_free_all(); steps_clear();
    expr = parse_str("1/x^2");
    ASSERT_TRUE(expr != NULL, "p73-step-guard: parse 1/x^2");
    if (expr) {
        /* integrate_definite with lo=0 (singularity): F(x)=-1/x, F(0)=-inf */
        integrate_definite(expr, 'x', 0.0f, 1.0f, NULL, 0, &err);
        /* Should fail because F(0) = -infinity */
        ASSERT_TRUE(err != CE_OK,
                    "p73-step-guard: integrate_definite(1/x^2,[0,1]) should fail (F(0)=inf)");
        /* Check that steps contain DIVERGES or non-finite message */
        {
            bool found_diverges = false;
            for (step_idx = 0; step_idx < steps_count(); step_idx++) {
                const char *s = steps_get(step_idx);
                if (s && (strstr(s, "DIVERGES") || strstr(s, "non-finite")))
                    found_diverges = true;
            }
            ASSERT_TRUE(found_diverges,
                        "p73-step-guard: steps contain DIVERGES or non-finite message");
        }
        ast_free(expr);
    }
    mem_free_all(); steps_clear();
}

/* ── T73.11  u-sub failure reason includes WHY ────────────────────── */
static void test_pass73_usub_failure_reason_content(void)
{
    ast_node_t *expr;

    /* x^3 + 1 has no obvious u-sub pattern */
    mem_free_all(); steps_clear();
    expr = parse_str("x^3+1");
    ASSERT_TRUE(expr != NULL, "p73-usub: parse x^3+1");
    if (expr) {
        ast_node_t *result;
        result = integrate_with_strategy(expr, 'x', INTEG_STRATEGY_USUB, NULL);
        ASSERT_TRUE(result == NULL, "p73-usub: x^3+1 u-sub returns NULL (expected)");
        if (!result) {
            const char *reason = integrate_last_failure_reason();
            ASSERT_TRUE(reason != NULL, "p73-usub: failure reason non-NULL");
            if (reason) {
                bool has_why = (strstr(reason, "factor") != NULL ||
                                strstr(reason, "applicable") != NULL ||
                                strstr(reason, "found") != NULL);
                ASSERT_TRUE(has_why,
                            "p73-usub: failure reason explains why u-sub failed");
            }
            /* Also check that a step was recorded explaining the failure */
            {
                bool found_step = false;
                int i;
                for (i = 0; i < steps_count(); i++) {
                    const char *s = steps_get(i);
                    if (s && (strstr(s, "u-sub") || strstr(s, "substitut")))
                        found_step = true;
                }
                ASSERT_TRUE(found_step,
                            "p73-usub: steps contain u-sub explanation");
            }
        }
        ast_free(expr);
    }
    mem_free_all(); steps_clear();
}

/* ── T73.12  simplify depth warning appears in steps ─────────────── */
static void test_pass73_simplify_depth_warning(void)
{
    /* Build a deeply nested expression: ((((x+0)+0)+0)+0)...50 layers
     * so that ast_simplify hits the depth limit.
     * We carefully allocate only what we need. */
    ast_node_t *deep = NULL;
    ast_node_t *var_node;
    int i;
    int step_before, step_after;
    bool found_warning;

    mem_free_all(); steps_clear();

    var_node = parse_str("x");
    ASSERT_TRUE(var_node != NULL, "p73-depth: parse x");
    if (!var_node) return;

    /* Wrap in 55 layers of (... + 0) to force depth > SIMPLIFY_MAX_DEPTH=50 */
    deep = var_node;
    for (i = 0; i < 55 && deep; i++) {
        ast_node_t *zero = ast_number(0.0f);
        if (!zero) break;
        deep = ast_binop(OP_ADD, deep, zero);
    }

    if (!deep) {
        mem_free_all(); steps_clear(); return;
    }

    step_before = steps_count();
    {
        ast_node_t *s = ast_simplify(deep);
        /* If simplify returned the node itself (depth limit), free it */
        if (s != deep) ast_free(s);
    }
    step_after = steps_count();

    found_warning = false;
    for (i = step_before; i < step_after; i++) {
        const char *s = steps_get(i);
        if (s && strstr(s, "depth limit"))
            found_warning = true;
    }
    /* Only assert if new steps were actually added */
    if (step_after > step_before) {
        ASSERT_TRUE(found_warning,
                    "p73-depth: simplify depth warning appears in steps when limit hit");
    }
    /* If no new steps (depth limit not reached), just pass the test — pool may
     * run out before hitting 55 levels. */
    mem_free_all(); steps_clear();
}

/* ── T73.13  areabetween: null / bad-args guards ──────────────────── */
static void test_pass73_areabetween_null_guards(void)
{
    ast_node_t *expr;
    ce_float_t area;
    ce_error_t err;

    mem_free_all(); steps_clear();
    expr = parse_str("x");

    /* NULL f */
    area = area_between_curves(NULL, expr, 'x', 0, 1, &err);
    ASSERT_EQ_INT((int)err, (int)CE_ERR_SYNTAX, "p73-guards: NULL f → CE_ERR_SYNTAX");
    ASSERT_EQ_FLOAT(area, 0.0f, 1e-6f, "p73-guards: NULL f → 0");

    /* NULL g */
    err = CE_OK;
    area = area_between_curves(expr, NULL, 'x', 0, 1, &err);
    ASSERT_EQ_INT((int)err, (int)CE_ERR_SYNTAX, "p73-guards: NULL g → CE_ERR_SYNTAX");

    /* a >= b (degenerate interval) */
    if (expr) {
        ast_node_t *g = parse_str("x^2");
        if (g) {
            err = CE_OK;
            area = area_between_curves(expr, g, 'x', 1.0f, 0.0f, &err);
            ASSERT_EQ_INT((int)err, (int)CE_ERR_SYNTAX,
                          "p73-guards: a>=b → CE_ERR_SYNTAX");
            ast_free(g);
        }
    }

    ast_free(expr);
    mem_free_all(); steps_clear();
}

/* ── T73.14  areabetween: two intersections on interior ──────────── */
static void test_pass73_areabetween_multi_intersection(void)
{
    ast_node_t *f, *g;
    ce_float_t area;
    ce_error_t err;

    /* f(x) = sin(x), g(x) = 0 on [0, 2*pi]:
     * sin crosses 0 at x=pi.
     * ∫_0^pi sin dx + ∫_pi^2pi |sin| dx = 2 + 2 = 4 */
    mem_free_all(); steps_clear();
    f = parse_str("sin(x)");
    g = parse_str("0");
    ASSERT_TRUE(f != NULL && g != NULL, "p73-multi: parse sin(x), 0");
    if (f && g) {
        area = area_between_curves(f, g, 'x', 0.0f, 2.0f * CE_PI, &err);
        ASSERT_EQ_INT((int)err, (int)CE_OK, "p73-multi: sin [0,2pi] no err");
        ASSERT_EQ_FLOAT(area, 4.0f, 0.1f,
                        "p73-multi: area(sin,0,[0,2pi]) = 4");
    }
    ast_free(f); ast_free(g);

    /* f(x)=x, g(x)=x^2-2 on [-1,2]:
     * Intersections: x^2-x-2=0 → x=-1,2 (at boundaries only on [-1,2]).
     * On this interval x > x^2-2.
     * ∫_{-1}^{2} (x - (x^2-2)) dx = ∫ (x - x^2 + 2) dx
     * = [x^2/2 - x^3/3 + 2x]_{-1}^{2} = (2-8/3+4) - (1/2+1/3-2) = 4.5 */
    mem_free_all(); steps_clear();
    f = parse_str("x");
    g = parse_str("x^2-2");
    ASSERT_TRUE(f != NULL && g != NULL, "p73-multi2: parse x, x^2-2");
    if (f && g) {
        area = area_between_curves(f, g, 'x', -1.0f, 2.0f, &err);
        ASSERT_EQ_INT((int)err, (int)CE_OK, "p73-multi2: x vs x^2-2 no err");
        ASSERT_EQ_FLOAT(area, 4.5f, 0.1f,
                        "p73-multi2: area(x,x^2-2,[-1,2]) = 4.5");
    }
    ast_free(f); ast_free(g);
}

