static void test_pass75_eigenvec_2x2(void)
{
    /*
     * [[4,1],[2,3]] eigenvalues 5, 2
     * For λ=5: (A-5I)v = [[-1,1],[2,-2]]v = 0 → v = [1,1] (normalized)
     * For λ=2: (A-2I)v = [[2,1],[2,1]]v = 0 → v = [1,-2] (normalized)
     */
    ce_matrix_t m;
    ce_float_t evals[MAX_MATRIX_DIM];
    ce_float_t evecs[MAX_MATRIX_DIM][MAX_MATRIX_DIM];
    int n_eig, n_vec;
    mem_free_all(); steps_clear();
    matrix_init(&m, 2, 2);
    MAT_AT(&m, 0, 0) = 4.0f; MAT_AT(&m, 0, 1) = 1.0f;
    MAT_AT(&m, 1, 0) = 2.0f; MAT_AT(&m, 1, 1) = 3.0f;
    n_eig = matrix_eigenvalues(&m, evals, MAX_MATRIX_DIM);
    ASSERT_EQ_INT(n_eig, 2, "evec2: two eigenvalues");
    n_vec = matrix_eigenvectors(&m, evals, evecs, n_eig);
    ASSERT_EQ_INT(n_vec, 2, "evec2: two eigenvectors");
    /* Each eigenvector should be non-zero */
    {
        int i;
        for (i = 0; i < n_vec; i++) {
            ce_float_t norm = evecs[i][0]*evecs[i][0] + evecs[i][1]*evecs[i][1];
            ASSERT_TRUE(norm > 0.01f, "evec2: eigenvector non-zero");
        }
    }
    mem_free_all(); steps_clear();
}

static void test_pass75_eigenvec_verify_Av_lambdav(void)
{
    /*
     * Verify A*v = λ*v for each eigenvector.
     * [[3,1],[0,2]] → eigenvalues 3, 2
     * For λ=3: v = [1,0]
     * For λ=2: v = [1,-1]
     */
    ce_matrix_t m;
    ce_float_t evals[MAX_MATRIX_DIM];
    ce_float_t evecs[MAX_MATRIX_DIM][MAX_MATRIX_DIM];
    int n_eig, n_vec, i, j, k;
    mem_free_all(); steps_clear();
    matrix_init(&m, 2, 2);
    MAT_AT(&m, 0, 0) = 3.0f; MAT_AT(&m, 0, 1) = 1.0f;
    MAT_AT(&m, 1, 0) = 0.0f; MAT_AT(&m, 1, 1) = 2.0f;
    n_eig = matrix_eigenvalues(&m, evals, MAX_MATRIX_DIM);
    n_vec = matrix_eigenvectors(&m, evals, evecs, n_eig);
    for (i = 0; i < n_vec; i++) {
        /* Compute Av */
        ce_float_t Av[MAX_MATRIX_DIM] = {0};
        for (j = 0; j < (int)m.rows; j++) {
            for (k = 0; k < (int)m.cols; k++) {
                Av[j] += MAT_AT(&m, j, k) * evecs[i][k];
            }
        }
        /* Compare Av with λv */
        for (j = 0; j < (int)m.rows; j++) {
            ce_float_t diff = fabsf(Av[j] - evals[i] * evecs[i][j]);
            ASSERT_TRUE(diff < 0.05f, "evec_verify: A*v = lambda*v");
        }
    }
    mem_free_all(); steps_clear();
}

