/* An operator typed without its variable uses the variable the
 * input contains.  The CE keypad types upper-case letters, so a fixed
 * lower-case default made int(X^2) integrate X^2 as a constant in x and
 * show "((X^2)*x) + C". */
static char default_var_of(const char *input, int which)
{
    ast_node_t *root;
    char v = 0;
    mem_free_all();
    root = parse_str(input);
    if (!root) return '?';
    switch (root->type) {
    case NODE_INTEGRAL: v = root->d.integral.var; break;
    case NODE_DERIV:    v = root->d.deriv.var;    break;
    case NODE_LIMIT:    v = root->d.limit.var;    break;
    case NODE_SUM:      v = root->d.sum.var;      break;
    case NODE_PRODUCT:  v = root->d.product.var;  break;
    case NODE_TAYLOR:   v = root->d.taylor.var;   break;
    case NODE_FOURIER:  v = root->d.fourier.var;  break;
    case NODE_SOLVE:    v = root->d.solve.var;    break;
    case NODE_TANGENT:  v = root->d.tangent.var;  break;
    case NODE_POLAR:
        if (which == 1) {
            /* nlsolve keeps v2 in lo as a number; graphimpl in expr2 */
            if (root->d.polar.op == POLOP_NLSOLVE && root->d.polar.lo &&
                root->d.polar.lo->type == NODE_NUMBER)
                v = (char)(int)root->d.polar.lo->d.number;
            else if (root->d.polar.expr2 &&
                     root->d.polar.expr2->type == NODE_VARIABLE)
                v = root->d.polar.expr2->d.variable;
        } else {
            v = root->d.polar.var;
        }
        break;
    default: v = '!'; break;
    }
    ast_free(root);
    mem_free_all();
    return v;
}

static void test_default_variable_follows_input_case(void)
{
    static const struct { const char *in; int which; char var; } cases[] = {
        /* the reported CE inputs */
        { "int(X^2)",               0, 'X' },
        { "int(int(--2X+X+X))",     0, 'X' },
        /* desktop lower-case input is unchanged */
        { "int(x^2)",               0, 'x' },
        { "int(x^2+1)dx",           0, 'x' },
        { "int(x) d y",             0, 'y' },
        /* differentials keep their case, then follow the integrand */
        { "int(X^2)dX",             0, 'X' },
        { "int(X^2)dx",             0, 'X' },
        { "int(X) d Y",             0, 'Y' },
        { "int(x^2)dX",             0, 'x' },
        /* an explicit variable always wins */
        { "int(X^2,T)",             0, 'T' },
        { "int(X^2,X)dx",           0, 'X' },
        { "int(x^2,X)",             0, 'X' },
        /* only the case is inferred, never another letter, so an
         * upper-case input parses like its lower-case form */
        { "int(A*X)",               0, 'X' },
        { "int(T^2)",               0, 'x' },
        { "int(t^2)",               0, 'x' },
        { "int(A*B)",               0, 'x' },
        { "int(5)",                 0, 'x' },
        /* the other operators that default their variable */
        { "deriv(X^3)",             0, 'X' },
        { "deriv(x^3)",             0, 'x' },
        { "nderiv(X^3)",            0, 'X' },
        { "lim(1/X)",               0, 'X' },
        { "sum(N^2)",               0, 'N' },
        { "sum(K^2)",               0, 'n' },
        { "sum(n^2)",               0, 'n' },
        { "prod(N)",                0, 'N' },
        { "taylor(sin(X))",         0, 'X' },
        { "fourier(X)",             0, 'X' },
        { "solve(X^2-4)",           0, 'X' },
        { "tangent(X^2)",           0, 'X' },
        { "continuity(1/X)",        0, 'X' },
        { "csquare(X^2+4*X+1)",     0, 'X' },
        { "descartes(X^3-X+1)",     0, 'X' },
        { "pfrac(1/(X*(X+1)))",     0, 'X' },
        /* two default variables resolve by case only, never to one letter */
        { "nlsolve(X+Y-3,X-Y-1)",   0, 'X' },
        { "nlsolve(X+Y-3,X-Y-1)",   1, 'Y' },
        { "nlsolve(X-1,X+1)",       0, 'X' },
        { "nlsolve(X-1,X+1)",       1, 'y' },
        /* an explicit first variable is never reused for the second */
        { "nlsolve(Y-1,2*Y-2,Y)",   0, 'Y' },
        { "nlsolve(Y-1,2*Y-2,Y)",   1, 'y' },
        { "graphimpl(Y^2-1,Y)",     0, 'Y' },
        { "graphimpl(Y^2-1,Y)",     1, 'y' },
        { "graphimpl(X^2+Y^2-1,Y,X)", 1, 'X' },
        { "graphimpl(X^2+Y^2-1)",   0, 'X' },
        { "graphimpl(X^2+Y^2-1)",   1, 'Y' },
        { "graphimpl(x+y)",         0, 'x' },
        /* letters of nested operators never become the default
         * (review, PR #124) */
        { "deriv(sum(k,k,1,3))",    0, 'x' },
        { "deriv(sum(K,K,1,3))",    0, 'x' },
        { "deriv(prod(K,K,1,3))",   0, 'x' },
        { "deriv(mean(sum(K,K,1,3)))", 0, 'x' },
        { "int(sum(K^2,K,1,N))",    0, 'x' },
        { "int(int(T,T,0,A))",      0, 'x' },
        { "int(lim(1/K,K,0)+X)",    0, 'X' },
        { "int(solve(K^2-4,K))",    0, 'x' },
        { "deriv(int(2,T))",        0, 'x' },
        /* parametric arclen: both coordinates decide */
        { "arclen(t,10*x)",         0, 'x' },
        { "arclen(1,X^2)",          0, 'X' },
        { "arclen(cos(T),sin(T))",  0, 'x' },
    };
    static const struct { const char *in; const char *out; } results[] = {
        { "int(X^2)",           "int = X^3/3 + C" },
        { "int(X^2)dX",         "int = X^3/3 + C" },
        { "int(X) d Y",         "int = X*Y + C" },
        { "int(x^2)",           "int = x^3/3 + C" },
        { "deriv(X^3)",         "d/dX = 3X^2" },
        { "solve(X^2-4)",       "X = 2 or X = -2" },
        { "deriv(sum(k,k,1,3))", "d/dx = 0" },
        { "arclen(t,10*x)",     "Parametric arc length = 10" },
    };
    size_t i;
    char msg[96];
    for (i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
        char got = default_var_of(cases[i].in, cases[i].which);
        snprintf(msg, sizeof(msg), "default var: %s [%d] -> %c (got %c)",
                 cases[i].in, cases[i].which, cases[i].var, got);
        ASSERT_TRUE(got == cases[i].var, msg);
    }
    for (i = 0; i < sizeof(results) / sizeof(results[0]); i++) {
        ce_response_t resp;
        memset(&resp, 0, sizeof(resp));
        mem_free_all(); steps_clear();
        snprintf(msg, sizeof(msg), "default var result: %s", results[i].in);
        ASSERT_TRUE(ce_processor_run(results[i].in, &resp), msg);
        ASSERT_TRUE(resp.ok == 1, msg);
        ASSERT_TRUE(strncmp(resp.result, results[i].out, strlen(results[i].out)) == 0
                    && (resp.result[strlen(results[i].out)] == '\n'
                        || resp.result[strlen(results[i].out)] == '\0'), msg);
    }
    /* Nested indefinite integrals are refused as with lower-case input,
     * instead of cloning the inner integral through the constant rule. */
    {
        ce_response_t resp;
        memset(&resp, 0, sizeof(resp));
        mem_free_all(); steps_clear();
        ce_processor_run("int(int(--2X+X+X))", &resp);
        ASSERT_TRUE(strstr(resp.result, "int(") == NULL,
                    "default var: nested int is not treated as a constant");
    }
    mem_free_all(); steps_clear();
}

/* Keep the first error when classifying a sum's upper bound. */
static void test_sum_classification_first_error(void)
{
    ce_response_t resp;
    ast_node_t *root;
    int i;
    static const struct { const char *input; const char *error; } errors[] = {
        { "sum(1,k,1,1/0)", "Division by zero" },
        { "sum(1,k,1,z)", "z has no value" },
        { "sum(1,k,x,y)", "y has no value" },
        { "sum(10^38,k,1,10)", "Sum overflow" },
    };

    mem_free_all(); steps_clear();
    g_last_answer = 37;
    tice_mock_cancel_once();
    ce_processor_run("sum(1,k,1,sum(1,j,0,5))", &resp);
    ASSERT_TRUE(!resp.ok, "classification cancellation refuses");
    ASSERT_STR_CONTAINS(resp.error, "Cancelled", "keep first cancellation");
    ASSERT_EQ_INT(tice_mock_cancel_calls(), 1, "no retry after cancellation");
    ASSERT_EQ_FLOAT(g_last_answer, 37, 1e-6f, "cancel preserves runtime Ans");
    ASSERT_EQ_FLOAT(resp.last_answer, 37, 1e-6f, "cancel preserves response Ans");
    ASSERT_TRUE(strstr(resp.result, "Convergence") == NULL, "cancel is not a series");
    tice_mock_set_cancel(false);

    /* Bypass the parser cap to exercise the evaluator's own depth guard.
     * The inner sum checks cancellation once before reaching that guard. */
    mem_free_all(); steps_clear();
    root = parse_str("sum(1,k,1,sum(1,j,0,0))");
    ASSERT_TRUE(root && root->type == NODE_SUM && root->d.sum.hi &&
                root->d.sum.hi->type == NODE_SUM, "depth fixture has nested sums");
    if (root && root->type == NODE_SUM && root->d.sum.hi &&
        root->d.sum.hi->type == NODE_SUM) {
        for (i = 0; i < CE_EVAL_MAX_DEPTH + 2; i++) {
            root->d.sum.hi->d.sum.expr =
                ast_unop(UOP_NEG, root->d.sum.hi->d.sum.expr);
        }
        ce_processor_run_preparsed("sum depth fixture", root, false, &resp);
        ASSERT_TRUE(!resp.ok, "classification depth refuses");
        ASSERT_STR_CONTAINS(resp.error, "Eval recursion limit", "keep depth error");
        ASSERT_EQ_INT(tice_mock_cancel_calls(), 1, "no retry after depth error");
        ASSERT_EQ_FLOAT(g_last_answer, 37, 1e-6f, "depth preserves runtime Ans");
        ASSERT_EQ_FLOAT(resp.last_answer, 37, 1e-6f, "depth preserves response Ans");
        ASSERT_TRUE(g_eval_refused, "classification keeps static depth refusal");
        ce_response_from_runtime(&resp, true, false, "= 10", "", 10);
        ASSERT_TRUE(!resp.ok, "static refusal blocks a later attempted success");
        ASSERT_STR_CONTAINS(resp.error, "Eval recursion limit", "sticky refusal reason");
        ASSERT_EQ_FLOAT(g_last_answer, 37, 1e-6f, "sticky refusal preserves runtime Ans");
        ASSERT_EQ_FLOAT(resp.last_answer, 37, 1e-6f, "sticky refusal preserves response Ans");
    } else if (root) {
        ast_free(root);
    }
    tice_mock_set_cancel(false);
    for (i = 0; i < (int)(sizeof(errors) / sizeof(errors[0])); i++) {
        mem_free_all(); steps_clear();
        ce_processor_run(errors[i].input, &resp);
        ASSERT_TRUE(!resp.ok, "sum error refuses");
        ASSERT_STR_CONTAINS(resp.error, errors[i].error, "sum keeps error reason");
        ASSERT_EQ_FLOAT(g_last_answer, 37, 1e-6f, "error preserves runtime Ans");
        ASSERT_EQ_FLOAT(resp.last_answer, 37, 1e-6f, "error preserves response Ans");
        ASSERT_TRUE(strstr(resp.result, "Convergence") == NULL, "error is not a series");
    }
    mem_free_all(); steps_clear();
    ce_processor_run("sum(k,k,1,3)", &resp);
    ASSERT_TRUE(resp.ok, "later sum succeeds");
    ASSERT_EQ_FLOAT(g_last_answer, 6, 1e-6f, "later success updates Ans");
    ASSERT_TRUE(!g_eval_refused, "new desktop request clears prior refusal");
    mem_free_all(); steps_clear();
}

/* Finite bounds evaluate a partial sum. Only positive infinity uses the
 * legacy convergence estimate and label, retained without certification. */
static void test_finite_sum_is_partial_sum(void)
{
    static const struct { const char *in; const char *want; } ok_cases[] = {
        { "sum(n,n,1,10)",          "= 55" },
        { "sum(N,N,1,10)",          "= 55" },
        { "sum(1/n^2,n,1,10)",      "= 1.54977" },
        { "sum(k^2,k,1,4)",         "= 30" },
        { "sum(k,k,0,0)",           "= 0" },
        { "sum(k,k,5,1)",           "= 0" },   /* empty sum */
        { "sum(2^k,k,0,10)",        "= 2047" },
        { "sum((-1)^k,k,1,3)",      "= -1" },
        { "sum(k!,k,0,5)",          "= 154" },
        { "sum(k,k,-3,3)",          "= 0" },
        { "sum(k,k,1,2+3)",         "= 15" },
        { "sum(1,k,0,10000)",       "= 10001" },
        { "sum(sum(k,k,1,2)+k,k,1,2)", "= 9" },
        { "sum(1,k,-2147483648,-2147483648)", "= 1" },
    };
    static const struct { const char *in; const char *want; } fail_cases[] = {
        { "sum(1/(n-3),n,1,5)",     "Division by zero" },  /* a failed term */
        { "sum(n,n,1,20000)",       "Sum too many terms" },
        { "sum(n,n,1,10.5)",        "integers" },
        { "sum(1,k,0,10001)",       "Sum too many terms" },
        { "sum(k,k,2147483648,2147483648)", "integers" },
        { "sum(10^38,k,1,10)",      "Sum overflow" },
        { "sum(k^2,k,1,n)",         "n has no value" },
        { "sum(k*x,k,1,3)",         "x has no value" },
        { "sum(n,n,1,-inf)",        "integers" },
    };
    static const struct { const char *in; const char *want; } series_cases[] = {
        { "sum(1/n^2,n,1,inf)",     "Convergence: converges" },
        { "sum(n,n,1,inf)",         "Convergence: diverges" },
        { "sum(1/n,n,1,inf)",       "Convergence: diverges" },
    };
    ce_response_t resp;
    size_t i;
    char msg[96];

    for (i = 0; i < sizeof(ok_cases) / sizeof(ok_cases[0]); i++) {
        mem_free_all(); steps_clear();
        memset(&resp, 0, sizeof(resp));
        snprintf(msg, sizeof(msg), "finite sum %s runs", ok_cases[i].in);
        ASSERT_TRUE(ce_processor_run(ok_cases[i].in, &resp), msg);
        snprintf(msg, sizeof(msg), "finite sum %s ok", ok_cases[i].in);
        ASSERT_TRUE(resp.ok, msg);
        snprintf(msg, sizeof(msg), "finite sum %s = %s (got %.40s)",
                 ok_cases[i].in, ok_cases[i].want, resp.result);
        ASSERT_TRUE(strcmp(resp.result, ok_cases[i].want) == 0, msg);
        snprintf(msg, sizeof(msg), "finite sum %s is no series test", ok_cases[i].in);
        ASSERT_TRUE(strstr(resp.result, "Convergence") == NULL, msg);
    }
    for (i = 0; i < sizeof(fail_cases) / sizeof(fail_cases[0]); i++) {
        mem_free_all(); steps_clear();
        memset(&resp, 0, sizeof(resp));
        (void)ce_processor_run(fail_cases[i].in, &resp);
        snprintf(msg, sizeof(msg), "finite sum %s fails", fail_cases[i].in);
        ASSERT_TRUE(!resp.ok, msg);
        snprintf(msg, sizeof(msg), "finite sum %s error", fail_cases[i].in);
        ASSERT_STR_CONTAINS(resp.error, fail_cases[i].want, msg);
    }
    for (i = 0; i < sizeof(series_cases) / sizeof(series_cases[0]); i++) {
        mem_free_all(); steps_clear();
        memset(&resp, 0, sizeof(resp));
        snprintf(msg, sizeof(msg), "series %s runs", series_cases[i].in);
        ASSERT_TRUE(ce_processor_run(series_cases[i].in, &resp), msg);
        snprintf(msg, sizeof(msg), "series %s", series_cases[i].in);
        ASSERT_STR_CONTAINS(resp.result, series_cases[i].want, msg);
    }
    /* Preserve the legacy 1.63993 estimate, not a pi^2/6 accuracy claim. */
    mem_free_all(); steps_clear();
    memset(&resp, 0, sizeof(resp));
    ASSERT_TRUE(ce_processor_run("sum(1/n^2,n,1,inf)", &resp), "series 1/n^2 runs");
    ASSERT_STR_CONTAINS(resp.result, "Sum ~= 1.6", "series 1/n^2 keeps its sum");
    mem_free_all(); steps_clear();
}

/* ── An eval refusal or failed sample is never shown as math ── */
static void sum_of_x(char *buf, int terms, const char *prefix, const char *suffix)
{
    char *p = buf + strlen(strcpy(buf, prefix));
    int i;
    for (i = 0; i < terms; i++) {
        if (i) *p++ = '+';
        *p++ = 'x';
    }
    strcpy(p, suffix);
}

